-- ==========================================================================
-- LUNOCA DOCERIA - MIGRATION 018: FRENTE C - CARTEIRA DE CRÉDITOS DO CLIENTE
-- ==========================================================================
-- Arquitetura e Contrato Financeiro:
-- 1. Livro-Razão Imutável (Append-Only):
--    - public.cliente_creditos: saldo consolidado por cliente (sem colunas redundantes).
--    - public.cliente_credito_movimentacoes: trilha de auditoria estrita. NUNCA UPDATE/DELETE.
--    - ON DELETE RESTRICT no cliente para preservar a integridade histórica contábil.
-- 2. Concorrência Serializada e Idempotência:
--    - Trava ordinal rigorosa: clientes(id) FOR UPDATE -> cliente_creditos(cliente_id) FOR UPDATE.
--    - Chaves de idempotência unívocas geradas server-side:
--      * Cancelamento: 'cancelamento:{pedido_id}:credito_cliente'
--      * Uso em Pedido: 'pedido:{pedido_id}:credito:{ciclo}'
--      * Ajuste Administrativo: 'ajuste:{auth.uid()}:{request_id}'
-- 3. Blindagem de Risco e DRE:
--    - saldo >= 0.00 com constraint de banco intransponível.
--    - Uso de crédito_cliente não lança receita operacional redundante no DRE (evita duplicar caixa).
--    - Cancelamento misto (C13): retorna exatamente o valor pago à carteira sem dupla restituição.
--    - Estorno de pedido pago parcialmente com crédito (C10): reverte a parcela à carteira
--      com movimentacao_origem_id preenchido.
-- 4. Segregação de Privilégios (RBAC Fail-Closed):
--    - Helper interno public.aplicar_movimento_credito_cliente: SEM grants para PUBLIC/anon/authenticated.
--    - RPC public.ajustar_credito_cliente_admin: estritamente admin (motivo >= 5 caracteres).
--    - RPC public.utilizar_credito_cliente_pedido: admin/operador atrelado a pedido existente.
--    - RPC public.consultar_saldo_credito: admin/operador.
-- ==========================================================================

-- --------------------------------------------------------------------------
-- 1. ESTRUTURA DE TABELAS DA CARTEIRA DE CRÉDITOS
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS public.cliente_creditos (
  cliente_id BIGINT PRIMARY KEY REFERENCES public.clientes(id) ON DELETE RESTRICT,
  saldo NUMERIC(10,2) NOT NULL DEFAULT 0.00 CHECK (saldo >= 0.00),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.cliente_credito_movimentacoes (
  id BIGSERIAL PRIMARY KEY,
  cliente_id BIGINT NOT NULL REFERENCES public.clientes(id) ON DELETE RESTRICT,
  tipo TEXT NOT NULL CHECK (tipo IN ('credito', 'debito')),
  origem TEXT NOT NULL CHECK (origem IN ('cancelamento_pedido', 'ajuste_manual_admin', 'uso_pedido', 'estorno_uso_pedido', 'expiracao_admin')),
  valor NUMERIC(10,2) NOT NULL CHECK (valor > 0.00),
  saldo_anterior NUMERIC(10,2) NOT NULL CHECK (saldo_anterior >= 0.00),
  saldo_posterior NUMERIC(10,2) NOT NULL CHECK (saldo_posterior >= 0.00),
  pedido_id BIGINT REFERENCES public.pedidos(id) ON DELETE SET NULL,
  movimentacao_origem_id BIGINT REFERENCES public.cliente_credito_movimentacoes(id) ON DELETE RESTRICT,
  motivo TEXT NOT NULL,
  idempotency_key TEXT NOT NULL,
  usuario_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  usuario_nome TEXT NOT NULL DEFAULT 'Sistema',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_cliente_credito_mov_idempotency
  ON public.cliente_credito_movimentacoes(idempotency_key);

CREATE INDEX IF NOT EXISTS idx_cliente_credito_mov_cliente_id
  ON public.cliente_credito_movimentacoes(cliente_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_cliente_credito_mov_pedido_id
  ON public.cliente_credito_movimentacoes(pedido_id)
  WHERE pedido_id IS NOT NULL;

-- --------------------------------------------------------------------------
-- 2. POLÍTICAS DE RLS E PROTEÇÃO CONTRA MUTAÇÃO NO LIVRO-RAZÃO
-- --------------------------------------------------------------------------

ALTER TABLE public.cliente_creditos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cliente_credito_movimentacoes ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.cliente_creditos FROM PUBLIC, anon;
REVOKE ALL ON public.cliente_credito_movimentacoes FROM PUBLIC, anon;

-- Imutabilidade do Livro-Razão: NENHUM UPDATE NEM DELETE sob nenhuma circunstância
REVOKE UPDATE, DELETE ON public.cliente_credito_movimentacoes FROM PUBLIC, anon, authenticated;

-- RLS: apenas equipe autorizada ou o próprio cliente (se vinculado por auth_user_id)
DROP POLICY IF EXISTS "Equipe visualiza saldo de creditos" ON public.cliente_creditos;
CREATE POLICY "Equipe visualiza saldo de creditos" ON public.cliente_creditos
  FOR SELECT USING (
    public.is_admin_or_operator() OR
    EXISTS (
      SELECT 1 FROM public.clientes c
      WHERE c.id = cliente_creditos.cliente_id
        AND c.auth_user_id IS NOT NULL
        AND c.auth_user_id = auth.uid()
    )
  );

DROP POLICY IF EXISTS "Equipe visualiza extrato de creditos" ON public.cliente_credito_movimentacoes;
CREATE POLICY "Equipe visualiza extrato de creditos" ON public.cliente_credito_movimentacoes
  FOR SELECT USING (
    public.is_admin_or_operator() OR
    EXISTS (
      SELECT 1 FROM public.clientes c
      WHERE c.id = cliente_credito_movimentacoes.cliente_id
        AND c.auth_user_id IS NOT NULL
        AND c.auth_user_id = auth.uid()
    )
  );

-- --------------------------------------------------------------------------
-- 3. EXTENSÃO DO MÉTODO DE PAGAMENTO EM PEDIDO_PAGAMENTOS
-- --------------------------------------------------------------------------
-- Substitui dinamicamente a check constraint para aceitar 'credito_cliente'

DO $$
DECLARE
  v_con_name TEXT;
BEGIN
  SELECT conname INTO v_con_name
  FROM pg_constraint c
  JOIN pg_class t ON t.oid = c.conrelid
  JOIN pg_namespace n ON n.oid = t.relnamespace
  WHERE n.nspname = 'public'
    AND t.relname = 'pedido_pagamentos'
    AND c.contype = 'c'
    AND pg_get_constraintdef(c.oid) LIKE '%metodo%ANY%';

  IF v_con_name IS NOT NULL THEN
    EXECUTE 'ALTER TABLE public.pedido_pagamentos DROP CONSTRAINT ' || quote_ident(v_con_name);
  END IF;

  -- Também busca por constraints que utilizam IN (...)
  SELECT conname INTO v_con_name
  FROM pg_constraint c
  JOIN pg_class t ON t.oid = c.conrelid
  JOIN pg_namespace n ON n.oid = t.relnamespace
  WHERE n.nspname = 'public'
    AND t.relname = 'pedido_pagamentos'
    AND c.contype = 'c'
    AND pg_get_constraintdef(c.oid) LIKE '%metodo%IN%';

  IF v_con_name IS NOT NULL THEN
    EXECUTE 'ALTER TABLE public.pedido_pagamentos DROP CONSTRAINT ' || quote_ident(v_con_name);
  END IF;

  ALTER TABLE public.pedido_pagamentos
    ADD CONSTRAINT chk_pedido_pagamentos_metodo
    CHECK (metodo IN ('pix', 'cartao', 'dinheiro', 'transferencia', 'outro', 'credito_cliente'));
END $$;

-- --------------------------------------------------------------------------
-- 4. HELPER INTERNO: APLICAR MOVIMENTO DE CRÉDITO DO CLIENTE (SERIALIZADO)
-- --------------------------------------------------------------------------
-- Sem GRANT para PUBLIC/anon/authenticated. Apenas SECURITY DEFINER interno.

CREATE OR REPLACE FUNCTION public.aplicar_movimento_credito_cliente(
  p_cliente_id BIGINT,
  p_tipo TEXT,
  p_origem TEXT,
  p_valor NUMERIC,
  p_motivo TEXT,
  p_idempotency_key TEXT,
  p_pedido_id BIGINT DEFAULT NULL,
  p_movimentacao_origem_id BIGINT DEFAULT NULL,
  p_usuario_id UUID DEFAULT NULL,
  p_usuario_nome TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_mov_existente RECORD;
  v_saldo_atual NUMERIC(10,2);
  v_saldo_novo NUMERIC(10,2);
  v_mov_id BIGINT;
  v_user_nome TEXT := COALESCE(NULLIF(TRIM(p_usuario_nome), ''), 'Sistema');
BEGIN
  IF p_cliente_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'CLIENT_ID_REQUIRED', 'error', 'ID do cliente é obrigatório.');
  END IF;

  IF p_tipo NOT IN ('credito', 'debito') THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_MOVEMENT_TYPE', 'error', 'Tipo de movimentação inválido. Use crédito ou débito.');
  END IF;

  IF p_valor IS NULL OR p_valor <= 0.00 THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_AMOUNT', 'error', 'Valor da movimentação deve ser maior que zero.');
  END IF;

  IF NULLIF(TRIM(p_idempotency_key), '') IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'IDEMPOTENCY_KEY_REQUIRED', 'error', 'Chave de idempotência é obrigatória.');
  END IF;

  -- 1. Idempotência por chave: se já foi executada, retorna sucesso sem reprocessar
  SELECT * INTO v_mov_existente
  FROM public.cliente_credito_movimentacoes
  WHERE idempotency_key = p_idempotency_key;

  IF FOUND THEN
    SELECT saldo INTO v_saldo_atual FROM public.cliente_creditos WHERE cliente_id = p_cliente_id;
    RETURN jsonb_build_object(
      'success', true,
      'idempotente', true,
      'movimentacao_id', v_mov_existente.id,
      'cliente_id', p_cliente_id,
      'tipo', v_mov_existente.tipo,
      'valor', v_mov_existente.valor,
      'saldo_anterior', v_mov_existente.saldo_anterior,
      'saldo_posterior', v_mov_existente.saldo_posterior,
      'saldo_atual', COALESCE(v_saldo_atual, v_mov_existente.saldo_posterior)
    );
  END IF;

  -- 2. LOCK ORDINAL ESTRITO: clientes -> cliente_creditos
  PERFORM 1 FROM public.clientes WHERE id = p_cliente_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'CLIENT_NOT_FOUND', 'error', 'Cliente não encontrado no CRM.');
  END IF;

  -- Garante registro de saldo para o cliente
  INSERT INTO public.cliente_creditos (cliente_id, saldo, created_at, updated_at)
  VALUES (p_cliente_id, 0.00, NOW(), NOW())
  ON CONFLICT (cliente_id) DO NOTHING;

  SELECT saldo INTO v_saldo_atual
  FROM public.cliente_creditos
  WHERE cliente_id = p_cliente_id
  FOR UPDATE;

  -- 3. Cálculo e guarda de saldo não negativo
  IF p_tipo = 'credito' THEN
    v_saldo_novo := v_saldo_atual + p_valor;
  ELSE
    IF v_saldo_atual < p_valor THEN
      RETURN jsonb_build_object(
        'success', false,
        'code', 'INSUFFICIENT_CREDIT_BALANCE',
        'error', 'Saldo de crédito insuficiente para débito.',
        'saldo_atual', v_saldo_atual,
        'valor_solicitado', p_valor
      );
    END IF;
    v_saldo_novo := v_saldo_atual - p_valor;
  END IF;

  -- 4. Atualiza saldo consolidado
  UPDATE public.cliente_creditos
  SET saldo = v_saldo_novo,
      updated_at = NOW()
  WHERE cliente_id = p_cliente_id;

  -- 5. Insere movimentação imutável no livro-razão
  INSERT INTO public.cliente_credito_movimentacoes (
    cliente_id, tipo, origem, valor,
    saldo_anterior, saldo_posterior,
    pedido_id, movimentacao_origem_id,
    motivo, idempotency_key,
    usuario_id, usuario_nome, created_at
  ) VALUES (
    p_cliente_id, p_tipo, p_origem, p_valor,
    v_saldo_atual, v_saldo_novo,
    p_pedido_id, p_movimentacao_origem_id,
    TRIM(p_motivo), p_idempotency_key,
    p_usuario_id, v_user_nome, NOW()
  ) RETURNING id INTO v_mov_id;

  RETURN jsonb_build_object(
    'success', true,
    'movimentacao_id', v_mov_id,
    'cliente_id', p_cliente_id,
    'tipo', p_tipo,
    'origem', p_origem,
    'valor', p_valor,
    'saldo_anterior', v_saldo_atual,
    'saldo_posterior', v_saldo_novo
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.aplicar_movimento_credito_cliente FROM PUBLIC, anon, authenticated;

-- --------------------------------------------------------------------------
-- 5. RPC ADMINISTRATIVA: AJUSTAR CRÉDITO DO CLIENTE (ADMIN-ONLY)
-- --------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.ajustar_credito_cliente_admin(
  p_cliente_id BIGINT,
  p_tipo TEXT,
  p_valor NUMERIC,
  p_motivo TEXT,
  p_request_id TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_is_admin BOOLEAN := public.is_admin();
  v_motivo TEXT := NULLIF(TRIM(COALESCE(p_motivo, '')), '');
  v_user_nome TEXT;
  v_idempotency_key TEXT;
  v_origem TEXT;
BEGIN
  IF NOT v_is_admin THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada. Apenas Administradores podem efetuar ajustes manuais de crédito.');
  END IF;

  IF p_cliente_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'CLIENT_ID_REQUIRED', 'error', 'ID do cliente é obrigatório.');
  END IF;

  IF p_tipo NOT IN ('credito', 'debito') THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_OPERATION_TYPE', 'error', 'Tipo de operação inválido. Use crédito ou débito.');
  END IF;

  IF p_valor IS NULL OR p_valor <= 0.00 THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_AMOUNT', 'error', 'Valor do ajuste deve ser maior que zero.');
  END IF;

  IF v_motivo IS NULL OR length(v_motivo) < 5 THEN
    RETURN jsonb_build_object('success', false, 'code', 'REASON_REQUIRED', 'error', 'Motivo explicativo obrigatório (mínimo de 5 caracteres).');
  END IF;

  SELECT nome INTO v_user_nome FROM public.profiles WHERE id = auth.uid();
  IF v_user_nome IS NULL THEN
    v_user_nome := CASE WHEN auth.role() = 'service_role' THEN 'Sistema / service_role' ELSE 'Administrador' END;
  END IF;

  v_idempotency_key := 'ajuste:' || COALESCE(auth.uid()::TEXT, 'sys') || ':' || COALESCE(NULLIF(TRIM(p_request_id), ''), encode(digest(p_cliente_id::TEXT || p_tipo || p_valor::TEXT || v_motivo, 'sha256'), 'hex'));
  v_origem := CASE WHEN p_tipo = 'credito' THEN 'ajuste_manual_admin' ELSE 'expiracao_admin' END;

  RETURN public.aplicar_movimento_credito_cliente(
    p_cliente_id := p_cliente_id,
    p_tipo := p_tipo,
    p_origem := v_origem,
    p_valor := p_valor,
    p_motivo := v_motivo,
    p_idempotency_key := v_idempotency_key,
    p_usuario_id := auth.uid(),
    p_usuario_nome := v_user_nome
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.ajustar_credito_cliente_admin FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.ajustar_credito_cliente_admin TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 6. RPC OPERACIONAL: UTILIZAR CRÉDITO EM PEDIDO (EQUIPE)
-- --------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.utilizar_credito_cliente_pedido(
  p_pedido_id BIGINT,
  p_valor NUMERIC
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_ped RECORD;
  v_cliente_id BIGINT;
  v_user_nome TEXT;
  v_idempotency_key TEXT;
  v_mov_res JSONB;
  v_pag_id BIGINT;
  v_ciclo_uso INT;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada. Apenas administradores ou operadores podem aplicar crédito em pedidos.');
  END IF;

  IF p_pedido_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_ID_REQUIRED', 'error', 'ID do pedido obrigatório.');
  END IF;

  IF p_valor IS NULL OR p_valor <= 0.00 THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_AMOUNT', 'error', 'Valor de crédito a utilizar deve ser maior que zero.');
  END IF;

  -- 1. Trava o pedido
  SELECT * INTO v_ped FROM public.pedidos WHERE id = p_pedido_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_NOT_FOUND', 'error', 'Pedido não encontrado.');
  END IF;

  IF v_ped.status_comercial = 'cancelado' THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_CANCELLED', 'error', 'Não é possível utilizar crédito em pedido cancelado.');
  END IF;

  IF v_ped.saldo <= 0.00 THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_ALREADY_PAID', 'error', 'Pedido já está integralmente quitado.');
  END IF;

  IF p_valor > v_ped.saldo THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'AMOUNT_EXCEEDS_BALANCE',
      'error', 'Valor informado (R$ ' || p_valor || ') é maior que o saldo em aberto do pedido (R$ ' || v_ped.saldo || ').',
      'saldo_pedido', v_ped.saldo
    );
  END IF;

  -- 2. Identifica o cliente canônico
  v_cliente_id := v_ped.cliente_id_rel;
  IF v_cliente_id IS NULL THEN
    -- Fallback: resolve ou cria cliente por telefone ou email
    IF v_ped.telefone_cliente IS NOT NULL AND length(v_ped.telefone_cliente) >= 8 THEN
      SELECT id INTO v_cliente_id FROM public.clientes
      WHERE telefone_normalizado = regexp_replace(v_ped.telefone_cliente, '\D', '', 'g')
      LIMIT 1;
    END IF;

    IF v_cliente_id IS NULL THEN
      INSERT INTO public.clientes (nome, telefone, email)
      VALUES (v_ped.nome_cliente, v_ped.telefone_cliente, v_ped.email_cliente)
      RETURNING id INTO v_cliente_id;
    END IF;

    UPDATE public.pedidos SET cliente_id_rel = v_cliente_id WHERE id = p_pedido_id;
  END IF;

  -- 3. Determina o ciclo de uso para chave idempotente
  SELECT COALESCE(COUNT(*), 0) + 1 INTO v_ciclo_uso
  FROM public.pedido_pagamentos
  WHERE pedido_id = p_pedido_id AND metodo = 'credito_cliente';

  v_idempotency_key := 'pedido:' || p_pedido_id || ':credito:' || v_ciclo_uso;

  SELECT nome INTO v_user_nome FROM public.profiles WHERE id = auth.uid();
  IF v_user_nome IS NULL THEN
    v_user_nome := CASE WHEN auth.role() = 'service_role' THEN 'Sistema / service_role' ELSE 'Equipe' END;
  END IF;

  -- 4. Debita da carteira via helper atômico
  v_mov_res := public.aplicar_movimento_credito_cliente(
    p_cliente_id := v_cliente_id,
    p_tipo := 'debito',
    p_origem := 'uso_pedido',
    p_valor := p_valor,
    p_motivo := 'Utilização de crédito no pedido #' || p_pedido_id,
    p_idempotency_key := v_idempotency_key,
    p_pedido_id := p_pedido_id,
    p_usuario_id := auth.uid(),
    p_usuario_nome := v_user_nome
  );

  IF NOT (v_mov_res->>'success')::BOOLEAN THEN
    RETURN v_mov_res;
  END IF;

  -- 5. Registra o pagamento no pedido (o trigger recalcular_financeiro_pedido atualizará valor_pago e saldo)
  INSERT INTO public.pedido_pagamentos (
    pedido_id, valor, metodo, provider, provider_payment_id,
    status, pago_em, registrado_por, observacoes
  ) VALUES (
    p_pedido_id, p_valor, 'credito_cliente', 'caixa', 'credito_mov:' || (v_mov_res->>'movimentacao_id'),
    'aprovado', NOW(), auth.uid(), 'Liquidação via saldo da carteira do cliente'
  ) RETURNING id INTO v_pag_id;

  RETURN jsonb_build_object(
    'success', true,
    'pedido_id', p_pedido_id,
    'cliente_id', v_cliente_id,
    'pagamento_id', v_pag_id,
    'valor_utilizado', p_valor,
    'saldo_credito_restante', (v_mov_res->>'saldo_posterior')::NUMERIC,
    'movimentacao_id', (v_mov_res->>'movimentacao_id')::BIGINT
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.utilizar_credito_cliente_pedido FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.utilizar_credito_cliente_pedido TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 7. RPC DE CONSULTA: SALDO E EXTRATO DE CRÉDITO DO CLIENTE
-- --------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.consultar_saldo_credito(
  p_cliente_id BIGINT
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_saldo NUMERIC(10,2);
  v_extrato JSONB;
BEGIN
  IF NOT v_is_equipe THEN
    -- Permite cliente autenticado consultar apenas o próprio saldo
    IF NOT EXISTS (
      SELECT 1 FROM public.clientes c
      WHERE c.id = p_cliente_id
        AND c.auth_user_id IS NOT NULL
        AND c.auth_user_id = auth.uid()
    ) THEN
      RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada para consultar saldo deste cliente.');
    END IF;
  END IF;

  IF p_cliente_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'CLIENT_ID_REQUIRED', 'error', 'ID do cliente é obrigatório.');
  END IF;

  SELECT COALESCE(saldo, 0.00) INTO v_saldo
  FROM public.cliente_creditos
  WHERE cliente_id = p_cliente_id;

  v_saldo := COALESCE(v_saldo, 0.00);

  SELECT COALESCE(jsonb_agg(m ORDER BY m.created_at DESC), '[]'::jsonb) INTO v_extrato
  FROM (
    SELECT id, tipo, origem, valor, saldo_anterior, saldo_posterior,
           pedido_id, motivo, created_at, usuario_nome
    FROM public.cliente_credito_movimentacoes
    WHERE cliente_id = p_cliente_id
    ORDER BY created_at DESC
    LIMIT 20
  ) m;

  RETURN jsonb_build_object(
    'success', true,
    'cliente_id', p_cliente_id,
    'saldo', v_saldo,
    'extrato', v_extrato
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.consultar_saldo_credito FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.consultar_saldo_credito TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 8. ATUALIZAÇÃO CANÔNICA DE CANCELAR_PEDIDO_EQUIPE (FRENTE C)
-- --------------------------------------------------------------------------
-- Incorpora 'CREDITO_CLIENTE' e 'ESTORNO' com cancelamento misto auditado e atômico.

CREATE OR REPLACE FUNCTION public.cancelar_pedido_equipe(
  p_pedido_id BIGINT,
  p_motivo TEXT DEFAULT NULL,
  p_destino_valor TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_ped RECORD;
  v_is_admin BOOLEAN := public.is_admin();
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_motivo TEXT := NULLIF(TRIM(COALESCE(p_motivo, '')), '');
  v_user_nome TEXT;
  v_cliente_id BIGINT;
  v_idempotency_key TEXT;
  v_mov_res JSONB;
  v_pago_credito NUMERIC(10,2) := 0.00;
  v_pago_externo NUMERIC(10,2) := 0.00;
  v_total_pago NUMERIC(10,2) := 0.00;
  v_pag RECORD;
  v_mov_origem_id BIGINT;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada. Apenas administradores ou operadores podem cancelar pedidos.');
  END IF;

  IF p_pedido_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_ID_REQUIRED', 'error', 'ID do pedido obrigatório.');
  END IF;

  SELECT * INTO v_ped FROM public.pedidos WHERE id = p_pedido_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_NOT_FOUND', 'error', 'Pedido não encontrado.');
  END IF;

  -- 1. Idempotência: se já cancelado comercial e operacionalmente
  IF v_ped.status_comercial = 'cancelado' AND v_ped.status_operacional = 'cancelado' THEN
    RETURN jsonb_build_object(
      'success', true,
      'idempotente', true,
      'pedido_id', p_pedido_id,
      'status_comercial', 'cancelado',
      'status_operacional', 'cancelado'
    );
  END IF;

  -- 2. Guarda de Produção Ativa: se já em preparo/pronto/entrega, operador é bloqueado
  IF v_ped.status_operacional NOT IN ('aguardando_producao', 'cancelado') AND NOT v_is_admin THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PRODUCTION_ACTIVE_CANCEL_DENIED',
      'error', 'Pedidos com produção já iniciada ("' || v_ped.status_operacional || '") só podem ser cancelados por Administradores.'
    );
  END IF;

  -- 3. Apuração precisa dos pagamentos aprovados existentes
  SELECT COALESCE(SUM(valor), 0.00) INTO v_pago_credito
  FROM public.pedido_pagamentos
  WHERE pedido_id = p_pedido_id AND status = 'aprovado' AND metodo = 'credito_cliente';

  SELECT COALESCE(SUM(valor), 0.00) INTO v_pago_externo
  FROM public.pedido_pagamentos
  WHERE pedido_id = p_pedido_id AND status = 'aprovado' AND metodo <> 'credito_cliente';

  v_total_pago := v_pago_credito + v_pago_externo;

  -- 4. Guarda de Destino Financeiro
  IF GREATEST(v_total_pago, COALESCE(v_ped.valor_pago, 0.00)) > 0.00 AND NOT v_is_admin THEN
    IF COALESCE(p_destino_valor, '') NOT IN ('RETENCAO_CANCELAMENTO', 'CREDITO_CLIENTE', 'ESTORNO') 
       AND v_ped.status_financeiro <> 'estornado' THEN
      RETURN jsonb_build_object(
        'success', false,
        'code', 'CANCELLATION_REQUIRES_VALUE_DESTINATION',
        'error', 'Pedido com pagamentos ativos requer estorno prévio ou definição explícita de destino (RETENCAO_CANCELAMENTO, CREDITO_CLIENTE ou ESTORNO).'
      );
    END IF;
  END IF;

  SELECT nome INTO v_user_nome FROM public.profiles WHERE id = auth.uid();
  IF v_user_nome IS NULL THEN
    v_user_nome := CASE WHEN auth.role() = 'service_role' THEN 'Sistema / service_role' ELSE 'Equipe' END;
  END IF;

  -- 5. Resolução/Garantia do cliente canônico se houver movimentação de crédito
  v_cliente_id := v_ped.cliente_id_rel;
  IF (v_total_pago > 0.00 OR v_pago_credito > 0.00) AND v_cliente_id IS NULL THEN
    IF v_ped.telefone_cliente IS NOT NULL AND length(v_ped.telefone_cliente) >= 8 THEN
      SELECT id INTO v_cliente_id FROM public.clientes
      WHERE telefone_normalizado = regexp_replace(v_ped.telefone_cliente, '\D', '', 'g')
      LIMIT 1;
    END IF;

    IF v_cliente_id IS NULL THEN
      INSERT INTO public.clientes (nome, telefone, email)
      VALUES (v_ped.nome_cliente, v_ped.telefone_cliente, v_ped.email_cliente)
      RETURNING id INTO v_cliente_id;
    END IF;

    UPDATE public.pedidos SET cliente_id_rel = v_cliente_id WHERE id = p_pedido_id;
  END IF;

  -- 6. Execução do Destino Financeiro
  IF p_destino_valor = 'CREDITO_CLIENTE' AND v_total_pago > 0.00 THEN
    -- C1 & C13: Todo o valor pago (crédito + externo) é transformado em crédito para a carteira
    v_idempotency_key := 'cancelamento:' || p_pedido_id || ':credito_cliente';
    
    v_mov_res := public.aplicar_movimento_credito_cliente(
      p_cliente_id := v_cliente_id,
      p_tipo := 'credito',
      p_origem := 'cancelamento_pedido',
      p_valor := v_total_pago,
      p_motivo := 'Crédito integral decorrente do cancelamento do pedido #' || p_pedido_id,
      p_idempotency_key := v_idempotency_key,
      p_pedido_id := p_pedido_id,
      p_usuario_id := auth.uid(),
      p_usuario_nome := v_user_nome
    );

    IF NOT (v_mov_res->>'success')::BOOLEAN THEN
      RETURN v_mov_res;
    END IF;

    -- Marca os pagamentos como estornados para atualizar o status financeiro do pedido
    UPDATE public.pedido_pagamentos
    SET status = 'estornado'
    WHERE pedido_id = p_pedido_id AND status = 'aprovado';

  ELSIF p_destino_valor = 'ESTORNO' THEN
    -- C10: Se houve pagamento em crédito, reverte a parcela à carteira; a parcela externa é estornada
    IF v_pago_credito > 0.00 THEN
      -- Localiza a movimentação original de débito para vinculação
      SELECT id INTO v_mov_origem_id
      FROM public.cliente_credito_movimentacoes
      WHERE pedido_id = p_pedido_id AND tipo = 'debito' AND origem = 'uso_pedido'
      ORDER BY id DESC LIMIT 1;

      v_idempotency_key := 'cancelamento:' || p_pedido_id || ':estorno_credito';
      
      v_mov_res := public.aplicar_movimento_credito_cliente(
        p_cliente_id := v_cliente_id,
        p_tipo := 'credito',
        p_origem := 'estorno_uso_pedido',
        p_valor := v_pago_credito,
        p_motivo := 'Estorno de crédito decorrente de cancelamento do pedido #' || p_pedido_id,
        p_idempotency_key := v_idempotency_key,
        p_pedido_id := p_pedido_id,
        p_movimentacao_origem_id := v_mov_origem_id,
        p_usuario_id := auth.uid(),
        p_usuario_nome := v_user_nome
      );

      IF NOT (v_mov_res->>'success')::BOOLEAN THEN
        RETURN v_mov_res;
      END IF;
    END IF;

    -- Atualiza todos os pagamentos aprovados para estornado
    UPDATE public.pedido_pagamentos
    SET status = 'estornado'
    WHERE pedido_id = p_pedido_id AND status = 'aprovado';

  ELSIF p_destino_valor = 'RETENCAO_CANCELAMENTO' THEN
    -- Valor é retido pela loja; não estorna pagamento e não devolve à carteira
    NULL;
  END IF;

  -- 7. Atualiza o pedido. O trigger trg_liberar_reserva_ao_cancelar liberará estoque e capacidade
  UPDATE public.pedidos
  SET 
    status_comercial = 'cancelado',
    status_operacional = 'cancelado',
    updated_at = NOW()
  WHERE id = p_pedido_id;

  -- 8. Registra no histórico auditável
  INSERT INTO public.pedido_status_historico (
    pedido_id, dimensao, status_anterior, status_novo, usuario_id, usuario_nome, origem, metadata
  ) VALUES (
    p_pedido_id,
    'comercial',
    v_ped.status_comercial,
    'cancelado',
    auth.uid(),
    v_user_nome,
    'admin',
    jsonb_build_object(
      'motivo', COALESCE(v_motivo, 'Cancelamento via porta dedicada cancelar_pedido_equipe'),
      'porta_dominio', 'cancelar_pedido_equipe',
      'destino_valor', p_destino_valor,
      'valor_pago_total', v_total_pago,
      'valor_credito_devolvido', CASE WHEN p_destino_valor = 'CREDITO_CLIENTE' THEN v_total_pago WHEN p_destino_valor = 'ESTORNO' THEN v_pago_credito ELSE 0.00 END,
      'status_operacional_anterior', v_ped.status_operacional
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'pedido_id', p_pedido_id,
    'status_comercial', 'cancelado',
    'status_operacional', 'cancelado',
    'destino_valor', p_destino_valor,
    'reservas_liberadas', true
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.cancelar_pedido_equipe FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.cancelar_pedido_equipe TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 9. ATUALIZAÇÃO DO TRIGGER RECALCULAR_FINANCEIRO_PEDIDO (BLINDAGEM DRE)
-- --------------------------------------------------------------------------
-- Ao estornar pagamentos com metodo = 'credito_cliente', NÃO gera despesa
-- contábil de estorno no DRE (preserva caixa real).

CREATE OR REPLACE FUNCTION public.recalcular_financeiro_pedido()
RETURNS TRIGGER AS $$
DECLARE
  v_cfg public.configuracoes_operacao := public.obter_config_operacao();
  v_ped_id BIGINT := COALESCE(NEW.pedido_id, OLD.pedido_id);
  v_ped RECORD;
  v_pago NUMERIC(10,2);
  v_saldo NUMERIC(10,2);
  v_novo_status_fin TEXT;
  v_novo_status_com TEXT;
  v_tem_estorno BOOLEAN := false;
  v_hold_expirado BOOLEAN := false;
  v_novo_expires_at TIMESTAMPTZ;
  v_limite_hold TIMESTAMPTZ;
  v_requer_revisao BOOLEAN;
  v_bloqueado_tardio BOOLEAN;
  v_motivo_revisao TEXT;
  v_motivo_com TEXT := NULL;
  v_cap public.capacidade_producao;
  v_pts_pedido NUMERIC(8,2);
  v_pts_ocupados NUMERIC(8,2);
  v_cap_ok BOOLEAN := true;
  v_reserva JSON;
  v_estoque_ok BOOLEAN := true;
BEGIN
  -- 1. LOCK DO PEDIDO (primeiro recurso da ordem global)
  SELECT id, total, sinal_minimo, status_comercial, status_operacional, status_financeiro,
         confirmacao_expires_at, requer_revisao_financeira, bloqueado_por_overbooking_tardio, data_entrega, hora_entrega
  INTO v_ped
  FROM public.pedidos
  WHERE id = v_ped_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  v_novo_expires_at := v_ped.confirmacao_expires_at;
  v_requer_revisao := v_ped.requer_revisao_financeira;
  v_bloqueado_tardio := v_ped.bloqueado_por_overbooking_tardio;
  v_motivo_revisao := NULL;

  -- 2. Soma estritamente pagamentos aprovados
  SELECT COALESCE(SUM(valor), 0) INTO v_pago
  FROM public.pedido_pagamentos
  WHERE pedido_id = v_ped_id AND status = 'aprovado';

  v_saldo := GREATEST(0, COALESCE(v_ped.total, 0) - v_pago);

  SELECT EXISTS (SELECT 1 FROM public.pedido_pagamentos WHERE pedido_id = v_ped_id AND status = 'estornado') INTO v_tem_estorno;

  IF v_tem_estorno AND v_pago <= 0 THEN
    v_novo_status_fin := 'estornado';
  ELSIF v_pago <= 0 THEN
    v_novo_status_fin := 'nao_pago';
  ELSIF v_saldo <= 0 THEN
    v_novo_status_fin := 'pago';
  ELSE
    v_novo_status_fin := 'parcialmente_pago';
  END IF;

  v_novo_status_com := v_ped.status_comercial;

  -- 3. Regra 1: Confirmação por sinal (com revalidação dupla se o hold já expirou)
  IF v_ped.sinal_minimo > 0 AND v_pago >= v_ped.sinal_minimo AND v_ped.status_comercial = 'aguardando_confirmacao' THEN
    v_hold_expirado := (v_ped.confirmacao_expires_at IS NOT NULL AND v_ped.confirmacao_expires_at <= NOW()) OR v_ped.requer_revisao_financeira;

    IF NOT v_hold_expirado THEN
      v_novo_status_com := 'confirmado';
      v_novo_expires_at := NULL;
      v_requer_revisao := false;
      v_bloqueado_tardio := false;
      v_motivo_com := 'Sinal mínimo atingido por pagamento acumulado dentro do prazo de confirmação';
    ELSE
      v_cap := public.travar_capacidade_data(v_ped.data_entrega);
      v_pts_pedido := public.pontos_pedido(v_ped_id);
      v_pts_ocupados := public.pontos_ocupados_data(v_ped.data_entrega, v_ped_id);
      v_cap_ok := NOT (v_cap.bloqueado = true OR (v_pts_ocupados + v_pts_pedido) > v_cap.capacidade_maxima_pontos);

      IF v_cap_ok THEN
        v_reserva := public.reservar_estoque_itens_pedido(v_ped_id, 'Reserva recriada após pagamento tardio do pedido #' || v_ped_id, true);
        v_estoque_ok := COALESCE((v_reserva->>'success')::BOOLEAN, false);
      ELSE
        v_reserva := NULL;
        SELECT NOT EXISTS (
          SELECT 1
          FROM public.pedido_itens pi
          JOIN public.produtos pr ON pr.id = pi.produto_id
          WHERE pi.pedido_id = v_ped_id
            AND pr.controlar_estoque IS NOT FALSE
            AND pi.reserva_estoque_ativa = false
            AND (COALESCE(pr.estoque_fisico, 0) - COALESCE(pr.estoque_reservado, 0)) < pi.quantidade
        ) INTO v_estoque_ok;
      END IF;

      IF v_cap_ok AND v_estoque_ok THEN
        v_novo_status_com := 'confirmado';
        v_novo_expires_at := NULL;
        v_requer_revisao := false;
        v_bloqueado_tardio := false;
        v_motivo_com := 'Pagamento tardio aceito após revalidação atômica com sucesso de capacidade e estoque';
      ELSE
        v_novo_status_com := 'aguardando_confirmacao';
        v_requer_revisao := true;
        v_bloqueado_tardio := true;
        v_motivo_revisao := 'Pagamento tardio recebido após expiração do hold, porém '
          || CASE
               WHEN NOT v_cap_ok AND NOT v_estoque_ok THEN 'a capacidade de produção e o estoque'
               WHEN NOT v_cap_ok THEN 'a capacidade de produção'
               ELSE 'o estoque'
             END
          || ' já não comportam esta encomenda. Requer decisão administrativa.';
        v_motivo_com := v_motivo_revisao;
      END IF;
    END IF;
  END IF;

  -- 4. Regra 2: Guarda de produção em caso de estorno do sinal (+ renovação do hold)
  IF v_ped.sinal_minimo > 0 AND v_pago < v_ped.sinal_minimo THEN
    IF v_ped.status_operacional = 'aguardando_producao' AND v_ped.status_comercial = 'confirmado' THEN
      v_novo_status_com := 'aguardando_confirmacao';
      v_limite_hold := (((v_ped.data_entrega + COALESCE(v_ped.hora_entrega, TIME '12:00:00'))::TIMESTAMP) AT TIME ZONE v_cfg.timezone)
                       - make_interval(hours => v_cfg.antecedencia_confirmacao_horas);
      v_novo_expires_at := LEAST(NOW() + make_interval(hours => v_cfg.hold_horas_padrao), v_limite_hold);
      IF v_novo_expires_at <= NOW() THEN
        v_novo_expires_at := NOW();
        v_requer_revisao := true;
        v_motivo_revisao := 'Estorno de sinal reduziu o valor pago abaixo do mínimo e a entrega está dentro da antecedência mínima; sem prazo de hold viável. Requer decisão administrativa.';
        v_motivo_com := v_motivo_revisao;
        PERFORM public.liberar_estoque_itens_pedido(v_ped_id, 'Liberação de reserva: estorno sem hold viável no pedido #' || v_ped_id);
      ELSE
        v_motivo_com := 'Estorno de sinal reduziu valor pago abaixo do mínimo antes do início da produção; hold renovado até ' || to_char(v_novo_expires_at AT TIME ZONE v_cfg.timezone, 'DD/MM HH24:MI');
      END IF;
    ELSE
      v_novo_status_com := v_ped.status_comercial;
    END IF;
  END IF;

  UPDATE public.pedidos
  SET valor_pago = v_pago,
      saldo = v_saldo,
      status_financeiro = v_novo_status_fin,
      status_comercial = v_novo_status_com,
      possui_estorno = v_tem_estorno,
      confirmacao_expires_at = v_novo_expires_at,
      requer_revisao_financeira = v_requer_revisao,
      bloqueado_por_overbooking_tardio = v_bloqueado_tardio,
      motivo_revisao_financeira = CASE WHEN v_requer_revisao THEN COALESCE(v_motivo_revisao, motivo_revisao_financeira) ELSE NULL END,
      updated_at = NOW()
  WHERE id = v_ped_id;

  -- 5. Lançamento compensatório no DRE ao estornar pagamento aprovado (apenas para métodos externos de caixa)
  IF TG_OP = 'UPDATE' AND OLD.status = 'aprovado' AND NEW.status = 'estornado' THEN
    IF NEW.metodo <> 'credito_cliente' THEN
      INSERT INTO public.financeiro_lancamentos (
        tipo, categoria, descricao, valor, data_lancamento, forma_pagamento, pedido_id, origem_tipo, origem_id, evento, observacoes
      ) VALUES (
        'despesa', 'Estornos',
        'Estorno de Pagamento #' || NEW.id || ' do Pedido #' || v_ped_id || ' (' || upper(NEW.metodo) || ')',
        NEW.valor, (NOW() AT TIME ZONE v_cfg.timezone)::DATE, NEW.metodo, v_ped_id,
        'pedido_pagamento', NEW.id, 'estorno',
        'Estorno financeiro contábil automático via pedido_pagamentos #' || NEW.id
      )
      ON CONFLICT (origem_tipo, origem_id, evento) WHERE origem_id IS NOT NULL AND evento IS NOT NULL DO NOTHING;
    END IF;
  END IF;

  -- 6. Auditoria financeira
  IF v_ped.status_financeiro IS DISTINCT FROM v_novo_status_fin THEN
    INSERT INTO public.pedido_status_historico (pedido_id, dimensao, status_anterior, status_novo, usuario_id, usuario_nome, origem, metadata)
    VALUES (
      v_ped_id, 'financeiro', COALESCE(v_ped.status_financeiro, 'nao_pago'), v_novo_status_fin, auth.uid(), 'Sistema / Trigger Financeiro',
      CASE WHEN auth.role() = 'service_role' THEN 'sistema' WHEN public.is_admin_or_operator() THEN 'admin' ELSE 'sistema' END,
      jsonb_build_object('motivo', 'Recálculo automático via pedido_pagamentos', 'valor_pago', v_pago, 'saldo', v_saldo, 'tem_estorno', v_tem_estorno)
    );
  END IF;

  -- 7. Auditoria comercial
  IF v_ped.status_comercial IS DISTINCT FROM v_novo_status_com
     OR (v_bloqueado_tardio AND NOT v_ped.bloqueado_por_overbooking_tardio) THEN
    INSERT INTO public.pedido_status_historico (pedido_id, dimensao, status_anterior, status_novo, usuario_id, usuario_nome, origem, metadata)
    VALUES (
      v_ped_id, 'comercial', v_ped.status_comercial, v_novo_status_com, auth.uid(), 'Sistema / Gatilho de Sinal', 'sistema',
      jsonb_build_object(
        'motivo', v_motivo_com,
        'valor_pago', v_pago,
        'sinal_minimo', v_ped.sinal_minimo,
        'hold_expirado', v_hold_expirado,
        'capacidade_ok', v_cap_ok,
        'estoque_ok', v_estoque_ok,
        'reserva', v_reserva,
        'requer_revisao_financeira', v_requer_revisao,
        'bloqueado_por_overbooking_tardio', v_bloqueado_tardio
      )
    );
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;


-- ==========================================================================
-- >>> MIGRATION 019_crm_cliente_visao_360.sql
-- ==========================================================================

-- ==========================================================================
-- LUNOCA DOCERIA - MIGRATION 019: FRENTE D - CRM & HISTÓRICO 360° DO CLIENTE
-- ==========================================================================
-- Diretrizes Centrais e Regras de Negócio:
-- 1. Camada de Projeção Pura: Não duplica nem cria fonte concorrente de verdade
--    para pedidos, orçamentos, crédito, pagamentos ou comunicações.
-- 2. Não inflar LTV / Caixa: 'valor_recebido_caixa' apura estritamente pagamentos
--    externos líquidos de estornos, excluindo 'credito_cliente' para evitar duplicar caixa.
-- 3. Métricas Derivadas On-Demand: LTV de pedidos considera exclusivamente 'concluido';
--    ticket médio = SUM(total concluído) / COUNT(concluído).
-- 4. Estruturas Próprias de Relacionamento:
--    - cliente_notas (observações internas sem DELETE físico, com arquivamento auditável).
--    - cliente_tags (tags operacionais unívocas por cliente).
--    - cliente_preferencias (sabor, decoração, restrição alimentar declarada).
-- 5. Timeline 360° Unificada: Construída dinamicamente via UNION ALL, sanitizada,
--    sem expor tokens públicos, segredos de provider ou hashes confidenciais.
-- 6. Isolamento e LGPD:
--    - obter_cliente_360_admin (restrito a admin/operador, CPF mascarado para operador).
--    - obter_meu_perfil_360 (visão privada do cliente via auth.uid(), fail-closed sem notas/tags internas).
--    - buscar_clientes_crm (busca rápida por nome, telefone normalizado ou email).
-- ==========================================================================

-- --------------------------------------------------------------------------
-- 1. ESTRUTURAS PRÓPRIAS DE RELACIONAMENTO (CRM)
-- --------------------------------------------------------------------------

-- 1.1 Notas Internas Auditáveis
CREATE TABLE IF NOT EXISTS public.cliente_notas (
  id BIGSERIAL PRIMARY KEY,
  cliente_id BIGINT NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE,
  nota TEXT NOT NULL,
  categoria TEXT NOT NULL DEFAULT 'atendimento' CHECK (categoria IN ('atendimento', 'preferencia', 'comercial', 'pos_venda', 'outro')),
  criado_por UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  criado_em TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  arquivada BOOLEAN NOT NULL DEFAULT false,
  arquivada_por UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  arquivada_em TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_cliente_notas_cliente_id_ativo 
  ON public.cliente_notas(cliente_id, criado_em DESC)
  WHERE arquivada = false;

-- 1.2 Tags Operacionais do Cliente
CREATE TABLE IF NOT EXISTS public.cliente_tags (
  id BIGSERIAL PRIMARY KEY,
  cliente_id BIGINT NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE,
  tag TEXT NOT NULL,
  criado_por UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_cliente_tags_cliente_tag UNIQUE (cliente_id, tag)
);

CREATE INDEX IF NOT EXISTS idx_cliente_tags_cliente_id 
  ON public.cliente_tags(cliente_id);

CREATE INDEX IF NOT EXISTS idx_cliente_tags_tag 
  ON public.cliente_tags(LOWER(tag));

-- 1.3 Preferências e Restrições Declaradas
CREATE TABLE IF NOT EXISTS public.cliente_preferencias (
  id BIGSERIAL PRIMARY KEY,
  cliente_id BIGINT NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE,
  categoria TEXT NOT NULL CHECK (categoria IN ('sabor', 'decoracao', 'ocasiao', 'atendimento', 'restricao_alimentar', 'outro')),
  valor TEXT NOT NULL,
  observacao TEXT,
  ativo BOOLEAN NOT NULL DEFAULT true,
  criado_por UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_cliente_preferencias_cliente_id_ativo 
  ON public.cliente_preferencias(cliente_id, categoria)
  WHERE ativo = true;

-- --------------------------------------------------------------------------
-- 2. RLS E RESTRIÇÕES DE SEGURANÇA NAS TABELAS DO CRM
-- --------------------------------------------------------------------------

ALTER TABLE public.cliente_notas ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cliente_tags ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cliente_preferencias ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.cliente_notas FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.cliente_tags FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.cliente_preferencias FROM PUBLIC, anon, authenticated;

-- Somente leitura via RLS para equipe autorizada
DROP POLICY IF EXISTS "Equipe visualiza notas crm" ON public.cliente_notas;
CREATE POLICY "Equipe visualiza notas crm" ON public.cliente_notas
  FOR SELECT USING (public.is_admin_or_operator());

DROP POLICY IF EXISTS "Equipe visualiza tags crm" ON public.cliente_tags;
CREATE POLICY "Equipe visualiza tags crm" ON public.cliente_tags
  FOR SELECT USING (public.is_admin_or_operator());

DROP POLICY IF EXISTS "Equipe visualiza preferencias crm" ON public.cliente_preferencias;
CREATE POLICY "Equipe visualiza preferencias crm" ON public.cliente_preferencias
  FOR SELECT USING (public.is_admin_or_operator());

-- Bloqueio total de DELETE direto para clientes, operadores e authenticated
-- Mutações devem ocorrer exclusivamente via RPCs auditáveis.
REVOKE DELETE ON public.cliente_notas FROM PUBLIC, anon, authenticated;
REVOKE DELETE ON public.cliente_tags FROM PUBLIC, anon, authenticated;
REVOKE DELETE ON public.cliente_preferencias FROM PUBLIC, anon, authenticated;

-- --------------------------------------------------------------------------
-- 3. ÍNDICES ADICIONAIS DE PERFORMANCE PARA PROJEÇÃO CRM
-- --------------------------------------------------------------------------

CREATE INDEX IF NOT EXISTS idx_pedidos_cliente_id_rel_status_com 
  ON public.pedidos(cliente_id_rel, status_comercial);

CREATE INDEX IF NOT EXISTS idx_orcamentos_cliente_id_status 
  ON public.orcamentos(cliente_id, status);

CREATE INDEX IF NOT EXISTS idx_pedido_pagamentos_pedido_metodo_status 
  ON public.pedido_pagamentos(pedido_id, metodo, status);

-- --------------------------------------------------------------------------
-- 4. RPC DE BUSCA RÁPIDA CRM (AUTOCOMPLETE & LISTAGEM LEVE)
-- --------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.buscar_clientes_crm(
  p_termo TEXT,
  p_limite INTEGER DEFAULT 20
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_limite INTEGER := LEAST(GREATEST(COALESCE(p_limite, 20), 1), 50);
  v_termo_norm TEXT;
  v_termo_digitos TEXT;
  v_resultados JSONB;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada. Apenas equipe autorizada pode buscar no CRM.');
  END IF;

  v_termo_norm := NULLIF(TRIM(COALESCE(p_termo, '')), '');
  IF v_termo_norm IS NULL THEN
    RETURN jsonb_build_object('success', true, 'clientes', '[]'::jsonb);
  END IF;

  v_termo_digitos := regexp_replace(v_termo_norm, '\D', '', 'g');

  SELECT COALESCE(jsonb_agg(c_row), '[]'::jsonb) INTO v_resultados
  FROM (
    SELECT 
      c.id,
      c.nome,
      c.telefone,
      c.telefone_normalizado,
      c.email,
      COALESCE(cc.saldo, 0.00) AS credito_disponivel,
      (
        SELECT COUNT(*)
        FROM public.pedidos p
        WHERE p.cliente_id_rel = c.id AND p.status_comercial = 'concluido'
      ) AS pedidos_concluidos,
      (
        SELECT MAX(p.created_at)
        FROM public.pedidos p
        WHERE p.cliente_id_rel = c.id AND p.status_comercial <> 'cancelado'
      ) AS ultimo_pedido_em
    FROM public.clientes c
    LEFT JOIN public.cliente_creditos cc ON cc.cliente_id = c.id
    WHERE (
      c.nome ILIKE '%' || v_termo_norm || '%'
      OR (c.email IS NOT NULL AND c.email ILIKE '%' || v_termo_norm || '%')
      OR (v_termo_digitos <> '' AND c.telefone_normalizado LIKE '%' || v_termo_digitos || '%')
      OR (v_termo_digitos <> '' AND c.telefone LIKE '%' || v_termo_digitos || '%')
    )
    ORDER BY c.nome ASC
    LIMIT v_limite
  ) c_row;

  RETURN jsonb_build_object('success', true, 'clientes', v_resultados);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.buscar_clientes_crm FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.buscar_clientes_crm TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 5. RPC PRINCIPAL: OBTER FICHA 360° DO CLIENTE (ADMIN/OPERADOR)
-- --------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.obter_cliente_360_admin(
  p_cliente_id BIGINT,
  p_timeline_limite INTEGER DEFAULT 50,
  p_timeline_offset INTEGER DEFAULT 0
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_is_admin BOOLEAN := public.is_admin();
  v_cli RECORD;
  v_limite INTEGER := LEAST(GREATEST(COALESCE(p_timeline_limite, 50), 1), 100);
  v_offset INTEGER := GREATEST(COALESCE(p_timeline_offset, 0), 0);
  
  -- Métricas
  v_ped_total INT := 0;
  v_ped_concluidos INT := 0;
  v_ped_cancelados INT := 0;
  v_val_concluidos NUMERIC(10,2) := 0.00;
  v_val_recebido_caixa NUMERIC(10,2) := 0.00;
  v_ticket_medio NUMERIC(10,2) := 0.00;
  v_ticket_maximo NUMERIC(10,2) := 0.00;
  v_primeiro_ped TIMESTAMPTZ;
  v_ultimo_ped TIMESTAMPTZ;
  v_ultima_compra_concluida TIMESTAMPTZ;
  
  v_orc_total INT := 0;
  v_orc_convertidos INT := 0;
  v_taxa_conversao NUMERIC(5,2) := 0.00;
  v_saldo_credito NUMERIC(10,2) := 0.00;

  -- Coleções
  v_tags JSONB;
  v_preferencias JSONB;
  v_notas JSONB;
  v_timeline JSONB;
  v_cpf_exibicao TEXT;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada. Apenas equipe autorizada pode acessar a Ficha 360 do CRM.');
  END IF;

  IF p_cliente_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'CLIENT_ID_REQUIRED', 'error', 'ID do cliente é obrigatório.');
  END IF;

  SELECT * INTO v_cli FROM public.clientes WHERE id = p_cliente_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'CLIENT_NOT_FOUND', 'error', 'Cliente não encontrado no CRM.');
  END IF;

  -- Tratamento LGPD de CPF (admin vê completo; operador vê mascarado)
  IF v_cli.cpf IS NOT NULL AND length(v_cli.cpf) >= 4 THEN
    IF v_is_admin THEN
      v_cpf_exibicao := v_cli.cpf;
    ELSE
      v_cpf_exibicao := '***.***.***-' || right(regexp_replace(v_cli.cpf, '\D', '', 'g'), 2);
    END IF;
  ELSE
    v_cpf_exibicao := v_cli.cpf;
  END IF;

  -- 1. Apuração de Métricas de Pedidos
  SELECT
    COALESCE(COUNT(*), 0),
    COALESCE(COUNT(*) FILTER (WHERE status_comercial = 'concluido'), 0),
    COALESCE(COUNT(*) FILTER (WHERE status_comercial = 'cancelado'), 0),
    COALESCE(SUM(total) FILTER (WHERE status_comercial = 'concluido'), 0.00),
    COALESCE(MAX(total) FILTER (WHERE status_comercial = 'concluido'), 0.00),
    MIN(created_at) FILTER (WHERE status_comercial <> 'cancelado'),
    MAX(created_at) FILTER (WHERE status_comercial <> 'cancelado'),
    MAX(created_at) FILTER (WHERE status_comercial = 'concluido')
  INTO
    v_ped_total, v_ped_concluidos, v_ped_cancelados,
    v_val_concluidos, v_ticket_maximo,
    v_primeiro_ped, v_ultimo_ped, v_ultima_compra_concluida
  FROM public.pedidos
  WHERE cliente_id_rel = p_cliente_id;

  IF v_ped_concluidos > 0 THEN
    v_ticket_medio := ROUND(v_val_concluidos / v_ped_concluidos, 2);
  ELSE
    v_ticket_medio := 0.00;
  END IF;

  -- 2. Apuração do Caixa Efetivo (SEM DUPLICAR CREDITO_CLIENTE)
  -- Considera pagamentos aprovados em dinheiro/pix/cartão/etc. subtraindo estornos externos desses métodos.
  SELECT COALESCE(SUM(
    CASE 
      WHEN pp.status = 'aprovado' THEN pp.valor
      WHEN pp.status = 'estornado' THEN -pp.valor
      ELSE 0.00
    END
  ), 0.00) INTO v_val_recebido_caixa
  FROM public.pedido_pagamentos pp
  JOIN public.pedidos p ON p.id = pp.pedido_id
  WHERE p.cliente_id_rel = p_cliente_id
    AND pp.metodo <> 'credito_cliente'
    AND pp.status IN ('aprovado', 'estornado');

  v_val_recebido_caixa := GREATEST(0.00, v_val_recebido_caixa);

  -- 3. Apuração de Orçamentos
  SELECT
    COALESCE(COUNT(*), 0),
    COALESCE(COUNT(*) FILTER (WHERE status = 'convertido'), 0)
  INTO
    v_orc_total, v_orc_convertidos
  FROM public.orcamentos
  WHERE cliente_id = p_cliente_id;

  IF v_orc_total > 0 THEN
    v_taxa_conversao := ROUND((v_orc_convertidos::NUMERIC / v_orc_total::NUMERIC) * 100.00, 2);
  ELSE
    v_taxa_conversao := 0.00;
  END IF;

  -- 4. Saldo da Carteira de Crédito
  SELECT COALESCE(saldo, 0.00) INTO v_saldo_credito
  FROM public.cliente_creditos
  WHERE cliente_id = p_cliente_id;

  -- 5. Tags Ativas
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'tag', tag, 'created_at', created_at) ORDER BY tag ASC), '[]'::jsonb)
  INTO v_tags
  FROM public.cliente_tags
  WHERE cliente_id = p_cliente_id;

  -- 6. Preferências Ativas
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', id, 'categoria', categoria, 'valor', valor,
      'observacao', observacao, 'created_at', created_at
    ) ORDER BY categoria ASC, created_at DESC
  ), '[]'::jsonb)
  INTO v_preferencias
  FROM public.cliente_preferencias
  WHERE cliente_id = p_cliente_id AND ativo = true;

  -- 7. Notas Internas Não Arquivadas
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', n.id, 'nota', n.nota, 'categoria', n.categoria,
      'criado_em', n.criado_em, 'criado_por_nome', COALESCE(p.nome, 'Equipe')
    ) ORDER BY n.criado_em DESC
  ), '[]'::jsonb)
  INTO v_notas
  FROM public.cliente_notas n
  LEFT JOIN public.profiles p ON p.id = n.criado_por
  WHERE n.cliente_id = p_cliente_id AND n.arquivada = false;

  -- 8. Timeline Cronológica Unificada (UNION ALL Dinâmico Sanitizado)
  SELECT COALESCE(jsonb_agg(t_item), '[]'::jsonb) INTO v_timeline
  FROM (
    SELECT * FROM (
      -- Eventos de Pedidos
      SELECT 
        'pedido' AS tipo,
        p.status_comercial AS subtitulo,
        p.id AS entidade_id,
        'Pedido #' || p.id || ' (' || UPPER(p.status_comercial) || ')' AS titulo,
        'Valor Total: R$ ' || TRIM(TO_CHAR(p.total, '999999990.00')) || ' | Pagamento: ' || UPPER(p.pagamento) AS descricao,
        p.total AS valor,
        p.status_comercial AS status,
        p.created_at AS ocorrido_em,
        jsonb_build_object(
          'canal', p.canal,
          'status_operacional', p.status_operacional,
          'status_financeiro', p.status_financeiro,
          'valor_pago', p.valor_pago,
          'saldo', p.saldo
        ) AS metadata
      FROM public.pedidos p
      WHERE p.cliente_id_rel = p_cliente_id

      UNION ALL

      -- Eventos de Orçamentos
      SELECT 
        'orcamento' AS tipo,
        o.status AS subtitulo,
        o.id AS entidade_id,
        'Orçamento ' || o.numero || ' (v' || o.versao || ')' AS titulo,
        'Valor Total: R$ ' || TRIM(TO_CHAR(o.total, '999999990.00')) || ' | Status: ' || UPPER(o.status) AS descricao,
        o.total AS valor,
        o.status AS status,
        o.created_at AS ocorrido_em,
        jsonb_build_object(
          'numero', o.numero,
          'versao', o.versao,
          'pedido_id', o.pedido_id,
          'validade_ate', o.validade_ate
        ) AS metadata
      FROM public.orcamentos o
      WHERE o.cliente_id = p_cliente_id

      UNION ALL

      -- Eventos de WhatsApp / Comunicações
      SELECT 
        'comunicacao' AS tipo,
        c.tipo AS subtitulo,
        c.id AS entidade_id,
        'WhatsApp: ' || c.tipo AS titulo,
        'Canal: ' || c.canal || ' | Status: ' || c.status || ' | Dest: ' || COALESCE(c.destinatario, '-') AS descricao,
        0.00 AS valor,
        c.status AS status,
        c.created_at AS ocorrido_em,
        jsonb_build_object(
          'tipo', c.tipo,
          'canal', c.canal,
          'pedido_id', c.pedido_id,
          'orcamento_id', c.orcamento_id
        ) AS metadata
      FROM public.comunicacoes_cliente c
      LEFT JOIN public.pedidos cp ON cp.id = c.pedido_id
      LEFT JOIN public.orcamentos co ON co.id = c.orcamento_id
      WHERE cp.cliente_id_rel = p_cliente_id OR co.cliente_id = p_cliente_id

      UNION ALL

      -- Eventos de Crédito / Carteira
      SELECT 
        'credito' AS tipo,
        m.origem AS subtitulo,
        m.id AS entidade_id,
        'Movimentação de Crédito: ' || UPPER(m.tipo) AS titulo,
        m.motivo || ' (Saldo Anterior: R$ ' || m.saldo_anterior || ' -> Atual: R$ ' || m.saldo_posterior || ')' AS descricao,
        m.valor AS valor,
        m.tipo AS status,
        m.created_at AS ocorrido_em,
        jsonb_build_object(
          'origem', m.origem,
          'pedido_id', m.pedido_id,
          'saldo_anterior', m.saldo_anterior,
          'saldo_posterior', m.saldo_posterior
        ) AS metadata
      FROM public.cliente_credito_movimentacoes m
      WHERE m.cliente_id = p_cliente_id

      UNION ALL

      -- Eventos de Notas Internas
      SELECT 
        'nota' AS tipo,
        n.categoria AS subtitulo,
        n.id AS entidade_id,
        'Nota Interna: ' || UPPER(n.categoria) AS titulo,
        n.nota AS descricao,
        0.00 AS valor,
        CASE WHEN n.arquivada THEN 'arquivada' ELSE 'ativa' END AS status,
        n.criado_em AS ocorrido_em,
        jsonb_build_object(
          'categoria', n.categoria,
          'arquivada', n.arquivada
        ) AS metadata
      FROM public.cliente_notas n
      WHERE n.cliente_id = p_cliente_id
    ) timeline_union
    ORDER BY ocorrido_em DESC
    LIMIT v_limite
    OFFSET v_offset
  ) t_item;

  RETURN jsonb_build_object(
    'success', true,
    'cliente', jsonb_build_object(
      'id', v_cli.id,
      'nome', v_cli.nome,
      'telefone', v_cli.telefone,
      'telefone_normalizado', v_cli.telefone_normalizado,
      'email', v_cli.email,
      'cpf', v_cpf_exibicao,
      'data_nascimento', v_cli.data_nascimento,
      'endereco_padrao', v_cli.endereco_padrao,
      'observacoes', v_cli.observacoes,
      'created_at', v_cli.created_at,
      'updated_at', v_cli.updated_at
    ),
    'metricas', jsonb_build_object(
      'pedidos_total', v_ped_total,
      'pedidos_concluidos', v_ped_concluidos,
      'pedidos_cancelados', v_ped_cancelados,
      'valor_pedidos_concluidos', v_val_concluidos,
      'valor_recebido_caixa', v_val_recebido_caixa,
      'ticket_medio', v_ticket_medio,
      'ticket_maximo', v_ticket_maximo,
      'primeiro_pedido_em', v_primeiro_ped,
      'ultimo_pedido_em', v_ultimo_ped,
      'ultima_compra_concluida_em', v_ultima_compra_concluida,
      'orcamentos_total', v_orc_total,
      'orcamentos_convertidos', v_orc_convertidos,
      'taxa_conversao_orcamentos', v_taxa_conversao
    ),
    'credito', jsonb_build_object(
      'saldo', v_saldo_credito
    ),
    'tags', v_tags,
    'preferencias', v_preferencias,
    'notas', v_notas,
    'timeline', v_timeline
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_cliente_360_admin FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_cliente_360_admin TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 6. RPCs DE MANUTENÇÃO CRM (NOTAS, TAGS E PREFERÊNCIAS)
-- --------------------------------------------------------------------------

-- 6.1 Adicionar Nota Interna
CREATE OR REPLACE FUNCTION public.adicionar_nota_cliente(
  p_cliente_id BIGINT,
  p_nota TEXT,
  p_categoria TEXT DEFAULT 'atendimento'
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_nota TEXT := NULLIF(TRIM(COALESCE(p_nota, '')), '');
  v_cat TEXT := LOWER(TRIM(COALESCE(p_categoria, 'atendimento')));
  v_nota_id BIGINT;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada. Apenas equipe autorizada pode adicionar notas internas.');
  END IF;

  IF p_cliente_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'CLIENT_ID_REQUIRED', 'error', 'ID do cliente é obrigatório.');
  END IF;

  IF v_nota IS NULL OR length(v_nota) < 3 THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_NOTE', 'error', 'A nota deve conter pelo menos 3 caracteres.');
  END IF;

  IF v_cat NOT IN ('atendimento', 'preferencia', 'comercial', 'pos_venda', 'outro') THEN
    v_cat := 'atendimento';
  END IF;

  INSERT INTO public.cliente_notas (cliente_id, nota, categoria, criado_por, criado_em)
  VALUES (p_cliente_id, v_nota, v_cat, auth.uid(), NOW())
  RETURNING id INTO v_nota_id;

  RETURN jsonb_build_object('success', true, 'nota_id', v_nota_id, 'cliente_id', p_cliente_id);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.adicionar_nota_cliente FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.adicionar_nota_cliente TO authenticated, service_role;

-- 6.2 Arquivar Nota Interna (Sem DELETE Físico)
CREATE OR REPLACE FUNCTION public.arquivar_nota_cliente(
  p_nota_id BIGINT
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada. Apenas equipe autorizada pode arquivar notas internas.');
  END IF;

  IF p_nota_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'NOTE_ID_REQUIRED', 'error', 'ID da nota é obrigatório.');
  END IF;

  UPDATE public.cliente_notas
  SET arquivada = true,
      arquivada_por = auth.uid(),
      arquivada_em = NOW()
  WHERE id = p_nota_id AND arquivada = false;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'NOTE_NOT_FOUND', 'error', 'Nota não encontrada ou já arquivada.');
  END IF;

  RETURN jsonb_build_object('success', true, 'nota_id', p_nota_id, 'arquivada', true);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.arquivar_nota_cliente FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.arquivar_nota_cliente TO authenticated, service_role;

-- 6.3 Adicionar Tag ao Cliente
CREATE OR REPLACE FUNCTION public.adicionar_tag_cliente(
  p_cliente_id BIGINT,
  p_tag TEXT
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_tag TEXT := NULLIF(TRIM(COALESCE(p_tag, '')), '');
  v_tag_id BIGINT;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada. Apenas equipe autorizada pode gerenciar tags.');
  END IF;

  IF p_cliente_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'CLIENT_ID_REQUIRED', 'error', 'ID do cliente é obrigatório.');
  END IF;

  IF v_tag IS NULL OR length(v_tag) < 2 THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_TAG', 'error', 'A tag deve conter pelo menos 2 caracteres.');
  END IF;

  INSERT INTO public.cliente_tags (cliente_id, tag, criado_por, created_at)
  VALUES (p_cliente_id, v_tag, auth.uid(), NOW())
  ON CONFLICT (cliente_id, tag) DO NOTHING
  RETURNING id INTO v_tag_id;

  RETURN jsonb_build_object('success', true, 'tag', v_tag, 'cliente_id', p_cliente_id);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.adicionar_tag_cliente FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.adicionar_tag_cliente TO authenticated, service_role;

-- 6.4 Remover Tag do Cliente (Exceção controlada para tags efêmeras)
CREATE OR REPLACE FUNCTION public.remover_tag_cliente(
  p_cliente_id BIGINT,
  p_tag TEXT
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_tag TEXT := NULLIF(TRIM(COALESCE(p_tag, '')), '');
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada. Apenas equipe autorizada pode gerenciar tags.');
  END IF;

  IF p_cliente_id IS NULL OR v_tag IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_PARAMS', 'error', 'ID do cliente e tag são obrigatórios.');
  END IF;

  DELETE FROM public.cliente_tags
  WHERE cliente_id = p_cliente_id AND LOWER(tag) = LOWER(v_tag);

  RETURN jsonb_build_object('success', true, 'tag_removida', v_tag, 'cliente_id', p_cliente_id);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.remover_tag_cliente FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.remover_tag_cliente TO authenticated, service_role;

-- 6.5 Definir Preferência do Cliente
CREATE OR REPLACE FUNCTION public.definir_preferencia_cliente(
  p_cliente_id BIGINT,
  p_categoria TEXT,
  p_valor TEXT,
  p_observacao TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_cat TEXT := LOWER(TRIM(COALESCE(p_categoria, 'outro')));
  v_val TEXT := NULLIF(TRIM(COALESCE(p_valor, '')), '');
  v_obs TEXT := NULLIF(TRIM(COALESCE(p_observacao, '')), '');
  v_pref_id BIGINT;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada. Apenas equipe autorizada pode gerenciar preferências.');
  END IF;

  IF p_cliente_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'CLIENT_ID_REQUIRED', 'error', 'ID do cliente é obrigatório.');
  END IF;

  IF v_val IS NULL OR length(v_val) < 2 THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_VALUE', 'error', 'O valor da preferência deve conter pelo menos 2 caracteres.');
  END IF;

  IF v_cat NOT IN ('sabor', 'decoracao', 'ocasiao', 'atendimento', 'restricao_alimentar', 'outro') THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_CATEGORY', 'error', 'Categoria de preferência inválida.');
  END IF;

  INSERT INTO public.cliente_preferencias (
    cliente_id, categoria, valor, observacao, ativo, criado_por, created_at, updated_at
  ) VALUES (
    p_cliente_id, v_cat, v_val, v_obs, true, auth.uid(), NOW(), NOW()
  ) RETURNING id INTO v_pref_id;

  RETURN jsonb_build_object('success', true, 'preferencia_id', v_pref_id, 'cliente_id', p_cliente_id);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.definir_preferencia_cliente FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.definir_preferencia_cliente TO authenticated, service_role;

-- 6.6 Arquivar Preferência do Cliente (Desativação Auditável)
CREATE OR REPLACE FUNCTION public.arquivar_preferencia_cliente(
  p_preferencia_id BIGINT
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada. Apenas equipe autorizada pode desativar preferências.');
  END IF;

  IF p_preferencia_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'PREFERENCE_ID_REQUIRED', 'error', 'ID da preferência é obrigatório.');
  END IF;

  UPDATE public.cliente_preferencias
  SET ativo = false,
      updated_at = NOW()
  WHERE id = p_preferencia_id AND ativo = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'PREFERENCE_NOT_FOUND', 'error', 'Preferência não encontrada ou já desativada.');
  END IF;

  RETURN jsonb_build_object('success', true, 'preferencia_id', p_preferencia_id, 'ativo', false);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.arquivar_preferencia_cliente FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.arquivar_preferencia_cliente TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 7. VISÃO PRÓPRIA DO CLIENTE AUTENTICADO (FAIL-CLOSED & SEM DADOS INTERNOS)
-- --------------------------------------------------------------------------
-- O cliente autenticado (auth.uid()) só visualiza seus próprios dados cadastrais,
-- seus pedidos, seus orçamentos e seu saldo de crédito, SEM NOTAS NEM TAGS INTERNAS.

CREATE OR REPLACE FUNCTION public.obter_meu_perfil_360()
RETURNS JSONB AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_cli RECORD;
  v_saldo NUMERIC(10,2) := 0.00;
  v_pedidos JSONB;
  v_orcamentos JSONB;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'UNAUTHENTICATED', 'error', 'Sessão necessária para consultar perfil.');
  END IF;

  SELECT * INTO v_cli FROM public.clientes WHERE auth_user_id = v_uid LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'PROFILE_NOT_LINKED', 'error', 'Perfil do cliente não encontrado.');
  END IF;

  -- Saldo de Crédito
  SELECT COALESCE(saldo, 0.00) INTO v_saldo
  FROM public.cliente_creditos
  WHERE cliente_id = v_cli.id;

  -- Pedidos do Próprio Cliente
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', id, 'total', total, 'status_comercial', status_comercial,
      'status_operacional', status_operacional, 'status_financeiro', status_financeiro,
      'data_entrega', data_entrega, 'created_at', created_at
    ) ORDER BY created_at DESC
  ), '[]'::jsonb) INTO v_pedidos
  FROM public.pedidos
  WHERE cliente_id_rel = v_cli.id;

  -- Orçamentos do Próprio Cliente
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', id, 'numero', numero, 'versao', versao,
      'status', status, 'total', total, 'data_evento', data_evento,
      'validade_ate', validade_ate, 'token_publico', token_publico, 'created_at', created_at
    ) ORDER BY created_at DESC
  ), '[]'::jsonb) INTO v_orcamentos
  FROM public.orcamentos
  WHERE cliente_id = v_cli.id;

  RETURN jsonb_build_object(
    'success', true,
    'cliente', jsonb_build_object(
      'id', v_cli.id,
      'nome', v_cli.nome,
      'telefone', v_cli.telefone,
      'email', v_cli.email,
      'endereco_padrao', v_cli.endereco_padrao
    ),
    'credito', jsonb_build_object(
      'saldo', v_saldo
    ),
    'pedidos', v_pedidos,
    'orcamentos', v_orcamentos
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_meu_perfil_360 FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_meu_perfil_360 TO authenticated, service_role;


-- ==========================================================================
-- >>> MIGRATION 020_agenda_producao_operacional.sql
-- ==========================================================================

-- ==========================================================================
-- LUNOCA DOCERIA - MIGRATION 020: AGENDA DE PRODUÇÃO & OPERAÇÃO VISUAL (FRENTE E)
-- ==========================================================================
-- Objetivo:
-- Projeção operacional dos pedidos canônicos para visualização e condução do fluxo diário:
-- 1. Fila de Produção: aguardando_producao -> em_producao -> pronto
-- 2. Expedição Segregada:
--    - Entrega: pronto -> saiu_para_entrega -> entregue
--    - Retirada: pronto -> entregue (rejeita saiu_para_entrega)
-- 3. Sanitização da Cozinha: Não expõe CPF, meios de pagamento ou margens no display operacional.
-- 4. Capacidade Diária: Projeção de carga máxima vs ocupada sem inventar disponibilidade no frontend.
-- 5. Estruturas complementares: observações de produção e prioridade operacional.
-- 6. Imutabilidade contábil: Conclusão operacional NUNCA duplica lançamentos financeiros.
-- ==========================================================================

-- --------------------------------------------------------------------------
-- 1. ESTRUTURAS COMPLEMENTARES DE PRODUÇÃO
-- --------------------------------------------------------------------------

-- 1.1 Observações de Produção da Equipe (auditável, sem delete físico)
CREATE TABLE IF NOT EXISTS public.pedido_producao_observacoes (
  id BIGSERIAL PRIMARY KEY,
  pedido_id BIGINT NOT NULL REFERENCES public.pedidos(id) ON DELETE CASCADE,
  observacao TEXT NOT NULL,
  categoria TEXT NOT NULL DEFAULT 'geral' CHECK (categoria IN ('geral', 'cozinha', 'embalagem', 'entrega', 'alergia')),
  autor_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  autor_nome TEXT,
  ativo BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_prod_obs_pedido_ativo 
  ON public.pedido_producao_observacoes(pedido_id) WHERE ativo = true;

ALTER TABLE public.pedido_producao_observacoes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.pedido_producao_observacoes FROM PUBLIC, anon;

DROP POLICY IF EXISTS "Equipe visualiza observacoes producao" ON public.pedido_producao_observacoes;
CREATE POLICY "Equipe visualiza observacoes producao" ON public.pedido_producao_observacoes
  FOR SELECT USING (public.is_admin_or_operator());

DROP POLICY IF EXISTS "Equipe insere observacoes producao" ON public.pedido_producao_observacoes;
CREATE POLICY "Equipe insere observacoes producao" ON public.pedido_producao_observacoes
  FOR INSERT WITH CHECK (public.is_admin_or_operator());

DROP POLICY IF EXISTS "Equipe atualiza observacoes producao" ON public.pedido_producao_observacoes;
CREATE POLICY "Equipe atualiza observacoes producao" ON public.pedido_producao_observacoes
  FOR UPDATE USING (public.is_admin_or_operator()) WITH CHECK (public.is_admin_or_operator());

-- Bloqueio de DELETE físico na tabela de observações de produção
CREATE OR REPLACE FUNCTION public.bloquear_delete_pedido_producao_observacoes()
RETURNS TRIGGER AS $$
BEGIN
  RAISE EXCEPTION 'Exclusão física bloqueada em observações de produção. Utilize arquivamento com ativo = false.';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_bloquear_delete_prod_obs ON public.pedido_producao_observacoes;
CREATE TRIGGER trg_bloquear_delete_prod_obs
  BEFORE DELETE ON public.pedido_producao_observacoes
  FOR EACH ROW
  EXECUTE FUNCTION public.bloquear_delete_pedido_producao_observacoes();

GRANT SELECT, INSERT, UPDATE ON public.pedido_producao_observacoes TO authenticated, service_role;
GRANT USAGE, SELECT ON SEQUENCE public.pedido_producao_observacoes_id_seq TO authenticated, service_role;

-- 1.2 Prioridade e Configurações Operacionais por Pedido
CREATE TABLE IF NOT EXISTS public.pedido_producao_config (
  pedido_id BIGINT PRIMARY KEY REFERENCES public.pedidos(id) ON DELETE CASCADE,
  prioridade TEXT NOT NULL DEFAULT 'normal' CHECK (prioridade IN ('baixa', 'normal', 'alta', 'urgente')),
  responsavel TEXT,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_by UUID REFERENCES auth.users(id) ON DELETE SET NULL
);

ALTER TABLE public.pedido_producao_config ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.pedido_producao_config FROM PUBLIC, anon;

DROP POLICY IF EXISTS "Equipe gerencia config producao" ON public.pedido_producao_config;
CREATE POLICY "Equipe gerencia config producao" ON public.pedido_producao_config
  FOR ALL USING (public.is_admin_or_operator())
  WITH CHECK (public.is_admin_or_operator());

GRANT SELECT, INSERT, UPDATE ON public.pedido_producao_config TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 2. RPC: OBTER_AGENDA_PRODUCAO
-- --------------------------------------------------------------------------
-- Projeta os pedidos confirmados/em andamento para a linha de produção no período,
-- agregando capacidade diária real e sanitizando dados financeiros para a cozinha.
CREATE OR REPLACE FUNCTION public.obter_agenda_producao(
  p_data_inicio DATE DEFAULT CURRENT_DATE,
  p_data_fim DATE DEFAULT (CURRENT_DATE + INTERVAL '7 days')::DATE,
  p_status_operacional TEXT DEFAULT NULL,
  p_modalidade TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_inicio DATE;
  v_fim DATE;
  v_pedidos JSONB;
  v_capacidades JSONB;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PERMISSION_DENIED',
      'error', 'Apenas operadores e administradores podem visualizar a agenda de produção.'
    );
  END IF;

  v_inicio := COALESCE(p_data_inicio, CURRENT_DATE);
  v_fim := COALESCE(p_data_fim, (v_inicio + INTERVAL '7 days')::DATE);

  IF v_fim < v_inicio THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'INVALID_DATE_RANGE',
      'error', 'Data final não pode ser anterior à data inicial.'
    );
  END IF;

  -- Limite preventivo de 31 dias por consulta
  IF (v_fim - v_inicio) > 31 THEN
    v_fim := (v_inicio + INTERVAL '31 days')::DATE;
  END IF;

  -- 1. Projeção dos Pedidos Ativos na Agenda (Ignora pedidos cancelados)
  SELECT COALESCE(jsonb_agg(ped_row), '[]'::jsonb) INTO v_pedidos
  FROM (
    SELECT
      p.id,
      p.id AS numero_pedido,
      p.data_entrega,
      p.hora_entrega,
      p.nome_cliente,
      p.telefone_cliente AS cliente_telefone,
      COALESCE(p.modalidade_entrega, 'retirada') AS modalidade_entrega,
      p.endereco_entrega,
      p.status_operacional,
      p.status_comercial,
      p.status_financeiro,
      COALESCE(cfg.prioridade, 'normal') AS prioridade,
      cfg.responsavel AS responsavel_producao,
      public.pontos_pedido(p.id) AS pontos_producao,
      p.observacoes_cliente AS observacoes_cliente,
      -- Lista estruturada de itens para a cozinha
      (
        SELECT COALESCE(jsonb_agg(
          jsonb_build_object(
            'item_id', pi.id,
            'produto_id', pi.produto_id,
            'produto_nome', COALESCE(pr.nome, 'Item'),
            'quantidade', pi.quantidade,
            'observacoes', pi.observacoes,
            'pontos_producao', pi.pontos_producao_snapshot,
            'opcoes', (
              SELECT COALESCE(jsonb_agg(
                jsonb_build_object(
                  'opcao_id', pio.id,
                  'nome', pio.opcao_nome,
                  'valor', pio.preco_adicional
                )
              ), '[]'::jsonb)
              FROM public.pedido_item_opcoes pio
              WHERE pio.pedido_item_id = pi.id
            )
          ) ORDER BY pi.id ASC
        ), '[]'::jsonb)
        FROM public.pedido_itens pi
        LEFT JOIN public.produtos pr ON pr.id = pi.produto_id
        WHERE pi.pedido_id = p.id
      ) AS itens,
      -- Observações de produção ativas
      (
        SELECT COALESCE(jsonb_agg(
          jsonb_build_object(
            'id', po.id,
            'observacao', po.observacao,
            'categoria', po.categoria,
            'autor_nome', po.autor_nome,
            'created_at', po.created_at
          ) ORDER BY po.created_at DESC
        ), '[]'::jsonb)
        FROM public.pedido_producao_observacoes po
        WHERE po.pedido_id = p.id AND po.ativo = true
      ) AS observacoes_producao
    FROM public.pedidos p
    LEFT JOIN public.pedido_producao_config cfg ON cfg.pedido_id = p.id
    WHERE p.data_entrega BETWEEN v_inicio AND v_fim
      AND p.status_comercial <> 'cancelado'
      AND (p_status_operacional IS NULL OR p.status_operacional = p_status_operacional)
      AND (p_modalidade IS NULL OR COALESCE(p.modalidade_entrega, 'retirada') = p_modalidade)
    ORDER BY
      p.data_entrega ASC,
      p.hora_entrega ASC NULLS LAST,
      CASE COALESCE(cfg.prioridade, 'normal')
        WHEN 'urgente' THEN 1
        WHEN 'alta' THEN 2
        WHEN 'normal' THEN 3
        WHEN 'baixa' THEN 4
        ELSE 5
      END ASC,
      p.id ASC
  ) ped_row;

  -- 2. Capacidade Diária para cada dia do intervalo
  SELECT COALESCE(jsonb_agg(cap_row), '[]'::jsonb) INTO v_capacidades
  FROM (
    SELECT
      d.dia::DATE AS data,
      COALESCE(cp.capacidade_maxima_pontos, 30.00) AS capacidade_maxima,
      public.pontos_ocupados_data(d.dia::DATE) AS pontos_ocupados,
      GREATEST(0.00, COALESCE(cp.capacidade_maxima_pontos, 30.00) - public.pontos_ocupados_data(d.dia::DATE)) AS pontos_disponiveis,
      ROUND(
        LEAST(100.00, (public.pontos_ocupados_data(d.dia::DATE) / GREATEST(1.00, COALESCE(cp.capacidade_maxima_pontos, 30.00))) * 100.00),
        1
      ) AS percentual_ocupado,
      COALESCE(cp.bloqueado, false) AS bloqueado,
      cp.motivo_bloqueio,
      CASE
        WHEN COALESCE(cp.bloqueado, false) THEN 'bloqueado'
        WHEN public.pontos_ocupados_data(d.dia::DATE) > COALESCE(cp.capacidade_maxima_pontos, 30.00) THEN 'excedido'
        WHEN public.pontos_ocupados_data(d.dia::DATE) >= COALESCE(cp.capacidade_maxima_pontos, 30.00) THEN 'lotado'
        WHEN public.pontos_ocupados_data(d.dia::DATE) >= (COALESCE(cp.capacidade_maxima_pontos, 30.00) * 0.80) THEN 'proximo_limite'
        ELSE 'normal'
      END AS status_capacidade
    FROM generate_series(v_inicio::TIMESTAMP, v_fim::TIMESTAMP, '1 day'::INTERVAL) d(dia)
    LEFT JOIN public.capacidade_producao cp ON cp.data = d.dia::DATE
    ORDER BY d.dia ASC
  ) cap_row;

  RETURN jsonb_build_object(
    'success', true,
    'data_inicio', v_inicio,
    'data_fim', v_fim,
    'pedidos', v_pedidos,
    'capacidades', v_capacidades,
    'total_pedidos', jsonb_array_length(v_pedidos)
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_agenda_producao FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_agenda_producao TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 3. RPC: OBTER_DETALHE_PRODUCAO_PEDIDO
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.obter_detalhe_producao_pedido(
  p_pedido_id BIGINT
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_ped public.pedidos;
  v_itens JSONB;
  v_historico JSONB;
  v_observacoes JSONB;
  v_preferencias_cliente JSONB;
  v_cfg RECORD;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas equipe autorizada pode ver detalhes de produção.');
  END IF;

  IF p_pedido_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_ID_REQUIRED', 'error', 'ID do pedido é obrigatório.');
  END IF;

  SELECT * INTO v_ped FROM public.pedidos WHERE id = p_pedido_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_NOT_FOUND', 'error', 'Pedido não encontrado.');
  END IF;

  -- Itens com opções
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', pi.id,
      'produto_id', pi.produto_id,
      'produto_nome', COALESCE(pr.nome, 'Produto'),
      'quantidade', pi.quantidade,
      'observacoes', pi.observacoes,
      'pontos_producao', pi.pontos_producao_snapshot,
      'opcoes', (
        SELECT COALESCE(jsonb_agg(
          jsonb_build_object(
            'nome', pio.opcao_nome,
            'valor', pio.preco_adicional
          )
        ), '[]'::jsonb)
        FROM public.pedido_item_opcoes pio
        WHERE pio.pedido_item_id = pi.id
      )
    ) ORDER BY pi.id ASC
  ), '[]'::jsonb) INTO v_itens
  FROM public.pedido_itens pi
  LEFT JOIN public.produtos pr ON pr.id = pi.produto_id
  WHERE pi.pedido_id = v_ped.id;

  -- Histórico operacional
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', h.id,
      'status_anterior', h.status_anterior,
      'status_novo', h.status_novo,
      'usuario_nome', h.usuario_nome,
      'origem', h.origem,
      'metadata', h.metadata,
      'created_at', h.created_at
    ) ORDER BY h.created_at ASC
  ), '[]'::jsonb) INTO v_historico
  FROM public.pedido_status_historico h
  WHERE h.pedido_id = v_ped.id AND h.dimensao = 'operacional';

  -- Observações de produção
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', po.id,
      'observacao', po.observacao,
      'categoria', po.categoria,
      'autor_nome', po.autor_nome,
      'created_at', po.created_at
    ) ORDER BY po.created_at DESC
  ), '[]'::jsonb) INTO v_observacoes
  FROM public.pedido_producao_observacoes po
  WHERE po.pedido_id = v_ped.id AND po.ativo = true;

  -- Restrições e preferências alimentares do cliente (da Frente D, se cliente vinculado)
  IF v_ped.cliente_id_rel IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'categoria', cp.categoria,
        'preferencia', cp.valor,
        'detalhes', cp.observacao
      ) ORDER BY cp.categoria ASC
    ), '[]'::jsonb) INTO v_preferencias_cliente
    FROM public.cliente_preferencias cp
    WHERE cp.cliente_id = v_ped.cliente_id_rel AND cp.ativo = true;
  ELSE
    v_preferencias_cliente := '[]'::jsonb;
  END IF;

  SELECT * INTO v_cfg FROM public.pedido_producao_config WHERE pedido_id = v_ped.id;

  RETURN jsonb_build_object(
    'success', true,
    'pedido', jsonb_build_object(
      'id', v_ped.id,
      'data_entrega', v_ped.data_entrega,
      'hora_entrega', v_ped.hora_entrega,
      'modalidade_entrega', COALESCE(v_ped.modalidade_entrega, 'retirada'),
      'endereco_entrega', v_ped.endereco_entrega,
      'nome_cliente', v_ped.nome_cliente,
      'telefone_cliente', v_ped.telefone_cliente,
      'status_operacional', v_ped.status_operacional,
      'status_comercial', v_ped.status_comercial,
      'observacoes_cliente', v_ped.observacoes_cliente,
      'pontos_producao', public.pontos_pedido(v_ped.id),
      'prioridade', COALESCE(v_cfg.prioridade, 'normal'),
      'responsavel_producao', v_cfg.responsavel
    ),
    'itens', v_itens,
    'historico_operacional', v_historico,
    'observacoes_producao', v_observacoes,
    'restricoes_cliente', v_preferencias_cliente
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_detalhe_producao_pedido FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_detalhe_producao_pedido TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 4. RPC: INICIAR_PRODUCAO_PEDIDO
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.iniciar_producao_pedido(
  p_pedido_id BIGINT
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_ped public.pedidos;
  v_usuario_nome TEXT;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas equipe pode iniciar produção.');
  END IF;

  IF p_pedido_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_ID_REQUIRED', 'error', 'ID do pedido é obrigatório.');
  END IF;

  SELECT * INTO v_ped FROM public.pedidos WHERE id = p_pedido_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_NOT_FOUND', 'error', 'Pedido não encontrado.');
  END IF;

  IF v_ped.status_comercial = 'cancelado' THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_CANCELLED', 'error', 'Não é possível iniciar produção de pedido cancelado.');
  END IF;

  -- Idempotência
  IF v_ped.status_operacional = 'em_producao' THEN
    RETURN jsonb_build_object('success', true, 'idempotente', true, 'status_operacional', 'em_producao', 'pedido_id', p_pedido_id);
  END IF;

  -- Validação de transição: não permite retroceder de pronto/entregue
  IF v_ped.status_operacional IN ('pronto', 'saiu_para_entrega', 'entregue', 'retirado') THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'INVALID_TRANSITION',
      'error', 'Pedido já foi finalizado ou está pronto/entregue. Não pode retornar para em produção.'
    );
  END IF;

  SELECT COALESCE(nome, email, 'Operador') INTO v_usuario_nome 
  FROM public.profiles WHERE id = auth.uid();
  IF v_usuario_nome IS NULL THEN v_usuario_nome := 'Equipe Produção'; END IF;

  -- Transição para em_producao
  UPDATE public.pedidos
  SET status_operacional = 'em_producao',
      status = 'Em Preparo',
      updated_at = NOW()
  WHERE id = p_pedido_id;

  INSERT INTO public.pedido_status_historico (
    pedido_id, dimensao, status_anterior, status_novo, usuario_id, usuario_nome, origem, metadata
  ) VALUES (
    p_pedido_id, 'operacional', v_ped.status_operacional, 'em_producao',
    auth.uid(), v_usuario_nome, 'admin',
    jsonb_build_object('acao', 'iniciar_producao')
  );

  RETURN jsonb_build_object(
    'success', true,
    'pedido_id', p_pedido_id,
    'status_anterior', v_ped.status_operacional,
    'status_operacional', 'em_producao'
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.iniciar_producao_pedido FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.iniciar_producao_pedido TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 5. RPC: MARCAR_PEDIDO_PRONTO
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.marcar_pedido_pronto(
  p_pedido_id BIGINT
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_ped public.pedidos;
  v_usuario_nome TEXT;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas equipe pode marcar pedido como pronto.');
  END IF;

  IF p_pedido_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_ID_REQUIRED', 'error', 'ID do pedido é obrigatório.');
  END IF;

  SELECT * INTO v_ped FROM public.pedidos WHERE id = p_pedido_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_NOT_FOUND', 'error', 'Pedido não encontrado.');
  END IF;

  IF v_ped.status_comercial = 'cancelado' THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_CANCELLED', 'error', 'Não é possível marcar pedido cancelado como pronto.');
  END IF;

  -- Idempotência
  IF v_ped.status_operacional = 'pronto' THEN
    RETURN jsonb_build_object('success', true, 'idempotente', true, 'status_operacional', 'pronto', 'pedido_id', p_pedido_id);
  END IF;

  -- Transição válida: apenas se estiver em_producao ou aguardando_producao
  IF v_ped.status_operacional IN ('saiu_para_entrega', 'entregue', 'retirado') THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'INVALID_TRANSITION',
      'error', 'Pedido já saiu para entrega ou foi entregue. Não pode retornar para pronto.'
    );
  END IF;

  SELECT COALESCE(nome, email, 'Operador') INTO v_usuario_nome 
  FROM public.profiles WHERE id = auth.uid();
  IF v_usuario_nome IS NULL THEN v_usuario_nome := 'Equipe Produção'; END IF;

  UPDATE public.pedidos
  SET status_operacional = 'pronto',
      status = 'Pronto',
      updated_at = NOW()
  WHERE id = p_pedido_id;

  INSERT INTO public.pedido_status_historico (
    pedido_id, dimensao, status_anterior, status_novo, usuario_id, usuario_nome, origem, metadata
  ) VALUES (
    p_pedido_id, 'operacional', v_ped.status_operacional, 'pronto',
    auth.uid(), v_usuario_nome, 'admin',
    jsonb_build_object('acao', 'marcar_pronto', 'modalidade', COALESCE(v_ped.modalidade_entrega, 'retirada'))
  );

  RETURN jsonb_build_object(
    'success', true,
    'pedido_id', p_pedido_id,
    'status_anterior', v_ped.status_operacional,
    'status_operacional', 'pronto',
    'modalidade_entrega', COALESCE(v_ped.modalidade_entrega, 'retirada')
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.marcar_pedido_pronto FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.marcar_pedido_pronto TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 6. RPC: MARCAR_SAIDA_ENTREGA
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.marcar_saida_entrega(
  p_pedido_id BIGINT
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_ped public.pedidos;
  v_usuario_nome TEXT;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas equipe pode despachar entrega.');
  END IF;

  IF p_pedido_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_ID_REQUIRED', 'error', 'ID do pedido é obrigatório.');
  END IF;

  SELECT * INTO v_ped FROM public.pedidos WHERE id = p_pedido_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_NOT_FOUND', 'error', 'Pedido não encontrado.');
  END IF;

  IF v_ped.status_comercial = 'cancelado' THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_CANCELLED', 'error', 'Pedido cancelado não pode sair para entrega.');
  END IF;

  -- SEGREGACAO ESTRITA DE MODALIDADE: Retirada não pode ter saída para entrega
  IF COALESCE(v_ped.modalidade_entrega, 'retirada') = 'retirada' THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'INVALID_DELIVERY_MODALITY',
      'error', 'Pedidos na modalidade retirada na loja não possuem etapa de saída para entrega.'
    );
  END IF;

  -- Idempotência
  IF v_ped.status_operacional = 'saiu_para_entrega' THEN
    RETURN jsonb_build_object('success', true, 'idempotente', true, 'status_operacional', 'saiu_para_entrega', 'pedido_id', p_pedido_id);
  END IF;

  -- Validação de transição: Não pode ir direto de aguardando_producao sem estar pronto
  IF v_ped.status_operacional NOT IN ('pronto', 'em_producao') THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'INVALID_TRANSITION',
      'error', 'Pedido precisa estar pronto (ou em finalização de produção) para sair para entrega.'
    );
  END IF;

  SELECT COALESCE(nome, email, 'Operador') INTO v_usuario_nome 
  FROM public.profiles WHERE id = auth.uid();
  IF v_usuario_nome IS NULL THEN v_usuario_nome := 'Expedição'; END IF;

  UPDATE public.pedidos
  SET status_operacional = 'saiu_para_entrega',
      updated_at = NOW()
  WHERE id = p_pedido_id;

  INSERT INTO public.pedido_status_historico (
    pedido_id, dimensao, status_anterior, status_novo, usuario_id, usuario_nome, origem, metadata
  ) VALUES (
    p_pedido_id, 'operacional', v_ped.status_operacional, 'saiu_para_entrega',
    auth.uid(), v_usuario_nome, 'admin',
    jsonb_build_object('acao', 'saiu_para_entrega')
  );

  RETURN jsonb_build_object(
    'success', true,
    'pedido_id', p_pedido_id,
    'status_anterior', v_ped.status_operacional,
    'status_operacional', 'saiu_para_entrega'
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.marcar_saida_entrega FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.marcar_saida_entrega TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 7. RPC: CONFIRMAR_ENTREGA_RETIRADA
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.confirmar_entrega_retirada(
  p_pedido_id BIGINT
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_ped public.pedidos;
  v_status_final TEXT;
  v_usuario_nome TEXT;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas equipe pode confirmar conclusão da entrega/retirada.');
  END IF;

  IF p_pedido_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_ID_REQUIRED', 'error', 'ID do pedido é obrigatório.');
  END IF;

  SELECT * INTO v_ped FROM public.pedidos WHERE id = p_pedido_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_NOT_FOUND', 'error', 'Pedido não encontrado.');
  END IF;

  IF v_ped.status_comercial = 'cancelado' THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_CANCELLED', 'error', 'Pedido cancelado não pode ser entregue.');
  END IF;

  -- Idempotência
  IF v_ped.status_operacional IN ('entregue', 'retirado') THEN
    RETURN jsonb_build_object(
      'success', true,
      'idempotente', true,
      'status_operacional', v_ped.status_operacional,
      'pedido_id', p_pedido_id
    );
  END IF;

  -- Validação estrita: não pode pular de aguardando_producao direto para entregue
  IF v_ped.status_operacional = 'aguardando_producao' THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'INVALID_TRANSITION',
      'error', 'Não é possível concluir entrega de pedido que ainda aguarda produção. O pedido deve passar pelas etapas de preparo.'
    );
  END IF;

  v_status_final := 'entregue';

  SELECT COALESCE(nome, email, 'Operador') INTO v_usuario_nome 
  FROM public.profiles WHERE id = auth.uid();
  IF v_usuario_nome IS NULL THEN v_usuario_nome := 'Balcão/Entrega'; END IF;

  -- Atualização operacional (sem duplicar ou forçar financeiro)
  UPDATE public.pedidos
  SET status_operacional = v_status_final,
      status = 'Entregue',
      updated_at = NOW()
  WHERE id = p_pedido_id;

  INSERT INTO public.pedido_status_historico (
    pedido_id, dimensao, status_anterior, status_novo, usuario_id, usuario_nome, origem, metadata
  ) VALUES (
    p_pedido_id, 'operacional', v_ped.status_operacional, v_status_final,
    auth.uid(), v_usuario_nome, 'admin',
    jsonb_build_object('acao', 'confirmar_entrega_retirada', 'modalidade', COALESCE(v_ped.modalidade_entrega, 'retirada'))
  );

  RETURN jsonb_build_object(
    'success', true,
    'pedido_id', p_pedido_id,
    'status_anterior', v_ped.status_operacional,
    'status_operacional', v_status_final,
    'modalidade_entrega', COALESCE(v_ped.modalidade_entrega, 'retirada')
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.confirmar_entrega_retirada FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.confirmar_entrega_retirada TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 8. RPC: DEFINIR_PRIORIDADE_PRODUCAO
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.definir_prioridade_producao(
  p_pedido_id BIGINT,
  p_prioridade TEXT
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_prio TEXT := LOWER(TRIM(COALESCE(p_prioridade, 'normal')));
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas equipe pode alterar prioridade.');
  END IF;

  IF p_pedido_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_ID_REQUIRED', 'error', 'ID do pedido é obrigatório.');
  END IF;

  IF v_prio NOT IN ('baixa', 'normal', 'alta', 'urgente') THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_PRIORITY', 'error', 'Prioridade inválida. Utilize: baixa, normal, alta ou urgente.');
  END IF;

  INSERT INTO public.pedido_producao_config (pedido_id, prioridade, updated_at, updated_by)
  VALUES (p_pedido_id, v_prio, NOW(), auth.uid())
  ON CONFLICT (pedido_id) DO UPDATE SET
    prioridade = EXCLUDED.prioridade,
    updated_at = NOW(),
    updated_by = auth.uid();

  RETURN jsonb_build_object(
    'success', true,
    'pedido_id', p_pedido_id,
    'prioridade', v_prio
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.definir_prioridade_producao FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.definir_prioridade_producao TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 9. RPC: ADICIONAR_OBSERVACAO_PRODUCAO
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.adicionar_observacao_producao(
  p_pedido_id BIGINT,
  p_observacao TEXT,
  p_categoria TEXT DEFAULT 'geral'
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_obs TEXT := NULLIF(TRIM(COALESCE(p_observacao, '')), '');
  v_cat TEXT := LOWER(TRIM(COALESCE(p_categoria, 'geral')));
  v_usuario_nome TEXT;
  v_obs_id BIGINT;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas equipe pode adicionar notas de produção.');
  END IF;

  IF p_pedido_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_ID_REQUIRED', 'error', 'ID do pedido é obrigatório.');
  END IF;

  IF v_obs IS NULL OR length(v_obs) < 2 THEN
    RETURN jsonb_build_object('success', false, 'code', 'OBSERVATION_REQUIRED', 'error', 'Observação de produção não pode ser vazia.');
  END IF;

  IF v_cat NOT IN ('geral', 'cozinha', 'embalagem', 'entrega', 'alergia') THEN
    v_cat := 'geral';
  END IF;

  SELECT COALESCE(nome, email, 'Equipe') INTO v_usuario_nome 
  FROM public.profiles WHERE id = auth.uid();

  INSERT INTO public.pedido_producao_observacoes (
    pedido_id, observacao, categoria, autor_id, autor_nome, ativo, created_at
  ) VALUES (
    p_pedido_id, v_obs, v_cat, auth.uid(), v_usuario_nome, true, NOW()
  ) RETURNING id INTO v_obs_id;

  RETURN jsonb_build_object(
    'success', true,
    'observacao_id', v_obs_id,
    'pedido_id', p_pedido_id,
    'categoria', v_cat,
    'observacao', v_obs
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.adicionar_observacao_producao FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.adicionar_observacao_producao TO authenticated, service_role;


-- ==========================================================================
-- >>> MIGRATION 021_dashboard_gerencial_indicadores.sql
-- ==========================================================================

-- ==========================================================================
-- LUNOCA DOCERIA - MIGRATION 021: DASHBOARD GERENCIAL, DRE & INDICADORES (FRENTE F)
-- ==========================================================================
-- Objetivo:
-- Projeções analíticas server-side sobre os dados canônicos existentes:
-- 1. Separação Contábil Estrita (Invariante Central):
--    Vendas Confirmadas != Faturamento Realizado != Entrada de Caixa Líquida != Crédito Utilizado
-- 2. Não cria tabelas estáticas de métricas; cálculo sob demanda por período.
-- 3. Timezone canônico: America/Fortaleza com bounds [inicio 00:00:00, fim + 1 dia 00:00:00)
-- 4. Segregação de Privilégios (RBAC):
--    - Admin: acesso a faturamento, DRE, caixa, saldos de crédito e ranking financeiro.
--    - Operador: acesso restrito a volumes, carga produtiva e capacidade (sem chaves financeiras).
--    - Anon/Cliente: fail-closed (PERMISSION_DENIED e REVOKE nativo).
-- ==========================================================================

-- --------------------------------------------------------------------------
-- 1. HELPER INTERNO: RESOLUÇÃO DE JANELA TEMPORAL CANÔNICA
-- --------------------------------------------------------------------------
-- Converte p_data_inicio e p_data_fim para timestamptz fechado em [inicio 00:00, fim+1 00:00)
CREATE OR REPLACE FUNCTION public._dashboard_resolver_datas(
  p_data_inicio DATE,
  p_data_fim DATE,
  OUT v_inicio_ts TIMESTAMPTZ,
  OUT v_fim_ts TIMESTAMPTZ,
  OUT v_inicio_date DATE,
  OUT v_fim_date DATE
)
AS $$
BEGIN
  v_inicio_date := COALESCE(p_data_inicio, (date_trunc('month', (NOW() AT TIME ZONE 'America/Fortaleza')::DATE))::DATE);
  v_fim_date := COALESCE(p_data_fim, (NOW() AT TIME ZONE 'America/Fortaleza')::DATE);

  IF v_fim_date < v_inicio_date THEN
    RAISE EXCEPTION 'Data final (%) não pode ser anterior à data inicial (%).', v_fim_date, v_inicio_date
      USING ERRCODE = '22023';
  END IF;

  -- Limite preventivo de 366 dias por consulta
  IF (v_fim_date - v_inicio_date) > 366 THEN
    v_inicio_date := (v_fim_date - INTERVAL '366 days')::DATE;
  END IF;

  v_inicio_ts := (v_inicio_date::TEXT || ' 00:00:00')::TIMESTAMP AT TIME ZONE 'America/Fortaleza';
  v_fim_ts := ((v_fim_date + 1)::TEXT || ' 00:00:00')::TIMESTAMP AT TIME ZONE 'America/Fortaleza';
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public._dashboard_resolver_datas(DATE, DATE) FROM PUBLIC, anon, authenticated;

-- --------------------------------------------------------------------------
-- 2. RPC: OBTER_INDICADORES_VENDAS_ADMIN
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.obter_indicadores_vendas_admin(
  p_data_inicio DATE DEFAULT NULL,
  p_data_fim DATE DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_inicio_ts TIMESTAMPTZ;
  v_fim_ts TIMESTAMPTZ;
  v_inicio_date DATE;
  v_fim_date DATE;

  v_vendas_conf_qtd BIGINT := 0;
  v_vendas_conf_val NUMERIC(10,2) := 0.00;

  v_ped_conc_qtd BIGINT := 0;
  v_fat_realizado NUMERIC(10,2) := 0.00;
  v_ticket_max NUMERIC(10,2) := 0.00;
  v_ticket_medio NUMERIC(10,2) := 0.00;

  v_ped_canc_qtd BIGINT := 0;
  v_taxa_canc NUMERIC(5,2) := 0.00;

  v_entrega_qtd BIGINT := 0;
  v_retirada_qtd BIGINT := 0;

  v_orc_emit_qtd BIGINT := 0;
  v_orc_conv_qtd BIGINT := 0;
  v_taxa_conv NUMERIC(5,2) := 0.00;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PERMISSION_DENIED',
      'error', 'Apenas administradores podem acessar os indicadores de vendas.'
    );
  END IF;

  SELECT * INTO v_inicio_ts, v_fim_ts, v_inicio_date, v_fim_date
  FROM public._dashboard_resolver_datas(p_data_inicio, p_data_fim);

  -- 1. Vendas Confirmadas no período (primeira transição para 'confirmado' na janela e não cancelados)
  SELECT
    COALESCE(COUNT(DISTINCT p.id), 0),
    COALESCE(SUM(p.total), 0.00)
  INTO v_vendas_conf_qtd, v_vendas_conf_val
  FROM public.pedidos p
  JOIN (
    SELECT pedido_id, MIN(created_at) AS primeiro_conf_at
    FROM public.pedido_status_historico
    WHERE dimensao = 'comercial' AND status_novo = 'confirmado'
    GROUP BY pedido_id
  ) conf ON conf.pedido_id = p.id
  WHERE conf.primeiro_conf_at >= v_inicio_ts AND conf.primeiro_conf_at < v_fim_ts
    AND p.status_comercial <> 'cancelado';

  -- 2. Faturamento Realizado (transição comercial para 'concluido' dentro do período)
  SELECT
    COALESCE(COUNT(DISTINCT p.id), 0),
    COALESCE(SUM(p.total), 0.00),
    COALESCE(MAX(p.total), 0.00)
  INTO v_ped_conc_qtd, v_fat_realizado, v_ticket_max
  FROM public.pedidos p
  JOIN (
    SELECT pedido_id, MIN(created_at) AS primeiro_conc_at
    FROM public.pedido_status_historico
    WHERE dimensao = 'comercial' AND status_novo = 'concluido'
    GROUP BY pedido_id
  ) conc ON conc.pedido_id = p.id
  WHERE conc.primeiro_conc_at >= v_inicio_ts AND conc.primeiro_conc_at < v_fim_ts;

  IF v_ped_conc_qtd > 0 THEN
    v_ticket_medio := ROUND(v_fat_realizado / v_ped_conc_qtd, 2);
  END IF;

  -- 3. Pedidos Cancelados no período
  SELECT COALESCE(COUNT(DISTINCT h.pedido_id), 0)
  INTO v_ped_canc_qtd
  FROM public.pedido_status_historico h
  WHERE h.dimensao = 'comercial' AND h.status_novo = 'cancelado'
    AND h.created_at >= v_inicio_ts AND h.created_at < v_fim_ts;

  IF (v_vendas_conf_qtd + v_ped_canc_qtd) > 0 THEN
    v_taxa_canc := ROUND((v_ped_canc_qtd * 100.0) / (v_vendas_conf_qtd + v_ped_canc_qtd), 2);
  END IF;

  -- 4. Pedidos por Modalidade (entrega vs retirada) dos concluídos no período
  SELECT
    COALESCE(COUNT(*) FILTER (WHERE COALESCE(p.modalidade_entrega, 'retirada') = 'entrega'), 0),
    COALESCE(COUNT(*) FILTER (WHERE COALESCE(p.modalidade_entrega, 'retirada') = 'retirada'), 0)
  INTO v_entrega_qtd, v_retirada_qtd
  FROM public.pedidos p
  JOIN (
    SELECT pedido_id, MIN(created_at) AS conc_at
    FROM public.pedido_status_historico
    WHERE dimensao = 'comercial' AND status_novo = 'concluido'
    GROUP BY pedido_id
  ) c ON c.pedido_id = p.id
  WHERE c.conc_at >= v_inicio_ts AND c.conc_at < v_fim_ts;

  -- 5. Orçamentos Emitidos e Convertidos
  SELECT COALESCE(COUNT(*), 0) INTO v_orc_emit_qtd
  FROM public.orcamentos
  WHERE created_at >= v_inicio_ts AND created_at < v_fim_ts;

  SELECT COALESCE(COUNT(*), 0) INTO v_orc_conv_qtd
  FROM public.orcamentos
  WHERE status = 'convertido' AND convertido_em >= v_inicio_ts AND convertido_em < v_fim_ts;

  IF v_orc_emit_qtd > 0 THEN
    v_taxa_conv := ROUND((v_orc_conv_qtd * 100.0) / v_orc_emit_qtd, 2);
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'periodo', jsonb_build_object(
      'data_inicio', v_inicio_date,
      'data_fim', v_fim_date,
      'timezone', 'America/Fortaleza'
    ),
    'vendas_confirmadas_quantidade', v_vendas_conf_qtd,
    'vendas_confirmadas_valor', v_vendas_conf_val,
    'pedidos_concluidos_quantidade', v_ped_conc_qtd,
    'faturamento_realizado', v_fat_realizado,
    'ticket_medio_realizado', v_ticket_medio,
    'ticket_maximo', v_ticket_max,
    'pedidos_cancelados', v_ped_canc_qtd,
    'taxa_cancelamento', v_taxa_canc,
    'entrega_quantidade', v_entrega_qtd,
    'retirada_quantidade', v_retirada_qtd,
    'orcamentos_emitidos', v_orc_emit_qtd,
    'orcamentos_convertidos', v_orc_conv_qtd,
    'taxa_conversao', v_taxa_conv
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_indicadores_vendas_admin(DATE, DATE) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_indicadores_vendas_admin(DATE, DATE) TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 3. RPC: OBTER_INDICADORES_FINANCEIROS_ADMIN
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.obter_indicadores_financeiros_admin(
  p_data_inicio DATE DEFAULT NULL,
  p_data_fim DATE DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_inicio_ts TIMESTAMPTZ;
  v_fim_ts TIMESTAMPTZ;
  v_inicio_date DATE;
  v_fim_date DATE;

  v_rec_pix NUMERIC(10,2) := 0.00;
  v_rec_cartao NUMERIC(10,2) := 0.00;
  v_rec_dinheiro NUMERIC(10,2) := 0.00;
  v_rec_transf NUMERIC(10,2) := 0.00;
  v_rec_outro NUMERIC(10,2) := 0.00;
  v_entrada_bruta NUMERIC(10,2) := 0.00;

  v_estornos NUMERIC(10,2) := 0.00;
  v_entrada_liquida NUMERIC(10,2) := 0.00;

  v_credito_utilizado NUMERIC(10,2) := 0.00;
  v_saldo_cred_fim NUMERIC(10,2) := 0.00;
  v_saldo_cred_atual NUMERIC(10,2) := 0.00;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PERMISSION_DENIED',
      'error', 'Apenas administradores podem acessar os indicadores financeiros.'
    );
  END IF;

  SELECT * INTO v_inicio_ts, v_fim_ts, v_inicio_date, v_fim_date
  FROM public._dashboard_resolver_datas(p_data_inicio, p_data_fim);

  -- 1. Entrada de Caixa Bruta por meio de pagamento externo recebido na janela
  -- Considera pagamentos aprovados em pedido_pagamentos (excluindo crédito que não é entrada externa)
  SELECT
    COALESCE(SUM(valor) FILTER (WHERE metodo = 'pix'), 0.00),
    COALESCE(SUM(valor) FILTER (WHERE metodo = 'cartao'), 0.00),
    COALESCE(SUM(valor) FILTER (WHERE metodo = 'dinheiro'), 0.00),
    COALESCE(SUM(valor) FILTER (WHERE metodo = 'transferencia'), 0.00),
    COALESCE(SUM(valor) FILTER (WHERE metodo NOT IN ('pix', 'cartao', 'dinheiro', 'transferencia')), 0.00),
    COALESCE(SUM(valor), 0.00)
  INTO v_rec_pix, v_rec_cartao, v_rec_dinheiro, v_rec_transf, v_rec_outro, v_entrada_bruta
  FROM public.pedido_pagamentos
  WHERE status IN ('aprovado', 'estornado')
    AND pago_em >= v_inicio_ts AND pago_em < v_fim_ts;

  -- 2. Estornos efetivados na janela (registrados no DRE ou pagamentos estornados no período)
  SELECT COALESCE(SUM(valor), 0.00)
  INTO v_estornos
  FROM public.financeiro_lancamentos
  WHERE tipo = 'despesa' AND categoria = 'Estornos'
    AND created_at >= v_inicio_ts AND created_at < v_fim_ts;

  v_entrada_liquida := GREATEST(0.00, v_entrada_bruta - v_estornos);

  -- 3. Crédito do cliente utilizado no período (livro-razão da Frente C)
  SELECT COALESCE(SUM(valor), 0.00)
  INTO v_credito_utilizado
  FROM public.cliente_credito_movimentacoes
  WHERE tipo = 'debito' AND origem = 'uso_pedido'
    AND created_at >= v_inicio_ts AND created_at < v_fim_ts;

  -- 4. Saldo de créditos histórico (reconstruído até o fim do período)
  SELECT COALESCE(SUM(CASE WHEN tipo = 'credito' THEN valor ELSE -valor END), 0.00)
  INTO v_saldo_cred_fim
  FROM public.cliente_credito_movimentacoes
  WHERE created_at < v_fim_ts;

  -- 5. Saldo de créditos atual na carteira consolidada
  SELECT COALESCE(SUM(saldo), 0.00)
  INTO v_saldo_cred_atual
  FROM public.cliente_creditos;

  RETURN jsonb_build_object(
    'success', true,
    'periodo', jsonb_build_object(
      'data_inicio', v_inicio_date,
      'data_fim', v_fim_date,
      'timezone', 'America/Fortaleza'
    ),
    'entrada_caixa_bruta', v_entrada_bruta,
    'estornos_caixa', v_estornos,
    'entrada_caixa_liquida', v_entrada_liquida,
    'recebido_pix', v_rec_pix,
    'recebido_cartao', v_rec_cartao,
    'recebido_dinheiro', v_rec_dinheiro,
    'recebido_transferencia', v_rec_transf,
    'recebido_outro', v_rec_outro,
    'credito_cliente_utilizado', v_credito_utilizado,
    'saldo_creditos_fim_periodo', v_saldo_cred_fim,
    'saldo_creditos_atual', v_saldo_cred_atual
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_indicadores_financeiros_admin(DATE, DATE) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_indicadores_financeiros_admin(DATE, DATE) TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 4. RPC: OBTER_INDICADORES_PRODUCAO (ADMIN & OPERADOR)
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.obter_indicadores_producao(
  p_data_inicio DATE DEFAULT NULL,
  p_data_fim DATE DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_inicio_ts TIMESTAMPTZ;
  v_fim_ts TIMESTAMPTZ;
  v_inicio_date DATE;
  v_fim_date DATE;

  v_pontos_total NUMERIC(10,2) := 0.00;
  v_cap_total NUMERIC(10,2) := 0.00;
  v_ocup_perc NUMERIC(5,2) := 0.00;

  v_dias_normais INT := 0;
  v_dias_prox_lim INT := 0;
  v_dias_lotados INT := 0;
  v_dias_excedidos INT := 0;
  v_dias_bloqueados INT := 0;
  v_total_dias INT := 0;
BEGIN
  IF NOT public.is_admin_or_operator() THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PERMISSION_DENIED',
      'error', 'Apenas a equipe autorizada pode visualizar indicadores de produção.'
    );
  END IF;

  SELECT * INTO v_inicio_ts, v_fim_ts, v_inicio_date, v_fim_date
  FROM public._dashboard_resolver_datas(p_data_inicio, p_data_fim);

  -- Itera dia a dia na série temporal da janela
  SELECT
    COALESCE(SUM(t.pts_dia), 0.00),
    COALESCE(SUM(t.cap_dia), 0.00),
    COALESCE(COUNT(*) FILTER (WHERE t.status_cap = 'normal'), 0),
    COALESCE(COUNT(*) FILTER (WHERE t.status_cap = 'proximo_limite'), 0),
    COALESCE(COUNT(*) FILTER (WHERE t.status_cap = 'lotado'), 0),
    COALESCE(COUNT(*) FILTER (WHERE t.status_cap = 'excedido'), 0),
    COALESCE(COUNT(*) FILTER (WHERE t.bloqueado = true), 0),
    COALESCE(COUNT(*), 0)
  INTO
    v_pontos_total,
    v_cap_total,
    v_dias_normais,
    v_dias_prox_lim,
    v_dias_lotados,
    v_dias_excedidos,
    v_dias_bloqueados,
    v_total_dias
  FROM (
    SELECT
      d.dia::DATE AS dt,
      public.pontos_ocupados_data(d.dia::DATE) AS pts_dia,
      COALESCE(cp.capacidade_maxima_pontos, 30.00) AS cap_dia,
      COALESCE(cp.bloqueado, false) AS bloqueado,
      CASE
        WHEN COALESCE(cp.bloqueado, false) THEN 'bloqueado'
        WHEN public.pontos_ocupados_data(d.dia::DATE) > COALESCE(cp.capacidade_maxima_pontos, 30.00) THEN 'excedido'
        WHEN public.pontos_ocupados_data(d.dia::DATE) >= COALESCE(cp.capacidade_maxima_pontos, 30.00) THEN 'lotado'
        WHEN public.pontos_ocupados_data(d.dia::DATE) >= (COALESCE(cp.capacidade_maxima_pontos, 30.00) * 0.80) THEN 'proximo_limite'
        ELSE 'normal'
      END AS status_cap
    FROM generate_series(v_inicio_date::TIMESTAMP, v_fim_date::TIMESTAMP, '1 day'::INTERVAL) d(dia)
    LEFT JOIN public.capacidade_producao cp ON cp.data = d.dia::DATE
  ) t;

  IF v_cap_total > 0 THEN
    v_ocup_perc := ROUND((v_pontos_total * 100.0) / v_cap_total, 2);
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'periodo', jsonb_build_object(
      'data_inicio', v_inicio_date,
      'data_fim', v_fim_date,
      'total_dias', v_total_dias
    ),
    'pontos_producao', v_pontos_total,
    'capacidade_total', v_cap_total,
    'ocupacao_percentual', v_ocup_perc,
    'dias_normais', v_dias_normais,
    'dias_proximo_limite', v_dias_prox_lim,
    'dias_lotados', v_dias_lotados,
    'dias_excedidos', v_dias_excedidos,
    'dias_bloqueados', v_dias_bloqueados
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_indicadores_producao(DATE, DATE) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_indicadores_producao(DATE, DATE) TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 5. RPC: OBTER_INDICADORES_CLIENTES_ADMIN
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.obter_indicadores_clientes_admin(
  p_data_inicio DATE DEFAULT NULL,
  p_data_fim DATE DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_inicio_ts TIMESTAMPTZ;
  v_fim_ts TIMESTAMPTZ;
  v_inicio_date DATE;
  v_fim_date DATE;

  v_clientes_ativos BIGINT := 0;
  v_clientes_novos BIGINT := 0;
  v_clientes_recorrentes BIGINT := 0;
  v_taxa_recorrencia NUMERIC(5,2) := 0.00;
  v_top_clientes JSONB := '[]'::jsonb;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PERMISSION_DENIED',
      'error', 'Apenas administradores podem acessar os indicadores de clientes.'
    );
  END IF;

  SELECT * INTO v_inicio_ts, v_fim_ts, v_inicio_date, v_fim_date
  FROM public._dashboard_resolver_datas(p_data_inicio, p_data_fim);

  -- 1. Clientes Ativos (clientes vinculados a pedidos concluídos ou confirmados no período)
  SELECT COUNT(DISTINCT p.cliente_id_rel)
  INTO v_clientes_ativos
  FROM public.pedidos p
  JOIN public.pedido_status_historico h ON h.pedido_id = p.id
  WHERE p.cliente_id_rel IS NOT NULL
    AND h.dimensao = 'comercial' AND h.status_novo IN ('confirmado', 'concluido')
    AND h.created_at >= v_inicio_ts AND h.created_at < v_fim_ts;

  -- 2. Clientes Novos (primeiro pedido concluído na vida ocorreu exatamente nesta janela)
  SELECT COUNT(DISTINCT c_primeiro.cliente_id_rel)
  INTO v_clientes_novos
  FROM (
    SELECT p.cliente_id_rel, MIN(h.created_at) AS primeiro_concluido_at
    FROM public.pedidos p
    JOIN public.pedido_status_historico h ON h.pedido_id = p.id
    WHERE p.cliente_id_rel IS NOT NULL
      AND h.dimensao = 'comercial' AND h.status_novo = 'concluido'
    GROUP BY p.cliente_id_rel
  ) c_primeiro
  WHERE c_primeiro.primeiro_concluido_at >= v_inicio_ts AND c_primeiro.primeiro_concluido_at < v_fim_ts;

  -- 3. Clientes Recorrentes (compraram no período e já possuíam pedido concluído anterior)
  SELECT COUNT(DISTINCT p.cliente_id_rel)
  INTO v_clientes_recorrentes
  FROM public.pedidos p
  JOIN public.pedido_status_historico h ON h.pedido_id = p.id
  WHERE p.cliente_id_rel IS NOT NULL
    AND h.dimensao = 'comercial' AND h.status_novo = 'concluido'
    AND h.created_at >= v_inicio_ts AND h.created_at < v_fim_ts
    AND EXISTS (
      SELECT 1 FROM public.pedido_status_historico h_ant
      JOIN public.pedidos p_ant ON p_ant.id = h_ant.pedido_id
      WHERE p_ant.cliente_id_rel = p.cliente_id_rel
        AND h_ant.dimensao = 'comercial' AND h_ant.status_novo = 'concluido'
        AND h_ant.created_at < v_inicio_ts
    );

  IF v_clientes_ativos > 0 THEN
    v_taxa_recorrencia := ROUND((v_clientes_recorrentes * 100.0) / v_clientes_ativos, 2);
  END IF;

  -- 4. Top Clientes por valor_historico_compras (somente pedidos concluídos)
  SELECT COALESCE(jsonb_agg(top_row), '[]'::jsonb)
  INTO v_top_clientes
  FROM (
    SELECT
      c.id AS cliente_id,
      c.nome,
      COUNT(DISTINCT p.id) AS pedidos,
      COALESCE(SUM(p.total), 0.00) AS valor_historico_compras
    FROM public.clientes c
    JOIN public.pedidos p ON p.cliente_id_rel = c.id
    JOIN public.pedido_status_historico h ON h.pedido_id = p.id
    WHERE h.dimensao = 'comercial' AND h.status_novo = 'concluido'
      AND h.created_at < v_fim_ts
    GROUP BY c.id, c.nome
    ORDER BY valor_historico_compras DESC, pedidos DESC
    LIMIT 10
  ) top_row;

  RETURN jsonb_build_object(
    'success', true,
    'periodo', jsonb_build_object(
      'data_inicio', v_inicio_date,
      'data_fim', v_fim_date
    ),
    'clientes_ativos', v_clientes_ativos,
    'clientes_novos', v_clientes_novos,
    'clientes_recorrentes', v_clientes_recorrentes,
    'taxa_recorrencia', v_taxa_recorrencia,
    'top_clientes', v_top_clientes
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_indicadores_clientes_admin(DATE, DATE) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_indicadores_clientes_admin(DATE, DATE) TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 6. RPC: OBTER_DASHBOARD_OPERACIONAL (ADMIN & OPERADOR - SEM CAMPOS FINANCEIROS)
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.obter_dashboard_operacional(
  p_data_inicio DATE DEFAULT NULL,
  p_data_fim DATE DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_inicio_ts TIMESTAMPTZ;
  v_fim_ts TIMESTAMPTZ;
  v_inicio_date DATE;
  v_fim_date DATE;

  v_ind_prod JSONB;
  v_vendas_qtd BIGINT := 0;
  v_concluidos_qtd BIGINT := 0;
  v_cancelados_qtd BIGINT := 0;
  v_em_producao_qtd BIGINT := 0;
  v_aguardando_qtd BIGINT := 0;
  v_prontos_qtd BIGINT := 0;

  v_entrega_qtd BIGINT := 0;
  v_retirada_qtd BIGINT := 0;
BEGIN
  IF NOT public.is_admin_or_operator() THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PERMISSION_DENIED',
      'error', 'Apenas a equipe autorizada pode visualizar o dashboard operacional.'
    );
  END IF;

  SELECT * INTO v_inicio_ts, v_fim_ts, v_inicio_date, v_fim_date
  FROM public._dashboard_resolver_datas(p_data_inicio, p_data_fim);

  -- Indicadores de capacidade da cozinha
  v_ind_prod := public.obter_indicadores_producao(v_inicio_date, v_fim_date);

  -- Volumes de pedidos com entrega na janela
  SELECT
    COALESCE(COUNT(*), 0),
    COALESCE(COUNT(*) FILTER (WHERE status_comercial = 'concluido'), 0),
    COALESCE(COUNT(*) FILTER (WHERE status_comercial = 'cancelado'), 0),
    COALESCE(COUNT(*) FILTER (WHERE status_operacional = 'em_producao'), 0),
    COALESCE(COUNT(*) FILTER (WHERE status_operacional = 'aguardando_producao'), 0),
    COALESCE(COUNT(*) FILTER (WHERE status_operacional = 'pronto'), 0),
    COALESCE(COUNT(*) FILTER (WHERE COALESCE(modalidade_entrega, 'retirada') = 'entrega'), 0),
    COALESCE(COUNT(*) FILTER (WHERE COALESCE(modalidade_entrega, 'retirada') = 'retirada'), 0)
  INTO
    v_vendas_qtd,
    v_concluidos_qtd,
    v_cancelados_qtd,
    v_em_producao_qtd,
    v_aguardando_qtd,
    v_prontos_qtd,
    v_entrega_qtd,
    v_retirada_qtd
  FROM public.pedidos
  WHERE data_entrega BETWEEN v_inicio_date AND v_fim_date;

  -- PAYLOAD SANITIZADO: sem faturamento, sem caixa, sem crédito, sem DRE, sem valores R$
  RETURN jsonb_build_object(
    'success', true,
    'periodo', jsonb_build_object(
      'data_inicio', v_inicio_date,
      'data_fim', v_fim_date
    ),
    'volumes_pedidos', jsonb_build_object(
      'total_agendados', v_vendas_qtd,
      'concluidos', v_concluidos_qtd,
      'cancelados', v_cancelados_qtd,
      'aguardando_producao', v_aguardando_qtd,
      'em_producao', v_em_producao_qtd,
      'prontos_expedicao', v_prontos_qtd,
      'entrega_quantidade', v_entrega_qtd,
      'retirada_quantidade', v_retirada_qtd
    ),
    'producao', v_ind_prod
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_dashboard_operacional(DATE, DATE) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_dashboard_operacional(DATE, DATE) TO authenticated, service_role;

-- --------------------------------------------------------------------------
-- 7. RPC: OBTER_DASHBOARD_RESUMO_ADMIN (CONSOLIDADO EXECUTIVO)
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.obter_dashboard_resumo_admin(
  p_data_inicio DATE DEFAULT NULL,
  p_data_fim DATE DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_vendas JSONB;
  v_financeiro JSONB;
  v_producao JSONB;
  v_clientes JSONB;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PERMISSION_DENIED',
      'error', 'Apenas administradores podem visualizar o resumo executivo do dashboard.'
    );
  END IF;

  v_vendas := public.obter_indicadores_vendas_admin(p_data_inicio, p_data_fim);
  v_financeiro := public.obter_indicadores_financeiros_admin(p_data_inicio, p_data_fim);
  v_producao := public.obter_indicadores_producao(p_data_inicio, p_data_fim);
  v_clientes := public.obter_indicadores_clientes_admin(p_data_inicio, p_data_fim);

  RETURN jsonb_build_object(
    'success', true,
    'vendas', v_vendas,
    'financeiro', v_financeiro,
    'producao', v_producao,
    'clientes', v_clientes
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_dashboard_resumo_admin(DATE, DATE) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_dashboard_resumo_admin(DATE, DATE) TO authenticated, service_role;


-- ==========================================================================
-- >>> MIGRATION 022_compras_fornecedores_estoque_insumos.sql
-- ==========================================================================

-- ==============================================================================
-- LUNOCA DOCERIA - MIGRATION 022: COMPRAS, FORNECEDORES, ESTOQUE DE INSUMOS E CMV REAL (FRENTE G)
-- ==============================================================================
-- Esta migration implementa a camada transacional de abastecimento e custos reais:
-- 1. Fornecedores (public.fornecedores)
-- 2. Saldos e Custo Médio Ponderado de Insumos (public.ingrediente_saldos)
-- 3. Livro-Razão Imutável de Movimentações de Insumos (public.ingrediente_movimentacoes)
-- 4. Pedidos de Compra e Itens (public.compras, public.compra_itens)
-- 5. Contas a Pagar de Fornecedores (public.contas_pagar) integrada ao DRE
-- 6. RPCs Transacionais:
--    - salvar_fornecedor_admin / listar_fornecedores_admin
--    - criar_compra / receber_compra / cancelar_compra
--    - registrar_perda_insumo / ajustar_estoque_insumo_admin
--    - registrar_pagamento_fornecedor
--    - obter_necessidade_reposicao / obter_cmv_real_produto
-- ==============================================================================

-- ------------------------------------------------------------------------------
-- 1. TABELA DE FORNECEDORES
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.fornecedores (
  id BIGSERIAL PRIMARY KEY,
  nome TEXT NOT NULL CHECK (char_length(btrim(nome)) >= 2),
  documento TEXT,
  telefone TEXT,
  telefone_normalizado TEXT,
  email TEXT,
  contato_nome TEXT,
  observacoes TEXT,
  ativo BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_fornecedores_nome ON public.fornecedores(nome);
CREATE INDEX IF NOT EXISTS idx_fornecedores_ativo ON public.fornecedores(ativo);

ALTER TABLE public.fornecedores ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS fornecedores_select_staff ON public.fornecedores;
CREATE POLICY fornecedores_select_staff ON public.fornecedores
  FOR SELECT TO authenticated
  USING (public.is_admin_or_operator());

DROP POLICY IF EXISTS fornecedores_write_admin ON public.fornecedores;
CREATE POLICY fornecedores_write_admin ON public.fornecedores
  FOR ALL TO authenticated
  USING (public.is_admin())
  WITH CHECK (public.is_admin());

REVOKE ALL ON public.fornecedores FROM PUBLIC, anon;
GRANT SELECT ON public.fornecedores TO authenticated;
GRANT ALL ON public.fornecedores TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.fornecedores_id_seq TO service_role;

-- ------------------------------------------------------------------------------
-- 2. EXTENSÃO DE PUBLIC.INGREDIENTES & TABELA DE SALDOS / CUSTO MÉDIO
-- ------------------------------------------------------------------------------
ALTER TABLE public.ingredientes
  ADD COLUMN IF NOT EXISTS custo_medio_unitario NUMERIC(12,4) NOT NULL DEFAULT 0.0000,
  ADD COLUMN IF NOT EXISTS ultimo_custo_compra NUMERIC(12,4) NOT NULL DEFAULT 0.0000,
  ADD COLUMN IF NOT EXISTS fornecedor_padrao_id BIGINT REFERENCES public.fornecedores(id) ON DELETE SET NULL;

-- Backfill inicial: se custo_medio_unitario for 0 e custo_unitario > 0, inicializa com custo_unitario
UPDATE public.ingredientes
SET
  custo_medio_unitario = custo_unitario,
  ultimo_custo_compra = custo_unitario
WHERE custo_medio_unitario = 0 AND custo_unitario > 0;

CREATE TABLE IF NOT EXISTS public.ingrediente_saldos (
  ingrediente_id BIGINT PRIMARY KEY REFERENCES public.ingredientes(id) ON DELETE RESTRICT,
  saldo_atual NUMERIC(12,3) NOT NULL DEFAULT 0.000 CHECK (saldo_atual >= 0),
  custo_medio_ponderado NUMERIC(12,4) NOT NULL DEFAULT 0.0000 CHECK (custo_medio_ponderado >= 0),
  ultimo_custo_compra NUMERIC(12,4) NOT NULL DEFAULT 0.0000 CHECK (ultimo_custo_compra >= 0),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Sincronização inicial de saldos a partir de public.ingredientes
INSERT INTO public.ingrediente_saldos (ingrediente_id, saldo_atual, custo_medio_ponderado, ultimo_custo_compra, updated_at)
SELECT
  i.id,
  GREATEST(0, COALESCE(i.estoque_qtd, 0)),
  GREATEST(0, COALESCE(NULLIF(i.custo_medio_unitario, 0), i.custo_unitario, 0)),
  GREATEST(0, COALESCE(NULLIF(i.ultimo_custo_compra, 0), i.custo_unitario, 0)),
  NOW()
FROM public.ingredientes i
ON CONFLICT (ingrediente_id) DO NOTHING;

-- Trigger para criar linha em ingrediente_saldos sempre que um novo ingrediente for cadastrado
CREATE OR REPLACE FUNCTION public._trg_inicializar_saldo_ingrediente()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.ingrediente_saldos (
    ingrediente_id, saldo_atual, custo_medio_ponderado, ultimo_custo_compra, updated_at
  ) VALUES (
    NEW.id,
    GREATEST(0, COALESCE(NEW.estoque_qtd, 0)),
    GREATEST(0, COALESCE(NULLIF(NEW.custo_medio_unitario, 0), NEW.custo_unitario, 0)),
    GREATEST(0, COALESCE(NULLIF(NEW.ultimo_custo_compra, 0), NEW.custo_unitario, 0)),
    NOW()
  )
  ON CONFLICT (ingrediente_id) DO NOTHING;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

DROP TRIGGER IF EXISTS trg_inicializar_saldo_ingrediente ON public.ingredientes;
CREATE TRIGGER trg_inicializar_saldo_ingrediente
  AFTER INSERT ON public.ingredientes
  FOR EACH ROW
  EXECUTE FUNCTION public._trg_inicializar_saldo_ingrediente();

ALTER TABLE public.ingrediente_saldos ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS ingrediente_saldos_select_staff ON public.ingrediente_saldos;
CREATE POLICY ingrediente_saldos_select_staff ON public.ingrediente_saldos
  FOR SELECT TO authenticated
  USING (public.is_admin_or_operator());

REVOKE ALL ON public.ingrediente_saldos FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.ingrediente_saldos TO authenticated;
GRANT ALL ON public.ingrediente_saldos TO service_role;

-- ------------------------------------------------------------------------------
-- 3. COMPRAS E ITENS DE COMPRA
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.compras (
  id BIGSERIAL PRIMARY KEY,
  numero_nota TEXT,
  fornecedor_id BIGINT NOT NULL REFERENCES public.fornecedores(id) ON DELETE RESTRICT,
  status TEXT NOT NULL DEFAULT 'aberta' CHECK (status IN ('aberta', 'recebida', 'cancelada')),
  data_compra DATE NOT NULL DEFAULT CURRENT_DATE,
  data_recebimento TIMESTAMPTZ,
  valor_subtotal NUMERIC(12,2) NOT NULL DEFAULT 0.00 CHECK (valor_subtotal >= 0),
  valor_frete NUMERIC(12,2) NOT NULL DEFAULT 0.00 CHECK (valor_frete >= 0),
  valor_desconto NUMERIC(12,2) NOT NULL DEFAULT 0.00 CHECK (valor_desconto >= 0),
  valor_total NUMERIC(12,2) NOT NULL DEFAULT 0.00 CHECK (valor_total >= 0),
  observacoes TEXT,
  motivo_cancelamento TEXT,
  criado_por UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  recebido_por UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  cancelado_por UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  idempotency_key TEXT UNIQUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_compras_fornecedor ON public.compras(fornecedor_id);
CREATE INDEX IF NOT EXISTS idx_compras_status ON public.compras(status);
CREATE INDEX IF NOT EXISTS idx_compras_data ON public.compras(data_compra);

CREATE TABLE IF NOT EXISTS public.compra_itens (
  id BIGSERIAL PRIMARY KEY,
  compra_id BIGINT NOT NULL REFERENCES public.compras(id) ON DELETE CASCADE,
  ingrediente_id BIGINT NOT NULL REFERENCES public.ingredientes(id) ON DELETE RESTRICT,
  quantidade NUMERIC(12,3) NOT NULL CHECK (quantidade > 0),
  unidade VARCHAR(10) NOT NULL DEFAULT 'g',
  custo_unitario NUMERIC(12,4) NOT NULL CHECK (custo_unitario >= 0),
  custo_unitario_efetivo NUMERIC(12,4) NOT NULL DEFAULT 0.0000 CHECK (custo_unitario_efetivo >= 0),
  subtotal NUMERIC(12,2) NOT NULL CHECK (subtotal >= 0),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_compra_ingrediente UNIQUE (compra_id, ingrediente_id)
);

CREATE INDEX IF NOT EXISTS idx_compra_itens_compra ON public.compra_itens(compra_id);
CREATE INDEX IF NOT EXISTS idx_compra_itens_ingrediente ON public.compra_itens(ingrediente_id);

ALTER TABLE public.compras ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.compra_itens ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS compras_select_admin ON public.compras;
CREATE POLICY compras_select_admin ON public.compras
  FOR SELECT TO authenticated
  USING (public.is_admin());

DROP POLICY IF EXISTS compra_itens_select_admin ON public.compra_itens;
CREATE POLICY compra_itens_select_admin ON public.compra_itens
  FOR SELECT TO authenticated
  USING (public.is_admin());

REVOKE ALL ON public.compras FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.compra_itens FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.compras TO authenticated;
GRANT SELECT ON public.compra_itens TO authenticated;
GRANT ALL ON public.compras TO service_role;
GRANT ALL ON public.compra_itens TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.compras_id_seq TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.compra_itens_id_seq TO service_role;

-- ------------------------------------------------------------------------------
-- 4. LIVRO-RAZÃO IMUTÁVEL DE MOVIMENTAÇÕES DE INSUMOS
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.ingrediente_movimentacoes (
  id BIGSERIAL PRIMARY KEY,
  ingrediente_id BIGINT NOT NULL REFERENCES public.ingredientes(id) ON DELETE RESTRICT,
  tipo TEXT NOT NULL CHECK (tipo IN (
    'entrada_compra',
    'consumo_producao',
    'perda',
    'ajuste_entrada',
    'ajuste_saida',
    'estorno_compra'
  )),
  quantidade NUMERIC(12,3) NOT NULL CHECK (quantidade > 0),
  saldo_anterior NUMERIC(12,3) NOT NULL CHECK (saldo_anterior >= 0),
  saldo_posterior NUMERIC(12,3) NOT NULL CHECK (saldo_posterior >= 0),
  custo_unitario_aplicado NUMERIC(12,4) NOT NULL DEFAULT 0.0000 CHECK (custo_unitario_aplicado >= 0),
  custo_medio_anterior NUMERIC(12,4) NOT NULL DEFAULT 0.0000 CHECK (custo_medio_anterior >= 0),
  custo_medio_posterior NUMERIC(12,4) NOT NULL DEFAULT 0.0000 CHECK (custo_medio_posterior >= 0),
  valor_total_movimento NUMERIC(12,2) NOT NULL DEFAULT 0.00 CHECK (valor_total_movimento >= 0),
  compra_id BIGINT REFERENCES public.compras(id) ON DELETE SET NULL,
  pedido_id BIGINT REFERENCES public.pedidos(id) ON DELETE SET NULL,
  motivo TEXT NOT NULL CHECK (char_length(btrim(motivo)) >= 3),
  usuario_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  usuario_nome TEXT,
  idempotency_key TEXT UNIQUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_ing_mov_ingrediente ON public.ingrediente_movimentacoes(ingrediente_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_ing_mov_compra ON public.ingrediente_movimentacoes(compra_id);
CREATE INDEX IF NOT EXISTS idx_ing_mov_pedido ON public.ingrediente_movimentacoes(pedido_id);
CREATE INDEX IF NOT EXISTS idx_ing_mov_tipo ON public.ingrediente_movimentacoes(tipo);

-- Imutabilidade estrita do Livro-Razão de Insumos
CREATE OR REPLACE FUNCTION public._bloquear_mutacao_ingrediente_movimentacoes()
RETURNS TRIGGER AS $$
BEGIN
  RAISE EXCEPTION 'IMMUTABLE_LEDGER_VIOLATION: O livro-razão ingrediente_movimentacoes é imutável e não permite %.', TG_OP;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_imutabilidade_ingrediente_mov ON public.ingrediente_movimentacoes;
CREATE TRIGGER trg_imutabilidade_ingrediente_mov
  BEFORE UPDATE OR DELETE ON public.ingrediente_movimentacoes
  FOR EACH ROW
  EXECUTE FUNCTION public._bloquear_mutacao_ingrediente_movimentacoes();

ALTER TABLE public.ingrediente_movimentacoes ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS ing_mov_select_staff ON public.ingrediente_movimentacoes;
CREATE POLICY ing_mov_select_staff ON public.ingrediente_movimentacoes
  FOR SELECT TO authenticated
  USING (public.is_admin_or_operator());

REVOKE ALL ON public.ingrediente_movimentacoes FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.ingrediente_movimentacoes TO authenticated;
GRANT ALL ON public.ingrediente_movimentacoes TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.ingrediente_movimentacoes_id_seq TO service_role;

-- ------------------------------------------------------------------------------
-- 5. CONTAS A PAGAR (FORNECEDORES & ABASTECIMENTO)
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.contas_pagar (
  id BIGSERIAL PRIMARY KEY,
  compra_id BIGINT UNIQUE REFERENCES public.compras(id) ON DELETE RESTRICT,
  fornecedor_id BIGINT NOT NULL REFERENCES public.fornecedores(id) ON DELETE RESTRICT,
  descricao TEXT NOT NULL,
  categoria TEXT NOT NULL DEFAULT 'Insumos / Fornecedores',
  valor_total NUMERIC(12,2) NOT NULL CHECK (valor_total > 0),
  valor_pago NUMERIC(12,2) NOT NULL DEFAULT 0.00 CHECK (valor_pago >= 0),
  saldo_aberto NUMERIC(12,2) NOT NULL CHECK (saldo_aberto >= 0),
  data_vencimento DATE NOT NULL DEFAULT CURRENT_DATE,
  data_quitacao TIMESTAMPTZ,
  status TEXT NOT NULL DEFAULT 'aberta' CHECK (status IN ('aberta', 'parcial', 'paga', 'cancelada')),
  observacoes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT chk_contas_pagar_consistencia CHECK (ROUND(valor_pago + saldo_aberto, 2) = ROUND(valor_total, 2) OR status = 'cancelada')
);

CREATE INDEX IF NOT EXISTS idx_contas_pagar_fornecedor ON public.contas_pagar(fornecedor_id);
CREATE INDEX IF NOT EXISTS idx_contas_pagar_status ON public.contas_pagar(status);
