-- ------------------------------------------------------------------------------
-- 7. HELPER INTERNO PRIVADO: _APLICAR_MOVIMENTO_PONTOS_CLIENTE (LOCK + LEDGER)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public._aplicar_movimento_pontos_cliente(
  p_cliente_id BIGINT,
  p_tipo TEXT,
  p_natureza TEXT,
  p_pontos INTEGER,
  p_motivo TEXT,
  p_chave_idempotencia TEXT,
  p_pedido_id BIGINT DEFAULT NULL,
  p_campanha_id BIGINT DEFAULT NULL,
  p_lote_origem_id BIGINT DEFAULT NULL,
  p_expira_em TIMESTAMPTZ DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_mov_existente RECORD;
  v_carteira RECORD;
  v_saldo_anterior INTEGER := 0;
  v_saldo_posterior INTEGER := 0;
  v_mov_id BIGINT;
BEGIN
  IF p_cliente_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'CLIENT_REQUIRED', 'error', 'Cliente é obrigatório.');
  END IF;

  IF p_pontos IS NULL OR p_pontos <= 0 THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_POINTS', 'error', 'Quantidade de pontos deve ser estritamente positiva.');
  END IF;

  IF p_natureza NOT IN ('credito', 'debito') THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_NATURE', 'error', 'Natureza da movimentação inválida.');
  END IF;

  IF p_chave_idempotencia IS NULL OR btrim(p_chave_idempotencia) = '' THEN
    RETURN jsonb_build_object('success', false, 'code', 'IDEMPOTENCY_KEY_REQUIRED', 'error', 'Chave de idempotência obrigatória.');
  END IF;

  -- Libera flag de mutação interna controlada para cliente_pontos
  PERFORM set_config('lunoca.internal_points_mutation', 'on', true);

  -- Garante existência da linha em cliente_pontos e adquire lock pessimista FOR UPDATE
  INSERT INTO public.cliente_pontos (cliente_id, saldo_pontos)
  VALUES (p_cliente_id, 0)
  ON CONFLICT (cliente_id) DO NOTHING;

  SELECT * INTO v_carteira
  FROM public.cliente_pontos
  WHERE cliente_id = p_cliente_id
  FOR UPDATE;

  -- Verifica idempotência sob o lock do cliente
  SELECT * INTO v_mov_existente
  FROM public.cliente_pontos_movimentacoes
  WHERE chave_idempotencia = btrim(p_chave_idempotencia);

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'idempotente', true,
      'movimentacao_id', v_mov_existente.id,
      'cliente_id', p_cliente_id,
      'tipo', v_mov_existente.tipo,
      'natureza', v_mov_existente.natureza,
      'pontos', v_mov_existente.pontos,
      'saldo_anterior', v_mov_existente.saldo_anterior,
      'saldo_posterior', v_mov_existente.saldo_posterior,
      'saldo_atual', v_carteira.saldo_pontos
    );
  END IF;

  v_saldo_anterior := COALESCE(v_carteira.saldo_pontos, 0);

  IF p_natureza = 'credito' THEN
    v_saldo_posterior := v_saldo_anterior + p_pontos;
  ELSE
    IF v_saldo_anterior < p_pontos THEN
      RETURN jsonb_build_object(
        'success', false,
        'code', 'INSUFFICIENT_POINTS_BALANCE',
        'saldo_atual', v_saldo_anterior,
        'pontos_solicitados', p_pontos,
        'error', 'Saldo de pontos insuficiente para a operação.'
      );
    END IF;
    v_saldo_posterior := v_saldo_anterior - p_pontos;
  END IF;

  UPDATE public.cliente_pontos
  SET saldo_pontos = v_saldo_posterior,
      pontos_acumulados_total = pontos_acumulados_total + CASE WHEN p_natureza = 'credito' AND p_tipo IN ('GANHO_COMPRA', 'BONUS_CAMPANHA', 'AJUSTE_ADMIN') THEN p_pontos ELSE 0 END,
      pontos_resgatados_total = pontos_resgatados_total + CASE WHEN p_tipo = 'RESGATE' THEN p_pontos ELSE 0 END,
      pontos_expirados_total = pontos_expirados_total + CASE WHEN p_tipo = 'EXPIRACAO' THEN p_pontos ELSE 0 END,
      updated_at = NOW()
  WHERE cliente_id = p_cliente_id;

  INSERT INTO public.cliente_pontos_movimentacoes (
    cliente_id,
    tipo,
    natureza,
    pontos,
    saldo_anterior,
    saldo_posterior,
    pedido_id,
    campanha_id,
    lote_origem_id,
    expira_em,
    motivo,
    chave_idempotencia,
    criado_por
  ) VALUES (
    p_cliente_id,
    p_tipo,
    p_natureza,
    p_pontos,
    v_saldo_anterior,
    v_saldo_posterior,
    p_pedido_id,
    p_campanha_id,
    p_lote_origem_id,
    p_expira_em,
    btrim(p_motivo),
    btrim(p_chave_idempotencia),
    auth.uid()
  ) RETURNING id INTO v_mov_id;

  RETURN jsonb_build_object(
    'success', true,
    'idempotente', false,
    'movimentacao_id', v_mov_id,
    'cliente_id', p_cliente_id,
    'tipo', p_tipo,
    'natureza', p_natureza,
    'pontos', p_pontos,
    'saldo_anterior', v_saldo_anterior,
    'saldo_posterior', v_saldo_posterior,
    'saldo_atual', v_saldo_posterior
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public._aplicar_movimento_pontos_cliente(BIGINT, TEXT, TEXT, INTEGER, TEXT, TEXT, BIGINT, BIGINT, BIGINT, TIMESTAMPTZ) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public._aplicar_movimento_pontos_cliente(BIGINT, TEXT, TEXT, INTEGER, TEXT, TEXT, BIGINT, BIGINT, BIGINT, TIMESTAMPTZ) TO service_role;

-- ------------------------------------------------------------------------------
-- 8. EXPIRAÇÃO FIFO E IDEMPOTENTE DE PONTOS (GATES I7 E I8)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public._processar_expiracao_pontos_cliente(
  p_cliente_id BIGINT,
  p_referencia TIMESTAMPTZ DEFAULT NOW()
)
RETURNS JSONB AS $$
DECLARE
  v_ref TIMESTAMPTZ := COALESCE(p_referencia, NOW());
  v_carteira RECORD;
  v_lote RECORD;
  v_debitos_nao_expiracao INTEGER := 0;
  v_creditos_anteriores INTEGER := 0;
  v_ja_consumido_do_lote INTEGER := 0;
  v_disponivel_lote INTEGER := 0;
  v_a_expirar INTEGER := 0;
  v_total_expirado INTEGER := 0;
  v_qtd_lotes INTEGER := 0;
  v_res JSONB;
BEGIN
  IF p_cliente_id IS NULL THEN
    RETURN jsonb_build_object('success', true, 'pontos_expirados', 0, 'lotes_processados', 0);
  END IF;

  PERFORM set_config('lunoca.internal_points_mutation', 'on', true);

  INSERT INTO public.cliente_pontos (cliente_id, saldo_pontos)
  VALUES (p_cliente_id, 0)
  ON CONFLICT (cliente_id) DO NOTHING;

  SELECT * INTO v_carteira
  FROM public.cliente_pontos
  WHERE cliente_id = p_cliente_id
  FOR UPDATE;

  IF COALESCE(v_carteira.saldo_pontos, 0) <= 0 THEN
    RETURN jsonb_build_object('success', true, 'pontos_expirados', 0, 'lotes_processados', 0, 'saldo_atual', 0);
  END IF;

  -- Total de débitos que consumiram pontos em ordem FIFO (resgates, compensações, ajustes de débito)
  SELECT COALESCE(SUM(pontos), 0)::INT
  INTO v_debitos_nao_expiracao
  FROM public.cliente_pontos_movimentacoes
  WHERE cliente_id = p_cliente_id
    AND natureza = 'debito'
    AND tipo <> 'EXPIRACAO';

  FOR v_lote IN
    SELECT m.*
    FROM public.cliente_pontos_movimentacoes m
    WHERE m.cliente_id = p_cliente_id
      AND m.natureza = 'credito'
      AND m.expira_em IS NOT NULL
      AND m.expira_em <= v_ref
      AND NOT EXISTS (
        SELECT 1 FROM public.cliente_pontos_movimentacoes e
        WHERE e.lote_origem_id = m.id AND e.tipo = 'EXPIRACAO'
      )
    ORDER BY m.id ASC
  LOOP
    -- Créditos acumulados estritamente antes deste lote
    SELECT COALESCE(SUM(c.pontos), 0)::INT
    INTO v_creditos_anteriores
    FROM public.cliente_pontos_movimentacoes c
    WHERE c.cliente_id = p_cliente_id
      AND c.natureza = 'credito'
      AND c.id < v_lote.id;

    -- Quanto dos débitos FIFO alcançou este lote
    v_ja_consumido_do_lote := GREATEST(0, LEAST(v_lote.pontos, v_debitos_nao_expiracao - v_creditos_anteriores));
    v_disponivel_lote := GREATEST(0, v_lote.pontos - v_ja_consumido_do_lote);

    -- Atualiza saldo corrente antes de expirar
    SELECT saldo_pontos INTO v_carteira.saldo_pontos
    FROM public.cliente_pontos
    WHERE cliente_id = p_cliente_id;

    v_a_expirar := LEAST(v_disponivel_lote, COALESCE(v_carteira.saldo_pontos, 0));

    IF v_a_expirar > 0 THEN
      v_res := public._aplicar_movimento_pontos_cliente(
        p_cliente_id := p_cliente_id,
        p_tipo := 'EXPIRACAO',
        p_natureza := 'debito',
        p_pontos := v_a_expirar,
        p_motivo := 'Expiração automática do lote #' || v_lote.id,
        p_chave_idempotencia := 'expiracao:lote:' || v_lote.id,
        p_pedido_id := v_lote.pedido_id,
        p_campanha_id := v_lote.campanha_id,
        p_lote_origem_id := v_lote.id,
        p_expira_em := NULL
      );
      IF (v_res->>'success')::BOOLEAN IS TRUE AND (v_res->>'idempotente')::BOOLEAN IS NOT TRUE THEN
        v_total_expirado := v_total_expirado + v_a_expirar;
        v_qtd_lotes := v_qtd_lotes + 1;
      END IF;
    END IF;
  END LOOP;

  SELECT saldo_pontos INTO v_carteira.saldo_pontos
  FROM public.cliente_pontos
  WHERE cliente_id = p_cliente_id;

  RETURN jsonb_build_object(
    'success', true,
    'cliente_id', p_cliente_id,
    'pontos_expirados', v_total_expirado,
    'lotes_processados', v_qtd_lotes,
    'saldo_atual', COALESCE(v_carteira.saldo_pontos, 0)
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public._processar_expiracao_pontos_cliente(BIGINT, TIMESTAMPTZ) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public._processar_expiracao_pontos_cliente(BIGINT, TIMESTAMPTZ) TO service_role;

CREATE OR REPLACE FUNCTION public.expirar_pontos_fidelidade(
  p_cliente_id BIGINT DEFAULT NULL,
  p_referencia TIMESTAMPTZ DEFAULT NOW()
)
RETURNS JSONB AS $$
DECLARE
  v_cli RECORD;
  v_res JSONB;
  v_total_pontos INTEGER := 0;
  v_total_lotes INTEGER := 0;
BEGIN
  IF NOT public.is_admin_or_operator() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada.');
  END IF;

  IF p_cliente_id IS NOT NULL THEN
    RETURN public._processar_expiracao_pontos_cliente(p_cliente_id, COALESCE(p_referencia, NOW()));
  END IF;

  FOR v_cli IN
    SELECT DISTINCT cliente_id
    FROM public.cliente_pontos_movimentacoes
    WHERE natureza = 'credito'
      AND expira_em IS NOT NULL
      AND expira_em <= COALESCE(p_referencia, NOW())
  LOOP
    v_res := public._processar_expiracao_pontos_cliente(v_cli.cliente_id, COALESCE(p_referencia, NOW()));
    v_total_pontos := v_total_pontos + COALESCE((v_res->>'pontos_expirados')::INT, 0);
    v_total_lotes := v_total_lotes + COALESCE((v_res->>'lotes_processados')::INT, 0);
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'pontos_expirados', v_total_pontos,
    'lotes_processados', v_total_lotes
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.expirar_pontos_fidelidade(BIGINT, TIMESTAMPTZ) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.expirar_pontos_fidelidade(BIGINT, TIMESTAMPTZ) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 9. CRÉDITO DE PONTOS EM COMPRA CONCLUÍDA E COMPENSAÇÃO NO CANCELAMENTO (I1-I4)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public._creditar_pontos_pedido_interno(
  p_pedido_id BIGINT
)
RETURNS JSONB AS $$
DECLARE
  v_ped public.pedidos;
  v_prog public.programas_fidelidade;
  v_valor_elegivel NUMERIC(10,2);
  v_pontos INTEGER;
  v_expira_em TIMESTAMPTZ;
BEGIN
  SELECT * INTO v_ped FROM public.pedidos WHERE id = p_pedido_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_NOT_FOUND', 'error', 'Pedido não encontrado.');
  END IF;

  IF v_ped.status_comercial <> 'concluido' THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'ORDER_NOT_COMPLETED',
      'status_comercial', v_ped.status_comercial,
      'error', 'Pontos de fidelidade só são creditados após o pedido atingir o marco estável concluído.'
    );
  END IF;

  IF v_ped.cliente_id_rel IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_WITHOUT_CLIENT', 'error', 'Pedido não possui cliente vinculado.');
  END IF;

  SELECT * INTO v_prog
  FROM public.programas_fidelidade
  WHERE ativo = true
  ORDER BY id ASC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'PROGRAM_INACTIVE', 'error', 'Nenhum programa de fidelidade ativo.');
  END IF;

  v_valor_elegivel := GREATEST(0.00, COALESCE(v_ped.subtotal, v_ped.total, 0.00) - COALESCE(v_ped.desconto, 0.00));

  IF v_valor_elegivel < v_prog.pedido_minimo_elegivel THEN
    RETURN jsonb_build_object(
      'success', true,
      'elegivel', false,
      'pontos', 0,
      'motivo', 'Valor elegível abaixo do mínimo do programa.'
    );
  END IF;

  v_pontos := FLOOR(v_valor_elegivel * v_prog.pontos_por_real)::INT;
  IF v_pontos <= 0 THEN
    RETURN jsonb_build_object('success', true, 'elegivel', false, 'pontos', 0);
  END IF;

  v_expira_em := NOW() + make_interval(days => v_prog.validade_pontos_dias);

  RETURN public._aplicar_movimento_pontos_cliente(
    p_cliente_id := v_ped.cliente_id_rel,
    p_tipo := 'GANHO_COMPRA',
    p_natureza := 'credito',
    p_pontos := v_pontos,
    p_motivo := 'Pontos por compra concluída (Pedido #' || v_ped.id || ')',
    p_chave_idempotencia := 'ganho_compra:pedido:' || v_ped.id,
    p_pedido_id := v_ped.id,
    p_campanha_id := NULL,
    p_lote_origem_id := NULL,
    p_expira_em := v_expira_em
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public._creditar_pontos_pedido_interno(BIGINT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public._creditar_pontos_pedido_interno(BIGINT) TO service_role;

CREATE OR REPLACE FUNCTION public.creditar_pontos_pedido_concluido(
  p_pedido_id BIGINT
)
RETURNS JSONB AS $$
BEGIN
  IF NOT public.is_admin_or_operator() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada.');
  END IF;
  RETURN public._creditar_pontos_pedido_interno(p_pedido_id);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.creditar_pontos_pedido_concluido(BIGINT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.creditar_pontos_pedido_concluido(BIGINT) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public._compensar_pontos_pedido_cancelado_interno(
  p_pedido_id BIGINT,
  p_motivo TEXT DEFAULT 'Estorno compensatório por cancelamento do pedido'
)
RETURNS JSONB AS $$
DECLARE
  v_ganho RECORD;
  v_resgate RECORD;
  v_carteira RECORD;
  v_pontos_compensar INTEGER := 0;
  v_res_comp JSONB := NULL;
  v_res_est_resgate JSONB := NULL;
BEGIN
  -- 1. Se o pedido gerou GANHO_COMPRA, lança COMPENSACAO_CANCELAMENTO (sem apagar o ganho original)
  SELECT * INTO v_ganho
  FROM public.cliente_pontos_movimentacoes
  WHERE pedido_id = p_pedido_id
    AND tipo = 'GANHO_COMPRA'
    AND natureza = 'credito'
  ORDER BY id DESC
  LIMIT 1;

  IF FOUND THEN
    PERFORM set_config('lunoca.internal_points_mutation', 'on', true);
    SELECT * INTO v_carteira
    FROM public.cliente_pontos
    WHERE cliente_id = v_ganho.cliente_id
    FOR UPDATE;

    v_pontos_compensar := LEAST(v_ganho.pontos, COALESCE(v_carteira.saldo_pontos, 0));
    IF v_pontos_compensar > 0 THEN
      v_res_comp := public._aplicar_movimento_pontos_cliente(
        p_cliente_id := v_ganho.cliente_id,
        p_tipo := 'COMPENSACAO_CANCELAMENTO',
        p_natureza := 'debito',
        p_pontos := v_pontos_compensar,
        p_motivo := COALESCE(NULLIF(btrim(p_motivo), ''), 'Compensação por cancelamento do Pedido #' || p_pedido_id),
        p_chave_idempotencia := 'compensacao_cancelamento:pedido:' || p_pedido_id,
        p_pedido_id := p_pedido_id,
        p_campanha_id := NULL,
        p_lote_origem_id := v_ganho.id,
        p_expira_em := NULL
      );
    END IF;
  END IF;

  -- 2. Se houve RESGATE vinculado ao pedido, devolve via ESTORNO_RESGATE
  SELECT * INTO v_resgate
  FROM public.cliente_pontos_movimentacoes
  WHERE pedido_id = p_pedido_id
    AND tipo = 'RESGATE'
    AND natureza = 'debito'
  ORDER BY id DESC
  LIMIT 1;

  IF FOUND THEN
    v_res_est_resgate := public._aplicar_movimento_pontos_cliente(
      p_cliente_id := v_resgate.cliente_id,
      p_tipo := 'ESTORNO_RESGATE',
      p_natureza := 'credito',
      p_pontos := v_resgate.pontos,
      p_motivo := 'Devolução de pontos resgatados por cancelamento do Pedido #' || p_pedido_id,
      p_chave_idempotencia := 'estorno_resgate:pedido:' || p_pedido_id,
      p_pedido_id := p_pedido_id,
      p_campanha_id := NULL,
      p_lote_origem_id := v_resgate.id,
      p_expira_em := NOW() + INTERVAL '180 days'
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'pedido_id', p_pedido_id,
    'compensacao_ganho', v_res_comp,
    'estorno_resgate', v_res_est_resgate
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public._compensar_pontos_pedido_cancelado_interno(BIGINT, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public._compensar_pontos_pedido_cancelado_interno(BIGINT, TEXT) TO service_role;

CREATE OR REPLACE FUNCTION public.compensar_pontos_pedido_cancelado(
  p_pedido_id BIGINT,
  p_motivo TEXT DEFAULT 'Estorno compensatório por cancelamento do pedido'
)
RETURNS JSONB AS $$
BEGIN
  IF NOT public.is_admin_or_operator() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada.');
  END IF;
  RETURN public._compensar_pontos_pedido_cancelado_interno(p_pedido_id, p_motivo);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.compensar_pontos_pedido_cancelado(BIGINT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.compensar_pontos_pedido_cancelado(BIGINT, TEXT) TO authenticated, service_role;

-- Trigger automático em public.pedidos para creditar na conclusão e compensar no cancelamento
CREATE OR REPLACE FUNCTION public.trg_fn_fidelidade_pedido_status()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.status_comercial = 'concluido' AND COALESCE(OLD.status_comercial, '') <> 'concluido' THEN
    PERFORM public._creditar_pontos_pedido_interno(NEW.id);
  ELSIF NEW.status_comercial = 'cancelado' AND COALESCE(OLD.status_comercial, '') <> 'cancelado' THEN
    PERFORM public._compensar_pontos_pedido_cancelado_interno(NEW.id, 'Cancelamento do Pedido #' || NEW.id);
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

DROP TRIGGER IF EXISTS trg_fidelidade_pedido_status ON public.pedidos;
CREATE TRIGGER trg_fidelidade_pedido_status
  AFTER UPDATE OF status_comercial ON public.pedidos
  FOR EACH ROW
  EXECUTE FUNCTION public.trg_fn_fidelidade_pedido_status();

-- ------------------------------------------------------------------------------
-- 10. RESGATE CONCORRENTE E AJUSTE ADMINISTRATIVO DE PONTOS (GATES I5, I6, I9, I10)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.resgatar_pontos_fidelidade(
  p_cliente_id BIGINT,
  p_pontos INTEGER,
  p_pedido_id BIGINT DEFAULT NULL,
  p_chave_idempotencia TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_prog public.programas_fidelidade;
  v_res JSONB;
  v_beneficio NUMERIC(10,2);
  v_chave TEXT;
BEGIN
  IF NOT public.is_admin_or_operator() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada.');
  END IF;

  IF p_cliente_id IS NULL OR p_pontos IS NULL OR p_pontos <= 0 THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_POINTS', 'error', 'Cliente e quantidade de pontos positiva são obrigatórios.');
  END IF;

  -- 1. Processa expiração de lotes vencidos antes de permitir qualquer resgate (Gate I7)
  PERFORM public._processar_expiracao_pontos_cliente(p_cliente_id, NOW());

  SELECT * INTO v_prog
  FROM public.programas_fidelidade
  WHERE ativo = true
  ORDER BY id ASC
  LIMIT 1;

  IF p_pontos < COALESCE(v_prog.resgate_minimo_pontos, 10) THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'MIN_REDEMPTION_NOT_MET',
      'minimo_pontos', COALESCE(v_prog.resgate_minimo_pontos, 10),
      'error', 'Quantidade de pontos abaixo do mínimo para resgate.'
    );
  END IF;

  v_chave := COALESCE(NULLIF(btrim(p_chave_idempotencia), ''), 'resgate:' || p_cliente_id || ':' || COALESCE(p_pedido_id::TEXT, gen_random_uuid()::TEXT));

  v_res := public._aplicar_movimento_pontos_cliente(
    p_cliente_id := p_cliente_id,
    p_tipo := 'RESGATE',
    p_natureza := 'debito',
    p_pontos := p_pontos,
    p_motivo := CASE WHEN p_pedido_id IS NOT NULL THEN 'Resgate de pontos no Pedido #' || p_pedido_id ELSE 'Resgate de pontos de fidelidade' END,
    p_chave_idempotencia := v_chave,
    p_pedido_id := p_pedido_id,
    p_campanha_id := NULL,
    p_lote_origem_id := NULL,
    p_expira_em := NULL
  );

  IF (v_res->>'success')::BOOLEAN IS NOT TRUE THEN
    RETURN v_res;
  END IF;

  v_beneficio := ROUND(p_pontos * COALESCE(v_prog.valor_por_ponto_resgate, 0.0500), 2);

  RETURN v_res || jsonb_build_object(
    'valor_beneficio_reais', v_beneficio
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.resgatar_pontos_fidelidade(BIGINT, INTEGER, BIGINT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.resgatar_pontos_fidelidade(BIGINT, INTEGER, BIGINT, TEXT) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.ajustar_pontos_fidelidade_admin(
  p_cliente_id BIGINT,
  p_natureza TEXT,
  p_pontos INTEGER,
  p_motivo TEXT,
  p_chave_idempotencia TEXT DEFAULT NULL,
  p_expira_em TIMESTAMPTZ DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_prog public.programas_fidelidade;
  v_chave TEXT;
  v_expira TIMESTAMPTZ;
BEGIN
  -- Gate I9: Operador nunca ajusta pontos arbitrariamente
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PERMISSION_DENIED',
      'error', 'Apenas administradores podem realizar ajustes manuais de pontos de fidelidade.'
    );
  END IF;

  -- Gate I10: Motivo obrigatório (>= 5 caracteres)
  IF p_motivo IS NULL OR char_length(btrim(p_motivo)) < 5 THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'REASON_REQUIRED',
      'error', 'Informe uma justificativa auditável com pelo menos 5 caracteres para ajustar pontos.'
    );
  END IF;

  SELECT * INTO v_prog FROM public.programas_fidelidade WHERE ativo = true ORDER BY id ASC LIMIT 1;
  v_expira := CASE
    WHEN p_natureza = 'credito' THEN COALESCE(p_expira_em, NOW() + make_interval(days => COALESCE(v_prog.validade_pontos_dias, 180)))
    ELSE NULL
  END;

  v_chave := COALESCE(NULLIF(btrim(p_chave_idempotencia), ''), 'ajuste_admin:' || p_cliente_id || ':' || gen_random_uuid()::TEXT);

  RETURN public._aplicar_movimento_pontos_cliente(
    p_cliente_id := p_cliente_id,
    p_tipo := 'AJUSTE_ADMIN',
    p_natureza := p_natureza,
    p_pontos := p_pontos,
    p_motivo := btrim(p_motivo),
    p_chave_idempotencia := v_chave,
    p_pedido_id := NULL,
    p_campanha_id := NULL,
    p_lote_origem_id := NULL,
    p_expira_em := v_expira
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.ajustar_pontos_fidelidade_admin(BIGINT, TEXT, INTEGER, TEXT, TEXT, TIMESTAMPTZ) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.ajustar_pontos_fidelidade_admin(BIGINT, TEXT, INTEGER, TEXT, TEXT, TIMESTAMPTZ) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 11. GESTÃO DE CUPONS E MOTOR CENTRAL DE DESCONTO COMBINADO (GATES I11, I12, I13, I18)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.salvar_cupom_promocional_admin(
  p_codigo TEXT,
  p_tipo TEXT,
  p_valor NUMERIC,
  p_validade_fim TIMESTAMPTZ,
  p_validade_inicio TIMESTAMPTZ DEFAULT NULL,
  p_uso_maximo_global INTEGER DEFAULT NULL,
  p_uso_maximo_cliente INTEGER DEFAULT 1,
  p_pedido_minimo NUMERIC DEFAULT 0.00,
  p_desconto_maximo NUMERIC DEFAULT NULL,
  p_descricao TEXT DEFAULT NULL,
  p_campanha_id BIGINT DEFAULT NULL,
  p_ativo BOOLEAN DEFAULT true,
  p_id BIGINT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_codigo_norm TEXT;
  v_cupom_id BIGINT;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas administradores podem gerenciar cupons promocionais.');
  END IF;

  v_codigo_norm := UPPER(btrim(COALESCE(p_codigo, '')));
  IF char_length(v_codigo_norm) < 3 THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_COUPON_CODE', 'error', 'Código do cupom deve ter ao menos 3 caracteres.');
  END IF;

  IF p_tipo NOT IN ('percentual', 'valor_fixo') OR p_valor IS NULL OR p_valor <= 0 THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_COUPON_VALUE', 'error', 'Tipo ou valor do cupom inválido.');
  END IF;

  IF p_id IS NOT NULL THEN
    UPDATE public.cupons_promocionais
    SET codigo = v_codigo_norm,
        descricao = p_descricao,
        tipo = p_tipo,
        valor = ROUND(p_valor, 2),
        validade_inicio = COALESCE(p_validade_inicio, validade_inicio),
        validade_fim = p_validade_fim,
        uso_maximo_global = p_uso_maximo_global,
        uso_maximo_cliente = COALESCE(p_uso_maximo_cliente, 1),
        pedido_minimo = COALESCE(p_pedido_minimo, 0.00),
        desconto_maximo = p_desconto_maximo,
        campanha_id = p_campanha_id,
        ativo = COALESCE(p_ativo, true),
        updated_at = NOW()
    WHERE id = p_id
    RETURNING id INTO v_cupom_id;
  ELSE
    INSERT INTO public.cupons_promocionais (
      codigo, descricao, tipo, valor, validade_inicio, validade_fim,
      uso_maximo_global, uso_maximo_cliente, pedido_minimo, desconto_maximo,
      campanha_id, ativo, criado_por
    ) VALUES (
      v_codigo_norm, p_descricao, p_tipo, ROUND(p_valor, 2),
      COALESCE(p_validade_inicio, NOW() - INTERVAL '1 minute'), p_validade_fim,
      p_uso_maximo_global, COALESCE(p_uso_maximo_cliente, 1),
      COALESCE(p_pedido_minimo, 0.00), p_desconto_maximo,
      p_campanha_id, COALESCE(p_ativo, true), auth.uid()
    )
    ON CONFLICT (codigo) DO UPDATE SET
      tipo = EXCLUDED.tipo,
      valor = EXCLUDED.valor,
      validade_inicio = EXCLUDED.validade_inicio,
      validade_fim = EXCLUDED.validade_fim,
      uso_maximo_global = EXCLUDED.uso_maximo_global,
      uso_maximo_cliente = EXCLUDED.uso_maximo_cliente,
      pedido_minimo = EXCLUDED.pedido_minimo,
      desconto_maximo = EXCLUDED.desconto_maximo,
      ativo = EXCLUDED.ativo,
      updated_at = NOW()
    RETURNING id INTO v_cupom_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'cupom_id', v_cupom_id, 'codigo', v_codigo_norm);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.salvar_cupom_promocional_admin(TEXT, TEXT, NUMERIC, TIMESTAMPTZ, TIMESTAMPTZ, INTEGER, INTEGER, NUMERIC, NUMERIC, TEXT, BIGINT, BOOLEAN, BIGINT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.salvar_cupom_promocional_admin(TEXT, TEXT, NUMERIC, TIMESTAMPTZ, TIMESTAMPTZ, INTEGER, INTEGER, NUMERIC, NUMERIC, TEXT, BIGINT, BOOLEAN, BIGINT) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.aplicar_cupom_promocional(
  p_codigo_cupom TEXT,
  p_cliente_id BIGINT,
  p_subtotal NUMERIC,
  p_desconto_manual NUMERIC DEFAULT 0.00,
  p_desconto_frete NUMERIC DEFAULT 0.00,
  p_pontos_resgate INTEGER DEFAULT 0,
  p_motivo TEXT DEFAULT NULL,
  p_pedido_id BIGINT DEFAULT NULL,
  p_registrar_uso BOOLEAN DEFAULT true,
  p_chave_idempotencia TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_cupom public.cupons_promocionais;
  v_prog public.programas_fidelidade;
  v_subtotal NUMERIC(10,2) := ROUND(COALESCE(p_subtotal, 0.00), 2);
  v_desc_manual NUMERIC(10,2) := GREATEST(0.00, ROUND(COALESCE(p_desconto_manual, 0.00), 2));
  v_desc_frete NUMERIC(10,2) := GREATEST(0.00, ROUND(COALESCE(p_desconto_frete, 0.00), 2));
  v_desc_pontos NUMERIC(10,2) := 0.00;
  v_desc_cupom NUMERIC(10,2) := 0.00;
  v_desc_total_combinado NUMERIC(10,2) := 0.00;
  v_usos_global INTEGER := 0;
  v_usos_cliente INTEGER := 0;
  v_pol JSONB;
  v_motivo_final TEXT;
  v_chave TEXT;
  v_utilizacao_id BIGINT;
BEGIN
  IF NOT public.is_admin_or_operator() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada.');
  END IF;

  IF v_subtotal <= 0.00 THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_SUBTOTAL', 'error', 'Subtotal do pedido inválido.');
  END IF;

  IF p_codigo_cupom IS NOT NULL AND btrim(p_codigo_cupom) <> '' THEN
    SELECT * INTO v_cupom
    FROM public.cupons_promocionais
    WHERE codigo = UPPER(btrim(p_codigo_cupom))
    FOR UPDATE;

    IF NOT FOUND OR v_cupom.ativo IS NOT TRUE THEN
      RETURN jsonb_build_object('success', false, 'code', 'COUPON_NOT_FOUND_OR_INACTIVE', 'error', 'Cupom promocional inexistente ou inativo.');
    END IF;

    IF NOW() < v_cupom.validade_inicio OR NOW() > v_cupom.validade_fim THEN
      RETURN jsonb_build_object('success', false, 'code', 'COUPON_EXPIRED', 'error', 'Este cupom promocional está fora do período de validade.');
    END IF;

    IF v_subtotal < v_cupom.pedido_minimo THEN
      RETURN jsonb_build_object(
        'success', false,
        'code', 'ORDER_BELOW_MINIMUM',
        'pedido_minimo', v_cupom.pedido_minimo,
        'error', 'O subtotal do pedido não atinge o valor mínimo exigido pelo cupom.'
      );
    END IF;

    SELECT COUNT(*)::INT INTO v_usos_global
    FROM public.cupom_utilizacoes
    WHERE cupom_id = v_cupom.id AND status = 'aplicado';

    IF v_cupom.uso_maximo_global IS NOT NULL AND v_usos_global >= v_cupom.uso_maximo_global THEN
      RETURN jsonb_build_object('success', false, 'code', 'COUPON_GLOBAL_LIMIT_REACHED', 'error', 'Limite global de utilizações deste cupom foi atingido.');
    END IF;

    IF p_cliente_id IS NOT NULL THEN
      SELECT COUNT(*)::INT INTO v_usos_cliente
      FROM public.cupom_utilizacoes
      WHERE cupom_id = v_cupom.id AND cliente_id = p_cliente_id AND status = 'aplicado';

      IF v_usos_cliente >= v_cupom.uso_maximo_cliente THEN
        RETURN jsonb_build_object('success', false, 'code', 'COUPON_CLIENT_LIMIT_REACHED', 'error', 'Cliente já atingiu o limite máximo de uso deste cupom.');
      END IF;
    END IF;

    IF v_cupom.tipo = 'percentual' THEN
      v_desc_cupom := ROUND(v_subtotal * (v_cupom.valor / 100.0), 2);
    ELSE
      v_desc_cupom := ROUND(v_cupom.valor, 2);
    END IF;

    IF v_cupom.desconto_maximo IS NOT NULL THEN
      v_desc_cupom := LEAST(v_desc_cupom, v_cupom.desconto_maximo);
    END IF;

    v_desc_cupom := LEAST(v_desc_cupom, v_subtotal);
  END IF;

  IF COALESCE(p_pontos_resgate, 0) > 0 THEN
    SELECT * INTO v_prog FROM public.programas_fidelidade WHERE ativo = true ORDER BY id ASC LIMIT 1;
    v_desc_pontos := ROUND(p_pontos_resgate * COALESCE(v_prog.valor_por_ponto_resgate, 0.0500), 2);
  END IF;

  -- Gate I13: Desconto combinado (cupom + manual + frete + pontos) validado centralizadamente em politica_desconto
  v_desc_total_combinado := ROUND(v_desc_cupom + v_desc_manual + v_desc_frete + v_desc_pontos, 2);
  v_motivo_final := COALESCE(
    NULLIF(btrim(p_motivo), ''),
    CASE WHEN v_cupom.id IS NOT NULL THEN 'Cupom promocional ' || v_cupom.codigo ELSE NULL END
  );

  v_pol := public.politica_desconto(v_subtotal, v_desc_total_combinado, v_motivo_final);
  IF (v_pol->>'success')::BOOLEAN IS NOT TRUE THEN
    RETURN v_pol;
  END IF;

  IF p_registrar_uso IS TRUE AND v_cupom.id IS NOT NULL AND p_cliente_id IS NOT NULL THEN
    v_chave := COALESCE(
      NULLIF(btrim(p_chave_idempotencia), ''),
      'cupom:' || v_cupom.id || ':cli:' || p_cliente_id || ':' || COALESCE(p_pedido_id::TEXT, (v_usos_cliente + 1)::TEXT)
    );

    INSERT INTO public.cupom_utilizacoes (
      cupom_id, cliente_id, pedido_id, subtotal_pedido,
      valor_desconto_cupom, desconto_manual_combinado, desconto_frete_combinado,
      beneficio_pontos_combinado, status, chave_idempotencia, usuario_id
    ) VALUES (
      v_cupom.id, p_cliente_id, p_pedido_id, v_subtotal,
      v_desc_cupom, v_desc_manual, v_desc_frete,
      v_desc_pontos, 'aplicado', v_chave, auth.uid()
    )
    ON CONFLICT (chave_idempotencia) DO NOTHING
    RETURNING id INTO v_utilizacao_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'cupom_id', v_cupom.id,
    'codigo_cupom', v_cupom.codigo,
    'utilizacao_id', v_utilizacao_id,
    'subtotal', v_subtotal,
    'desconto_cupom', v_desc_cupom,
    'desconto_manual', v_desc_manual,
    'desconto_frete', v_desc_frete,
    'beneficio_pontos', v_desc_pontos,
    'desconto_total_combinado', v_desc_total_combinado,
    'total_liquido', ROUND(v_subtotal - v_desc_total_combinado, 2),
    'percentual_combinado', (v_pol->>'percentual')::NUMERIC
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.aplicar_cupom_promocional(TEXT, BIGINT, NUMERIC, NUMERIC, NUMERIC, INTEGER, TEXT, BIGINT, BOOLEAN, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.aplicar_cupom_promocional(TEXT, BIGINT, NUMERIC, NUMERIC, NUMERIC, INTEGER, TEXT, BIGINT, BOOLEAN, TEXT) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 12. CONSENTIMENTO DE MARKETING (OPT-IN / OPT-OUT) E VERIFICAÇÃO (GATES I14, I15, I16)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.obter_status_consentimento_marketing(
  p_cliente_id BIGINT,
  p_canal TEXT DEFAULT 'whatsapp_marketing'
)
RETURNS TEXT AS $$
DECLARE
  v_status TEXT;
BEGIN
  SELECT status INTO v_status
  FROM public.cliente_consentimentos_marketing
  WHERE cliente_id = p_cliente_id
    AND canal = p_canal
  ORDER BY data_hora DESC, id DESC
  LIMIT 1;

  -- Fail-closed para marketing: sem opt-in explícito registrado, considera opt_out
  RETURN COALESCE(v_status, 'sem_consentimento');
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_status_consentimento_marketing(BIGINT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_status_consentimento_marketing(BIGINT, TEXT) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.registrar_consentimento_marketing(
  p_cliente_id BIGINT,
  p_canal TEXT,
  p_status TEXT,
  p_origem TEXT DEFAULT 'painel_admin',
  p_versao_termo TEXT DEFAULT 'v1.0',
  p_observacao TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_id BIGINT;
BEGIN
  IF NOT public.is_admin_or_operator() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada.');
  END IF;

  IF p_cliente_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'CLIENT_REQUIRED', 'error', 'Cliente é obrigatório.');
  END IF;

  IF p_canal NOT IN ('whatsapp_marketing', 'email_marketing', 'sms_marketing') THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_MARKETING_CHANNEL', 'error', 'Canal de marketing inválido.');
  END IF;

  IF p_status NOT IN ('opt_in', 'opt_out') THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_CONSENT_STATUS', 'error', 'Status deve ser opt_in ou opt_out.');
  END IF;

  INSERT INTO public.cliente_consentimentos_marketing (
    cliente_id, canal, status, origem, versao_termo, observacao, data_hora, registrado_por
  ) VALUES (
    p_cliente_id,
    p_canal,
    p_status,
    COALESCE(NULLIF(btrim(p_origem), ''), 'painel_admin'),
    COALESCE(NULLIF(btrim(p_versao_termo), ''), 'v1.0'),
    p_observacao,
    NOW(),
    auth.uid()
  ) RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'success', true,
    'consentimento_id', v_id,
    'cliente_id', p_cliente_id,
    'canal', p_canal,
    'status_vigente', p_status
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.registrar_consentimento_marketing(BIGINT, TEXT, TEXT, TEXT, TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.registrar_consentimento_marketing(BIGINT, TEXT, TEXT, TEXT, TEXT, TEXT) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 13. EXTENSÃO DA ESTEIRA CANÔNICA DE COMUNICAÇÃO (FRENTE B) PARA MARKETING
-- ------------------------------------------------------------------------------
-- Mantém assinatura única para obter_preview_comunicacao (3 args) e
-- registrar_comunicacao_cliente (7 args) para 100% de idempotência do install.sql
-- com a Migration 015, e expõe obter_preview_comunicacao_marketing e
-- registrar_comunicacao_cliente_marketing gravando na mesma trilha comunicacoes_cliente.
DROP FUNCTION IF EXISTS public.obter_preview_comunicacao(TEXT, BIGINT, BIGINT, BIGINT, BIGINT);
DROP FUNCTION IF EXISTS public.registrar_comunicacao_cliente(TEXT, BIGINT, BIGINT, TEXT, TEXT, TEXT, TEXT, BIGINT, BIGINT);

CREATE OR REPLACE FUNCTION public.obter_preview_comunicacao_marketing(
  p_tipo TEXT,
  p_campanha_id BIGINT,
  p_cliente_id BIGINT
)
RETURNS JSONB AS $$
DECLARE
  v_camp public.campanhas;
  v_cli public.clientes;
  v_cupom public.cupons_promocionais;
  v_telefone_raw TEXT;
  v_telefone_norm TEXT;
  v_mensagem TEXT;
  v_chave_idempotencia TEXT;
  v_consentimento TEXT;
  v_saldo_pontos INTEGER := 0;
BEGIN
  IF NOT public.is_admin_or_operator() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada. Apenas equipe autorizada pode gerar previews de comunicação.');
  END IF;

  IF p_tipo IS NULL OR p_tipo NOT IN (
    'CUPOM_ANIVERSARIO',
    'VOLTE_A_COMPRAR',
    'CAMPANHA_PASCOA',
    'CAMPANHA_PROMOCIONAL',
    'LEMBRETE_PONTOS_EXPIRANDO'
  ) THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_TEMPLATE_TYPE', 'error', 'Tipo de template de marketing inválido.');
  END IF;

  IF p_campanha_id IS NULL OR p_cliente_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'CAMPAIGN_AND_CLIENT_REQUIRED', 'error', 'Campanha e cliente são obrigatórios para templates de marketing.');
  END IF;

  SELECT * INTO v_camp FROM public.campanhas WHERE id = p_campanha_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'CAMPAIGN_NOT_FOUND', 'error', 'Campanha não encontrada.');
  END IF;

  SELECT * INTO v_cli FROM public.clientes WHERE id = p_cliente_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'CLIENT_NOT_FOUND', 'error', 'Cliente não encontrado.');
  END IF;

  v_consentimento := public.obter_status_consentimento_marketing(v_cli.id, v_camp.canal);
  IF v_consentimento <> 'opt_in' THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'MARKETING_OPT_IN_REQUIRED',
      'consentimento_status', v_consentimento,
      'error', 'Envio promocional bloqueado: o cliente não possui consentimento ativo (opt-in) para marketing neste canal.'
    );
  END IF;

  v_telefone_raw := COALESCE(v_cli.telefone_normalizado, v_cli.telefone);
  v_telefone_norm := public.normalizar_telefone_e164(v_telefone_raw);
  IF v_telefone_norm IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_PHONE', 'telefone_informado', v_telefone_raw, 'error', 'Telefone do cliente inválido para envio.');
  END IF;

  SELECT COALESCE((
    SELECT saldo_pontos FROM public.cliente_pontos WHERE cliente_id = v_cli.id
  ), 0) INTO v_saldo_pontos;

  IF v_camp.cupom_id IS NOT NULL THEN
    SELECT * INTO v_cupom FROM public.cupons_promocionais WHERE id = v_camp.cupom_id;
  END IF;

  v_chave_idempotencia := 'campanha:' || v_camp.id || ':cliente:' || v_cli.id;
  v_mensagem := replace(COALESCE(v_camp.mensagem_template, ''), '{{nome}}', COALESCE(v_cli.nome, 'Cliente'));
  v_mensagem := replace(v_mensagem, '{{pontos}}', COALESCE(v_saldo_pontos, 0)::TEXT);
  v_mensagem := replace(v_mensagem, '{{cupom}}', COALESCE(v_cupom.codigo, ''));

  RETURN jsonb_build_object(
    'success', true,
    'tipo', p_tipo,
    'natureza_comunicacao', 'marketing',
    'entidade_tipo', 'campanha',
    'campanha_id', v_camp.id,
    'cliente_id', v_cli.id,
    'cliente_nome', v_cli.nome,
    'telefone', v_telefone_norm,
    'mensagem', v_mensagem,
    'link_publico', NULL,
    'chave_idempotencia', v_chave_idempotencia
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_preview_comunicacao_marketing(TEXT, BIGINT, BIGINT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_preview_comunicacao_marketing(TEXT, BIGINT, BIGINT) TO authenticated, service_role;

-- Mantém assinatura única de 3 argumentos de obter_preview_comunicacao (com suporte a naturezas transacionais e, via p_orcamento_id=campanha_id e p_pedido_id=cliente_id quando p_tipo for template de marketing)
CREATE OR REPLACE FUNCTION public.obter_preview_comunicacao(
  p_tipo TEXT,
  p_orcamento_id BIGINT DEFAULT NULL,
  p_pedido_id BIGINT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_orc public.orcamentos;
  v_ped public.pedidos;
  v_pag RECORD;
  v_hist RECORD;
  v_telefone_raw TEXT;
  v_telefone_norm TEXT;
  v_mensagem TEXT;
  v_chave_idempotencia TEXT;
  v_link_publico TEXT := NULL;
  v_saldo_restante NUMERIC(10,2);
  v_valor_sinal NUMERIC(10,2);
  v_data_formatada TEXT;
  v_hora_formatada TEXT;
  v_validade_formatada TEXT;
BEGIN
  IF NOT public.is_admin_or_operator() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada. Apenas equipe autorizada pode gerar previews de comunicação.');
  END IF;

  IF p_tipo IN (
    'CUPOM_ANIVERSARIO',
    'VOLTE_A_COMPRAR',
    'CAMPANHA_PASCOA',
    'CAMPANHA_PROMOCIONAL',
    'LEMBRETE_PONTOS_EXPIRANDO'
  ) THEN
    RETURN public.obter_preview_comunicacao_marketing(p_tipo, p_orcamento_id, p_pedido_id);
  END IF;

  IF p_tipo IS NULL OR p_tipo NOT IN (
    'ORCAMENTO_ENVIADO',
    'ORCAMENTO_VENCENDO',
    'SINAL_CONFIRMADO',
    'PEDIDO_PRONTO',
    'SAIU_PARA_ENTREGA'
  ) THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_TEMPLATE_TYPE', 'error', 'Tipo de template de comunicação inválido.');
  END IF;

  -- 1. Templates Transacionais de Orçamento (NÃO exigem opt-in de marketing — Gate I16)
  IF p_tipo IN ('ORCAMENTO_ENVIADO', 'ORCAMENTO_VENCENDO') THEN
    IF p_orcamento_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'code', 'ORCAMENTO_ID_REQUIRED', 'error', 'ID do orçamento é obrigatório para este template.');
    END IF;

    SELECT * INTO v_orc FROM public.orcamentos WHERE id = p_orcamento_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'code', 'ORCAMENTO_NOT_FOUND', 'error', 'Orçamento não encontrado.');
    END IF;

    v_telefone_raw := v_orc.cliente_telefone;
    v_telefone_norm := public.normalizar_telefone_e164(v_telefone_raw);
    IF v_telefone_norm IS NULL THEN
      RETURN jsonb_build_object('success', false, 'code', 'INVALID_PHONE', 'telefone_informado', v_telefone_raw, 'error', 'Telefone do cliente inválido ou ambíguo. Corrija o cadastro para prosseguir.');
    END IF;

    v_link_publico := 'https://lunocadoceria.com.br/orcamento.html?t=' || v_orc.token_publico::TEXT;
    v_data_formatada := to_char(v_orc.data_evento, 'DD/MM/YYYY');
    v_hora_formatada := COALESCE(to_char(v_orc.hora_evento, 'HH24:MI'), 'A combinar');
    v_validade_formatada := to_char(v_orc.validade_ate AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY "às" HH24:MI');

    IF p_tipo = 'ORCAMENTO_ENVIADO' THEN
      v_chave_idempotencia := 'orcamento:' || v_orc.id || ':v' || v_orc.versao || ':envio';
      v_mensagem := 'Olá, ' || v_orc.cliente_nome || '! 🎂' || E'\n\n' ||
                    'Preparamos sua proposta Lunoca:' || E'\n' ||
                    'Orçamento ' || v_orc.numero || ' (v' || v_orc.versao || ')' || E'\n' ||
                    'Evento: ' || v_data_formatada || ' às ' || v_hora_formatada || E'\n' ||
                    'Total: R$ ' || to_char(v_orc.total, 'FM999G999G990D00') || E'\n' ||
                    'Validade: até ' || v_validade_formatada || E'\n\n' ||
                    'Veja todos os detalhes e aprove sua proposta:' || E'\n' ||
                    v_link_publico || E'\n\n' ||
                    'A aprovação da proposta não reserva estoque ou capacidade até que a encomenda seja efetivamente convertida e confirmada.';

    ELSIF p_tipo = 'ORCAMENTO_VENCENDO' THEN
      v_chave_idempotencia := 'orcamento:' || v_orc.id || ':v' || v_orc.versao || ':vencendo';
      v_mensagem := 'Olá, ' || v_orc.cliente_nome || '! 🎂' || E'\n\n' ||
                    'Lembramos que sua proposta Lunoca está próxima do vencimento:' || E'\n' ||
                    'Orçamento ' || v_orc.numero || ' (v' || v_orc.versao || ')' || E'\n' ||
                    'Validade: até ' || v_validade_formatada || E'\n' ||
                    'Total: R$ ' || to_char(v_orc.total, 'FM999G999G990D00') || E'\n\n' ||
                    'Acesse para conferir ou aprovar antes do prazo expirar:' || E'\n' ||
                    v_link_publico || E'\n\n' ||
                    'Lembramos que a disponibilidade de data e capacidade de produção permanece sujeita à confirmação no momento da conversão da encomenda.';
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'tipo', p_tipo,
      'natureza_comunicacao', 'transacional',
      'entidade_tipo', 'orcamento',
      'orcamento_id', v_orc.id,
      'numero', v_orc.numero,
      'versao', v_orc.versao,
      'cliente_nome', v_orc.cliente_nome,
      'telefone', v_telefone_norm,
      'mensagem', v_mensagem,
      'link_publico', v_link_publico,
      'chave_idempotencia', v_chave_idempotencia
    );

  -- 2. Templates Transacionais de Pedido (NÃO exigem opt-in de marketing — Gate I16)
  ELSE
    IF p_pedido_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'code', 'PEDIDO_ID_REQUIRED', 'error', 'ID do pedido é obrigatório para este template.');
    END IF;

    SELECT * INTO v_ped FROM public.pedidos WHERE id = p_pedido_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'code', 'PEDIDO_NOT_FOUND', 'error', 'Pedido não encontrado.');
    END IF;

    v_telefone_raw := v_ped.telefone_cliente;
    v_telefone_norm := public.normalizar_telefone_e164(v_telefone_raw);
    IF v_telefone_norm IS NULL THEN
      RETURN jsonb_build_object('success', false, 'code', 'INVALID_PHONE', 'telefone_informado', v_telefone_raw, 'error', 'Telefone do cliente inválido ou ambíguo. Corrija o cadastro para prosseguir.');
    END IF;

    v_data_formatada := COALESCE(to_char(v_ped.data_entrega, 'DD/MM/YYYY'), 'A combinar');
    v_hora_formatada := COALESCE(to_char(v_ped.hora_entrega, 'HH24:MI'), 'A combinar');
    v_saldo_restante := GREATEST(0.00, COALESCE(v_ped.total, 0.00) - COALESCE(v_ped.valor_pago, 0.00));

    IF p_tipo = 'SINAL_CONFIRMADO' THEN
      SELECT id, valor INTO v_pag
      FROM public.pedido_pagamentos
      WHERE pedido_id = v_ped.id AND status = 'aprovado'
      ORDER BY id DESC LIMIT 1;

      IF NOT FOUND THEN
        IF COALESCE(v_ped.valor_pago, 0.00) > 0.00 THEN
          v_valor_sinal := v_ped.valor_pago;
          v_chave_idempotencia := 'pedido:' || v_ped.id || ':pagamento:0:sinal';
        ELSE
          RETURN jsonb_build_object('success', false, 'code', 'PAYMENT_NOT_APPROVED', 'error', 'Nenhum pagamento aprovado foi localizado para este pedido.');
        END IF;
      ELSE
        v_valor_sinal := v_pag.valor;
        v_chave_idempotencia := 'pedido:' || v_ped.id || ':pagamento:' || v_pag.id || ':sinal';
      END IF;

      v_mensagem := 'Recebemos seu sinal de R$ ' || to_char(v_valor_sinal, 'FM999G999G990D00') || ' ✅' || E'\n\n' ||
                    'Encomenda #' || v_ped.id || ' confirmada!' || E'\n' ||
                    'Data: ' || v_data_formatada || E'\n' ||
                    'Horário: ' || v_hora_formatada || E'\n' ||
                    'Modalidade: ' || CASE WHEN COALESCE(v_ped.modalidade_entrega, 'retirada') = 'entrega' THEN 'Entrega' ELSE 'Retirada na loja' END || E'\n' ||
                    'Total: R$ ' || to_char(v_ped.total, 'FM999G999G990D00') || E'\n' ||
                    'Saldo restante: R$ ' || to_char(v_saldo_restante, 'FM999G999G990D00') || E'\n\n' ||
                    'Agradecemos a confiança! Em breve sua encomenda entrará em produção.';

    ELSIF p_tipo = 'PEDIDO_PRONTO' THEN
      SELECT id INTO v_hist
      FROM public.pedido_status_historico
      WHERE pedido_id = v_ped.id AND status_novo = 'pronto'
      ORDER BY id DESC LIMIT 1;

      v_chave_idempotencia := 'pedido:' || v_ped.id || ':historico:' || COALESCE(v_hist.id::TEXT, '0') || ':pronto';
      v_mensagem := 'Sua encomenda está pronta! 🎂✨' || E'\n\n' ||
                    'Pedido #' || v_ped.id || E'\n' ||
                    'Cliente: ' || v_ped.nome_cliente || E'\n' ||
                    'Modalidade: ' || CASE WHEN COALESCE(v_ped.modalidade_entrega, 'retirada') = 'entrega' THEN 'Entrega' ELSE 'Retirada na loja' END || E'\n\n' ||
                    CASE
                      WHEN COALESCE(v_ped.modalidade_entrega, 'retirada') = 'entrega' THEN 'Já finalizamos a preparação e em breve seu pedido sairá para entrega!'
                      ELSE 'Seu pedido já está disponível para retirada em nossa doceria. Aguardamos sua visita!'
                    END;

    ELSIF p_tipo = 'SAIU_PARA_ENTREGA' THEN
      SELECT id INTO v_hist
      FROM public.pedido_status_historico
      WHERE pedido_id = v_ped.id AND status_novo IN ('entregue', 'saiu_para_entrega', 'em_rota')
      ORDER BY id DESC LIMIT 1;

      v_chave_idempotencia := 'pedido:' || v_ped.id || ':historico:' || COALESCE(v_hist.id::TEXT, '0') || ':entrega';
      v_mensagem := 'Sua encomenda Lunoca saiu para entrega! 🚗💨' || E'\n\n' ||
                    'Pedido #' || v_ped.id || E'\n' ||
                    'Destinatário: ' || v_ped.nome_cliente || E'\n' ||
                    'Endereço: ' || COALESCE(v_ped.endereco_entrega, 'Conforme combinado') || E'\n\n' ||
                    'Por favor, certifique-se de que haverá alguém para receber o pedido.' || E'\n' ||
                    'Bom apetite! 🍰';
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'tipo', p_tipo,
      'natureza_comunicacao', 'transacional',
      'entidade_tipo', 'pedido',
      'pedido_id', v_ped.id,
      'cliente_nome', v_ped.nome_cliente,
      'telefone', v_telefone_norm,
      'mensagem', v_mensagem,
      'link_publico', NULL,
      'chave_idempotencia', v_chave_idempotencia
    );
  END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_preview_comunicacao(TEXT, BIGINT, BIGINT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_preview_comunicacao(TEXT, BIGINT, BIGINT) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.registrar_comunicacao_cliente_marketing(
  p_tipo TEXT,
  p_campanha_id BIGINT,
  p_cliente_id BIGINT,
  p_canal TEXT DEFAULT 'whatsapp_link',
  p_status TEXT DEFAULT 'link_aberto',
  p_provider_message_id TEXT DEFAULT NULL,
  p_erro TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_preview JSONB;
  v_com_id BIGINT;
  v_status_final TEXT;
  v_chave TEXT;
  v_destinatario TEXT;
  v_mensagem TEXT;
  v_enviado_em TIMESTAMPTZ := NULL;
BEGIN
  IF NOT public.is_admin_or_operator() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada. Apenas equipe autorizada pode registrar comunicações.');
  END IF;

  IF p_canal NOT IN ('whatsapp_link', 'evolution_api') THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_CHANNEL', 'error', 'Canal de comunicação inválido.');
  END IF;

  v_status_final := COALESCE(p_status, 'link_aberto');

  IF p_canal = 'whatsapp_link' AND v_status_final IN ('enviado', 'entregue') THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'INVALID_STATUS_FOR_CHANNEL',
      'error', 'Abertura de link wa.me não comprova envio efetivo da mensagem. Para whatsapp_link, utilize status "link_aberto" ou "gerado".'
    );
  END IF;

  v_preview := public.obter_preview_comunicacao_marketing(p_tipo, p_campanha_id, p_cliente_id);
  IF (v_preview->>'success')::BOOLEAN IS NOT TRUE THEN
    RETURN v_preview;
  END IF;

  v_destinatario := v_preview->>'telefone';
  v_mensagem := v_preview->>'mensagem';
  v_chave := v_preview->>'chave_idempotencia';

  IF v_status_final IN ('enviado', 'entregue') THEN
    v_enviado_em := NOW();
  END IF;

  INSERT INTO public.comunicacoes_cliente (
    orcamento_id,
    pedido_id,
    campanha_id,
    cliente_id,
    tipo,
    canal,
    destinatario,
    mensagem_snapshot,
    status,
    provider,
    provider_message_id,
    chave_idempotencia,
    erro,
    metadata,
    criado_por,
    created_at,
    enviado_em
  ) VALUES (
    NULL,
    NULL,
    p_campanha_id,
    p_cliente_id,
    p_tipo,
    p_canal,
    v_destinatario,
    v_mensagem,
    v_status_final,
    CASE WHEN p_canal = 'evolution_api' THEN 'evolution_api' ELSE NULL END,
    p_provider_message_id,
    v_chave,
    p_erro,
    jsonb_build_object('preview_gerado_em', NOW(), 'natureza', 'marketing'),
    auth.uid(),
    NOW(),
    v_enviado_em
  )
  ON CONFLICT (chave_idempotencia) DO UPDATE SET
    status = EXCLUDED.status,
    provider_message_id = COALESCE(EXCLUDED.provider_message_id, comunicacoes_cliente.provider_message_id),
    erro = COALESCE(EXCLUDED.erro, comunicacoes_cliente.erro),
    enviado_em = COALESCE(EXCLUDED.enviado_em, comunicacoes_cliente.enviado_em)
  RETURNING id INTO v_com_id;

  RETURN jsonb_build_object(
    'success', true,
    'id', v_com_id,
    'tipo', p_tipo,
    'canal', p_canal,
    'status', v_status_final,
    'destinatario', v_destinatario,
    'chave_idempotencia', v_chave
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.registrar_comunicacao_cliente_marketing(TEXT, BIGINT, BIGINT, TEXT, TEXT, TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.registrar_comunicacao_cliente_marketing(TEXT, BIGINT, BIGINT, TEXT, TEXT, TEXT, TEXT) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 14. SEGMENTAÇÃO DINÂMICA E DISPARO AUDITÁVEL DE CAMPANHAS (GATE I17)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.salvar_campanha_admin(
  p_codigo TEXT,
  p_nome TEXT,
  p_tipo_template TEXT,
  p_mensagem_template TEXT,
  p_regra_segmentacao JSONB DEFAULT '{"segmento": "todos"}'::jsonb,
  p_canal TEXT DEFAULT 'whatsapp_marketing',
  p_cupom_id BIGINT DEFAULT NULL,
  p_bonus_pontos INTEGER DEFAULT 0,
  p_status TEXT DEFAULT 'ativa',
  p_id BIGINT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_camp_id BIGINT;
  v_cod TEXT := UPPER(btrim(COALESCE(p_codigo, '')));
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas administradores podem gerenciar campanhas.');
  END IF;

  IF char_length(v_cod) < 3 OR p_nome IS NULL OR btrim(p_nome) = '' THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_CAMPAIGN', 'error', 'Código e nome da campanha são obrigatórios.');
  END IF;

  IF p_id IS NOT NULL THEN
    UPDATE public.campanhas
    SET codigo = v_cod,
        nome = btrim(p_nome),
        tipo_template = p_tipo_template,
        mensagem_template = p_mensagem_template,
        regra_segmentacao = COALESCE(p_regra_segmentacao, '{"segmento": "todos"}'::jsonb),
        canal = COALESCE(p_canal, 'whatsapp_marketing'),
        cupom_id = p_cupom_id,
        bonus_pontos = COALESCE(p_bonus_pontos, 0),
        status = COALESCE(p_status, 'ativa'),
        updated_at = NOW()
    WHERE id = p_id
    RETURNING id INTO v_camp_id;
  ELSE
    INSERT INTO public.campanhas (
      codigo, nome, tipo_template, mensagem_template,
      regra_segmentacao, canal, cupom_id, bonus_pontos, status, criado_por
    ) VALUES (
      v_cod, btrim(p_nome), p_tipo_template, p_mensagem_template,
      COALESCE(p_regra_segmentacao, '{"segmento": "todos"}'::jsonb),
      COALESCE(p_canal, 'whatsapp_marketing'),
      p_cupom_id, COALESCE(p_bonus_pontos, 0), COALESCE(p_status, 'ativa'), auth.uid()
    )
    ON CONFLICT (codigo) DO UPDATE SET
      nome = EXCLUDED.nome,
      tipo_template = EXCLUDED.tipo_template,
      mensagem_template = EXCLUDED.mensagem_template,
      regra_segmentacao = EXCLUDED.regra_segmentacao,
      cupom_id = EXCLUDED.cupom_id,
      bonus_pontos = EXCLUDED.bonus_pontos,
      status = EXCLUDED.status,
      updated_at = NOW()
    RETURNING id INTO v_camp_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'campanha_id', v_camp_id, 'codigo', v_cod);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.salvar_campanha_admin(TEXT, TEXT, TEXT, TEXT, JSONB, TEXT, BIGINT, INTEGER, TEXT, BIGINT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.salvar_campanha_admin(TEXT, TEXT, TEXT, TEXT, JSONB, TEXT, BIGINT, INTEGER, TEXT, BIGINT) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.avaliar_publico_campanha(
  p_campanha_id BIGINT
)
RETURNS JSONB AS $$
DECLARE
  v_camp public.campanhas;
  v_seg TEXT;
  v_dias_inativo INT;
  v_ticket_min NUMERIC(10,2);
  v_mes_aniv INT;
  v_dias_expiracao INT;
  v_audiencia JSONB;
BEGIN
  IF NOT public.is_admin_or_operator() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada.');
  END IF;

  SELECT * INTO v_camp FROM public.campanhas WHERE id = p_campanha_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'CAMPAIGN_NOT_FOUND', 'error', 'Campanha não encontrada.');
  END IF;

  v_seg := COALESCE(v_camp.regra_segmentacao->>'segmento', 'todos');
  v_dias_inativo := COALESCE((v_camp.regra_segmentacao->>'dias_inatividade')::INT, 30);
  v_ticket_min := COALESCE((v_camp.regra_segmentacao->>'ticket_minimo')::NUMERIC, 150.00);
  v_mes_aniv := COALESCE((v_camp.regra_segmentacao->>'mes_aniversario')::INT, EXTRACT(MONTH FROM (NOW() AT TIME ZONE 'America/Fortaleza'))::INT);
  v_dias_expiracao := COALESCE((v_camp.regra_segmentacao->>'dias_expiracao')::INT, 30);

  WITH metricas_cli AS (
    SELECT
      c.id AS cliente_id,
      c.nome,
      c.telefone,
      c.telefone_normalizado,
      c.data_nascimento,
      COUNT(p.id) FILTER (WHERE p.status_comercial = 'concluido') AS qtd_concluidos,
      COALESCE(AVG(p.total) FILTER (WHERE p.status_comercial = 'concluido'), 0.00) AS ticket_medio,
      MAX(p.created_at) FILTER (WHERE p.status_comercial <> 'cancelado') AS ultimo_pedido_em,
      EXISTS (
        SELECT 1 FROM public.orcamentos o
        WHERE o.cliente_id = c.id AND o.status IN ('enviado', 'aprovado', 'expirado') AND o.pedido_id IS NULL
      ) AS tem_orcamento_nao_convertido,
      COALESCE(cp.saldo_pontos, 0) AS saldo_pontos,
      EXISTS (
        SELECT 1 FROM public.cliente_pontos_movimentacoes pm
        WHERE pm.cliente_id = c.id
          AND pm.natureza = 'credito'
          AND pm.expira_em IS NOT NULL
          AND pm.expira_em > NOW()
          AND pm.expira_em <= NOW() + make_interval(days => v_dias_expiracao)
      ) AS tem_pontos_expirando,
      public.obter_status_consentimento_marketing(c.id, v_camp.canal) AS consentimento_status
    FROM public.clientes c
    LEFT JOIN public.pedidos p ON p.cliente_id_rel = c.id
    LEFT JOIN public.cliente_pontos cp ON cp.cliente_id = c.id
    GROUP BY c.id, c.nome, c.telefone, c.telefone_normalizado, c.data_nascimento, cp.saldo_pontos
  ),
  filtrados AS (
    SELECT *
    FROM metricas_cli m
    WHERE
      CASE v_seg
        WHEN 'recorrentes' THEN m.qtd_concluidos >= 2
        WHEN 'inativos' THEN m.qtd_concluidos >= 1 AND m.ultimo_pedido_em < (NOW() - make_interval(days => v_dias_inativo))
        WHEN 'aniversariantes' THEN m.data_nascimento IS NOT NULL AND EXTRACT(MONTH FROM m.data_nascimento)::INT = v_mes_aniv
        WHEN 'alto_ticket' THEN m.ticket_medio >= v_ticket_min
        WHEN 'orcamento_nao_convertido' THEN m.tem_orcamento_nao_convertido IS TRUE
        WHEN 'pontos_expirando' THEN m.saldo_pontos > 0 AND m.tem_pontos_expirando IS TRUE
        ELSE true
      END
  )
  SELECT COALESCE(jsonb_agg(row_to_json(f)::jsonb ORDER BY f.cliente_id ASC), '[]'::jsonb)
  INTO v_audiencia
  FROM filtrados f;

  RETURN jsonb_build_object(
    'success', true,
    'campanha_id', v_camp.id,
    'segmento', v_seg,
    'total_Matching', jsonb_array_length(v_audiencia),
    'audiencia', v_audiencia
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.avaliar_publico_campanha(BIGINT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.avaliar_publico_campanha(BIGINT) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.disparar_campanha_marketing(
  p_campanha_id BIGINT,
  p_canal_envio TEXT DEFAULT 'whatsapp_link'
)
RETURNS JSONB AS $$
DECLARE
  v_camp public.campanhas;
  v_aval JSONB;
  v_item JSONB;
  v_cli_id BIGINT;
  v_consent TEXT;
  v_com_res JSONB;
  v_qtd_disparados INTEGER := 0;
  v_qtd_bloqueados INTEGER := 0;
  v_qtd_ja_processados INTEGER := 0;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas administradores podem disparar campanhas de marketing.');
  END IF;

  SELECT * INTO v_camp FROM public.campanhas WHERE id = p_campanha_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'CAMPAIGN_NOT_FOUND', 'error', 'Campanha não encontrada.');
  END IF;

  v_aval := public.avaliar_publico_campanha(p_campanha_id);
  IF (v_aval->>'success')::BOOLEAN IS NOT TRUE THEN
    RETURN v_aval;
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_aval->'audiencia')
  LOOP
    v_cli_id := (v_item->>'cliente_id')::BIGINT;
    v_consent := v_item->>'consentimento_status';

    -- Gate I17: Nunca duplica destinatário na mesma campanha
    IF EXISTS (
      SELECT 1 FROM public.campanha_publicos
      WHERE campanha_id = p_campanha_id AND cliente_id = v_cli_id
    ) THEN
      v_qtd_ja_processados := v_qtd_ja_processados + 1;
      CONTINUE;
    END IF;

    IF v_consent <> 'opt_in' THEN
      INSERT INTO public.campanha_publicos (
        campanha_id, cliente_id, telefone_destino, consentimento_status,
        comunicacao_id, status_disparo, motivo_bloqueio, snapshot_criterio
      ) VALUES (
        p_campanha_id, v_cli_id, v_item->>'telefone_normalizado', v_consent,
        NULL, 'bloqueado_sem_consentimento', 'Cliente sem opt-in ativo de marketing', v_item
      ) ON CONFLICT (campanha_id, cliente_id) DO NOTHING;

      v_qtd_bloqueados := v_qtd_bloqueados + 1;
      CONTINUE;
    END IF;

    -- Dispara pela esteira canônica da Frente B (registrar_comunicacao_cliente_marketing -> comunicacoes_cliente)
    v_com_res := public.registrar_comunicacao_cliente_marketing(
      p_tipo := v_camp.tipo_template,
      p_campanha_id := p_campanha_id,
      p_cliente_id := v_cli_id,
      p_canal := p_canal_envio,
      p_status := CASE WHEN p_canal_envio = 'evolution_api' THEN 'enviado' ELSE 'link_aberto' END,
      p_provider_message_id := NULL,
      p_erro := NULL
    );

    IF (v_com_res->>'success')::BOOLEAN IS TRUE THEN
      INSERT INTO public.campanha_publicos (
        campanha_id, cliente_id, telefone_destino, consentimento_status,
        comunicacao_id, status_disparo, motivo_bloqueio, snapshot_criterio
      ) VALUES (
        p_campanha_id, v_cli_id, v_com_res->>'destinatario', v_consent,
        (v_com_res->>'id')::BIGINT, 'disparado', NULL, v_item
      ) ON CONFLICT (campanha_id, cliente_id) DO NOTHING;

      IF v_camp.bonus_pontos > 0 THEN
        PERFORM public._aplicar_movimento_pontos_cliente(
          p_cliente_id := v_cli_id,
          p_tipo := 'BONUS_CAMPANHA',
          p_natureza := 'credito',
          p_pontos := v_camp.bonus_pontos,
          p_motivo := 'Bônus da campanha ' || v_camp.codigo,
          p_chave_idempotencia := 'bonus_campanha:' || p_campanha_id || ':cli:' || v_cli_id,
          p_pedido_id := NULL,
          p_campanha_id := p_campanha_id,
          p_lote_origem_id := NULL,
          p_expira_em := NOW() + INTERVAL '90 days'
        );
      END IF;

      v_qtd_disparados := v_qtd_disparados + 1;
    ELSE
      INSERT INTO public.campanha_publicos (
        campanha_id, cliente_id, telefone_destino, consentimento_status,
        comunicacao_id, status_disparo, motivo_bloqueio, snapshot_criterio
      ) VALUES (
        p_campanha_id, v_cli_id, v_item->>'telefone_normalizado', v_consent,
        NULL, 'ignorado_sem_telefone', v_com_res->>'error', v_item
      ) ON CONFLICT (campanha_id, cliente_id) DO NOTHING;
    END IF;
  END LOOP;

  UPDATE public.campanhas
  SET status = 'disparada', updated_at = NOW()
  WHERE id = p_campanha_id;

  RETURN jsonb_build_object(
    'success', true,
    'campanha_id', p_campanha_id,
    'disparados', v_qtd_disparados,
    'bloqueados_sem_consentimento', v_qtd_bloqueados,
    'ja_processados_idempotente', v_qtd_ja_processados
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.disparar_campanha_marketing(BIGINT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.disparar_campanha_marketing(BIGINT, TEXT) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 15. RPC DE LEITURA ADMINISTRATIVA: OBTER_PAINEL_FIDELIDADE_CAMPANHAS_ADMIN
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.obter_painel_fidelidade_campanhas_admin()
RETURNS JSONB AS $$
DECLARE
  v_prog JSONB;
  v_resumo JSONB;
  v_cupons JSONB;
  v_campanhas JSONB;
  v_carteira_top JSONB;
  v_movs JSONB;
BEGIN
  IF NOT public.is_admin_or_operator() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Permissão negada.');
  END IF;

  SELECT row_to_json(pf)::jsonb INTO v_prog
  FROM public.programas_fidelidade pf
  WHERE pf.ativo = true
  ORDER BY pf.id ASC
  LIMIT 1;

  SELECT jsonb_build_object(
    'clientes_com_pontos', (SELECT COUNT(*) FROM public.cliente_pontos WHERE saldo_pontos > 0),
    'saldo_pontos_circulacao', COALESCE((SELECT SUM(saldo_pontos) FROM public.cliente_pontos), 0),
    'pontos_acumulados_total', COALESCE((SELECT SUM(pontos_acumulados_total) FROM public.cliente_pontos), 0),
    'pontos_resgatados_total', COALESCE((SELECT SUM(pontos_resgatados_total) FROM public.cliente_pontos), 0),
    'pontos_expirados_total', COALESCE((SELECT SUM(pontos_expirados_total) FROM public.cliente_pontos), 0),
    'cupons_ativos', (SELECT COUNT(*) FROM public.cupons_promocionais WHERE ativo = true AND validade_fim >= NOW()),
    'campanhas_registradas', (SELECT COUNT(*) FROM public.campanhas),
    'clientes_opt_in_whatsapp', (
      SELECT COUNT(*) FROM (
        SELECT DISTINCT ON (cliente_id) cliente_id, status
        FROM public.cliente_consentimentos_marketing
        WHERE canal = 'whatsapp_marketing'
        ORDER BY cliente_id, data_hora DESC, id DESC
      ) s WHERE s.status = 'opt_in'
    )
  ) INTO v_resumo;

  SELECT COALESCE(jsonb_agg(row_to_json(cp)::jsonb ORDER BY cp.id DESC), '[]'::jsonb)
  INTO v_cupons
  FROM (
    SELECT
      c.*,
      (SELECT COUNT(*) FROM public.cupom_utilizacoes cu WHERE cu.cupom_id = c.id AND cu.status = 'aplicado') AS total_usos
    FROM public.cupons_promocionais c
    ORDER BY c.id DESC
    LIMIT 50
  ) cp;

  SELECT COALESCE(jsonb_agg(row_to_json(cm)::jsonb ORDER BY cm.id DESC), '[]'::jsonb)
  INTO v_campanhas
  FROM (
    SELECT
      ca.*,
      (SELECT COUNT(*) FROM public.campanha_publicos pub WHERE pub.campanha_id = ca.id AND pub.status_disparo = 'disparado') AS total_disparados,
      (SELECT COUNT(*) FROM public.campanha_publicos pub WHERE pub.campanha_id = ca.id AND pub.status_disparo = 'bloqueado_sem_consentimento') AS total_bloqueados
    FROM public.campanhas ca
    ORDER BY ca.id DESC
    LIMIT 50
  ) cm;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.saldo_pontos DESC), '[]'::jsonb)
  INTO v_carteira_top
  FROM (
    SELECT
      cp.cliente_id,
      cl.nome AS cliente_nome,
      cl.telefone,
      cp.saldo_pontos,
      cp.pontos_acumulados_total,
      cp.pontos_resgatados_total,
      cp.pontos_expirados_total,
      public.obter_status_consentimento_marketing(cp.cliente_id, 'whatsapp_marketing') AS consentimento_whatsapp
    FROM public.cliente_pontos cp
    JOIN public.clientes cl ON cl.id = cp.cliente_id
    ORDER BY cp.saldo_pontos DESC, cp.cliente_id ASC
    LIMIT 50
  ) t;

  SELECT COALESCE(jsonb_agg(row_to_json(m)::jsonb ORDER BY m.id DESC), '[]'::jsonb)
  INTO v_movs
  FROM (
    SELECT
      pm.id,
      pm.cliente_id,
      cl.nome AS cliente_nome,
      pm.tipo,
      pm.natureza,
      pm.pontos,
      pm.saldo_anterior,
      pm.saldo_posterior,
      pm.pedido_id,
      pm.expira_em,
      pm.motivo,
      pm.created_at
    FROM public.cliente_pontos_movimentacoes pm
    JOIN public.clientes cl ON cl.id = pm.cliente_id
    ORDER BY pm.id DESC
    LIMIT 50
  ) m;

  RETURN jsonb_build_object(
    'success', true,
    'programa', v_prog,
    'resumo', v_resumo,
    'cupons', v_cupons,
    'campanhas', v_campanhas,
    'clientes_pontos', v_carteira_top,
    'movimentacoes_recentes', v_movs
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_painel_fidelidade_campanhas_admin() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_painel_fidelidade_campanhas_admin() TO authenticated, service_role;


-- ==========================================================================
-- >>> MIGRATION 025_portal_cliente_minha_conta.sql
-- ==========================================================================

-- ==============================================================================
-- LUNOCA DOCERIA - MIGRATION 025: FRENTE J - PORTAL DO CLIENTE / MINHA CONTA
-- ==============================================================================
-- Diretrizes Centrais e Invariantes (Frente J):
-- 1. Zero lógica de negócio nova: O portal é uma camada pura de projeção
--    sanitizada e self-service fail-closed sobre as Frentes B, C, D, E e I.
-- 2. Resolução estrita de identidade:
--      auth.uid() -> clientes.auth_user_id -> cliente_id
--    Sem fallback por e-mail ou telefone, sem aceitar p_cliente_id vindo do
--    navegador em nenhuma RPC pública do portal (Gate J4).
-- 3. Unicidade estrutural de vínculo: no máximo 1 cliente por auth_user_id;
--    ausência de vínculo falha fechado com CLIENT_LINK_REQUIRED (Gate J2).
-- 4. Zero exposição de credenciais ou dados internos:
--    - Orçamentos no portal JAMAIS retornam token_publico (Gate J7).
--    - Aprovação autenticada usa aprovar_meu_orcamento(p_orcamento_id, p_versao_esperada)
--      validando propriedade do cliente e delegando internamente para
--      aprovar_orcamento_publico (Gate J8).
--    - Pedidos JAMAIS expõem observacoes_internas, pedido_producao_observacoes,
--      prioridade_cozinha, custos, margens, provider_payment_id ou metadata (Gates J5, J6).
-- 5. Separação semântica estrita (Gates J9, J10, J11):
--    - Meu Crédito Financeiro (R$ - Frente C) != Meus Pontos (pts - Frente I).
-- 6. Preferências Self-Service e Privacidade (Gates J13, J14, J15, J16):
--    - Cliente gerencia apenas categorias permitidas ('sabor', 'decoracao',
--      'ocasiao', 'restricao_alimentar', 'embalagem').
--    - Notas internas e tags administrativas permanecem 100% invisíveis e intocáveis.
--    - Consentimento de marketing (opt_in / opt_out) é gravado append-only com
--      origem = 'portal_cliente' e prevalece imediatamente sobre campanhas,
--      sem bloquear comunicações transacionais.
-- ==============================================================================

-- ------------------------------------------------------------------------------
-- 1. UNICIDADE ESTRUTURAL DO VÍNCULO AUTH_USER_ID E CATEGORIAS DE PREFERÊNCIA
-- ------------------------------------------------------------------------------
CREATE UNIQUE INDEX IF NOT EXISTS uq_clientes_auth_user_id
  ON public.clientes(auth_user_id)
  WHERE auth_user_id IS NOT NULL;

-- Amplia o CHECK de categorias de cliente_preferencias para incluir 'embalagem'
-- (mantendo retrocompatibilidade com 'atendimento' e 'outro' para uso da equipe)
DO $$
BEGIN
  ALTER TABLE public.cliente_preferencias
    DROP CONSTRAINT IF EXISTS cliente_preferencias_categoria_check;
  ALTER TABLE public.cliente_preferencias
    ADD CONSTRAINT cliente_preferencias_categoria_check
    CHECK (categoria IN ('sabor', 'decoracao', 'ocasiao', 'atendimento', 'restricao_alimentar', 'embalagem', 'outro'));
EXCEPTION
  WHEN OTHERS THEN NULL;
END $$;

-- ------------------------------------------------------------------------------
-- 2. HELPER INTERNO FAIL-CLOSED DE RESOLUÇÃO DE IDENTIDADE DO CLIENTE
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public._resolver_meu_cliente_id()
RETURNS JSONB AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_qtd INTEGER := 0;
  v_cli public.clientes;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'UNAUTHENTICATED',
      'error', 'Sessão autenticada obrigatória para acessar o Portal do Cliente.'
    );
  END IF;

  SELECT COUNT(*) INTO v_qtd
  FROM public.clientes
  WHERE auth_user_id = v_uid;

  IF v_qtd = 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'CLIENT_LINK_REQUIRED',
      'error', 'Sua conta ainda não possui um cadastro de cliente vinculado.'
    );
  END IF;

  IF v_qtd > 1 THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'AMBIGUOUS_CLIENT_LINK',
      'error', 'Múltiplos cadastros vinculados ao mesmo usuário. Contate o suporte.'
    );
  END IF;

  SELECT * INTO v_cli
  FROM public.clientes
  WHERE auth_user_id = v_uid
  LIMIT 1;

  RETURN jsonb_build_object(
    'success', true,
    'cliente_id', v_cli.id,
    'nome', v_cli.nome,
    'email', v_cli.email,
    'telefone', v_cli.telefone,
    'data_nascimento', v_cli.data_nascimento,
    'endereco_padrao', COALESCE(v_cli.endereco_padrao, '{}'::jsonb)
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public._resolver_meu_cliente_id() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public._resolver_meu_cliente_id() TO service_role;

-- ------------------------------------------------------------------------------
-- 3. HELPER INTERNO DE DERIVAÇÃO DA ETAPA AMIGÁVEL DO CLIENTE
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public._derivar_etapa_cliente_pedido(
  p_status_comercial TEXT,
  p_status_operacional TEXT,
  p_modalidade TEXT
)
RETURNS TEXT AS $$
BEGIN
  IF COALESCE(p_status_comercial, '') = 'cancelado' OR COALESCE(p_status_operacional, '') = 'cancelado' THEN
    RETURN 'cancelado';
  END IF;

  IF COALESCE(p_status_operacional, '') = 'entregue' THEN
    RETURN 'entregue';
  END IF;

  IF COALESCE(p_status_operacional, '') = 'retirado' THEN
    RETURN 'retirado';
  END IF;

  IF COALESCE(p_status_operacional, '') IN ('saiu_para_entrega', 'em_rota') THEN
    RETURN 'saiu_para_entrega';
  END IF;

  IF COALESCE(p_status_operacional, '') = 'pronto' THEN
    IF COALESCE(p_modalidade, 'retirada') = 'entrega' THEN
      RETURN 'pronto_para_entrega';
    ELSE
      RETURN 'pronto_para_retirada';
    END IF;
  END IF;

  IF COALESCE(p_status_operacional, '') = 'em_producao' THEN
    RETURN 'em_preparo';
  END IF;

  RETURN 'aguardando_preparo';
END;
$$ LANGUAGE plpgsql IMMUTABLE;

REVOKE ALL ON FUNCTION public._derivar_etapa_cliente_pedido(TEXT, TEXT, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public._derivar_etapa_cliente_pedido(TEXT, TEXT, TEXT) TO service_role;

-- ------------------------------------------------------------------------------
-- 4. RPC RESUMO DO PORTAL: OBTER_PAINEL_MINHA_CONTA_CLIENTE()
-- ------------------------------------------------------------------------------
-- Retorna apenas resumo enxuto e itens recentes (sem históricos gigantescos).
CREATE OR REPLACE FUNCTION public.obter_painel_minha_conta_cliente()
RETURNS JSONB AS $$
DECLARE
  v_ident JSONB := public._resolver_meu_cliente_id();
  v_cli_id BIGINT;
  v_saldo_credito NUMERIC(10,2) := 0.00;
  v_saldo_pontos INTEGER := 0;
  v_pontos_expirando_30d INTEGER := 0;
  v_prog RECORD;
  v_pedidos_recentes JSONB;
  v_orcamentos_recentes JSONB;
  v_cupons_elegiveis_qtd INTEGER := 0;
  v_preferencias JSONB;
  v_consentimento_whatsapp TEXT;
BEGIN
  IF (v_ident->>'success')::BOOLEAN IS NOT TRUE THEN
    RETURN v_ident;
  END IF;

  v_cli_id := (v_ident->>'cliente_id')::BIGINT;

  -- Atualiza expiração de pontos vencidos de forma transparente antes da leitura
  PERFORM public._processar_expiracao_pontos_cliente(v_cli_id, NOW());

  -- 1. Saldo Financeiro (Frente C - estritamente separado de pontos)
  SELECT COALESCE(saldo, 0.00) INTO v_saldo_credito
  FROM public.cliente_creditos
  WHERE cliente_id = v_cli_id;

  -- 2. Saldo de Pontos de Fidelidade (Frente I - benefício promocional)
  SELECT COALESCE(saldo_pontos, 0) INTO v_saldo_pontos
  FROM public.cliente_pontos
  WHERE cliente_id = v_cli_id;

  SELECT COALESCE(SUM(pontos), 0) INTO v_pontos_expirando_30d
  FROM public.cliente_pontos_movimentacoes pm
  WHERE pm.cliente_id = v_cli_id
    AND pm.natureza = 'credito'
    AND pm.expira_em IS NOT NULL
    AND pm.expira_em > NOW()
    AND pm.expira_em <= NOW() + INTERVAL '30 days'
    AND NOT EXISTS (
      SELECT 1 FROM public.cliente_pontos_movimentacoes exp_m
      WHERE exp_m.lote_origem_id = pm.id AND exp_m.tipo = 'EXPIRACAO'
    );

  SELECT nome, pontos_por_real, valor_por_ponto_resgate, resgate_minimo_pontos
  INTO v_prog
  FROM public.programas_fidelidade
  WHERE ativo = true
  ORDER BY id ASC
  LIMIT 1;

  -- 3. Pedidos recentes (máximo 5, sanitizados)
  SELECT COALESCE(jsonb_agg(row_to_json(p_row)::jsonb ORDER BY p_row.created_at DESC), '[]'::jsonb)
  INTO v_pedidos_recentes
  FROM (
    SELECT
      p.id AS pedido_id,
      p.data_entrega,
      p.hora_entrega,
      COALESCE(p.modalidade_entrega, 'retirada') AS modalidade,
      p.status_comercial,
      p.status_financeiro,
      public._derivar_etapa_cliente_pedido(p.status_comercial, p.status_operacional, p.modalidade_entrega) AS etapa_cliente,
      ROUND(COALESCE(p.total, 0.00), 2) AS total,
      ROUND(GREATEST(0.00, COALESCE(p.saldo, COALESCE(p.total, 0.00) - COALESCE(p.valor_pago, 0.00))), 2) AS saldo_a_pagar,
      p.created_at
    FROM public.pedidos p
    WHERE p.cliente_id_rel = v_cli_id
    ORDER BY p.created_at DESC, p.id DESC
    LIMIT 5
  ) p_row;

  -- 4. Orçamentos recentes (máximo 5, SEM token_publico)
  SELECT COALESCE(jsonb_agg(row_to_json(o_row)::jsonb ORDER BY o_row.created_at DESC), '[]'::jsonb)
  INTO v_orcamentos_recentes
  FROM (
    SELECT
      o.id AS orcamento_id,
      o.numero,
      o.versao,
      o.status,
      o.data_evento,
      o.hora_evento,
      o.tipo_entrega AS modalidade,
      ROUND(COALESCE(o.total, 0.00), 2) AS total,
      o.validade_ate,
      o.aprovado_em,
      o.pedido_id,
      o.created_at
    FROM public.orcamentos o
    WHERE o.cliente_id = v_cli_id
    ORDER BY o.created_at DESC, o.id DESC
    LIMIT 5
  ) o_row;

  -- 5. Contagem de cupons elegíveis para o próprio cliente
  SELECT COUNT(*) INTO v_cupons_elegiveis_qtd
  FROM public.cupons_promocionais cp
  WHERE cp.ativo = true
    AND cp.validade_inicio <= NOW()
    AND cp.validade_fim >= NOW()
    AND (
      cp.uso_maximo_global IS NULL
      OR (SELECT COUNT(*) FROM public.cupom_utilizacoes cu WHERE cu.cupom_id = cp.id AND cu.status = 'aplicado') < cp.uso_maximo_global
    )
    AND (
      cp.uso_maximo_cliente IS NULL
      OR (SELECT COUNT(*) FROM public.cupom_utilizacoes cu WHERE cu.cupom_id = cp.id AND cu.cliente_id = v_cli_id AND cu.status = 'aplicado') < cp.uso_maximo_cliente
    );

  -- 6. Preferências declaradas ativas (apenas categorias self-service)
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', pref.id,
      'categoria', pref.categoria,
      'valor', pref.valor,
      'observacao', pref.observacao,
      'updated_at', pref.updated_at
    ) ORDER BY pref.categoria ASC, pref.id DESC
  ), '[]'::jsonb)
  INTO v_preferencias
  FROM public.cliente_preferencias pref
  WHERE pref.cliente_id = v_cli_id
    AND pref.ativo = true
    AND pref.categoria IN ('sabor', 'decoracao', 'ocasiao', 'restricao_alimentar', 'embalagem');

  -- 7. Status atual de consentimento de marketing
  v_consentimento_whatsapp := public.obter_status_consentimento_marketing(v_cli_id, 'whatsapp_marketing');

  RETURN jsonb_build_object(
    'success', true,
    'perfil', jsonb_build_object(
      'nome', v_ident->>'nome',
      'email', v_ident->>'email',
      'telefone', v_ident->>'telefone',
      'data_nascimento', v_ident->>'data_nascimento',
      'endereco_padrao', v_ident->'endereco_padrao'
    ),
    'meu_credito', jsonb_build_object(
      'natureza', 'valor_financeiro',
      'moeda', 'BRL',
      'saldo_reais', ROUND(v_saldo_credito, 2),
      'descricao', 'Crédito financeiro em carteira (Frente C)'
    ),
    'meus_pontos', jsonb_build_object(
      'natureza', 'beneficio_promocional',
      'unidade', 'pts',
      'saldo_pontos', v_saldo_pontos,
      'pontos_expirando_30d', LEAST(v_saldo_pontos, v_pontos_expirando_30d),
      'programa_nome', COALESCE(v_prog.nome, 'Clube de Fidelidade Lunoca'),
      'resgate_minimo_pontos', COALESCE(v_prog.resgate_minimo_pontos, 20),
      'valor_por_ponto_resgate', COALESCE(v_prog.valor_por_ponto_resgate, 0.0500),
      'descricao', 'Pontos promocionais do programa de fidelidade (Frente I)'
    ),
    'resumo_contadores', jsonb_build_object(
      'cupons_disponiveis', v_cupons_elegiveis_qtd,
      'consentimento_whatsapp_marketing', v_consentimento_whatsapp
    ),
    'pedidos_recentes', v_pedidos_recentes,
    'orcamentos_recentes', v_orcamentos_recentes,
    'preferencias_declaradas', v_preferencias
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_painel_minha_conta_cliente() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_painel_minha_conta_cliente() TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 5. MEUS PEDIDOS E DETALHE DE PEDIDO SANITIZADO (GATES J3, J5, J6)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.listar_meus_pedidos(
  p_limite INTEGER DEFAULT 20,
  p_offset INTEGER DEFAULT 0
)
RETURNS JSONB AS $$
DECLARE
  v_ident JSONB := public._resolver_meu_cliente_id();
  v_cli_id BIGINT;
  v_lim INTEGER := LEAST(GREATEST(COALESCE(p_limite, 20), 1), 50);
  v_off INTEGER := GREATEST(COALESCE(p_offset, 0), 0);
  v_total INTEGER := 0;
  v_pedidos JSONB;
BEGIN
  IF (v_ident->>'success')::BOOLEAN IS NOT TRUE THEN
    RETURN v_ident;
  END IF;

  v_cli_id := (v_ident->>'cliente_id')::BIGINT;

  SELECT COUNT(*) INTO v_total
  FROM public.pedidos p
  WHERE p.cliente_id_rel = v_cli_id;

  SELECT COALESCE(jsonb_agg(row_to_json(r)::jsonb ORDER BY r.created_at DESC, r.pedido_id DESC), '[]'::jsonb)
  INTO v_pedidos
  FROM (
    SELECT
      p.id AS pedido_id,
      p.data_entrega,
      p.hora_entrega,
      COALESCE(p.modalidade_entrega, 'retirada') AS modalidade,
      p.status_comercial,
      p.status_financeiro,
      public._derivar_etapa_cliente_pedido(p.status_comercial, p.status_operacional, p.modalidade_entrega) AS etapa_cliente,
      ROUND(COALESCE(p.subtotal, p.total, 0.00), 2) AS subtotal,
      ROUND(COALESCE(p.desconto, 0.00), 2) AS desconto,
      ROUND(COALESCE(p.taxa_entrega, 0.00), 2) AS taxa_entrega,
      ROUND(COALESCE(p.total, 0.00), 2) AS total,
      ROUND(COALESCE(p.valor_pago, 0.00), 2) AS valor_pago,
      ROUND(GREATEST(0.00, COALESCE(p.saldo, COALESCE(p.total, 0.00) - COALESCE(p.valor_pago, 0.00))), 2) AS saldo_a_pagar,
      p.observacoes_cliente,
      p.created_at,
      COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'item_id', pi.id,
            'nome', pi.produto_nome_snapshot,
            'quantidade', pi.quantidade,
            'unidade', COALESCE(pi.unidade, 'un'),
            'preco_unitario', ROUND(COALESCE(pi.preco_unitario_snapshot, 0.00), 2),
            'opcoes', COALESCE((
              SELECT jsonb_agg(
                jsonb_build_object(
                  'tipo', pio.tipo,
                  'opcao_nome', pio.opcao_nome,
                  'preco_adicional', ROUND(COALESCE(pio.preco_adicional, 0.00), 2)
                ) ORDER BY pio.id ASC
              )
              FROM public.pedido_item_opcoes pio
              WHERE pio.pedido_item_id = pi.id
            ), '[]'::jsonb)
          ) ORDER BY pi.id ASC
        )
        FROM public.pedido_itens pi
        WHERE pi.pedido_id = p.id
      ), '[]'::jsonb) AS itens
    FROM public.pedidos p
    WHERE p.cliente_id_rel = v_cli_id
    ORDER BY p.created_at DESC, p.id DESC
    LIMIT v_lim OFFSET v_off
  ) r;

  RETURN jsonb_build_object(
    'success', true,
    'total_registros', v_total,
    'limite', v_lim,
    'offset', v_off,
    'pedidos', v_pedidos
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.listar_meus_pedidos(INTEGER, INTEGER) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.listar_meus_pedidos(INTEGER, INTEGER) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.obter_meu_pedido(
  p_pedido_id BIGINT
)
RETURNS JSONB AS $$
DECLARE
  v_ident JSONB := public._resolver_meu_cliente_id();
  v_cli_id BIGINT;
  v_ped RECORD;
  v_itens JSONB;
BEGIN
  IF (v_ident->>'success')::BOOLEAN IS NOT TRUE THEN
    RETURN v_ident;
  END IF;

  IF p_pedido_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_ID_REQUIRED', 'error', 'ID do pedido é obrigatório.');
  END IF;

  v_cli_id := (v_ident->>'cliente_id')::BIGINT;

  -- Gate J3: Filtra estritamente por id E cliente_id_rel = v_cli_id
  SELECT
    p.id AS pedido_id,
    p.data_entrega,
    p.hora_entrega,
    COALESCE(p.modalidade_entrega, 'retirada') AS modalidade,
    p.endereco_entrega,
    p.status_comercial,
    p.status_financeiro,
    public._derivar_etapa_cliente_pedido(p.status_comercial, p.status_operacional, p.modalidade_entrega) AS etapa_cliente,
    ROUND(COALESCE(p.subtotal, p.total, 0.00), 2) AS subtotal,
    ROUND(COALESCE(p.desconto, 0.00), 2) AS desconto,
    ROUND(COALESCE(p.taxa_entrega, 0.00), 2) AS taxa_entrega,
    ROUND(COALESCE(p.total, 0.00), 2) AS total,
    ROUND(COALESCE(p.valor_pago, 0.00), 2) AS valor_pago,
    ROUND(GREATEST(0.00, COALESCE(p.saldo, COALESCE(p.total, 0.00) - COALESCE(p.valor_pago, 0.00))), 2) AS saldo_a_pagar,
    p.observacoes_cliente,
    p.created_at
  INTO v_ped
  FROM public.pedidos p
  WHERE p.id = p_pedido_id
    AND p.cliente_id_rel = v_cli_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'ORDER_NOT_FOUND',
      'error', 'Pedido não encontrado para sua conta.'
    );
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'item_id', pi.id,
      'nome', pi.produto_nome_snapshot,
      'quantidade', pi.quantidade,
      'unidade', COALESCE(pi.unidade, 'un'),
      'preco_unitario', ROUND(COALESCE(pi.preco_unitario_snapshot, 0.00), 2),
      'opcoes', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'tipo', pio.tipo,
            'opcao_nome', pio.opcao_nome,
            'preco_adicional', ROUND(COALESCE(pio.preco_adicional, 0.00), 2)
          ) ORDER BY pio.id ASC
        )
        FROM public.pedido_item_opcoes pio
        WHERE pio.pedido_item_id = pi.id
      ), '[]'::jsonb)
    ) ORDER BY pi.id ASC
  ), '[]'::jsonb)
  INTO v_itens
  FROM public.pedido_itens pi
  WHERE pi.pedido_id = v_ped.pedido_id;

  RETURN jsonb_build_object(
    'success', true,
    'pedido', jsonb_build_object(
      'pedido_id', v_ped.pedido_id,
      'data_entrega', v_ped.data_entrega,
      'hora_entrega', v_ped.hora_entrega,
      'modalidade', v_ped.modalidade,
      'endereco_entrega', v_ped.endereco_entrega,
      'status_comercial', v_ped.status_comercial,
      'status_financeiro', v_ped.status_financeiro,
      'etapa_cliente', v_ped.etapa_cliente,
      'subtotal', v_ped.subtotal,
      'desconto', v_ped.desconto,
      'taxa_entrega', v_ped.taxa_entrega,
      'total', v_ped.total,
      'valor_pago', v_ped.valor_pago,
      'saldo_a_pagar', v_ped.saldo_a_pagar,
      'observacoes_cliente', v_ped.observacoes_cliente,
      'created_at', v_ped.created_at,
      'itens', v_itens
    )
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_meu_pedido(BIGINT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_meu_pedido(BIGINT) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 6. MEUS ORÇAMENTOS SEM TOKEN_PUBLICO E APROVAÇÃO AUTENTICADA (GATES J7, J8)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.listar_meus_orcamentos(
  p_limite INTEGER DEFAULT 20,
  p_offset INTEGER DEFAULT 0
)
RETURNS JSONB AS $$
DECLARE
  v_ident JSONB := public._resolver_meu_cliente_id();
  v_cli_id BIGINT;
  v_lim INTEGER := LEAST(GREATEST(COALESCE(p_limite, 20), 1), 50);
  v_off INTEGER := GREATEST(COALESCE(p_offset, 0), 0);
  v_total INTEGER := 0;
  v_orcamentos JSONB;
BEGIN
  IF (v_ident->>'success')::BOOLEAN IS NOT TRUE THEN
    RETURN v_ident;
  END IF;

  v_cli_id := (v_ident->>'cliente_id')::BIGINT;

  SELECT COUNT(*) INTO v_total
  FROM public.orcamentos o
  WHERE o.cliente_id = v_cli_id;

  -- Gate J7: JAMAIS inclui token_publico nem observacoes_internas
  SELECT COALESCE(jsonb_agg(row_to_json(r)::jsonb ORDER BY r.created_at DESC, r.orcamento_id DESC), '[]'::jsonb)
  INTO v_orcamentos
  FROM (
    SELECT
      o.id AS orcamento_id,
      o.numero,
      o.versao,
      o.status,
      o.data_evento,
      o.hora_evento,
      o.tipo_entrega AS modalidade,
      o.endereco_entrega,
      ROUND(COALESCE(o.subtotal, 0.00), 2) AS subtotal,
      ROUND(COALESCE(o.desconto_produtos, 0.00) + COALESCE(o.desconto_frete, 0.00), 2) AS desconto,
      ROUND(COALESCE(o.taxa_entrega_cobrada, 0.00), 2) AS taxa_entrega,
      ROUND(COALESCE(o.total, 0.00), 2) AS total,
      ROUND(COALESCE(o.sinal_sugerido, 0.00), 2) AS sinal_minimo,
      o.validade_ate,
      o.aprovado_em,
      o.pedido_id,
      o.observacoes_cliente,
      o.created_at,
      COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'item_id', oi.id,
            'nome', COALESCE(pr.nome, 'Produto #' || oi.produto_id::TEXT),
            'quantidade', oi.quantidade,
            'unidade', 'un',
            'preco_unitario', ROUND(COALESCE(oi.preco_unitario_snapshot, 0.00), 2),
            'subtotal', ROUND(COALESCE(oi.subtotal, 0.00), 2),
            'opcoes', COALESCE((
              SELECT jsonb_agg(
                jsonb_build_object(
                  'categoria', oio.tipo,
                  'opcao_nome', oio.opcao_nome,
                  'preco_adicional', ROUND(COALESCE(oio.preco_adicional_snapshot, 0.00), 2)
                ) ORDER BY oio.id ASC
              )
              FROM public.orcamento_item_opcoes oio
              WHERE oio.orcamento_item_id = oi.id
            ), '[]'::jsonb)
          ) ORDER BY oi.id ASC
        )
        FROM public.orcamento_itens oi
        LEFT JOIN public.produtos pr ON pr.id = oi.produto_id
        WHERE oi.orcamento_id = o.id
      ), '[]'::jsonb) AS itens
    FROM public.orcamentos o
    WHERE o.cliente_id = v_cli_id
    ORDER BY o.created_at DESC, o.id DESC
    LIMIT v_lim OFFSET v_off
  ) r;

  RETURN jsonb_build_object(
    'success', true,
    'total_registros', v_total,
    'limite', v_lim,
    'offset', v_off,
    'orcamentos', v_orcamentos
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.listar_meus_orcamentos(INTEGER, INTEGER) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.listar_meus_orcamentos(INTEGER, INTEGER) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.aprovar_meu_orcamento(
  p_orcamento_id BIGINT,
  p_versao_esperada INTEGER
)
RETURNS JSONB AS $$
DECLARE
  v_ident JSONB := public._resolver_meu_cliente_id();
  v_cli_id BIGINT;
  v_orc public.orcamentos;
  v_res JSONB;
BEGIN
  IF (v_ident->>'success')::BOOLEAN IS NOT TRUE THEN
    RETURN v_ident;
  END IF;

  IF p_orcamento_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'QUOTE_ID_REQUIRED', 'error', 'ID do orçamento é obrigatório.');
  END IF;

  IF p_versao_esperada IS NULL OR p_versao_esperada < 1 THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'VERSION_REQUIRED',
      'error', 'A versão esperada da proposta é obrigatória para aprovação.'
    );
  END IF;

  v_cli_id := (v_ident->>'cliente_id')::BIGINT;

  -- Gate J8: Valida propriedade estrita (orcamento pertence ao cliente autenticado)
  SELECT * INTO v_orc
  FROM public.orcamentos
  WHERE id = p_orcamento_id
    AND cliente_id = v_cli_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'QUOTE_NOT_FOUND',
      'error', 'Orçamento não encontrado para sua conta.'
    );
  END IF;

  -- Reutiliza internamente o motor canônico da Migration 017 sem expor o token_publico ao cliente
  v_res := public.aprovar_orcamento_publico(v_orc.token_publico, p_versao_esperada);

  RETURN v_res || jsonb_build_object('orcamento_id', v_orc.id, 'numero', v_orc.numero);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.aprovar_meu_orcamento(BIGINT, INTEGER) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.aprovar_meu_orcamento(BIGINT, INTEGER) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 7. EXTRATO DE CRÉDITO FINANCEIRO E EXTRATO DE PONTOS (GATES J9, J10, J11)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.listar_meu_extrato_credito(
  p_limite INTEGER DEFAULT 25,
  p_offset INTEGER DEFAULT 0
)
RETURNS JSONB AS $$
DECLARE
  v_ident JSONB := public._resolver_meu_cliente_id();
  v_cli_id BIGINT;
  v_lim INTEGER := LEAST(GREATEST(COALESCE(p_limite, 25), 1), 100);
  v_off INTEGER := GREATEST(COALESCE(p_offset, 0), 0);
  v_saldo NUMERIC(10,2) := 0.00;
  v_movs JSONB;
BEGIN
  IF (v_ident->>'success')::BOOLEAN IS NOT TRUE THEN
    RETURN v_ident;
  END IF;

  v_cli_id := (v_ident->>'cliente_id')::BIGINT;

  SELECT COALESCE(saldo, 0.00) INTO v_saldo
  FROM public.cliente_creditos
  WHERE cliente_id = v_cli_id;

  SELECT COALESCE(jsonb_agg(row_to_json(m)::jsonb ORDER BY m.created_at DESC, m.id DESC), '[]'::jsonb)
  INTO v_movs
  FROM (
    SELECT
      cm.id,
      cm.origem AS tipo,
      cm.tipo AS natureza,
      ROUND(cm.valor, 2) AS valor,
      ROUND(cm.saldo_anterior, 2) AS saldo_anterior,
      ROUND(cm.saldo_posterior, 2) AS saldo_posterior,
      cm.pedido_id,
      cm.motivo,
      cm.created_at
    FROM public.cliente_credito_movimentacoes cm
    WHERE cm.cliente_id = v_cli_id
    ORDER BY cm.created_at DESC, cm.id DESC
    LIMIT v_lim OFFSET v_off
  ) m;

  RETURN jsonb_build_object(
    'success', true,
    'natureza_carteira', 'valor_financeiro',
    'moeda', 'BRL',
    'saldo_reais', ROUND(v_saldo, 2),
    'movimentacoes', v_movs
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.listar_meu_extrato_credito(INTEGER, INTEGER) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.listar_meu_extrato_credito(INTEGER, INTEGER) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.listar_meu_extrato_pontos(
  p_limite INTEGER DEFAULT 25,
  p_offset INTEGER DEFAULT 0
)
RETURNS JSONB AS $$
DECLARE
  v_ident JSONB := public._resolver_meu_cliente_id();
  v_cli_id BIGINT;
  v_lim INTEGER := LEAST(GREATEST(COALESCE(p_limite, 25), 1), 100);
  v_off INTEGER := GREATEST(COALESCE(p_offset, 0), 0);
  v_carteira RECORD;
  v_movs JSONB;
BEGIN
  IF (v_ident->>'success')::BOOLEAN IS NOT TRUE THEN
    RETURN v_ident;
  END IF;

  v_cli_id := (v_ident->>'cliente_id')::BIGINT;

  PERFORM public._processar_expiracao_pontos_cliente(v_cli_id, NOW());

  SELECT
    COALESCE(saldo_pontos, 0) AS saldo_pontos,
    COALESCE(pontos_acumulados_total, 0) AS pontos_acumulados_total,
    COALESCE(pontos_resgatados_total, 0) AS pontos_resgatados_total,
    COALESCE(pontos_expirados_total, 0) AS pontos_expirados_total
  INTO v_carteira
  FROM public.cliente_pontos
  WHERE cliente_id = v_cli_id;

  SELECT COALESCE(jsonb_agg(row_to_json(m)::jsonb ORDER BY m.created_at DESC, m.id DESC), '[]'::jsonb)
  INTO v_movs
  FROM (
    SELECT
      pm.id,
      pm.tipo,
      pm.natureza,
      pm.pontos,
      pm.saldo_anterior,
      pm.saldo_posterior,
      pm.pedido_id,
      pm.expira_em,
      pm.motivo,
      pm.created_at
    FROM public.cliente_pontos_movimentacoes pm
    WHERE pm.cliente_id = v_cli_id
    ORDER BY pm.created_at DESC, pm.id DESC
    LIMIT v_lim OFFSET v_off
  ) m;

  RETURN jsonb_build_object(
    'success', true,
    'natureza_carteira', 'beneficio_promocional',
    'unidade', 'pts',
    'saldo_pontos', COALESCE(v_carteira.saldo_pontos, 0),
    'pontos_acumulados_total', COALESCE(v_carteira.pontos_acumulados_total, 0),
    'pontos_resgatados_total', COALESCE(v_carteira.pontos_resgatados_total, 0),
    'pontos_expirados_total', COALESCE(v_carteira.pontos_expirados_total, 0),
    'movimentacoes', v_movs
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.listar_meu_extrato_pontos(INTEGER, INTEGER) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.listar_meu_extrato_pontos(INTEGER, INTEGER) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 8. MEUS CUPONS PROMOCIONAIS ELEGÍVEIS E UTILIZADOS (GATE J12)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.listar_meus_cupons()
RETURNS JSONB AS $$
DECLARE
  v_ident JSONB := public._resolver_meu_cliente_id();
  v_cli_id BIGINT;
  v_disponiveis JSONB;
  v_utilizados JSONB;
BEGIN
  IF (v_ident->>'success')::BOOLEAN IS NOT TRUE THEN
    RETURN v_ident;
  END IF;

  v_cli_id := (v_ident->>'cliente_id')::BIGINT;

  -- Gate J12: Retorna apenas cupons ativos, dentro da vigência e cujo limite global e por cliente ainda não foi atingido
  SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY c.validade_fim ASC, c.cupom_id DESC), '[]'::jsonb)
  INTO v_disponiveis
  FROM (
    SELECT
      cp.id AS cupom_id,
      cp.codigo,
      cp.descricao,
      cp.tipo,
      ROUND(cp.valor, 2) AS valor,
      ROUND(COALESCE(cp.pedido_minimo, 0.00), 2) AS pedido_minimo,
      CASE WHEN cp.desconto_maximo IS NOT NULL THEN ROUND(cp.desconto_maximo, 2) ELSE NULL END AS desconto_maximo,
      cp.validade_fim
    FROM public.cupons_promocionais cp
    WHERE cp.ativo = true
      AND cp.validade_inicio <= NOW()
      AND cp.validade_fim >= NOW()
      AND (
        cp.uso_maximo_global IS NULL
        OR (SELECT COUNT(*) FROM public.cupom_utilizacoes cu WHERE cu.cupom_id = cp.id AND cu.status = 'aplicado') < cp.uso_maximo_global
      )
      AND (
        cp.uso_maximo_cliente IS NULL
        OR (SELECT COUNT(*) FROM public.cupom_utilizacoes cu WHERE cu.cupom_id = cp.id AND cu.cliente_id = v_cli_id AND cu.status = 'aplicado') < cp.uso_maximo_cliente
      )
      -- Se o cupom for vinculado a uma campanha específica que teve disparo segmentado,
      -- exibe apenas se a campanha for geral (sem campanha_publicos restrito) ou se o cliente foi público elegível
      AND (
        cp.campanha_id IS NULL
        OR NOT EXISTS (SELECT 1 FROM public.campanha_publicos pub WHERE pub.campanha_id = cp.campanha_id)
        OR EXISTS (SELECT 1 FROM public.campanha_publicos pub WHERE pub.campanha_id = cp.campanha_id AND pub.cliente_id = v_cli_id)
      )
  ) c;

  SELECT COALESCE(jsonb_agg(row_to_json(u)::jsonb ORDER BY u.created_at DESC), '[]'::jsonb)
  INTO v_utilizados
  FROM (
    SELECT
      cu.id AS utilizacao_id,
      cp.codigo,
      cp.descricao,
      cu.pedido_id,
      ROUND(cu.valor_desconto_cupom, 2) AS valor_desconto_aplicado,
      cu.status,
      cu.created_at
    FROM public.cupom_utilizacoes cu
    JOIN public.cupons_promocionais cp ON cp.id = cu.cupom_id
    WHERE cu.cliente_id = v_cli_id
    ORDER BY cu.created_at DESC
    LIMIT 30
  ) u;

  RETURN jsonb_build_object(
    'success', true,
    'cupons_disponiveis', v_disponiveis,
    'historico_utilizacoes', v_utilizados
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.listar_meus_cupons() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.listar_meus_cupons() TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 9. HISTÓRICO SANITIZADO DE COMUNICAÇÕES DO CLIENTE
-- ------------------------------------------------------------------------------
-- Retorna somente tipo, canal, status público amigável, descrição amigável e data.
CREATE OR REPLACE FUNCTION public.listar_minhas_comunicacoes(
  p_limite INTEGER DEFAULT 20,
  p_offset INTEGER DEFAULT 0
)
RETURNS JSONB AS $$
DECLARE
  v_ident JSONB := public._resolver_meu_cliente_id();
  v_cli_id BIGINT;
  v_lim INTEGER := LEAST(GREATEST(COALESCE(p_limite, 20), 1), 50);
  v_off INTEGER := GREATEST(COALESCE(p_offset, 0), 0);
  v_lista JSONB;
BEGIN
  IF (v_ident->>'success')::BOOLEAN IS NOT TRUE THEN
    RETURN v_ident;
  END IF;

  v_cli_id := (v_ident->>'cliente_id')::BIGINT;

  SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY c.data DESC, c.id DESC), '[]'::jsonb)
  INTO v_lista
  FROM (
    SELECT
      cc.id,
      cc.tipo,
      CASE
        WHEN cc.canal IN ('whatsapp_link', 'evolution_api', 'whatsapp_marketing') THEN 'whatsapp'
        ELSE cc.canal
      END AS canal,
      CASE
        WHEN cc.status IN ('enviado', 'entregue') THEN 'enviado'
        WHEN cc.status IN ('link_aberto', 'gerado') THEN 'disponibilizado'
        ELSE 'processado'
      END AS status_publico,
      CASE cc.tipo
        WHEN 'ORCAMENTO_ENVIADO' THEN 'Proposta de orçamento disponibilizada'
        WHEN 'ORCAMENTO_VENCENDO' THEN 'Lembrete de validade de orçamento'
        WHEN 'SINAL_CONFIRMADO' THEN 'Confirmação de recebimento de sinal'
        WHEN 'PEDIDO_PRONTO' THEN 'Aviso de encomenda pronta'
        WHEN 'SAIU_PARA_ENTREGA' THEN 'Aviso de saída para entrega'
        WHEN 'CUPOM_ANIVERSARIO' THEN 'Presente de aniversário Lunoca'
        WHEN 'VOLTE_A_COMPRAR' THEN 'Convite especial de recompra'
        WHEN 'CAMPANHA_PASCOA' THEN 'Novidades sazonais de Páscoa'
        WHEN 'CAMPANHA_PROMOCIONAL' THEN 'Comunicado promocional Lunoca'
        WHEN 'LEMBRETE_PONTOS_EXPIRANDO' THEN 'Aviso de pontos próximos de expirar'
        ELSE 'Notificação de atendimento Lunoca'
      END AS descricao,
      COALESCE(cc.enviado_em, cc.created_at) AS data
    FROM public.comunicacoes_cliente cc
    WHERE cc.cliente_id = v_cli_id
       OR (cc.pedido_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.pedidos p WHERE p.id = cc.pedido_id AND p.cliente_id_rel = v_cli_id))
       OR (cc.orcamento_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.orcamentos o WHERE o.id = cc.orcamento_id AND o.cliente_id = v_cli_id))
    ORDER BY COALESCE(cc.enviado_em, cc.created_at) DESC, cc.id DESC
    LIMIT v_lim OFFSET v_off
  ) c;

  RETURN jsonb_build_object(
    'success', true,
    'comunicacoes', v_lista
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.listar_minhas_comunicacoes(INTEGER, INTEGER) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.listar_minhas_comunicacoes(INTEGER, INTEGER) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 10. ATUALIZAR MINHAS PREFERÊNCIAS SELF-SERVICE (GATES J13, J14)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.atualizar_minhas_preferencias_cliente(
  p_categoria TEXT,
  p_valor TEXT,
  p_observacao TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_ident JSONB := public._resolver_meu_cliente_id();
  v_cli_id BIGINT;
  v_cat TEXT := LOWER(TRIM(COALESCE(p_categoria, '')));
  v_val TEXT := NULLIF(TRIM(COALESCE(p_valor, '')), '');
  v_obs TEXT := NULLIF(TRIM(COALESCE(p_observacao, '')), '');
  v_pref_id BIGINT;
BEGIN
  IF (v_ident->>'success')::BOOLEAN IS NOT TRUE THEN
    RETURN v_ident;
  END IF;

  v_cli_id := (v_ident->>'cliente_id')::BIGINT;

  -- Gate J13: Restrito exclusivamente às 5 categorias self-service autorizadas para o cliente
  IF v_cat NOT IN ('sabor', 'decoracao', 'ocasiao', 'restricao_alimentar', 'embalagem') THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'INVALID_PREFERENCE_CATEGORY',
      'error', 'Categoria não permitida no autoatendimento. Escolha entre sabor, decoracao, ocasiao, restricao_alimentar ou embalagem.'
    );
  END IF;

  IF v_val IS NULL OR char_length(v_val) < 2 THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'INVALID_PREFERENCE_VALUE',
      'error', 'Informe uma preferência válida com pelo menos 2 caracteres.'
    );
  END IF;

  -- Desativa declaração anterior da mesma categoria para manter o estado atual limpo e histórico preservado
  UPDATE public.cliente_preferencias
  SET ativo = false,
      updated_at = NOW()
  WHERE cliente_id = v_cli_id
    AND categoria = v_cat
    AND ativo = true;

  INSERT INTO public.cliente_preferencias (
    cliente_id,
    categoria,
    valor,
    observacao,
    ativo,
    criado_por,
    created_at,
    updated_at
  ) VALUES (
    v_cli_id,
    v_cat,
    v_val,
    COALESCE(v_obs, 'Declarado pelo próprio cliente no Portal Minha Conta'),
    true,
    auth.uid(),
    NOW(),
    NOW()
  )
  RETURNING id INTO v_pref_id;

  RETURN jsonb_build_object(
    'success', true,
    'preferencia_id', v_pref_id,
    'categoria', v_cat,
    'valor', v_val,
    'declarado_pelo_cliente', true
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.atualizar_minhas_preferencias_cliente(TEXT, TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.atualizar_minhas_preferencias_cliente(TEXT, TEXT, TEXT) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 11. ATUALIZAR MEU CONSENTIMENTO DE MARKETING (GATES J15, J16)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.atualizar_meu_consentimento_marketing(
  p_canal TEXT DEFAULT 'whatsapp_marketing',
  p_status TEXT DEFAULT 'opt_out',
  p_versao_termo TEXT DEFAULT 'v1.0-portal'
)
RETURNS JSONB AS $$
DECLARE
  v_ident JSONB := public._resolver_meu_cliente_id();
  v_cli_id BIGINT;
  v_canal TEXT := LOWER(TRIM(COALESCE(p_canal, 'whatsapp_marketing')));
  v_status TEXT := LOWER(TRIM(COALESCE(p_status, '')));
  v_versao TEXT := COALESCE(NULLIF(TRIM(p_versao_termo), ''), 'v1.0-portal');
  v_id BIGINT;
BEGIN
  IF (v_ident->>'success')::BOOLEAN IS NOT TRUE THEN
    RETURN v_ident;
  END IF;

  v_cli_id := (v_ident->>'cliente_id')::BIGINT;

  IF v_canal NOT IN ('whatsapp_marketing', 'email_marketing', 'sms_marketing') THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'INVALID_MARKETING_CHANNEL',
      'error', 'Canal de marketing inválido.'
    );
  END IF;

  IF v_status NOT IN ('opt_in', 'opt_out') THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'INVALID_CONSENT_STATUS',
      'error', 'O status de consentimento deve ser opt_in ou opt_out.'
    );
  END IF;

  -- Registro append-only auditável em cliente_consentimentos_marketing
  INSERT INTO public.cliente_consentimentos_marketing (
    cliente_id,
    canal,
    status,
    origem,
    versao_termo,
    observacao,
    registrado_por,
    data_hora
  ) VALUES (
    v_cli_id,
    v_canal,
    v_status,
    'portal_cliente',
    v_versao,
    'Atualizado pelo titular via Portal Minha Conta (auth.uid=' || auth.uid()::TEXT || ')',
    auth.uid(),
    NOW()
  )
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'success', true,
    'consentimento_id', v_id,
    'canal', v_canal,
    'status', v_status,
    'origem', 'portal_cliente',
    'versao_termo', v_versao,
    'registrado_em', NOW()
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.atualizar_meu_consentimento_marketing(TEXT, TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.atualizar_meu_consentimento_marketing(TEXT, TEXT, TEXT) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 12. SANEAMENTO DE OBTER_MEU_PERFIL_360 LEGADO (MIGRATION 019) PARA NÃO EXPOR TOKEN_PUBLICO
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.obter_meu_perfil_360()
RETURNS JSONB AS $$
DECLARE
  v_ident JSONB := public._resolver_meu_cliente_id();
  v_cli_id BIGINT;
  v_saldo NUMERIC(10,2) := 0.00;
  v_pedidos JSONB;
  v_orcamentos JSONB;
BEGIN
  IF (v_ident->>'success')::BOOLEAN IS NOT TRUE THEN
    RETURN v_ident;
  END IF;

  v_cli_id := (v_ident->>'cliente_id')::BIGINT;

  SELECT COALESCE(saldo, 0.00) INTO v_saldo
  FROM public.cliente_creditos
  WHERE cliente_id = v_cli_id;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', id,
      'total', total,
      'status_comercial', status_comercial,
      'etapa_cliente', public._derivar_etapa_cliente_pedido(status_comercial, status_operacional, modalidade_entrega),
      'status_financeiro', status_financeiro,
      'data_entrega', data_entrega,
      'created_at', created_at
    ) ORDER BY created_at DESC
  ), '[]'::jsonb) INTO v_pedidos
  FROM public.pedidos
  WHERE cliente_id_rel = v_cli_id;

  -- Sem token_publico
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', id,
      'numero', numero,
      'versao', versao,
      'status', status,
      'total', total,
      'data_evento', data_evento,
      'validade_ate', validade_ate,
      'created_at', created_at
    ) ORDER BY created_at DESC
  ), '[]'::jsonb) INTO v_orcamentos
  FROM public.orcamentos
  WHERE cliente_id = v_cli_id;

  RETURN jsonb_build_object(
    'success', true,
    'cliente', jsonb_build_object(
      'id', v_cli_id,
      'nome', v_ident->>'nome',
      'telefone', v_ident->>'telefone',
      'email', v_ident->>'email',
      'endereco_padrao', v_ident->'endereco_padrao'
    ),
    'credito', jsonb_build_object(
      'saldo', v_saldo
    ),
    'pedidos', v_pedidos,
    'orcamentos', v_orcamentos
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_meu_perfil_360() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_meu_perfil_360() TO authenticated, service_role;


-- ==========================================================================
-- >>> MIGRATION 026_logistica_rotas_entregas.sql
-- ==========================================================================

-- ==============================================================================
-- LUNOCA DOCERIA - MIGRATION 026: FRENTE K - LOGÍSTICA, ROTAS E COMPROVANTE DE ENTREGA
-- ==============================================================================
-- Diretrizes Arquiteturais e Invariantes Congeladas (Frente K):
-- 1. Zero duplicação de máquina de estados ou de pedido:
--    - public.pedidos.status_operacional continua sendo a única fonte da verdade
--      para pronto -> saiu_para_entrega -> entregue.
--    - Endereço, telefone e nome do cliente nunca são duplicados em entregas;
--      são lidos dos snapshots canônicos de public.pedidos.
-- 2. Segregação estrita de modalidade (Gates K1, K15):
--    - Pedidos com modalidade_entrega = 'retirada' jamais entram em rota de entrega,
--      jamais são despachados como entrega e jamais acessam tracking de rota.
-- 3. Pré-condição de despacho e idempotência (Gates K2, K3, K4, K16):
--    - Pedido que não está 'pronto' não pode ser despachado.
--    - Despacho válido move status_operacional para 'saiu_para_entrega' com lock FOR UPDATE.
--    - Retry de despacho é idempotente e não duplica eventos.
-- 4. Falha de entrega como evento logístico próprio (Gates K7, K8):
--    - Problemas de rua (DESTINATARIO_AUSENTE, ENDERECO_NAO_LOCALIZADO, RECUSADO,
--      PROBLEMA_TRANSPORTE, OUTRO) ficam em entrega_eventos e status_logistico,
--      sem explodir pedidos.status_operacional e sem alterar o financeiro.
--    - Permite reagendamento e nova tentativa até a entrega efetiva.
-- 5. Confirmação de entrega e Comprovante Imutável (Gates K5, K6, K10, K11, K12):
--    - confirmar_entrega_pedido() serializa o pedido (FOR UPDATE), muda
--      status_operacional para 'entregue', é idempotente e JAMAIS gera
--      lançamentos em financeiro_lancamentos ou pedido_pagamentos.
--    - entrega_eventos e entrega_comprovantes são estritamente append-only
--      (triggers bloqueando UPDATE e DELETE físicos).
--    - Comprovante armazena apenas metadados e referência externa (sem BYTEA).
-- 6. Sanitização de Rota e Tracking no Portal do Cliente (Gates K9, K14, K15):
--    - obter_acompanhamento_entrega_cliente() resolve identidade por
--      _resolver_meu_cliente_id() (auth.uid()), valida propriedade do pedido,
--      bloqueia pedidos de retirada e não expõe entregador, telefone interno,
--      notas logísticas nem outros clientes/endereços da rota.
-- ==============================================================================

-- ------------------------------------------------------------------------------
-- 1. TABELA: ROTAS_ENTREGA (AGRUPAMENTO DE ENTREGAS POR DIA / TURNO)
-- ------------------------------------------------------------------------------
CREATE SEQUENCE IF NOT EXISTS public.rotas_entrega_seq START 1;

CREATE TABLE IF NOT EXISTS public.rotas_entrega (
  id BIGSERIAL PRIMARY KEY,
  codigo TEXT NOT NULL UNIQUE,
  data_rota DATE NOT NULL,
  turno TEXT NOT NULL CHECK (turno IN ('manha', 'tarde', 'noite', 'personalizado')),
  responsavel_nome TEXT NOT NULL CHECK (char_length(btrim(responsavel_nome)) >= 2),
  responsavel_telefone TEXT,
  veiculo_identificacao TEXT,
  status TEXT NOT NULL DEFAULT 'planejada' CHECK (status IN ('planejada', 'em_andamento', 'concluida', 'cancelada')),
  observacoes_internas TEXT,
  iniciada_em TIMESTAMPTZ,
  concluida_em TIMESTAMPTZ,
  criado_por UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_rotas_entrega_data_turno
  ON public.rotas_entrega(data_rota DESC, turno, id DESC);

-- ------------------------------------------------------------------------------
-- 2. TABELA: ENTREGAS (OPERAÇÃO LOGÍSTICA 1:1 COM PEDIDO DE ENTREGA)
-- ------------------------------------------------------------------------------
-- Não duplica nome, telefone ou endereço do cliente (usa public.pedidos).
CREATE TABLE IF NOT EXISTS public.entregas (
  id BIGSERIAL PRIMARY KEY,
  pedido_id BIGINT NOT NULL UNIQUE REFERENCES public.pedidos(id) ON DELETE CASCADE,
  status_logistico TEXT NOT NULL DEFAULT 'aguardando_despacho' CHECK (
    status_logistico IN ('aguardando_despacho', 'em_rota', 'falha_temporaria', 'reagendada', 'entregue', 'cancelada')
  ),
  tentativas_count INTEGER NOT NULL DEFAULT 0 CHECK (tentativas_count >= 0),
  ultimo_motivo_falha TEXT CHECK (
    ultimo_motivo_falha IS NULL OR ultimo_motivo_falha IN (
      'DESTINATARIO_AUSENTE',
      'ENDERECO_NAO_LOCALIZADO',
      'RECUSADO',
      'PROBLEMA_TRANSPORTE',
      'OUTRO'
    )
  ),
  proxima_janela_data DATE,
  proxima_janela_hora TIME,
  despachado_em TIMESTAMPTZ,
  entregue_em TIMESTAMPTZ,
  observacoes_logisticas TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_entregas_status_logistico
  ON public.entregas(status_logistico, updated_at DESC);

-- ------------------------------------------------------------------------------
-- 3. TABELA: ROTA_ENTREGAS (SEQUÊNCIA DE ENTREGAS DENTRO DE UMA ROTA)
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.rota_entregas (
  id BIGSERIAL PRIMARY KEY,
  rota_id BIGINT NOT NULL REFERENCES public.rotas_entrega(id) ON DELETE CASCADE,
  entrega_id BIGINT NOT NULL REFERENCES public.entregas(id) ON DELETE CASCADE,
  pedido_id BIGINT NOT NULL REFERENCES public.pedidos(id) ON DELETE CASCADE,
  ordem_sequencia INTEGER NOT NULL DEFAULT 1 CHECK (ordem_sequencia >= 1),
  ativo BOOLEAN NOT NULL DEFAULT true,
  atribuido_por UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_rota_entrega_vinculo UNIQUE (rota_id, entrega_id)
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_rota_entregas_entrega_ativa
  ON public.rota_entregas(entrega_id)
  WHERE ativo = true;

CREATE INDEX IF NOT EXISTS idx_rota_entregas_rota_ordem
  ON public.rota_entregas(rota_id, ordem_sequencia ASC)
  WHERE ativo = true;

-- ------------------------------------------------------------------------------
-- 4. TABELA: ENTREGA_EVENTOS (HISTÓRICO LOGÍSTICO APPEND-ONLY IMUTÁVEL)
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.entrega_eventos (
  id BIGSERIAL PRIMARY KEY,
  entrega_id BIGINT NOT NULL REFERENCES public.entregas(id) ON DELETE RESTRICT,
  pedido_id BIGINT NOT NULL REFERENCES public.pedidos(id) ON DELETE RESTRICT,
  rota_id BIGINT REFERENCES public.rotas_entrega(id) ON DELETE SET NULL,
  tipo_evento TEXT NOT NULL CHECK (
    tipo_evento IN (
      'ROTA_ATRIBUIDA',
      'DESPACHADO',
      'TENTATIVA_ENTREGA',
      'FALHA_ENTREGA',
      'REAGENDADO',
      'NOVA_TENTATIVA_DESPACHO',
      'ENTREGUE',
      'COMPROVANTE_REGISTRADO'
    )
  ),
  motivo_falha TEXT CHECK (
    motivo_falha IS NULL OR motivo_falha IN (
      'DESTINATARIO_AUSENTE',
      'ENDERECO_NAO_LOCALIZADO',
      'RECUSADO',
      'PROBLEMA_TRANSPORTE',
      'OUTRO'
    )
  ),
  descricao TEXT NOT NULL CHECK (char_length(btrim(descricao)) >= 3),
  chave_idempotencia TEXT NOT NULL UNIQUE,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  usuario_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  usuario_nome TEXT NOT NULL DEFAULT 'Equipe Logística',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_entrega_eventos_pedido
  ON public.entrega_eventos(pedido_id, id ASC);

CREATE INDEX IF NOT EXISTS idx_entrega_eventos_entrega
  ON public.entrega_eventos(entrega_id, id ASC);

CREATE OR REPLACE FUNCTION public.bloquear_mutacao_entrega_eventos()
RETURNS TRIGGER AS $$
BEGIN
  RAISE EXCEPTION 'Operação % não permitida em entrega_eventos. O histórico de eventos logísticos é estritamente imutável (append-only).', TG_OP
    USING ERRCODE = '42501';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_imutabilidade_entrega_eventos ON public.entrega_eventos;
CREATE TRIGGER trg_imutabilidade_entrega_eventos
  BEFORE UPDATE OR DELETE ON public.entrega_eventos
  FOR EACH ROW
  EXECUTE FUNCTION public.bloquear_mutacao_entrega_eventos();

-- ------------------------------------------------------------------------------
-- 5. TABELA: ENTREGA_COMPROVANTES (COMPROVANTE DE RECEBIMENTO APPEND-ONLY IMUTÁVEL)
-- ------------------------------------------------------------------------------
-- Sem BYTEA no banco: armazena apenas fatos do recebimento e referência externa.
CREATE TABLE IF NOT EXISTS public.entrega_comprovantes (
  id BIGSERIAL PRIMARY KEY,
  pedido_id BIGINT NOT NULL REFERENCES public.pedidos(id) ON DELETE RESTRICT,
  entrega_id BIGINT NOT NULL REFERENCES public.entregas(id) ON DELETE RESTRICT,
  recebido_por TEXT NOT NULL CHECK (char_length(btrim(recebido_por)) >= 2),
  tipo_comprovante TEXT NOT NULL DEFAULT 'assinatura_recebedor' CHECK (
    tipo_comprovante IN (
      'assinatura_recebedor',
      'foto_entrega',
      'codigo_confirmacao',
      'confirmacao_verbal_autorizada'
    )
  ),
  documento_recebedor TEXT,
  referencia_arquivo TEXT,
  hash_arquivo TEXT,
  metadata_tecnica JSONB NOT NULL DEFAULT '{}'::jsonb,
  chave_idempotencia TEXT NOT NULL UNIQUE,
  registrado_por UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  registrado_por_nome TEXT NOT NULL DEFAULT 'Equipe Logística',
  registrado_em TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_entrega_comprovantes_pedido
  ON public.entrega_comprovantes(pedido_id, id DESC);

CREATE OR REPLACE FUNCTION public.bloquear_mutacao_entrega_comprovantes()
RETURNS TRIGGER AS $$
BEGIN
  RAISE EXCEPTION 'Operação % não permitida em entrega_comprovantes. Os comprovantes de entrega são estritamente imutáveis (append-only).', TG_OP
    USING ERRCODE = '42501';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_imutabilidade_entrega_comprovantes ON public.entrega_comprovantes;
CREATE TRIGGER trg_imutabilidade_entrega_comprovantes
  BEFORE UPDATE OR DELETE ON public.entrega_comprovantes
  FOR EACH ROW
  EXECUTE FUNCTION public.bloquear_mutacao_entrega_comprovantes();

-- ------------------------------------------------------------------------------
-- 6. RLS & PRIVILÉGIOS FAIL-CLOSED NAS TABELAS LOGÍSTICAS
-- ------------------------------------------------------------------------------
ALTER TABLE public.rotas_entrega ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.entregas ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.rota_entregas ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.entrega_eventos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.entrega_comprovantes ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.rotas_entrega FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.entregas FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.rota_entregas FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.entrega_eventos FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.entrega_comprovantes FROM PUBLIC, anon, authenticated;

GRANT SELECT ON public.rotas_entrega TO authenticated;
GRANT SELECT ON public.entregas TO authenticated;
GRANT SELECT ON public.rota_entregas TO authenticated;
GRANT SELECT ON public.entrega_eventos TO authenticated;
GRANT SELECT ON public.entrega_comprovantes TO authenticated;

GRANT ALL ON public.rotas_entrega TO service_role;
GRANT ALL ON public.entregas TO service_role;
GRANT ALL ON public.rota_entregas TO service_role;
GRANT ALL ON public.entrega_eventos TO service_role;
GRANT ALL ON public.entrega_comprovantes TO service_role;

DROP POLICY IF EXISTS rutas_entrega_equipe_select ON public.rotas_entrega;
CREATE POLICY rutas_entrega_equipe_select ON public.rotas_entrega
  FOR SELECT TO authenticated
  USING (public.is_admin_or_operator());

DROP POLICY IF EXISTS entregas_equipe_select ON public.entregas;
CREATE POLICY entregas_equipe_select ON public.entregas
  FOR SELECT TO authenticated
  USING (public.is_admin_or_operator());

DROP POLICY IF EXISTS rota_entregas_equipe_select ON public.rota_entregas;
CREATE POLICY rota_entregas_equipe_select ON public.rota_entregas
  FOR SELECT TO authenticated
  USING (public.is_admin_or_operator());

DROP POLICY IF EXISTS entrega_eventos_equipe_select ON public.entrega_eventos;
CREATE POLICY entrega_eventos_equipe_select ON public.entrega_eventos
  FOR SELECT TO authenticated
  USING (public.is_admin_or_operator());

DROP POLICY IF EXISTS entrega_comprovantes_equipe_select ON public.entrega_comprovantes;
CREATE POLICY entrega_comprovantes_equipe_select ON public.entrega_comprovantes
  FOR SELECT TO authenticated
  USING (public.is_admin_or_operator());

-- ------------------------------------------------------------------------------
-- 7. RPC: CRIAR_ROTA_ENTREGA_ADMIN
-- ------------------------------------------------------------------------------
-- Cria ou atualiza uma rota diária/turno. JAMAIS altera pedidos diretamente.
CREATE OR REPLACE FUNCTION public.criar_rota_entrega_admin(
  p_data_rota DATE,
  p_turno TEXT,
  p_responsavel_nome TEXT,
  p_responsavel_telefone TEXT DEFAULT NULL,
  p_veiculo_identificacao TEXT DEFAULT NULL,
  p_observacoes_internas TEXT DEFAULT NULL,
  p_codigo TEXT DEFAULT NULL,
  p_rota_id BIGINT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_turno TEXT := LOWER(TRIM(COALESCE(p_turno, 'manha')));
  v_resp TEXT := NULLIF(TRIM(COALESCE(p_responsavel_nome, '')), '');
  v_codigo TEXT := UPPER(NULLIF(TRIM(COALESCE(p_codigo, '')), ''));
  v_id BIGINT;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PERMISSION_DENIED',
      'error', 'Apenas administradores ou operadores podem planejar rotas de entrega.'
    );
  END IF;

  IF p_data_rota IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'ROUTE_DATE_REQUIRED',
      'error', 'A data da rota de entrega é obrigatória.'
    );
  END IF;

  IF v_turno NOT IN ('manha', 'tarde', 'noite', 'personalizado') THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'INVALID_ROUTE_SHIFT',
      'error', 'Turno inválido. Utilize manha, tarde, noite ou personalizado.'
    );
  END IF;

  IF v_resp IS NULL OR char_length(v_resp) < 2 THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'DRIVER_NAME_REQUIRED',
      'error', 'Informe o nome do responsável/entregador da rota.'
    );
  END IF;

  IF p_rota_id IS NOT NULL THEN
    UPDATE public.rotas_entrega
    SET data_rota = p_data_rota,
        turno = v_turno,
        responsavel_nome = v_resp,
        responsavel_telefone = NULLIF(TRIM(COALESCE(p_responsavel_telefone, '')), ''),
        veiculo_identificacao = NULLIF(TRIM(COALESCE(p_veiculo_identificacao, '')), ''),
        observacoes_internas = NULLIF(TRIM(COALESCE(p_observacoes_internas, '')), ''),
        updated_at = NOW()
    WHERE id = p_rota_id
    RETURNING id, codigo INTO v_id, v_codigo;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'code', 'ROUTE_NOT_FOUND', 'error', 'Rota não encontrada.');
    END IF;
  ELSE
    IF v_codigo IS NULL THEN
      v_codigo := 'ROTA-' || to_char(p_data_rota, 'YYYYMMDD') || '-' || UPPER(SUBSTRING(v_turno FROM 1 FOR 3)) || '-' || LPAD(nextval('public.rotas_entrega_seq')::TEXT, 3, '0');
    END IF;

    INSERT INTO public.rotas_entrega (
      codigo,
      data_rota,
      turno,
      responsavel_nome,
      responsavel_telefone,
      veiculo_identificacao,
      status,
      observacoes_internas,
      criado_por,
      created_at,
      updated_at
    ) VALUES (
      v_codigo,
      p_data_rota,
      v_turno,
      v_resp,
      NULLIF(TRIM(COALESCE(p_responsavel_telefone, '')), ''),
      NULLIF(TRIM(COALESCE(p_veiculo_identificacao, '')), ''),
      'planejada',
      NULLIF(TRIM(COALESCE(p_observacoes_internas, '')), ''),
      auth.uid(),
      NOW(),
      NOW()
    )
    RETURNING id INTO v_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'rota_id', v_id,
    'codigo', v_codigo,
    'data_rota', p_data_rota,
    'turno', v_turno,
    'responsavel_nome', v_resp
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.criar_rota_entrega_admin(DATE, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, BIGINT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.criar_rota_entrega_admin(DATE, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, BIGINT) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 8. RPC: ATRIBUIR_ENTREGA_ROTA (GATE K1: RETIRADA NUNCA ENTRA EM ROTA)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.atribuir_entrega_rota(
  p_rota_id BIGINT,
  p_pedido_id BIGINT,
  p_ordem_sequencia INTEGER DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_rota public.rotas_entrega;
  v_ped public.pedidos;
  v_entrega_id BIGINT;
  v_ordem INTEGER;
  v_usuario_nome TEXT;
  v_evt_key TEXT;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PERMISSION_DENIED',
      'error', 'Apenas equipe autorizada pode atribuir entregas a rotas.'
    );
  END IF;

  IF p_rota_id IS NULL OR p_pedido_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PARAMS_REQUIRED',
      'error', 'ID da rota e ID do pedido são obrigatórios.'
    );
  END IF;

  SELECT * INTO v_rota
  FROM public.rotas_entrega
  WHERE id = p_rota_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'ROUTE_NOT_FOUND', 'error', 'Rota de entrega não encontrada.');
  END IF;

  IF v_rota.status IN ('concluida', 'cancelada') THEN
    RETURN jsonb_build_object('success', false, 'code', 'ROUTE_CLOSED', 'error', 'Não é possível atribuir pedidos a uma rota já concluída ou cancelada.');
  END IF;

  SELECT * INTO v_ped
  FROM public.pedidos
  WHERE id = p_pedido_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_NOT_FOUND', 'error', 'Pedido não encontrado.');
  END IF;

  IF v_ped.status_comercial = 'cancelado' OR v_ped.status_operacional = 'cancelado' THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_CANCELLED', 'error', 'Pedido cancelado não pode entrar em rota de entrega.');
  END IF;

  -- GATE K1: Pedidos de retirada na loja NUNCA entram em rota de entrega
  IF COALESCE(v_ped.modalidade_entrega, 'retirada') <> 'entrega' THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PICKUP_ORDER_NOT_ROUTABLE',
      'error', 'Pedidos na modalidade retirada na loja não podem ser incluídos em rotas de entrega.'
    );
  END IF;

  IF v_ped.status_operacional IN ('entregue', 'retirado') THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'ORDER_ALREADY_DELIVERED',
      'error', 'Este pedido já foi entregue e não pode ser atribuído a uma nova rota.'
    );
  END IF;

  -- Garante a existência do registro logístico em public.entregas sem alterar o pedido
  INSERT INTO public.entregas (
    pedido_id,
    status_logistico,
    created_at,
    updated_at
  ) VALUES (
    p_pedido_id,
    CASE WHEN v_ped.status_operacional = 'saiu_para_entrega' THEN 'em_rota' ELSE 'aguardando_despacho' END,
    NOW(),
    NOW()
  )
  ON CONFLICT (pedido_id) DO UPDATE
    SET updated_at = NOW()
  RETURNING id INTO v_entrega_id;

  -- Desativa vínculo ativo anterior em outra rota, se existir
  UPDATE public.rota_entregas
  SET ativo = false,
      updated_at = NOW()
  WHERE entrega_id = v_entrega_id
    AND rota_id <> p_rota_id
    AND ativo = true;

  IF p_ordem_sequencia IS NOT NULL AND p_ordem_sequencia >= 1 THEN
    v_ordem := p_ordem_sequencia;
  ELSE
    SELECT COALESCE(MAX(ordem_sequencia), 0) + 1 INTO v_ordem
    FROM public.rota_entregas
    WHERE rota_id = p_rota_id
      AND ativo = true;
  END IF;

  INSERT INTO public.rota_entregas (
    rota_id,
    entrega_id,
    pedido_id,
    ordem_sequencia,
    ativo,
    atribuido_por,
    created_at,
    updated_at
  ) VALUES (
    p_rota_id,
    v_entrega_id,
    p_pedido_id,
    v_ordem,
    true,
    auth.uid(),
    NOW(),
    NOW()
  )
  ON CONFLICT (rota_id, entrega_id) DO UPDATE
    SET ordem_sequencia = EXCLUDED.ordem_sequencia,
        ativo = true,
        atribuido_por = EXCLUDED.atribuido_por,
        updated_at = NOW();

  SELECT COALESCE(nome, email, 'Equipe Logística') INTO v_usuario_nome
  FROM public.profiles WHERE id = auth.uid();
  IF v_usuario_nome IS NULL THEN v_usuario_nome := 'Equipe Logística'; END IF;

  v_evt_key := 'rota_atrib:' || p_rota_id::TEXT || ':ped:' || p_pedido_id::TEXT || ':ord:' || v_ordem::TEXT;

  INSERT INTO public.entrega_eventos (
    entrega_id,
    pedido_id,
    rota_id,
    tipo_evento,
    descricao,
    chave_idempotencia,
    metadata,
    usuario_id,
    usuario_nome
  ) VALUES (
    v_entrega_id,
    p_pedido_id,
    p_rota_id,
    'ROTA_ATRIBUIDA',
    'Pedido #' || p_pedido_id::TEXT || ' atribuído à rota ' || v_rota.codigo || ' (sequência #' || v_ordem::TEXT || ').',
    v_evt_key,
    jsonb_build_object('rota_codigo', v_rota.codigo, 'ordem_sequencia', v_ordem),
    auth.uid(),
    v_usuario_nome
  )
  ON CONFLICT (chave_idempotencia) DO NOTHING;

  RETURN jsonb_build_object(
    'success', true,
    'rota_id', p_rota_id,
    'rota_codigo', v_rota.codigo,
    'entrega_id', v_entrega_id,
    'pedido_id', p_pedido_id,
    'ordem_sequencia', v_ordem
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.atribuir_entrega_rota(BIGINT, BIGINT, INTEGER) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.atribuir_entrega_rota(BIGINT, BIGINT, INTEGER) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 9. RPC: REORDENAR_ROTA_ENTREGA
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.reordenar_rota_entrega(
  p_rota_id BIGINT,
  p_pedido_ids_ordenados BIGINT[]
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_idx INTEGER;
  v_ped_id BIGINT;
  v_atualizados INTEGER := 0;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas equipe autorizada pode reordenar rotas.');
  END IF;

  IF p_rota_id IS NULL OR p_pedido_ids_ordenados IS NULL OR array_length(p_pedido_ids_ordenados, 1) IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'PARAMS_REQUIRED', 'error', 'Informe a rota e a lista ordenada de pedidos.');
  END IF;

  PERFORM 1 FROM public.rotas_entrega WHERE id = p_rota_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'ROUTE_NOT_FOUND', 'error', 'Rota não encontrada.');
  END IF;

  FOR v_idx IN 1..array_length(p_pedido_ids_ordenados, 1) LOOP
    v_ped_id := p_pedido_ids_ordenados[v_idx];
    UPDATE public.rota_entregas
    SET ordem_sequencia = v_idx,
        updated_at = NOW()
    WHERE rota_id = p_rota_id
      AND pedido_id = v_ped_id
      AND ativo = true;

    IF FOUND THEN
      v_atualizados := v_atualizados + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'rota_id', p_rota_id,
    'itens_reordenados', v_atualizados
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.reordenar_rota_entrega(BIGINT, BIGINT[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.reordenar_rota_entrega(BIGINT, BIGINT[]) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 10. RPC: DESPACHAR_PEDIDO_ENTREGA (GATES K1, K2, K3, K4, K8, K16)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.despachar_pedido_entrega(
  p_pedido_id BIGINT,
  p_observacao TEXT DEFAULT NULL,
  p_chave_idempotencia TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_ped public.pedidos;
  v_entrega public.entregas;
  v_rota_id BIGINT;
  v_usuario_nome TEXT;
  v_tipo_evento TEXT;
  v_evt_key TEXT;
  v_tentativa INTEGER;
  v_obs TEXT := NULLIF(TRIM(COALESCE(p_observacao, '')), '');
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas equipe autorizada pode despachar entregas.');
  END IF;

  IF p_pedido_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_ID_REQUIRED', 'error', 'ID do pedido é obrigatório.');
  END IF;

  -- Lock serializado no pedido (Gate K16)
  SELECT * INTO v_ped
  FROM public.pedidos
  WHERE id = p_pedido_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_NOT_FOUND', 'error', 'Pedido não encontrado.');
  END IF;

  IF v_ped.status_comercial = 'cancelado' OR v_ped.status_operacional = 'cancelado' THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_CANCELLED', 'error', 'Pedido cancelado não pode ser despachado.');
  END IF;

  -- Gate K1: Retirada nunca é despachada como entrega
  IF COALESCE(v_ped.modalidade_entrega, 'retirada') <> 'entrega' THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'INVALID_DELIVERY_MODALITY',
      'error', 'Pedidos na modalidade retirada na loja não possuem despacho logístico de entrega.'
    );
  END IF;

  IF v_ped.status_operacional IN ('entregue', 'retirado') THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'ORDER_ALREADY_DELIVERED',
      'error', 'Este pedido já consta como entregue.'
    );
  END IF;

  -- Garante registro em public.entregas com lock
  INSERT INTO public.entregas (
    pedido_id,
    status_logistico,
    created_at,
    updated_at
  ) VALUES (
    p_pedido_id,
    'aguardando_despacho',
    NOW(),
    NOW()
  )
  ON CONFLICT (pedido_id) DO NOTHING;

  SELECT * INTO v_entrega
  FROM public.entregas
  WHERE pedido_id = p_pedido_id
  FOR UPDATE;

  -- Gate K4: Idempotência estrita — se já está em saiu_para_entrega E status_logistico = 'em_rota'
  IF v_ped.status_operacional = 'saiu_para_entrega' AND v_entrega.status_logistico = 'em_rota' THEN
    RETURN jsonb_build_object(
      'success', true,
      'idempotente', true,
      'pedido_id', p_pedido_id,
      'entrega_id', v_entrega.id,
      'status_operacional', 'saiu_para_entrega',
      'status_logistico', 'em_rota',
      'tentativas_count', v_entrega.tentativas_count
    );
  END IF;

  -- Gate K2: Pedido não pronto não pode ser despachado
  -- Exceção legítima (Gate K8): se já estava em saiu_para_entrega porém com status_logistico IN ('falha_temporaria', 'reagendada')
  IF v_ped.status_operacional <> 'pronto'
     AND NOT (v_ped.status_operacional = 'saiu_para_entrega' AND v_entrega.status_logistico IN ('falha_temporaria', 'reagendada', 'aguardando_despacho')) THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'ORDER_NOT_READY_FOR_DISPATCH',
      'error', 'Pedido ainda não está pronto na produção e não pode ser despachado para entrega.',
      'status_operacional_atual', v_ped.status_operacional
    );
  END IF;

  SELECT COALESCE(nome, email, 'Expedição Logística') INTO v_usuario_nome
  FROM public.profiles WHERE id = auth.uid();
  IF v_usuario_nome IS NULL THEN v_usuario_nome := 'Expedição Logística'; END IF;

  SELECT re.rota_id INTO v_rota_id
  FROM public.rota_entregas re
  WHERE re.entrega_id = v_entrega.id
    AND re.ativo = true
  LIMIT 1;

  v_tentativa := COALESCE(v_entrega.tentativas_count, 0) + 1;

  IF v_entrega.status_logistico IN ('falha_temporaria', 'reagendada') THEN
    v_tipo_evento := 'NOVA_TENTATIVA_DESPACHO';
  ELSE
    v_tipo_evento := 'DESPACHADO';
  END IF;

  v_evt_key := COALESCE(
    NULLIF(TRIM(COALESCE(p_chave_idempotencia, '')), ''),
    'despacho:ped:' || p_pedido_id::TEXT || ':tentativa:' || v_tentativa::TEXT
  );

  -- Gate K3: Transição canônica de pedidos.status_operacional para saiu_para_entrega
  IF v_ped.status_operacional <> 'saiu_para_entrega' THEN
    UPDATE public.pedidos
    SET status_operacional = 'saiu_para_entrega',
        updated_at = NOW()
    WHERE id = p_pedido_id;

    INSERT INTO public.pedido_status_historico (
      pedido_id, dimensao, status_anterior, status_novo, usuario_id, usuario_nome, origem, metadata
    ) VALUES (
      p_pedido_id, 'operacional', v_ped.status_operacional, 'saiu_para_entrega',
      auth.uid(), v_usuario_nome, 'admin',
      jsonb_build_object('acao', 'despachar_pedido_entrega', 'tentativa', v_tentativa, 'rota_id', v_rota_id)
    );
  END IF;

  UPDATE public.entregas
  SET status_logistico = 'em_rota',
      tentativas_count = v_tentativa,
      despachado_em = COALESCE(despachado_em, NOW()),
      observacoes_logisticas = COALESCE(v_obs, observacoes_logisticas),
      updated_at = NOW()
  WHERE id = v_entrega.id;

  IF v_rota_id IS NOT NULL THEN
    UPDATE public.rotas_entrega
    SET status = CASE WHEN status = 'planejada' THEN 'em_andamento' ELSE status END,
        iniciada_em = COALESCE(iniciada_em, NOW()),
        updated_at = NOW()
    WHERE id = v_rota_id;
  END IF;

  INSERT INTO public.entrega_eventos (
    entrega_id,
    pedido_id,
    rota_id,
    tipo_evento,
    descricao,
    chave_idempotencia,
    metadata,
    usuario_id,
    usuario_nome
  ) VALUES (
    v_entrega.id,
    p_pedido_id,
    v_rota_id,
    v_tipo_evento,
    COALESCE(v_obs, CASE WHEN v_tipo_evento = 'NOVA_TENTATIVA_DESPACHO'
      THEN 'Nova saída para entrega iniciada (tentativa #' || v_tentativa::TEXT || ').'
      ELSE 'Pedido despachado e saiu para entrega (tentativa #' || v_tentativa::TEXT || ').'
    END),
    v_evt_key,
    jsonb_build_object('tentativa', v_tentativa, 'rota_id', v_rota_id),
    auth.uid(),
    v_usuario_nome
  );

  RETURN jsonb_build_object(
    'success', true,
    'idempotente', false,
    'pedido_id', p_pedido_id,
    'entrega_id', v_entrega.id,
    'rota_id', v_rota_id,
    'status_operacional', 'saiu_para_entrega',
    'status_logistico', 'em_rota',
    'tipo_evento', v_tipo_evento,
    'tentativas_count', v_tentativa
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.despachar_pedido_entrega(BIGINT, TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.despachar_pedido_entrega(BIGINT, TEXT, TEXT) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 11. RPC: REGISTRAR_FALHA_ENTREGA (GATE K7: FALHA MANTÉM HISTÓRICO E NÃO TOCA NO FINANCEIRO)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.registrar_falha_entrega(
  p_pedido_id BIGINT,
  p_motivo_falha TEXT,
  p_descricao TEXT DEFAULT NULL,
  p_chave_idempotencia TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_ped public.pedidos;
  v_entrega public.entregas;
  v_motivo TEXT := UPPER(TRIM(COALESCE(p_motivo_falha, '')));
  v_desc TEXT := NULLIF(TRIM(COALESCE(p_descricao, '')), '');
  v_rota_id BIGINT;
  v_usuario_nome TEXT;
  v_evt_key TEXT;
  v_evt_id BIGINT;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas equipe autorizada pode registrar ocorrências de entrega.');
  END IF;

  IF p_pedido_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_ID_REQUIRED', 'error', 'ID do pedido é obrigatório.');
  END IF;

  IF v_motivo NOT IN ('DESTINATARIO_AUSENTE', 'ENDERECO_NAO_LOCALIZADO', 'RECUSADO', 'PROBLEMA_TRANSPORTE', 'OUTRO') THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'INVALID_FAILURE_REASON',
      'error', 'Motivo de falha inválido. Use DESTINATARIO_AUSENTE, ENDERECO_NAO_LOCALIZADO, RECUSADO, PROBLEMA_TRANSPORTE ou OUTRO.'
    );
  END IF;

  SELECT * INTO v_ped
  FROM public.pedidos
  WHERE id = p_pedido_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_NOT_FOUND', 'error', 'Pedido não encontrado.');
  END IF;

  IF v_ped.status_operacional <> 'saiu_para_entrega' THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'ORDER_NOT_IN_TRANSIT',
      'error', 'Apenas pedidos que saíram para entrega podem receber registro de falha de entrega.'
    );
  END IF;

  SELECT * INTO v_entrega
  FROM public.entregas
  WHERE pedido_id = p_pedido_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'DELIVERY_NOT_FOUND', 'error', 'Registro logístico de entrega não localizado.');
  END IF;

  SELECT re.rota_id INTO v_rota_id
  FROM public.rota_entregas re
  WHERE re.entrega_id = v_entrega.id
    AND re.ativo = true
  LIMIT 1;

  SELECT COALESCE(nome, email, 'Equipe Logística') INTO v_usuario_nome
  FROM public.profiles WHERE id = auth.uid();
  IF v_usuario_nome IS NULL THEN v_usuario_nome := 'Equipe Logística'; END IF;

  IF v_desc IS NULL THEN
    v_desc := 'Falha na tentativa #' || GREATEST(1, v_entrega.tentativas_count)::TEXT || ': ' || v_motivo;
  END IF;

  v_evt_key := COALESCE(
    NULLIF(TRIM(COALESCE(p_chave_idempotencia, '')), ''),
    'falha:ped:' || p_pedido_id::TEXT || ':tentativa:' || GREATEST(1, v_entrega.tentativas_count)::TEXT || ':' || v_motivo
  );

  SELECT id INTO v_evt_id
  FROM public.entrega_eventos
  WHERE chave_idempotencia = v_evt_key;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'idempotente', true,
      'pedido_id', p_pedido_id,
      'entrega_id', v_entrega.id,
      'evento_id', v_evt_id,
      'status_operacional', v_ped.status_operacional,
      'status_logistico', v_entrega.status_logistico,
      'motivo_falha', v_motivo
    );
  END IF;

  UPDATE public.entregas
  SET status_logistico = 'falha_temporaria',
      ultimo_motivo_falha = v_motivo,
      observacoes_logisticas = v_desc,
      updated_at = NOW()
  WHERE id = v_entrega.id;

  INSERT INTO public.entrega_eventos (
    entrega_id,
    pedido_id,
    rota_id,
    tipo_evento,
    motivo_falha,
    descricao,
    chave_idempotencia,
    metadata,
    usuario_id,
    usuario_nome
  ) VALUES (
    v_entrega.id,
    p_pedido_id,
    v_rota_id,
    'FALHA_ENTREGA',
    v_motivo,
    v_desc,
    v_evt_key,
    jsonb_build_object('tentativa', v_entrega.tentativas_count, 'motivo_falha', v_motivo),
    auth.uid(),
    v_usuario_nome
  )
  RETURNING id INTO v_evt_id;

  RETURN jsonb_build_object(
    'success', true,
    'idempotente', false,
    'pedido_id', p_pedido_id,
    'entrega_id', v_entrega.id,
    'evento_id', v_evt_id,
    'status_operacional', v_ped.status_operacional,
    'status_logistico', 'falha_temporaria',
    'motivo_falha', v_motivo
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.registrar_falha_entrega(BIGINT, TEXT, TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.registrar_falha_entrega(BIGINT, TEXT, TEXT, TEXT) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 12. RPC: REAGENDAR_ENTREGA (GATE K8: PREPARA NOVA TENTATIVA APÓS FALHA)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.reagendar_entrega(
  p_pedido_id BIGINT,
  p_nova_data DATE,
  p_nova_hora TIME DEFAULT NULL,
  p_observacao TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_ped public.pedidos;
  v_entrega public.entregas;
  v_obs TEXT := NULLIF(TRIM(COALESCE(p_observacao, '')), '');
  v_usuario_nome TEXT;
  v_evt_key TEXT;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas equipe autorizada pode reagendar entregas.');
  END IF;

  IF p_pedido_id IS NULL OR p_nova_data IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'PARAMS_REQUIRED', 'error', 'ID do pedido e nova data são obrigatórios.');
  END IF;

  SELECT * INTO v_ped
  FROM public.pedidos
  WHERE id = p_pedido_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_NOT_FOUND', 'error', 'Pedido não encontrado.');
  END IF;

  IF COALESCE(v_ped.modalidade_entrega, 'retirada') <> 'entrega' THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_DELIVERY_MODALITY', 'error', 'Apenas pedidos de entrega podem ser reagendados na logística.');
  END IF;

  IF v_ped.status_operacional IN ('entregue', 'retirado', 'cancelado') THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_CLOSED', 'error', 'Pedido já entregue ou cancelado não pode ser reagendado.');
  END IF;

  SELECT * INTO v_entrega
  FROM public.entregas
  WHERE pedido_id = p_pedido_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'DELIVERY_NOT_FOUND', 'error', 'Entrega não localizada para este pedido.');
  END IF;

  SELECT COALESCE(nome, email, 'Equipe Logística') INTO v_usuario_nome
  FROM public.profiles WHERE id = auth.uid();
  IF v_usuario_nome IS NULL THEN v_usuario_nome := 'Equipe Logística'; END IF;

  UPDATE public.entregas
  SET status_logistico = 'reagendada',
      proxima_janela_data = p_nova_data,
      proxima_janela_hora = p_nova_hora,
      observacoes_logisticas = COALESCE(v_obs, observacoes_logisticas),
      updated_at = NOW()
  WHERE id = v_entrega.id;

  v_evt_key := 'reagendado:ped:' || p_pedido_id::TEXT || ':tent:' || v_entrega.tentativas_count::TEXT || ':' || p_nova_data::TEXT || ':' || COALESCE(p_nova_hora::TEXT, 'sem_hora');

  INSERT INTO public.entrega_eventos (
    entrega_id,
    pedido_id,
    tipo_evento,
    descricao,
    chave_idempotencia,
    metadata,
    usuario_id,
    usuario_nome
  ) VALUES (
    v_entrega.id,
    p_pedido_id,
    'REAGENDADO',
    COALESCE(v_obs, 'Entrega reagendada para ' || to_char(p_nova_data, 'DD/MM/YYYY') || COALESCE(' às ' || to_char(p_nova_hora, 'HH24:MI'), '')),
    v_evt_key,
    jsonb_build_object('nova_data', p_nova_data, 'nova_hora', p_nova_hora),
    auth.uid(),
    v_usuario_nome
  )
  ON CONFLICT (chave_idempotencia) DO NOTHING;

  RETURN jsonb_build_object(
    'success', true,
    'pedido_id', p_pedido_id,
    'entrega_id', v_entrega.id,
    'status_operacional', v_ped.status_operacional,
    'status_logistico', 'reagendada',
    'proxima_janela_data', p_nova_data,
    'proxima_janela_hora', p_nova_hora
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.reagendar_entrega(BIGINT, DATE, TIME, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.reagendar_entrega(BIGINT, DATE, TIME, TEXT) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 13. RPC: REGISTRAR_COMPROVANTE_ENTREGA (GATE K10: COMPROVANTE APPEND-ONLY IMUTÁVEL)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.registrar_comprovante_entrega(
  p_pedido_id BIGINT,
  p_recebido_por TEXT,
  p_tipo_comprovante TEXT DEFAULT 'assinatura_recebedor',
  p_documento_recebedor TEXT DEFAULT NULL,
  p_referencia_arquivo TEXT DEFAULT NULL,
  p_hash_arquivo TEXT DEFAULT NULL,
  p_metadata_tecnica JSONB DEFAULT '{}'::jsonb,
  p_chave_idempotencia TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_ped public.pedidos;
  v_entrega public.entregas;
  v_rec_por TEXT := NULLIF(TRIM(COALESCE(p_recebido_por, '')), '');
  v_tipo TEXT := LOWER(TRIM(COALESCE(p_tipo_comprovante, 'assinatura_recebedor')));
  v_usuario_nome TEXT;
  v_comp_key TEXT;
  v_comp_existente public.entrega_comprovantes;
  v_comp_id BIGINT;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas equipe autorizada pode registrar comprovante de entrega.');
  END IF;

  IF p_pedido_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_ID_REQUIRED', 'error', 'ID do pedido é obrigatório.');
  END IF;

  IF v_rec_por IS NULL OR char_length(v_rec_por) < 2 THEN
    RETURN jsonb_build_object('success', false, 'code', 'RECIPIENT_REQUIRED', 'error', 'Informe o nome de quem recebeu a encomenda (mínimo 2 caracteres).');
  END IF;

  IF v_tipo NOT IN ('assinatura_recebedor', 'foto_entrega', 'codigo_confirmacao', 'confirmacao_verbal_autorizada') THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_PROOF_TYPE', 'error', 'Tipo de comprovante inválido.');
  END IF;

  SELECT * INTO v_ped FROM public.pedidos WHERE id = p_pedido_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_NOT_FOUND', 'error', 'Pedido não encontrado.');
  END IF;

  IF COALESCE(v_ped.modalidade_entrega, 'retirada') <> 'entrega' THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_DELIVERY_MODALITY', 'error', 'Comprovante logístico de rota aplica-se apenas a pedidos de entrega.');
  END IF;

  SELECT * INTO v_entrega FROM public.entregas WHERE pedido_id = p_pedido_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'DELIVERY_NOT_FOUND', 'error', 'Operação logística de entrega não localizada para este pedido.');
  END IF;

  v_comp_key := COALESCE(
    NULLIF(TRIM(COALESCE(p_chave_idempotencia, '')), ''),
    'comprovante:ped:' || p_pedido_id::TEXT || ':' || v_tipo || ':' || LOWER(v_rec_por)
  );

  SELECT * INTO v_comp_existente
  FROM public.entrega_comprovantes
  WHERE chave_idempotencia = v_comp_key;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'idempotente', true,
      'comprovante_id', v_comp_existente.id,
      'pedido_id', p_pedido_id,
      'entrega_id', v_entrega.id,
      'recebido_por', v_comp_existente.recebido_por,
      'tipo_comprovante', v_comp_existente.tipo_comprovante,
      'registrado_em', v_comp_existente.registrado_em
    );
  END IF;

  SELECT COALESCE(nome, email, 'Equipe Logística') INTO v_usuario_nome
  FROM public.profiles WHERE id = auth.uid();
  IF v_usuario_nome IS NULL THEN v_usuario_nome := 'Equipe Logística'; END IF;

  INSERT INTO public.entrega_comprovantes (
    pedido_id,
    entrega_id,
    recebido_por,
    tipo_comprovante,
    documento_recebedor,
    referencia_arquivo,
    hash_arquivo,
    metadata_tecnica,
    chave_idempotencia,
    registrado_por,
    registrado_por_nome,
    registrado_em
  ) VALUES (
    p_pedido_id,
    v_entrega.id,
    v_rec_por,
    v_tipo,
    NULLIF(TRIM(COALESCE(p_documento_recebedor, '')), ''),
    NULLIF(TRIM(COALESCE(p_referencia_arquivo, '')), ''),
    NULLIF(TRIM(COALESCE(p_hash_arquivo, '')), ''),
    COALESCE(p_metadata_tecnica, '{}'::jsonb),
    v_comp_key,
    auth.uid(),
    v_usuario_nome,
    NOW()
  )
  RETURNING id INTO v_comp_id;

  INSERT INTO public.entrega_eventos (
    entrega_id,
    pedido_id,
    tipo_evento,
    descricao,
    chave_idempotencia,
    metadata,
    usuario_id,
    usuario_nome
  ) VALUES (
    v_entrega.id,
    p_pedido_id,
    'COMPROVANTE_REGISTRADO',
    'Comprovante de entrega registrado — recebido por: ' || v_rec_por,
    'evt:' || v_comp_key,
    jsonb_build_object('comprovante_id', v_comp_id, 'recebido_por', v_rec_por, 'tipo_comprovante', v_tipo),
    auth.uid(),
    v_usuario_nome
  )
  ON CONFLICT (chave_idempotencia) DO NOTHING;

  RETURN jsonb_build_object(
    'success', true,
    'idempotente', false,
    'comprovante_id', v_comp_id,
    'pedido_id', p_pedido_id,
    'entrega_id', v_entrega.id,
    'recebido_por', v_rec_por,
    'tipo_comprovante', v_tipo,
    'registrado_em', NOW()
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.registrar_comprovante_entrega(BIGINT, TEXT, TEXT, TEXT, TEXT, TEXT, JSONB, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.registrar_comprovante_entrega(BIGINT, TEXT, TEXT, TEXT, TEXT, TEXT, JSONB, TEXT) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 14. RPC: CONFIRMAR_ENTREGA_PEDIDO (GATES K5, K6, K12, K16)
-- ------------------------------------------------------------------------------
-- Serializa o pedido, transiciona saiu_para_entrega -> entregue de forma idempotente,
-- registra o comprovante quando informado e JAMAIS gera financeiro_lancamentos.
CREATE OR REPLACE FUNCTION public.confirmar_entrega_pedido(
  p_pedido_id BIGINT,
  p_recebido_por TEXT DEFAULT NULL,
  p_tipo_comprovante TEXT DEFAULT 'assinatura_recebedor',
  p_documento_recebedor TEXT DEFAULT NULL,
  p_referencia_arquivo TEXT DEFAULT NULL,
  p_hash_arquivo TEXT DEFAULT NULL,
  p_observacao TEXT DEFAULT NULL,
  p_chave_idempotencia TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_ped public.pedidos;
  v_entrega public.entregas;
  v_rota_id BIGINT;
  v_usuario_nome TEXT;
  v_rec_por TEXT := COALESCE(NULLIF(TRIM(COALESCE(p_recebido_por, '')), ''), 'Destinatário');
  v_obs TEXT := NULLIF(TRIM(COALESCE(p_observacao, '')), '');
  v_evt_key TEXT;
  v_comp_res JSONB;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas equipe autorizada pode confirmar conclusão de entrega.');
  END IF;

  IF p_pedido_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_ID_REQUIRED', 'error', 'ID do pedido é obrigatório.');
  END IF;

  -- Lock serializado no pedido (Gate K16)
  SELECT * INTO v_ped
  FROM public.pedidos
  WHERE id = p_pedido_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_NOT_FOUND', 'error', 'Pedido não encontrado.');
  END IF;

  IF v_ped.status_comercial = 'cancelado' OR v_ped.status_operacional = 'cancelado' THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_CANCELLED', 'error', 'Pedido cancelado não pode ter entrega confirmada.');
  END IF;

  IF COALESCE(v_ped.modalidade_entrega, 'retirada') <> 'entrega' THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'INVALID_DELIVERY_MODALITY',
      'error', 'Este pedido é de retirada na loja. Use a conclusão de retirada no balcão.'
    );
  END IF;

  SELECT * INTO v_entrega
  FROM public.entregas
  WHERE pedido_id = p_pedido_id
  FOR UPDATE;

  -- Gate K6: Idempotência estrita — se já consta entregue, não duplica evento nem comprovante
  IF v_ped.status_operacional = 'entregue' THEN
    RETURN jsonb_build_object(
      'success', true,
      'idempotente', true,
      'pedido_id', p_pedido_id,
      'entrega_id', v_entrega.id,
      'status_operacional', 'entregue',
      'status_logistico', 'entregue'
    );
  END IF;

  -- Exige que tenha saído para entrega antes de confirmar entrega logística
  IF v_ped.status_operacional <> 'saiu_para_entrega' THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'ORDER_NOT_DISPATCHED',
      'error', 'O pedido precisa ser despachado (saiu_para_entrega) antes de confirmar a entrega.',
      'status_operacional_atual', v_ped.status_operacional
    );
  END IF;

  IF v_entrega.id IS NULL THEN
    INSERT INTO public.entregas (
      pedido_id, status_logistico, tentativas_count, despachado_em, created_at, updated_at
    ) VALUES (
      p_pedido_id, 'em_rota', 1, NOW(), NOW(), NOW()
    )
    RETURNING * INTO v_entrega;
  END IF;

  SELECT re.rota_id INTO v_rota_id
  FROM public.rota_entregas re
  WHERE re.entrega_id = v_entrega.id
    AND re.ativo = true
  LIMIT 1;

  SELECT COALESCE(nome, email, 'Equipe Logística') INTO v_usuario_nome
  FROM public.profiles WHERE id = auth.uid();
  IF v_usuario_nome IS NULL THEN v_usuario_nome := 'Equipe Logística'; END IF;

  -- Gate K5 & K12: Atualiza status_operacional para 'entregue' SEM tocar em financeiro_lancamentos
  UPDATE public.pedidos
  SET status_operacional = 'entregue',
      status = 'Entregue',
      updated_at = NOW()
  WHERE id = p_pedido_id;

  INSERT INTO public.pedido_status_historico (
    pedido_id, dimensao, status_anterior, status_novo, usuario_id, usuario_nome, origem, metadata
  ) VALUES (
    p_pedido_id, 'operacional', v_ped.status_operacional, 'entregue',
    auth.uid(), v_usuario_nome, 'admin',
    jsonb_build_object('acao', 'confirmar_entrega_pedido', 'recebido_por', v_rec_por, 'rota_id', v_rota_id)
  );

  UPDATE public.entregas
  SET status_logistico = 'entregue',
      entregue_em = NOW(),
      observacoes_logisticas = COALESCE(v_obs, observacoes_logisticas),
      updated_at = NOW()
  WHERE id = v_entrega.id;

  v_evt_key := COALESCE(
    NULLIF(TRIM(COALESCE(p_chave_idempotencia, '')), ''),
    'entregue:ped:' || p_pedido_id::TEXT
  );

  INSERT INTO public.entrega_eventos (
    entrega_id,
    pedido_id,
    rota_id,
    tipo_evento,
    descricao,
    chave_idempotencia,
    metadata,
    usuario_id,
    usuario_nome
  ) VALUES (
    v_entrega.id,
    p_pedido_id,
    v_rota_id,
    'ENTREGUE',
    COALESCE(v_obs, 'Entrega concluída com sucesso. Recebido por: ' || v_rec_por),
    v_evt_key,
    jsonb_build_object('recebido_por', v_rec_por, 'tentativas', v_entrega.tentativas_count),
    auth.uid(),
    v_usuario_nome
  )
  ON CONFLICT (chave_idempotencia) DO NOTHING;

  -- Registra o comprovante canônico de entrega de forma idempotente
  v_comp_res := public.registrar_comprovante_entrega(
    p_pedido_id := p_pedido_id,
    p_recebido_por := v_rec_por,
    p_tipo_comprovante := COALESCE(p_tipo_comprovante, 'assinatura_recebedor'),
    p_documento_recebedor := p_documento_recebedor,
    p_referencia_arquivo := p_referencia_arquivo,
    p_hash_arquivo := p_hash_arquivo,
    p_metadata_tecnica := jsonb_build_object('origem', 'confirmar_entrega_pedido'),
    p_chave_idempotencia := 'comp:confirmacao:ped:' || p_pedido_id::TEXT
  );

  -- Se todas as entregas ativas da rota estiverem entregues, marca a rota como concluída
  IF v_rota_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.rota_entregas re
      JOIN public.entregas e ON e.id = re.entrega_id
      WHERE re.rota_id = v_rota_id
        AND re.ativo = true
        AND e.status_logistico <> 'entregue'
    ) THEN
      UPDATE public.rotas_entrega
      SET status = 'concluida',
          concluida_em = NOW(),
          updated_at = NOW()
      WHERE id = v_rota_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'idempotente', false,
    'pedido_id', p_pedido_id,
    'entrega_id', v_entrega.id,
    'rota_id', v_rota_id,
    'status_operacional', 'entregue',
    'status_logistico', 'entregue',
    'recebido_por', v_rec_por,
    'comprovante_id', v_comp_res->>'comprovante_id'
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.confirmar_entrega_pedido(BIGINT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.confirmar_entrega_pedido(BIGINT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 15. RPC: OBTER_PAINEL_LOGISTICA (VISÃO OPERACIONAL DA EQUIPE: EXPEDIÇÃO, ROTAS, EM ROTA)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.obter_painel_logistica(
  p_data DATE DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_is_equipe BOOLEAN := public.is_admin_or_operator();
  v_data_ref DATE := COALESCE(p_data, (NOW() AT TIME ZONE 'America/Fortaleza')::DATE);
  v_expedicao JSONB;
  v_rotas JSONB;
  v_em_rota JSONB;
  v_qtd_prontos INTEGER := 0;
  v_qtd_em_rota INTEGER := 0;
  v_qtd_falha INTEGER := 0;
  v_qtd_entregues INTEGER := 0;
  v_qtd_rotas INTEGER := 0;
BEGIN
  IF NOT v_is_equipe THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PERMISSION_DENIED',
      'error', 'Apenas administradores ou operadores podem consultar o painel de logística.'
    );
  END IF;

  -- 1. EXPEDIÇÃO: pedidos de entrega com status_operacional = 'pronto' aguardando despacho
  SELECT COALESCE(jsonb_agg(row_to_json(exp_row)::jsonb ORDER BY exp_row.data_entrega ASC, exp_row.hora_entrega ASC NULLS LAST, exp_row.pedido_id ASC), '[]'::jsonb)
  INTO v_expedicao
  FROM (
    SELECT
      p.id AS pedido_id,
      p.nome_cliente,
      p.telefone_cliente,
      p.endereco_entrega,
      p.data_entrega,
      p.hora_entrega,
      p.status_comercial,
      p.status_operacional,
      COALESCE(e.id, NULL) AS entrega_id,
      COALESCE(e.status_logistico, 'aguardando_despacho') AS status_logistico,
      r.id AS rota_id,
      r.codigo AS rota_codigo,
      r.turno AS rota_turno,
      r.responsavel_nome AS rota_responsavel,
      re.ordem_sequencia
    FROM public.pedidos p
    LEFT JOIN public.entregas e ON e.pedido_id = p.id
    LEFT JOIN public.rota_entregas re ON re.entrega_id = e.id AND re.ativo = true
    LEFT JOIN public.rotas_entrega r ON r.id = re.rota_id
    WHERE COALESCE(p.modalidade_entrega, 'retirada') = 'entrega'
      AND p.status_comercial <> 'cancelado'
      AND p.status_operacional = 'pronto'
      AND (p_data IS NULL OR p.data_entrega = v_data_ref OR COALESCE(e.proxima_janela_data, p.data_entrega) = v_data_ref)
  ) exp_row;

  -- 2. ROTAS DO DIA
  SELECT COALESCE(jsonb_agg(row_to_json(rt_row)::jsonb ORDER BY rt_row.data_rota DESC, rt_row.id DESC), '[]'::jsonb)
  INTO v_rotas
  FROM (
    SELECT
      r.id,
      r.codigo,
      r.data_rota,
      r.turno,
      r.responsavel_nome,
      r.responsavel_telefone,
      r.veiculo_identificacao,
      r.status,
      r.observacoes_internas,
      r.iniciada_em,
      r.concluida_em,
      COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'ordem_sequencia', re.ordem_sequencia,
            'pedido_id', p.id,
            'entrega_id', e.id,
            'nome_cliente', p.nome_cliente,
            'telefone_cliente', p.telefone_cliente,
            'endereco_entrega', p.endereco_entrega,
            'hora_entrega', p.hora_entrega,
            'status_operacional', p.status_operacional,
            'status_logistico', e.status_logistico,
            'tentativas_count', e.tentativas_count,
            'ultimo_motivo_falha', e.ultimo_motivo_falha
          ) ORDER BY re.ordem_sequencia ASC, re.id ASC
        )
        FROM public.rota_entregas re
        JOIN public.entregas e ON e.id = re.entrega_id
        JOIN public.pedidos p ON p.id = re.pedido_id
        WHERE re.rota_id = r.id
          AND re.ativo = true
      ), '[]'::jsonb) AS paradas
    FROM public.rotas_entrega r
    WHERE r.data_rota = v_data_ref
  ) rt_row;

  -- 3. EM ROTA / OCORRÊNCIAS / ENTREGUES
  SELECT COALESCE(jsonb_agg(row_to_json(tr_row)::jsonb ORDER BY tr_row.updated_at DESC, tr_row.pedido_id DESC), '[]'::jsonb)
  INTO v_em_rota
  FROM (
    SELECT
      p.id AS pedido_id,
      e.id AS entrega_id,
      p.nome_cliente,
      p.telefone_cliente,
      p.endereco_entrega,
      p.data_entrega,
      p.hora_entrega,
      p.status_operacional,
      e.status_logistico,
      e.tentativas_count,
      e.ultimo_motivo_falha,
      e.proxima_janela_data,
      e.proxima_janela_hora,
      e.despachado_em,
      e.entregue_em,
      e.observacoes_logisticas,
      e.updated_at,
      r.id AS rota_id,
      r.codigo AS rota_codigo,
      r.responsavel_nome AS rota_responsavel,
      re.ordem_sequencia,
      (
        SELECT jsonb_build_object(
          'comprovante_id', ec.id,
          'recebido_por', ec.recebido_por,
          'tipo_comprovante', ec.tipo_comprovante,
          'referencia_arquivo', ec.referencia_arquivo,
          'registrado_em', ec.registrado_em
        )
        FROM public.entrega_comprovantes ec
        WHERE ec.pedido_id = p.id
        ORDER BY ec.id DESC
        LIMIT 1
      ) AS comprovante
    FROM public.pedidos p
    JOIN public.entregas e ON e.pedido_id = p.id
    LEFT JOIN public.rota_entregas re ON re.entrega_id = e.id AND re.ativo = true
    LEFT JOIN public.rotas_entrega r ON r.id = re.rota_id
    WHERE COALESCE(p.modalidade_entrega, 'retirada') = 'entrega'
      AND (
        p.status_operacional = 'saiu_para_entrega'
        OR e.status_logistico IN ('em_rota', 'falha_temporaria', 'reagendada')
        OR (p.status_operacional = 'entregue' AND (p.data_entrega = v_data_ref OR (e.entregue_em AT TIME ZONE 'America/Fortaleza')::DATE = v_data_ref))
      )
  ) tr_row;

  SELECT COUNT(*) INTO v_qtd_prontos FROM jsonb_array_elements(v_expedicao);
  SELECT COUNT(*) INTO v_qtd_rotas FROM jsonb_array_elements(v_rotas);

  SELECT
    COUNT(*) FILTER (WHERE e.status_logistico = 'em_rota'),
    COUNT(*) FILTER (WHERE e.status_logistico IN ('falha_temporaria', 'reagendada')),
    COUNT(*) FILTER (WHERE e.status_logistico = 'entregue' AND (p.data_entrega = v_data_ref OR (e.entregue_em AT TIME ZONE 'America/Fortaleza')::DATE = v_data_ref))
  INTO v_qtd_em_rota, v_qtd_falha, v_qtd_entregues
  FROM public.entregas e
  JOIN public.pedidos p ON p.id = e.pedido_id
  WHERE COALESCE(p.modalidade_entrega, 'retirada') = 'entrega';

  RETURN jsonb_build_object(
    'success', true,
    'data_referencia', v_data_ref,
    'resumo', jsonb_build_object(
      'prontos_expedicao', v_qtd_prontos,
      'em_rota', v_qtd_em_rota,
      'com_falha_ou_reagendados', v_qtd_falha,
      'entregues_no_dia', v_qtd_entregues,
      'rotas_no_dia', v_qtd_rotas
    ),
    'expedicao_aguardando', v_expedicao,
    'rotas_do_dia', v_rotas,
    'em_rota_e_ocorrencias', v_em_rota
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_painel_logistica(DATE) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_painel_logistica(DATE) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 16. RPC PORTAL DO CLIENTE: OBTER_ACOMPANHAMENTO_ENTREGA_CLIENTE (GATES K9, K14, K15)
-- ------------------------------------------------------------------------------
-- Resolve identidade exclusivamente por _resolver_meu_cliente_id() (auth.uid()).
-- Jamais expõe telefone do entregador, notas logísticas da equipe, placa,
-- rota completa, endereços de outros clientes ou comprovantes de terceiros.
CREATE OR REPLACE FUNCTION public.obter_acompanhamento_entrega_cliente(
  p_pedido_id BIGINT
)
RETURNS JSONB AS $$
DECLARE
  v_ident JSONB := public._resolver_meu_cliente_id();
  v_cli_id BIGINT;
  v_ped public.pedidos;
  v_entrega public.entregas;
  v_eventos JSONB;
  v_comp JSONB;
  v_etapa_cliente TEXT;
  v_prod_concluida BOOLEAN := false;
  v_saiu_entrega BOOLEAN := false;
  v_em_rota BOOLEAN := false;
  v_entregue BOOLEAN := false;
BEGIN
  IF (v_ident->>'success')::BOOLEAN IS NOT TRUE THEN
    RETURN v_ident;
  END IF;

  IF p_pedido_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_ID_REQUIRED', 'error', 'ID do pedido é obrigatório.');
  END IF;

  v_cli_id := (v_ident->>'cliente_id')::BIGINT;

  -- Gate K14: Isolamento estrito por titular da conta
  SELECT * INTO v_ped
  FROM public.pedidos
  WHERE id = p_pedido_id
    AND cliente_id_rel = v_cli_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'ORDER_NOT_FOUND',
      'error', 'Pedido não encontrado para sua conta.'
    );
  END IF;

  -- Gate K15: Pedido de retirada não acessa tracking de rota de entrega
  IF COALESCE(v_ped.modalidade_entrega, 'retirada') <> 'entrega' THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'DELIVERY_TRACKING_NOT_APPLICABLE',
      'error', 'Este pedido está na modalidade retirada na loja e não possui rastreamento de rota de entrega.'
    );
  END IF;

  SELECT * INTO v_entrega
  FROM public.entregas
  WHERE pedido_id = p_pedido_id;

  v_etapa_cliente := public._derivar_etapa_cliente_pedido(
    v_ped.status_comercial,
    v_ped.status_operacional,
    v_ped.modalidade_entrega
  );

  v_prod_concluida := v_ped.status_operacional IN ('pronto', 'saiu_para_entrega', 'entregue');
  v_saiu_entrega := v_ped.status_operacional IN ('saiu_para_entrega', 'entregue') OR v_entrega.despachado_em IS NOT NULL;
  v_em_rota := v_ped.status_operacional = 'saiu_para_entrega' AND COALESCE(v_entrega.status_logistico, 'em_rota') = 'em_rota';
  v_entregue := v_ped.status_operacional = 'entregue';

  -- Gate K9: Linha do tempo estritamente sanitizada (sem usuario_nome, sem rota_id, sem notas internas)
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'tipo_evento', ev.tipo_evento,
      'titulo', CASE ev.tipo_evento
        WHEN 'DESPACHADO' THEN 'Saiu para entrega'
        WHEN 'NOVA_TENTATIVA_DESPACHO' THEN 'Nova saída para entrega iniciada'
        WHEN 'FALHA_ENTREGA' THEN 'Tentativa de entrega não concluída'
        WHEN 'REAGENDADO' THEN 'Entrega reagendada'
        WHEN 'ENTREGUE' THEN 'Pedido entregue'
        ELSE 'Atualização de entrega'
      END,
      'motivo_falha', ev.motivo_falha,
      'horario', ev.created_at
    ) ORDER BY ev.id ASC
  ), '[]'::jsonb)
  INTO v_eventos
  FROM public.entrega_eventos ev
  WHERE ev.pedido_id = p_pedido_id
    AND ev.tipo_evento IN ('DESPACHADO', 'NOVA_TENTATIVA_DESPACHO', 'FALHA_ENTREGA', 'REAGENDADO', 'ENTREGUE');

  -- Comprovante sanitizado do próprio pedido (apenas recebido_por, tipo_comprovante e registrado_em)
  SELECT jsonb_build_object(
    'recebido_por', ec.recebido_por,
    'tipo_comprovante', ec.tipo_comprovante,
    'registrado_em', ec.registrado_em
  )
  INTO v_comp
  FROM public.entrega_comprovantes ec
  WHERE ec.pedido_id = p_pedido_id
  ORDER BY ec.id DESC
  LIMIT 1;

  RETURN jsonb_build_object(
    'success', true,
    'rastreamento', jsonb_build_object(
      'pedido_id', v_ped.id,
      'data_entrega_prevista', v_ped.data_entrega,
      'hora_entrega_prevista', v_ped.hora_entrega,
      'etapa_cliente', v_etapa_cliente,
      'status_logistico', COALESCE(v_entrega.status_logistico, CASE
        WHEN v_ped.status_operacional = 'entregue' THEN 'entregue'
        WHEN v_ped.status_operacional = 'saiu_para_entrega' THEN 'em_rota'
        ELSE 'aguardando_despacho'
      END),
      'tentativas_realizadas', COALESCE(v_entrega.tentativas_count, 0),
      'ultimo_motivo_falha', v_entrega.ultimo_motivo_falha,
      'proxima_janela_data', v_entrega.proxima_janela_data,
      'proxima_janela_hora', v_entrega.proxima_janela_hora,
      'despachado_em', v_entrega.despachado_em,
      'entregue_em', v_entrega.entregue_em,
      'etapas_visuais', jsonb_build_object(
        'producao_concluida', v_prod_concluida,
        'saiu_para_entrega', v_saiu_entrega,
        'em_rota', v_em_rota,
        'entregue', v_entregue
      ),
      'eventos', v_eventos,
      'comprovante', v_comp
    )
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_acompanhamento_entrega_cliente(BIGINT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_acompanhamento_entrega_cliente(BIGINT) TO authenticated, service_role;


-- ==========================================================================
-- >>> MIGRATION 027_lotes_validade_rastreabilidade_qualidade.sql
-- ==========================================================================

-- ==============================================================================
-- LUNOCA DOCERIA - MIGRATION 027: LOTES, VALIDADE, RASTREABILIDADE E QUALIDADE DE PRODUÇÃO (FRENTE L)
-- ==============================================================================
-- Fecha o elo físico-operacional entre Fornecedor -> Ingrediente (Lote/Validade) ->
-- Consumo Produtivo (FEFO) -> Controle de Qualidade -> Pedido -> Cliente.
--
-- Invariantes garantidas:
-- 1. Zero substituição de public.ingrediente_saldos: o saldo agregado permanece a
--    verdade consolidada e public.ingrediente_lotes é a sua composição rastreável.
-- 2. Invariante matemática universal (Gate L7):
--    SUM(ingrediente_lotes.quantidade_atual) == ingrediente_saldos.saldo_atual
--    verificada transacionalmente ao final de toda movimentação.
-- 3. Política FEFO (First Expire, First Out) server-side com FOR UPDATE (Gates L3, L4, L5, L6):
--    Consome primeiro o lote elegível com menor data_validade, ignorando lotes
--    vencidos (data_validade < hoje) e lotes bloqueados por qualidade.
-- 4. Livros-razão estritamente append-only (Gate L10):
--    public.ingrediente_lote_movimentacoes, public.pedido_consumos_lote e
--    public.producao_controles_qualidade bloqueiam UPDATE e DELETE físicos.
-- 5. Bloqueio de escrita direta em public.ingrediente_lotes fora das portas canônicas.
-- 6. Controle de Qualidade com bloqueio automático de avanço operacional em caso de
--    reprovação até que haja reinspeção aprovada (Gates L14, L15) e efeito financeiro ZERO (Gate L16).
-- ==============================================================================

-- ------------------------------------------------------------------------------
-- 1. EXTENSÕES FORWARD-ONLY EM CONFIGURAÇÕES, INGREDIENTES E COMPRA_ITENS
-- ------------------------------------------------------------------------------
ALTER TABLE public.configuracoes_operacao
  ADD COLUMN IF NOT EXISTS dias_alerta_validade_padrao INTEGER NOT NULL DEFAULT 7
  CHECK (dias_alerta_validade_padrao >= 1 AND dias_alerta_validade_padrao <= 365);

ALTER TABLE public.ingredientes
  ADD COLUMN IF NOT EXISTS controlar_lote BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS controlar_validade BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS dias_alerta_validade INTEGER
    CHECK (dias_alerta_validade IS NULL OR (dias_alerta_validade >= 1 AND dias_alerta_validade <= 365));

ALTER TABLE public.compra_itens
  ADD COLUMN IF NOT EXISTS codigo_lote TEXT,
  ADD COLUMN IF NOT EXISTS data_fabricacao DATE,
  ADD COLUMN IF NOT EXISTS data_validade DATE;

ALTER TABLE public.compra_itens
  DROP CONSTRAINT IF EXISTS uq_compra_ingrediente;

-- ------------------------------------------------------------------------------
-- 2. TABELA PUBLIC.INGREDIENTE_LOTES (COMPOSIÇÃO RASTREÁVEL DO SALDO)
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.ingrediente_lotes (
  id BIGSERIAL PRIMARY KEY,
  ingrediente_id BIGINT NOT NULL REFERENCES public.ingredientes(id) ON DELETE RESTRICT,
  fornecedor_id BIGINT REFERENCES public.fornecedores(id) ON DELETE SET NULL,
  compra_id BIGINT REFERENCES public.compras(id) ON DELETE SET NULL,
  compra_item_id BIGINT REFERENCES public.compra_itens(id) ON DELETE SET NULL,
  codigo_lote TEXT NOT NULL CHECK (char_length(btrim(codigo_lote)) >= 1),
  data_recebimento DATE NOT NULL DEFAULT CURRENT_DATE,
  data_fabricacao DATE,
  data_validade DATE,
  quantidade_inicial NUMERIC(12,3) NOT NULL CHECK (quantidade_inicial > 0),
  quantidade_atual NUMERIC(12,3) NOT NULL CHECK (quantidade_atual >= 0 AND quantidade_atual <= quantidade_inicial),
  custo_unitario_lote NUMERIC(12,4) NOT NULL DEFAULT 0.0000 CHECK (custo_unitario_lote >= 0),
  bloqueado_qualidade BOOLEAN NOT NULL DEFAULT false,
  motivo_bloqueio TEXT,
  bloqueado_em TIMESTAMPTZ,
  bloqueado_por UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  observacoes TEXT,
  idempotency_key TEXT UNIQUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_ingrediente_codigo_lote UNIQUE (ingrediente_id, codigo_lote)
);

CREATE INDEX IF NOT EXISTS idx_ing_lotes_fefo
  ON public.ingrediente_lotes(ingrediente_id, data_validade ASC NULLS LAST, data_recebimento ASC, id ASC)
  WHERE quantidade_atual > 0 AND bloqueado_qualidade = false;

CREATE INDEX IF NOT EXISTS idx_ing_lotes_validade
  ON public.ingrediente_lotes(data_validade ASC)
  WHERE quantidade_atual > 0;

CREATE INDEX IF NOT EXISTS idx_ing_lotes_compra
  ON public.ingrediente_lotes(compra_id);

-- Proteção contra escrita/UPDATE direto fora das RPCs canônicas
CREATE OR REPLACE FUNCTION public._proteger_escrita_direta_ingrediente_lotes()
RETURNS TRIGGER AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'IMMUTABLE_LOT_RECORD: Lotes de ingredientes não podem ser excluídos fisicamente.'
      USING ERRCODE = '42501';
  END IF;

  IF COALESCE(current_setting('lunoca.allow_lote_mutation', true), '') <> 'true' THEN
    RAISE EXCEPTION 'DIRECT_LOT_MUTATION_FORBIDDEN: Alteração direta em ingrediente_lotes proibida. Utilize as RPCs canônicas de recebimento, consumo FEFO, perda ou ajuste.'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_proteger_escrita_ingrediente_lotes ON public.ingrediente_lotes;
CREATE TRIGGER trg_proteger_escrita_ingrediente_lotes
  BEFORE INSERT OR UPDATE OR DELETE ON public.ingrediente_lotes
  FOR EACH ROW
  EXECUTE FUNCTION public._proteger_escrita_direta_ingrediente_lotes();

-- ------------------------------------------------------------------------------
-- 3. TABELA PUBLIC.INGREDIENTE_LOTE_MOVIMENTACOES (LIVRO-RAZÃO APPEND-ONLY)
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.ingrediente_lote_movimentacoes (
  id BIGSERIAL PRIMARY KEY,
  lote_id BIGINT NOT NULL REFERENCES public.ingrediente_lotes(id) ON DELETE RESTRICT,
  ingrediente_id BIGINT NOT NULL REFERENCES public.ingredientes(id) ON DELETE RESTRICT,
  ingrediente_movimentacao_id BIGINT REFERENCES public.ingrediente_movimentacoes(id) ON DELETE SET NULL,
  tipo_evento TEXT NOT NULL CHECK (tipo_evento IN (
    'ENTRADA_COMPRA',
    'CONSUMO_PRODUCAO',
    'PERDA',
    'VENCIMENTO',
    'AJUSTE_CONTAGEM',
    'DEVOLUCAO'
  )),
  quantidade NUMERIC(12,3) NOT NULL CHECK (quantidade > 0),
  saldo_lote_anterior NUMERIC(12,3) NOT NULL CHECK (saldo_lote_anterior >= 0),
  saldo_lote_posterior NUMERIC(12,3) NOT NULL CHECK (saldo_lote_posterior >= 0),
  custo_unitario_aplicado NUMERIC(12,4) NOT NULL DEFAULT 0.0000 CHECK (custo_unitario_aplicado >= 0),
  compra_id BIGINT REFERENCES public.compras(id) ON DELETE SET NULL,
  pedido_id BIGINT REFERENCES public.pedidos(id) ON DELETE SET NULL,
  motivo TEXT NOT NULL CHECK (char_length(btrim(motivo)) >= 3),
  usuario_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  usuario_nome TEXT,
  idempotency_key TEXT UNIQUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_ing_lote_mov_lote ON public.ingrediente_lote_movimentacoes(lote_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_ing_lote_mov_ing ON public.ingrediente_lote_movimentacoes(ingrediente_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_ing_lote_mov_pedido ON public.ingrediente_lote_movimentacoes(pedido_id) WHERE pedido_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_ing_lote_mov_compra ON public.ingrediente_lote_movimentacoes(compra_id) WHERE compra_id IS NOT NULL;

CREATE OR REPLACE FUNCTION public._bloquear_mutacao_ingrediente_lote_mov()
RETURNS TRIGGER AS $$
BEGIN
  RAISE EXCEPTION 'IMMUTABLE_LOT_LEDGER_VIOLATION: O livro-razão ingrediente_lote_movimentacoes é estritamente append-only e não permite %.', TG_OP
    USING ERRCODE = '42501';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_imutabilidade_ingrediente_lote_mov ON public.ingrediente_lote_movimentacoes;
CREATE TRIGGER trg_imutabilidade_ingrediente_lote_mov
  BEFORE UPDATE OR DELETE ON public.ingrediente_lote_movimentacoes
  FOR EACH ROW
  EXECUTE FUNCTION public._bloquear_mutacao_ingrediente_lote_mov();

-- ------------------------------------------------------------------------------
-- 4. TABELA PUBLIC.PEDIDO_CONSUMOS_LOTE (RASTREABILIDADE LOTE <-> PEDIDO)
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.pedido_consumos_lote (
  id BIGSERIAL PRIMARY KEY,
  pedido_id BIGINT NOT NULL REFERENCES public.pedidos(id) ON DELETE RESTRICT,
  pedido_item_id BIGINT REFERENCES public.pedido_itens(id) ON DELETE SET NULL,
  produto_id BIGINT REFERENCES public.produtos(id) ON DELETE SET NULL,
  ingrediente_id BIGINT NOT NULL REFERENCES public.ingredientes(id) ON DELETE RESTRICT,
  lote_id BIGINT NOT NULL REFERENCES public.ingrediente_lotes(id) ON DELETE RESTRICT,
  lote_movimentacao_id BIGINT REFERENCES public.ingrediente_lote_movimentacoes(id) ON DELETE SET NULL,
  codigo_lote_snapshot TEXT NOT NULL,
  data_validade_snapshot DATE,
  quantidade_consumida NUMERIC(12,3) NOT NULL CHECK (quantidade_consumida > 0),
  unidade VARCHAR(10) NOT NULL DEFAULT 'g',
  custo_unitario_lote_snapshot NUMERIC(12,4) NOT NULL DEFAULT 0.0000 CHECK (custo_unitario_lote_snapshot >= 0),
  consumido_em TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  registrado_por UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  registrado_por_nome TEXT,
  idempotency_key TEXT UNIQUE
);

CREATE INDEX IF NOT EXISTS idx_ped_consumos_lote_pedido ON public.pedido_consumos_lote(pedido_id);
CREATE INDEX IF NOT EXISTS idx_ped_consumos_lote_lote ON public.pedido_consumos_lote(lote_id);
CREATE INDEX IF NOT EXISTS idx_ped_consumos_lote_ingrediente ON public.pedido_consumos_lote(ingrediente_id);

CREATE OR REPLACE FUNCTION public._bloquear_mutacao_pedido_consumos_lote()
RETURNS TRIGGER AS $$
BEGIN
  RAISE EXCEPTION 'IMMUTABLE_TRACEABILITY_VIOLATION: Os registros de rastreabilidade pedido_consumos_lote são imutáveis e não permitem %.', TG_OP
    USING ERRCODE = '42501';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_imutabilidade_pedido_consumos_lote ON public.pedido_consumos_lote;
CREATE TRIGGER trg_imutabilidade_pedido_consumos_lote
  BEFORE UPDATE OR DELETE ON public.pedido_consumos_lote
  FOR EACH ROW
  EXECUTE FUNCTION public._bloquear_mutacao_pedido_consumos_lote();

