-- ------------------------------------------------------------------------------
-- 9. RPC SIMULAR_PRECO_PRODUTO_ADMIN
-- ------------------------------------------------------------------------------
-- Calcula a estrutura estimada de custos do produto e projeta preços de venda.
-- NÃO altera catálogo (produtos.preco permanece intocado).
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.simular_preco_produto_admin(
  p_produto_id BIGINT,
  p_margem_alvo NUMERIC DEFAULT NULL,
  p_politica_id BIGINT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_prod RECORD;
  v_pol RECORD;
  v_custo_insumos NUMERIC(10,2) := 0.00;
  v_custo_mao_obra NUMERIC(10,2) := 0.00;
  v_custo_embalagem NUMERIC(10,2) := 0.00;
  v_custo_adicionais NUMERIC(10,2) := 0.00;
  v_custo_direto_total NUMERIC(10,2) := 0.00;
  v_margem_alvo NUMERIC(5,2);
  v_taxa_cartao NUMERIC(5,2);
  v_impostos NUMERIC(5,2);
  v_comissao NUMERIC(5,2);
  v_custo_indireto_pct NUMERIC(5,2);
  v_deducoes_break_even NUMERIC(5,2);
  v_deducoes_alvo NUMERIC(5,2);
  v_preco_atual NUMERIC(10,2);
  v_preco_equilibrio NUMERIC(10,2);
  v_preco_margem_alvo NUMERIC(10,2);
  v_margem_atual_valor NUMERIC(10,2);
  v_margem_atual_pct NUMERIC(6,2);
  v_insumos_detalhes JSONB := '[]'::jsonb;
  v_tempos_detalhes JSONB := '[]'::jsonb;
  v_adicionais_detalhes JSONB := '[]'::jsonb;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PERMISSION_DENIED',
      'error', 'Apenas administradores podem simular preços e custos de produtos.'
    );
  END IF;

  SELECT * INTO v_prod FROM public.produtos WHERE id = p_produto_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'PRODUCT_NOT_FOUND', 'error', 'Produto não encontrado.');
  END IF;
  v_preco_atual := COALESCE(v_prod.preco, 0.00);

  -- Carregar política de precificação ativa
  IF p_politica_id IS NOT NULL THEN
    SELECT * INTO v_pol FROM public.politicas_precificacao WHERE id = p_politica_id;
  ELSE
    SELECT * INTO v_pol FROM public.politicas_precificacao WHERE padrao = true AND ativo = true LIMIT 1;
  END IF;

  IF NOT FOUND THEN
    SELECT * INTO v_pol FROM public.politicas_precificacao WHERE ativo = true ORDER BY id ASC LIMIT 1;
  END IF;

  v_margem_alvo := COALESCE(p_margem_alvo, v_pol.margem_alvo_padrao_percentual, 40.00);
  v_taxa_cartao := COALESCE(v_pol.taxa_cartao_padrao_percentual, 3.99);
  v_impostos := COALESCE(v_pol.impostos_padrao_percentual, 6.00);
  v_comissao := COALESCE(v_pol.comissao_padrao_percentual, 0.00);
  v_custo_indireto_pct := COALESCE(v_pol.custo_indireto_padrao_percentual, 5.00);

  -- 1. Custo de insumos pelo CMP atual (ou custo_unitario se CMP zerado)
  SELECT
    COALESCE(ROUND(SUM(pi.quantidade * COALESCE(NULLIF(s.custo_medio_ponderado, 0), i.custo_unitario, 0)), 2), 0.00),
    COALESCE(jsonb_agg(jsonb_build_object(
      'ingrediente_id', i.id,
      'nome', i.nome,
      'quantidade', pi.quantidade,
      'unidade', i.unidade,
      'custo_unitario_cmp', COALESCE(NULLIF(s.custo_medio_ponderado, 0), i.custo_unitario, 0),
      'custo_total', ROUND(pi.quantidade * COALESCE(NULLIF(s.custo_medio_ponderado, 0), i.custo_unitario, 0), 2)
    )), '[]'::jsonb)
  INTO v_custo_insumos, v_insumos_detalhes
  FROM public.produto_ingredientes pi
  JOIN public.ingredientes i ON i.id = pi.ingrediente_id
  LEFT JOIN public.ingrediente_saldos s ON s.ingrediente_id = i.id
  WHERE pi.produto_id = p_produto_id;

  -- 2. Custo de mão de obra e processos pelos tempos padrão
  SELECT
    COALESCE(ROUND(SUM((pt.minutos_padrao / 60.0) * r.custo_hora), 2), 0.00),
    COALESCE(jsonb_agg(jsonb_build_object(
      'etapa', pt.etapa,
      'minutos', pt.minutos_padrao,
      'recurso_id', r.id,
      'recurso_nome', r.nome,
      'recurso_tipo', r.tipo,
      'custo_hora', r.custo_hora,
      'custo_etapa', ROUND((pt.minutos_padrao / 60.0) * r.custo_hora, 2)
    )), '[]'::jsonb)
  INTO v_custo_mao_obra, v_tempos_detalhes
  FROM public.produto_tempos_producao pt
  JOIN public.recursos_producao r ON r.id = pt.recurso_id
  WHERE pt.produto_id = p_produto_id AND r.ativo = true;

  -- 3. Embalagens e adicionais configurados para o produto
  SELECT
    COALESCE(ROUND(SUM(CASE WHEN categoria = 'embalagem' THEN valor ELSE 0.00 END), 2), 0.00),
    COALESCE(ROUND(SUM(CASE WHEN categoria <> 'embalagem' THEN valor ELSE 0.00 END), 2), 0.00),
    COALESCE(jsonb_agg(jsonb_build_object(
      'id', ca.id,
      'nome', ca.nome,
      'categoria', ca.categoria,
      'tipo_aplicacao', ca.tipo_aplicacao,
      'valor', ca.valor
    )), '[]'::jsonb)
  INTO v_custo_embalagem, v_custo_adicionais, v_adicionais_detalhes
  FROM public.produto_custos_adicionais ca
  WHERE ca.produto_id = p_produto_id AND ca.ativo = true;

  v_custo_direto_total := v_custo_insumos + v_custo_mao_obra + v_custo_embalagem + v_custo_adicionais;

  -- 4. Cálculo de Preço de Equilíbrio (Break-even: margem 0)
  v_deducoes_break_even := (v_taxa_cartao + v_impostos + v_comissao + v_custo_indireto_pct);
  IF v_deducoes_break_even >= 100.00 THEN
    v_preco_equilibrio := 0.00;
  ELSE
    v_preco_equilibrio := ROUND(v_custo_direto_total / (1.00 - (v_deducoes_break_even / 100.00)), 2);
  END IF;

  -- 5. Cálculo de Preço para Margem Alvo
  v_deducoes_alvo := (v_deducoes_break_even + v_margem_alvo);
  IF v_deducoes_alvo >= 100.00 THEN
    v_preco_margem_alvo := 0.00;
  ELSE
    v_preco_margem_alvo := ROUND(v_custo_direto_total / (1.00 - (v_deducoes_alvo / 100.00)), 2);
  END IF;

  -- 6. Margem Atual no Preço de Catálogo
  IF v_preco_atual > 0 THEN
    v_margem_atual_valor := ROUND(v_preco_atual - v_custo_direto_total - (v_preco_atual * (v_deducoes_break_even / 100.00)), 2);
    v_margem_atual_pct := ROUND((v_margem_atual_valor / v_preco_atual) * 100.0, 2);
  ELSE
    v_margem_atual_valor := 0.00;
    v_margem_atual_pct := 0.00;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'produto_id', p_produto_id,
    'produto_nome', v_prod.nome,
    'preco_atual_catalogo', v_preco_atual,
    'custo_insumos_cmp', v_custo_insumos,
    'custo_mao_de_obra', v_custo_mao_obra,
    'custo_embalagem', v_custo_embalagem,
    'custo_adicionais', v_custo_adicionais,
    'custo_direto_total', v_custo_direto_total,
    'parametros_politica', jsonb_build_object(
      'politica_id', v_pol.id,
      'politica_nome', v_pol.nome,
      'margem_alvo_pct', v_margem_alvo,
      'taxa_cartao_pct', v_taxa_cartao,
      'impostos_pct', v_impostos,
      'comissao_pct', v_comissao,
      'custo_indireto_pct', v_custo_indireto_pct
    ),
    'preco_equilibrio_breakeven', v_preco_equilibrio,
    'preco_sugerido_margem_alvo', v_preco_margem_alvo,
    'margem_atual_no_preco', jsonb_build_object(
      'margem_valor', v_margem_atual_valor,
      'margem_percentual', v_margem_atual_pct,
      'abaixo_do_alvo', (v_margem_atual_pct < v_margem_alvo),
      'margem_negativa', (v_margem_atual_valor < 0)
    ),
    'detalhamento', jsonb_build_object(
      'insumos', v_insumos_detalhes,
      'tempos_producao', v_tempos_detalhes,
      'adicionais', v_adicionais_detalhes
    )
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.simular_preco_produto_admin FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.simular_preco_produto_admin TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 10. RPC CALCULAR_CUSTO_REAL_PEDIDO_ADMIN
-- ------------------------------------------------------------------------------
-- Consolida o custo realizado e a margem de contribuição efetiva do pedido.
-- Salva snapshot imutável em pedido_custos_realizados e linhas em pedido_custo_componentes.
-- Idempotente caso já calculado e sem motivo de retificação.
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.calcular_custo_real_pedido_admin(
  p_pedido_id BIGINT,
  p_motivo_retificacao TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_ped RECORD;
  v_pol RECORD;
  v_existente RECORD;
  v_nova_versao INT := 1;
  v_rec RECORD;
  v_custo_realizado_id BIGINT;

  v_receita_liquida NUMERIC(12,2) := 0.00;
  v_desconto_comercial NUMERIC(12,2) := 0.00;
  v_frete_base NUMERIC(12,2) := 0.00;
  v_frete_cobrado NUMERIC(12,2) := 0.00;
  v_frete_subsidiado NUMERIC(12,2) := 0.00;

  v_custo_insumos NUMERIC(12,2) := 0.00;
  v_custo_embalagem NUMERIC(12,2) := 0.00;
  v_custo_mao_obra NUMERIC(12,2) := 0.00;
  v_custo_adicionais NUMERIC(12,2) := 0.00;
  v_taxas_variaveis NUMERIC(12,2) := 0.00;
  v_custo_indireto NUMERIC(12,2) := 0.00;
  v_custo_atribuivel_total NUMERIC(12,2) := 0.00;

  v_margem_valor NUMERIC(12,2) := 0.00;
  v_margem_pct NUMERIC(6,2) := 0.00;

  v_motivo TEXT := NULLIF(TRIM(COALESCE(p_motivo_retificacao, '')), '');
  v_user_id UUID := auth.uid();
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PERMISSION_DENIED',
      'error', 'Apenas administradores podem calcular ou auditar custos e margens de pedidos.'
    );
  END IF;

  SELECT * INTO v_ped FROM public.pedidos WHERE id = p_pedido_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'ORDER_NOT_FOUND', 'error', 'Pedido não encontrado.');
  END IF;

  -- Pedido cancelado antes de produzir não gera custo realizado
  IF v_ped.status_comercial = 'cancelado' AND v_ped.status_operacional IN ('aguardando_producao', 'cancelado') THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'ORDER_CANCELLED_BEFORE_PRODUCTION',
      'error', 'Pedidos cancelados antes do início da produção não possuem custo realizado atribuível.'
    );
  END IF;

  -- Verificar cálculo existente finalizado (idempotência)
  SELECT * INTO v_existente
  FROM public.pedido_custos_realizados
  WHERE pedido_id = p_pedido_id AND status = 'finalizado'
  ORDER BY versao DESC LIMIT 1;

  IF FOUND AND v_motivo IS NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'idempotente', true,
      'custo_realizado_id', v_existente.id,
      'pedido_id', p_pedido_id,
      'versao', v_existente.versao,
      'status', v_existente.status,
      'receita_liquida', v_existente.receita_liquida_snapshot,
      'custo_ingredientes_real', v_existente.custo_ingredientes_real,
      'custo_embalagem', v_existente.custo_embalagem,
      'custo_mao_de_obra', v_existente.custo_mao_de_obra,
      'custo_adicionais', v_existente.custo_adicionais,
      'frete_subsidiado', v_existente.frete_subsidiado,
      'custo_indireto_rateado', v_existente.custo_indireto_rateado,
      'taxas_variaveis_atribuiveis', v_existente.taxas_variaveis_atribuiveis,
      'custo_atribuivel_total', v_existente.custo_atribuivel_total,
      'margem_contribuicao_valor', v_existente.margem_contribuicao_valor,
      'margem_contribuicao_percentual', v_existente.margem_contribuicao_percentual,
      'calculado_em', v_existente.calculado_em
    );
  END IF;

  IF FOUND AND v_motivo IS NOT NULL THEN
    IF length(v_motivo) < 5 THEN
      RETURN jsonb_build_object(
        'success', false,
        'code', 'RETIFICATION_REASON_REQUIRED',
        'error', 'Para gerar uma nova versão retificada de custos, informe a justificativa (mínimo 5 caracteres).'
      );
    END IF;
    v_nova_versao := v_existente.versao + 1;
  END IF;

  -- 1. Obter Política de Precificação vigente para o cálculo
  SELECT * INTO v_pol FROM public.politicas_precificacao WHERE padrao = true AND ativo = true LIMIT 1;
  IF NOT FOUND THEN
    SELECT * INTO v_pol FROM public.politicas_precificacao WHERE ativo = true ORDER BY id ASC LIMIT 1;
  END IF;

  -- 2. Determinar Receita Líquida Comercial
  -- receita_liquida = subtotal - desconto
  v_desconto_comercial := GREATEST(0.00, COALESCE(v_ped.desconto, 0.00));
  v_receita_liquida := GREATEST(0.00, COALESCE(v_ped.subtotal, 0.00) - v_desconto_comercial);

  -- Frete Subsidiado
  v_frete_base := COALESCE(v_ped.taxa_entrega_base, v_ped.taxa_entrega, 0.00);
  v_frete_cobrado := COALESCE(v_ped.taxa_entrega_cobrada, v_ped.taxa_entrega, 0.00);
  IF v_frete_base > v_frete_cobrado THEN
    v_frete_subsidiado := ROUND(v_frete_base - v_frete_cobrado, 2);
  ELSE
    v_frete_subsidiado := 0.00;
  END IF;

  -- Se existia versão anterior e estamos retificando, marcar como substituído
  IF v_existente.id IS NOT NULL THEN
    UPDATE public.pedido_custos_realizados
    SET status = 'substituido'
    WHERE id = v_existente.id;
  END IF;

  -- Inserir cabeçalho em pedido_custos_realizados (temporário com valores zerados para obter ID)
  INSERT INTO public.pedido_custos_realizados (
    pedido_id, versao, receita_liquida_snapshot, politica_id,
    politica_snapshot, status, substitui_versao, motivo_retificacao,
    calculado_por
  ) VALUES (
    p_pedido_id, v_nova_versao, v_receita_liquida, v_pol.id,
    to_jsonb(v_pol), 'finalizado',
    CASE WHEN v_existente.id IS NOT NULL THEN v_existente.versao ELSE NULL END,
    v_motivo, v_user_id
  ) RETURNING id INTO v_custo_realizado_id;

  -- 3. Insumos Efetivamente Consumidos (Frente L - pedido_consumos_lote)
  -- Se houver lotes consumidos registrados, usamos os lotes!
  IF EXISTS (SELECT 1 FROM public.pedido_consumos_lote WHERE pedido_id = p_pedido_id) THEN
    FOR v_rec IN
      SELECT
        pcl.id AS lote_consumo_id,
        pcl.ingrediente_id,
        i.nome AS ingrediente_nome,
        pcl.codigo_lote_snapshot,
        pcl.quantidade_consumida,
        pcl.unidade,
        pcl.custo_unitario_lote_snapshot,
        ROUND(pcl.quantidade_consumida * pcl.custo_unitario_lote_snapshot, 2) AS valor_insumo
      FROM public.pedido_consumos_lote pcl
      JOIN public.ingredientes i ON i.id = pcl.ingrediente_id
      WHERE pcl.pedido_id = p_pedido_id
    LOOP
      v_custo_insumos := v_custo_insumos + v_rec.valor_insumo;
      INSERT INTO public.pedido_custo_componentes (
        custo_realizado_id, pedido_id, tipo, referencia_tipo, referencia_id,
        descricao, quantidade, unidade, custo_unitario_snapshot, valor_total, detalhes
      ) VALUES (
        v_custo_realizado_id, p_pedido_id, 'ingrediente', 'lote_consumo', v_rec.lote_consumo_id,
        'Insumo: ' || v_rec.ingrediente_nome || ' (Lote: ' || v_rec.codigo_lote_snapshot || ')',
        v_rec.quantidade_consumida, v_rec.unidade, v_rec.custo_unitario_lote_snapshot, v_rec.valor_insumo,
        jsonb_build_object('ingrediente_id', v_rec.ingrediente_id, 'codigo_lote', v_rec.codigo_lote_snapshot)
      );
    END LOOP;
  ELSE
    -- Fallback para itens com cmv_total_snapshot se não houve registro em lotes
    FOR v_rec IN
      SELECT
        pi.id AS item_id,
        pi.produto_id,
        pi.produto_nome_snapshot,
        pi.quantidade,
        COALESCE(pi.cmv_unitario_snapshot, 0.00) AS cmv_unitario,
        COALESCE(pi.cmv_total_snapshot, 0.00) AS cmv_total
      FROM public.pedido_itens pi
      WHERE pi.pedido_id = p_pedido_id
    LOOP
      v_custo_insumos := v_custo_insumos + v_rec.cmv_total;
      INSERT INTO public.pedido_custo_componentes (
        custo_realizado_id, pedido_id, tipo, referencia_tipo, referencia_id,
        descricao, quantidade, unidade, custo_unitario_snapshot, valor_total, detalhes
      ) VALUES (
        v_custo_realizado_id, p_pedido_id, 'ingrediente', 'item_snapshot', v_rec.item_id,
        'Insumo estimado (Snapshot item): ' || v_rec.produto_nome_snapshot,
        v_rec.quantidade, 'un', v_rec.cmv_unitario, v_rec.cmv_total,
        jsonb_build_object('produto_id', v_rec.produto_id)
      );
    END LOOP;
  END IF;

  -- 4. Mão de Obra e Processos Atribuíveis por Item Produzido
  FOR v_rec IN
    SELECT
      pi.id AS item_id,
      pi.produto_nome_snapshot,
      pi.quantidade AS item_qtd,
      pt.etapa,
      pt.minutos_padrao,
      r.id AS recurso_id,
      r.nome AS recurso_nome,
      r.tipo AS recurso_tipo,
      r.custo_hora,
      ROUND(( (pt.minutos_padrao * pi.quantidade) / 60.0 ) * r.custo_hora, 2) AS valor_etapa
    FROM public.pedido_itens pi
    JOIN public.produto_tempos_producao pt ON pt.produto_id = pi.produto_id
    JOIN public.recursos_producao r ON r.id = pt.recurso_id
    WHERE pi.pedido_id = p_pedido_id AND r.ativo = true
  LOOP
    v_custo_mao_obra := v_custo_mao_obra + v_rec.valor_etapa;
    INSERT INTO public.pedido_custo_componentes (
      custo_realizado_id, pedido_id, tipo, referencia_tipo, referencia_id,
      descricao, quantidade, unidade, custo_unitario_snapshot, valor_total, detalhes
    ) VALUES (
      v_custo_realizado_id, p_pedido_id, 'mao_de_obra', 'recurso_producao', v_rec.recurso_id,
      'Mão de obra / Processo: ' || v_rec.etapa || ' (' || v_rec.recurso_nome || ') para ' || v_rec.produto_nome_snapshot,
      ROUND((v_rec.minutos_padrao * v_rec.item_qtd) / 60.0, 3), 'h', v_rec.custo_hora, v_rec.valor_etapa,
      jsonb_build_object('item_id', v_rec.item_id, 'minutos_total', v_rec.minutos_padrao * v_rec.item_qtd, 'custo_hora', v_rec.custo_hora)
    );
  END LOOP;

  -- 5. Embalagens e Custos Adicionais dos Itens e Opções
  -- A: Adicionais por item (POR_UNIDADE ou FIXO)
  FOR v_rec IN
    SELECT
      pi.id AS item_id,
      pi.produto_nome_snapshot,
      pi.quantidade AS item_qtd,
      ca.id AS adicional_id,
      ca.nome AS adicional_nome,
      ca.categoria,
      ca.tipo_aplicacao,
      ca.valor AS valor_unitario,
      CASE
        WHEN ca.tipo_aplicacao = 'POR_UNIDADE' THEN ROUND(ca.valor * pi.quantidade, 2)
        ELSE ROUND(ca.valor, 2)
      END AS valor_total_adic
    FROM public.pedido_itens pi
    JOIN public.produto_custos_adicionais ca ON ca.produto_id = pi.produto_id AND ca.ativo = true
    WHERE pi.pedido_id = p_pedido_id
  LOOP
    IF v_rec.categoria = 'embalagem' THEN
      v_custo_embalagem := v_custo_embalagem + v_rec.valor_total_adic;
      INSERT INTO public.pedido_custo_componentes (
        custo_realizado_id, pedido_id, tipo, referencia_tipo, referencia_id,
        descricao, quantidade, unidade, custo_unitario_snapshot, valor_total, detalhes
      ) VALUES (
        v_custo_realizado_id, p_pedido_id, 'embalagem', 'produto_custos_adicionais', v_rec.adicional_id,
        'Embalagem: ' || v_rec.adicional_nome || ' (' || v_rec.produto_nome_snapshot || ')',
        CASE WHEN v_rec.tipo_aplicacao = 'POR_UNIDADE' THEN v_rec.item_qtd ELSE 1.000 END, 'un',
        v_rec.valor_unitario, v_rec.valor_total_adic,
        jsonb_build_object('item_id', v_rec.item_id, 'tipo_aplicacao', v_rec.tipo_aplicacao)
      );
    ELSE
      v_custo_adicionais := v_custo_adicionais + v_rec.valor_total_adic;
      INSERT INTO public.pedido_custo_componentes (
        custo_realizado_id, pedido_id, tipo, referencia_tipo, referencia_id,
        descricao, quantidade, unidade, custo_unitario_snapshot, valor_total, detalhes
      ) VALUES (
        v_custo_realizado_id, p_pedido_id, 'adicional', 'produto_custos_adicionais', v_rec.adicional_id,
        'Adicional: ' || v_rec.adicional_nome || ' (' || v_rec.produto_nome_snapshot || ')',
        CASE WHEN v_rec.tipo_aplicacao = 'POR_UNIDADE' THEN v_rec.item_qtd ELSE 1.000 END, 'un',
        v_rec.valor_unitario, v_rec.valor_total_adic,
        jsonb_build_object('item_id', v_rec.item_id, 'tipo_aplicacao', v_rec.tipo_aplicacao)
      );
    END IF;
  END LOOP;

  -- B: Adicionais por Pedido Geral (produto_id IS NULL)
  FOR v_rec IN
    SELECT
      ca.id AS adicional_id,
      ca.nome AS adicional_nome,
      ca.categoria,
      ca.valor AS valor_unitario
    FROM public.produto_custos_adicionais ca
    WHERE ca.produto_id IS NULL AND ca.tipo_aplicacao = 'POR_PEDIDO' AND ca.ativo = true
  LOOP
    IF v_rec.categoria = 'embalagem' THEN
      v_custo_embalagem := v_custo_embalagem + v_rec.valor_unitario;
      INSERT INTO public.pedido_custo_componentes (
        custo_realizado_id, pedido_id, tipo, referencia_tipo, referencia_id,
        descricao, quantidade, unidade, custo_unitario_snapshot, valor_total, detalhes
      ) VALUES (
        v_custo_realizado_id, p_pedido_id, 'embalagem', 'produto_custos_adicionais', v_rec.adicional_id,
        'Embalagem Pedido Geral: ' || v_rec.adicional_nome,
        1.000, 'un', v_rec.valor_unitario, v_rec.valor_unitario,
        jsonb_build_object('tipo_aplicacao', 'POR_PEDIDO')
      );
    ELSE
      v_custo_adicionais := v_custo_adicionais + v_rec.valor_unitario;
      INSERT INTO public.pedido_custo_componentes (
        custo_realizado_id, pedido_id, tipo, referencia_tipo, referencia_id,
        descricao, quantidade, unidade, custo_unitario_snapshot, valor_total, detalhes
      ) VALUES (
        v_custo_realizado_id, p_pedido_id, 'adicional', 'produto_custos_adicionais', v_rec.adicional_id,
        'Adicional Pedido Geral: ' || v_rec.adicional_nome,
        1.000, 'un', v_rec.valor_unitario, v_rec.valor_unitario,
        jsonb_build_object('tipo_aplicacao', 'POR_PEDIDO')
      );
    END IF;
  END LOOP;

  -- 6. Frete Subsidiado (se houver subsídio bancado pela confeitaria)
  IF v_frete_subsidiado > 0 THEN
    INSERT INTO public.pedido_custo_componentes (
      custo_realizado_id, pedido_id, tipo, referencia_tipo, referencia_id,
      descricao, quantidade, unidade, custo_unitario_snapshot, valor_total, detalhes
    ) VALUES (
      v_custo_realizado_id, p_pedido_id, 'frete_subsidiado', 'pedidos', p_pedido_id,
      'Frete Subsidiado pela Loja (Taxa Base R$ ' || v_frete_base || ' - Cobrada R$ ' || v_frete_cobrado || ')',
      1.000, 'un', v_frete_subsidiado, v_frete_subsidiado,
      jsonb_build_object('frete_base', v_frete_base, 'frete_cobrado', v_frete_cobrado)
    );
  END IF;

  -- 7. Taxas Variáveis Atribuíveis (Taxa de adquirência/cartão estimada sobre receita líquida)
  IF COALESCE(v_pol.taxa_cartao_padrao_percentual, 0.00) > 0 AND v_receita_liquida > 0 THEN
    v_taxas_variaveis := ROUND(v_receita_liquida * (v_pol.taxa_cartao_padrao_percentual / 100.0), 2);
    INSERT INTO public.pedido_custo_componentes (
      custo_realizado_id, pedido_id, tipo, referencia_tipo, referencia_id,
      descricao, quantidade, unidade, custo_unitario_snapshot, valor_total, detalhes
    ) VALUES (
      v_custo_realizado_id, p_pedido_id, 'taxa', 'politicas_precificacao', v_pol.id,
      'Taxa variável estimada de transação (' || v_pol.taxa_cartao_padrao_percentual || '%)',
      1.000, 'un', v_taxas_variaveis, v_taxas_variaveis,
      jsonb_build_object('taxa_cartao_pct', v_pol.taxa_cartao_padrao_percentual)
    );
  END IF;

  -- 8. Custo Indireto Rateado (energia, depreciação geral rateada sobre o subtotal)
  IF COALESCE(v_pol.custo_indireto_padrao_percentual, 0.00) > 0 AND v_receita_liquida > 0 THEN
    v_custo_indireto := ROUND(v_receita_liquida * (v_pol.custo_indireto_padrao_percentual / 100.0), 2);
    INSERT INTO public.pedido_custo_componentes (
      custo_realizado_id, pedido_id, tipo, referencia_tipo, referencia_id,
      descricao, quantidade, unidade, custo_unitario_snapshot, valor_total, detalhes
    ) VALUES (
      v_custo_realizado_id, p_pedido_id, 'indireto', 'politicas_precificacao', v_pol.id,
      'Custo indireto rateado fabril (' || v_pol.custo_indireto_padrao_percentual || '%)',
      1.000, 'un', v_custo_indireto, v_custo_indireto,
      jsonb_build_object('custo_indireto_pct', v_pol.custo_indireto_padrao_percentual)
    );
  END IF;

  -- 9. Fechamento Matemático dos Totais
  v_custo_atribuivel_total := v_custo_insumos + v_custo_embalagem + v_custo_mao_obra +
                              v_custo_adicionais + v_frete_subsidiado + v_taxas_variaveis + v_custo_indireto;

  v_margem_valor := ROUND(v_receita_liquida - v_custo_atribuivel_total, 2);
  IF v_receita_liquida > 0 THEN
    v_margem_pct := ROUND((v_margem_valor / v_receita_liquida) * 100.0, 2);
  ELSE
    v_margem_pct := 0.00;
  END IF;

  -- Atualizar registro do cabeçalho com os valores consolidados exatos
  PERFORM set_config('lunoca.allow_custo_real_mutation', 'true', true);
  UPDATE public.pedido_custos_realizados
  SET
    custo_ingredientes_real = v_custo_insumos,
    custo_embalagem = v_custo_embalagem,
    custo_mao_de_obra = v_custo_mao_obra,
    custo_adicionais = v_custo_adicionais,
    custo_indireto_rateado = v_custo_indireto,
    taxas_variaveis_atribuiveis = v_taxas_variaveis,
    frete_subsidiado = v_frete_subsidiado,
    custo_atribuivel_total = v_custo_atribuivel_total,
    margem_contribuicao_valor = v_margem_valor,
    margem_contribuicao_percentual = v_margem_pct,
    calculado_em = NOW()
  WHERE id = v_custo_realizado_id;
  PERFORM set_config('lunoca.allow_custo_real_mutation', 'false', true);

  RETURN jsonb_build_object(
    'success', true,
    'custo_realizado_id', v_custo_realizado_id,
    'pedido_id', p_pedido_id,
    'versao', v_nova_versao,
    'status', 'finalizado',
    'receita_liquida', v_receita_liquida,
    'custo_ingredientes_real', v_custo_insumos,
    'custo_embalagem', v_custo_embalagem,
    'custo_mao_de_obra', v_custo_mao_obra,
    'custo_adicionais', v_custo_adicionais,
    'frete_subsidiado', v_frete_subsidiado,
    'custo_indireto_rateado', v_custo_indireto,
    'taxas_variaveis_atribuiveis', v_taxas_variaveis,
    'custo_atribuivel_total', v_custo_atribuivel_total,
    'margem_contribuicao_valor', v_margem_valor,
    'margem_contribuicao_percentual', v_margem_pct,
    'calculado_em', NOW()
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.calcular_custo_real_pedido_admin FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.calcular_custo_real_pedido_admin TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 11. RPC OBTER_MARGEM_PEDIDO_ADMIN
-- ------------------------------------------------------------------------------
-- Consulta analítica da margem e componentes de um pedido (exclusiva Admin).
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.obter_margem_pedido_admin(p_pedido_id BIGINT)
RETURNS JSONB AS $$
DECLARE
  v_cr RECORD;
  v_componentes JSONB;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PERMISSION_DENIED',
      'error', 'Apenas administradores podem visualizar margens e custos de pedidos.'
    );
  END IF;

  SELECT * INTO v_cr
  FROM public.pedido_custos_realizados
  WHERE pedido_id = p_pedido_id AND status = 'finalizado'
  ORDER BY versao DESC LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'COSTS_NOT_CALCULATED',
      'error', 'Os custos e margens deste pedido ainda não foram consolidados. Execute o cálculo após a produção.'
    );
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY c.id ASC), '[]'::jsonb)
  INTO v_componentes
  FROM public.pedido_custo_componentes c
  WHERE c.custo_realizado_id = v_cr.id;

  RETURN jsonb_build_object(
    'success', true,
    'custo_realizado_id', v_cr.id,
    'pedido_id', p_pedido_id,
    'versao', v_cr.versao,
    'status', v_cr.status,
    'receita_liquida', v_cr.receita_liquida_snapshot,
    'custo_ingredientes_real', v_cr.custo_ingredientes_real,
    'custo_embalagem', v_cr.custo_embalagem,
    'custo_mao_de_obra', v_cr.custo_mao_de_obra,
    'custo_adicionais', v_cr.custo_adicionais,
    'frete_subsidiado', v_cr.frete_subsidiado,
    'custo_indireto_rateado', v_cr.custo_indireto_rateado,
    'taxas_variaveis_atribuiveis', v_cr.taxas_variaveis_atribuiveis,
    'custo_atribuivel_total', v_cr.custo_atribuivel_total,
    'margem_contribuicao_valor', v_cr.margem_contribuicao_valor,
    'margem_contribuicao_percentual', v_cr.margem_contribuicao_percentual,
    'calculado_em', v_cr.calculado_em,
    'motivo_retificacao', v_cr.motivo_retificacao,
    'componentes', v_componentes
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_margem_pedido_admin FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_margem_pedido_admin TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 12. RPC OBTER_MARGENS_PRODUTOS_ADMIN
-- ------------------------------------------------------------------------------
-- Visão consolidada de margem estimada por produto do catálogo para gestão de preços.
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.obter_margens_produtos_admin(
  p_categoria TEXT DEFAULT NULL,
  p_limite INT DEFAULT 50
)
RETURNS JSONB AS $$
DECLARE
  v_itens JSONB;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PERMISSION_DENIED',
      'error', 'Apenas administradores podem consultar margens consolidadas de produtos.'
    );
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(r)::jsonb ORDER BY r.margem_percentual ASC), '[]'::jsonb)
  INTO v_itens
  FROM (
    SELECT
      p.id AS produto_id,
      p.nome AS produto_nome,
      p.preco AS preco_venda,
      p.ativo,
      COALESCE(ROUND(SUM(pi.quantidade * COALESCE(NULLIF(s.custo_medio_ponderado, 0), i.custo_unitario, 0)), 2), 0.00) AS custo_insumos_cmp,
      COALESCE(tempos.custo_mo, 0.00) AS custo_mao_obra,
      COALESCE(adics.custo_adicionais, 0.00) AS custo_embalagens_adicionais,
      ROUND(
        COALESCE(SUM(pi.quantidade * COALESCE(NULLIF(s.custo_medio_ponderado, 0), i.custo_unitario, 0)), 0.00) +
        COALESCE(tempos.custo_mo, 0.00) +
        COALESCE(adics.custo_adicionais, 0.00)
      , 2) AS custo_direto_total,
      CASE
        WHEN p.preco > 0 THEN ROUND(
          (p.preco - (
            COALESCE(SUM(pi.quantidade * COALESCE(NULLIF(s.custo_medio_ponderado, 0), i.custo_unitario, 0)), 0.00) +
            COALESCE(tempos.custo_mo, 0.00) +
            COALESCE(adics.custo_adicionais, 0.00)
          ))
        , 2)
        ELSE 0.00
      END AS margem_bruta_valor,
      CASE
        WHEN p.preco > 0 THEN ROUND(
          ((p.preco - (
            COALESCE(SUM(pi.quantidade * COALESCE(NULLIF(s.custo_medio_ponderado, 0), i.custo_unitario, 0)), 0.00) +
            COALESCE(tempos.custo_mo, 0.00) +
            COALESCE(adics.custo_adicionais, 0.00)
          )) / p.preco) * 100.0
        , 2)
        ELSE 0.00
      END AS margem_percentual
    FROM public.produtos p
    LEFT JOIN public.produto_ingredientes pi ON pi.produto_id = p.id
    LEFT JOIN public.ingredientes i ON i.id = pi.ingrediente_id
    LEFT JOIN public.ingrediente_saldos s ON s.ingrediente_id = i.id
    LEFT JOIN (
      SELECT pt.produto_id, ROUND(SUM((pt.minutos_padrao / 60.0) * r.custo_hora), 2) AS custo_mo
      FROM public.produto_tempos_producao pt
      JOIN public.recursos_producao r ON r.id = pt.recurso_id AND r.ativo = true
      GROUP BY pt.produto_id
    ) tempos ON tempos.produto_id = p.id
    LEFT JOIN (
      SELECT ca.produto_id, ROUND(SUM(ca.valor), 2) AS custo_adicionais
      FROM public.produto_custos_adicionais ca
      WHERE ca.ativo = true AND ca.produto_id IS NOT NULL
      GROUP BY ca.produto_id
    ) adics ON adics.produto_id = p.id
    GROUP BY p.id, p.nome, p.preco, p.ativo, tempos.custo_mo, adics.custo_adicionais
    LIMIT GREATEST(1, LEAST(200, p_limite))
  ) r;

  RETURN jsonb_build_object('success', true, 'produtos', v_itens);
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_margens_produtos_admin FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_margens_produtos_admin TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 13. RPCs DE CADASTRO E GESTÃO FABRIL (ADMIN)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.salvar_recurso_producao_admin(
  p_id BIGINT DEFAULT NULL,
  p_nome TEXT DEFAULT NULL,
  p_tipo TEXT DEFAULT 'mao_de_obra',
  p_custo_hora NUMERIC DEFAULT 0.00,
  p_descricao TEXT DEFAULT NULL,
  p_ativo BOOLEAN DEFAULT true
)
RETURNS JSONB AS $$
DECLARE
  v_rec_id BIGINT;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas administradores podem gerenciar recursos fabris.');
  END IF;

  IF p_nome IS NULL OR length(trim(p_nome)) < 2 THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_RESOURCE_NAME', 'error', 'Informe um nome válido para o recurso.');
  END IF;

  IF p_custo_hora < 0 THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_HOURLY_COST', 'error', 'O custo por hora não pode ser negativo.');
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO public.recursos_producao (nome, tipo, custo_hora, descricao, ativo)
    VALUES (trim(p_nome), p_tipo, p_custo_hora, p_descricao, p_ativo)
    RETURNING id INTO v_rec_id;
  ELSE
    UPDATE public.recursos_producao
    SET nome = trim(p_nome), tipo = p_tipo, custo_hora = p_custo_hora, descricao = p_descricao, ativo = p_ativo, updated_at = NOW()
    WHERE id = p_id
    RETURNING id INTO v_rec_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'recurso_id', v_rec_id);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.salvar_recurso_producao_admin FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.salvar_recurso_producao_admin TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.salvar_tempo_producao_produto_admin(
  p_produto_id BIGINT,
  p_etapa TEXT,
  p_minutos_padrao NUMERIC,
  p_recurso_id BIGINT,
  p_observacoes TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_tempo_id BIGINT;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas administradores podem configurar tempos de produção.');
  END IF;

  IF p_minutos_padrao <= 0 THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_MINUTES', 'error', 'A duração em minutos deve ser maior que zero.');
  END IF;

  INSERT INTO public.produto_tempos_producao (produto_id, etapa, minutos_padrao, recurso_id, observacoes)
  VALUES (p_produto_id, p_etapa, p_minutos_padrao, p_recurso_id, p_observacoes)
  ON CONFLICT (produto_id, etapa, recurso_id)
  DO UPDATE SET minutos_padrao = EXCLUDED.minutos_padrao, observacoes = EXCLUDED.observacoes, updated_at = NOW()
  RETURNING id INTO v_tempo_id;

  RETURN jsonb_build_object('success', true, 'tempo_id', v_tempo_id);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.salvar_tempo_producao_produto_admin FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.salvar_tempo_producao_produto_admin TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.salvar_custo_adicional_produto_admin(
  p_id BIGINT DEFAULT NULL,
  p_produto_id BIGINT DEFAULT NULL,
  p_produto_opcao_id BIGINT DEFAULT NULL,
  p_nome TEXT DEFAULT NULL,
  p_categoria TEXT DEFAULT 'embalagem',
  p_tipo_aplicacao TEXT DEFAULT 'POR_UNIDADE',
  p_valor NUMERIC DEFAULT 0.00,
  p_ativo BOOLEAN DEFAULT true
)
RETURNS JSONB AS $$
DECLARE
  v_adic_id BIGINT;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas administradores podem gerenciar custos adicionais e embalagens.');
  END IF;

  IF p_nome IS NULL OR length(trim(p_nome)) < 2 THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_NAME', 'error', 'Nome do custo adicional/embalagem inválido.');
  END IF;

  IF p_valor < 0 THEN
    RETURN jsonb_build_object('success', false, 'code', 'INVALID_VALUE', 'error', 'O valor não pode ser negativo.');
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO public.produto_custos_adicionais (
      produto_id, produto_opcao_id, nome, categoria, tipo_aplicacao, valor, ativo
    ) VALUES (
      p_produto_id, p_produto_opcao_id, trim(p_nome), p_categoria, p_tipo_aplicacao, p_valor, p_ativo
    ) RETURNING id INTO v_adic_id;
  ELSE
    UPDATE public.produto_custos_adicionais
    SET produto_id = p_produto_id, produto_opcao_id = p_produto_opcao_id, nome = trim(p_nome),
        categoria = p_categoria, tipo_aplicacao = p_tipo_aplicacao, valor = p_valor, ativo = p_ativo, updated_at = NOW()
    WHERE id = p_id
    RETURNING id INTO v_adic_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'custo_adicional_id', v_adic_id);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.salvar_custo_adicional_produto_admin FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.salvar_custo_adicional_produto_admin TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.salvar_politica_precificacao_admin(
  p_id BIGINT DEFAULT NULL,
  p_nome TEXT DEFAULT 'Padrão Confeitaria',
  p_margem_alvo NUMERIC DEFAULT 40.00,
  p_taxa_cartao NUMERIC DEFAULT 3.99,
  p_impostos NUMERIC DEFAULT 6.00,
  p_comissao NUMERIC DEFAULT 0.00,
  p_custo_indireto NUMERIC DEFAULT 5.00,
  p_padrao BOOLEAN DEFAULT true
)
RETURNS JSONB AS $$
DECLARE
  v_pol_id BIGINT;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas administradores podem configurar políticas de precificação.');
  END IF;

  IF p_padrao THEN
    UPDATE public.politicas_precificacao SET padrao = false WHERE padrao = true;
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO public.politicas_precificacao (
      nome, margem_alvo_padrao_percentual, taxa_cartao_padrao_percentual,
      impostos_padrao_percentual, comissao_padrao_percentual, custo_indireto_padrao_percentual, padrao
    ) VALUES (
      trim(p_nome), p_margem_alvo, p_taxa_cartao, p_impostos, p_comissao, p_custo_indireto, p_padrao
    ) RETURNING id INTO v_pol_id;
  ELSE
    UPDATE public.politicas_precificacao
    SET nome = trim(p_nome), margem_alvo_padrao_percentual = p_margem_alvo,
        taxa_cartao_padrao_percentual = p_taxa_cartao, impostos_padrao_percentual = p_impostos,
        comissao_padrao_percentual = p_comissao, custo_indireto_padrao_percentual = p_custo_indireto,
        padrao = p_padrao, updated_at = NOW()
    WHERE id = p_id
    RETURNING id INTO v_pol_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'politica_id', v_pol_id);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.salvar_politica_precificacao_admin FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.salvar_politica_precificacao_admin TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 14. RPC OBTER_ENGENHARIA_CUSTOS_PRODUTO_ADMIN
-- ------------------------------------------------------------------------------
-- Retorna a ficha técnica fabril completa do produto (insumos CMP, tempos e adicionais).
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.obter_engenharia_custos_produto_admin(p_produto_id BIGINT)
RETURNS JSONB AS $$
DECLARE
  v_prod RECORD;
  v_tempos JSONB;
  v_adicionais JSONB;
  v_insumos JSONB;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object('success', false, 'code', 'PERMISSION_DENIED', 'error', 'Apenas administradores podem consultar engenharia de custos de produtos.');
  END IF;

  SELECT * INTO v_prod FROM public.produtos WHERE id = p_produto_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'PRODUCT_NOT_FOUND', 'error', 'Produto não encontrado.');
  END IF;

  -- Insumos com CMP
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'ingrediente_id', i.id,
    'nome', i.nome,
    'quantidade', pi.quantidade,
    'unidade', i.unidade,
    'custo_unitario_teorico', i.custo_unitario,
    'custo_medio_ponderado', COALESCE(s.custo_medio_ponderado, i.custo_unitario),
    'custo_cmp_total', ROUND(pi.quantidade * COALESCE(NULLIF(s.custo_medio_ponderado, 0), i.custo_unitario, 0), 2)
  )), '[]'::jsonb)
  INTO v_insumos
  FROM public.produto_ingredientes pi
  JOIN public.ingredientes i ON i.id = pi.ingrediente_id
  LEFT JOIN public.ingrediente_saldos s ON s.ingrediente_id = i.id
  WHERE pi.produto_id = p_produto_id;

  -- Tempos
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', pt.id,
    'etapa', pt.etapa,
    'minutos_padrao', pt.minutos_padrao,
    'recurso_id', r.id,
    'recurso_nome', r.nome,
    'recurso_tipo', r.tipo,
    'custo_hora', r.custo_hora,
    'custo_estimado', ROUND((pt.minutos_padrao / 60.0) * r.custo_hora, 2)
  )), '[]'::jsonb)
  INTO v_tempos
  FROM public.produto_tempos_producao pt
  JOIN public.recursos_producao r ON r.id = pt.recurso_id
  WHERE pt.produto_id = p_produto_id;

  -- Adicionais / Embalagens
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', ca.id,
    'nome', ca.nome,
    'categoria', ca.categoria,
    'tipo_aplicacao', ca.tipo_aplicacao,
    'valor', ca.valor,
    'ativo', ca.ativo
  )), '[]'::jsonb)
  INTO v_adicionais
  FROM public.produto_custos_adicionais ca
  WHERE ca.produto_id = p_produto_id;

  RETURN jsonb_build_object(
    'success', true,
    'produto_id', p_produto_id,
    'produto_nome', v_prod.nome,
    'preco_atual', v_prod.preco,
    'insumos', v_insumos,
    'tempos', v_tempos,
    'adicionais', v_adicionais
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_engenharia_custos_produto_admin FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_engenharia_custos_produto_admin TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 15. RPC OBTER_DASHBOARD_MARGENS_ADMIN
-- ------------------------------------------------------------------------------
-- Dashboard gerencial de custos e margens de contribuição (Admin only).
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.obter_dashboard_margens_admin(
  p_data_inicio DATE DEFAULT NULL,
  p_data_fim DATE DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_inicio DATE := COALESCE(p_data_inicio, (NOW() AT TIME ZONE 'America/Fortaleza')::DATE - INTERVAL '30 days');
  v_fim DATE := COALESCE(p_data_fim, (NOW() AT TIME ZONE 'America/Fortaleza')::DATE);
  v_resumo RECORD;
  v_top_produtos JSONB;
  v_pedidos_alerta JSONB;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object(
      'success', false,
      'code', 'PERMISSION_DENIED',
      'error', 'Apenas administradores podem visualizar o dashboard de margens.'
    );
  END IF;

  -- Resumo agregado de margens dos pedidos calculados no período
  SELECT
    COUNT(cr.id) AS total_pedidos_calculados,
    COALESCE(SUM(cr.receita_liquida_snapshot), 0.00) AS receita_liquida_total,
    COALESCE(SUM(cr.custo_atribuivel_total), 0.00) AS custo_atribuivel_total,
    COALESCE(SUM(cr.margem_contribuicao_valor), 0.00) AS margem_contribuicao_total,
    COALESCE(SUM(cr.frete_subsidiado), 0.00) AS frete_subsidiado_total,
    CASE
      WHEN SUM(cr.receita_liquida_snapshot) > 0 THEN
        ROUND((SUM(cr.margem_contribuicao_valor) / SUM(cr.receita_liquida_snapshot)) * 100.0, 2)
      ELSE 0.00
    END AS margem_media_percentual
  INTO v_resumo
  FROM public.pedido_custos_realizados cr
  JOIN public.pedidos p ON p.id = cr.pedido_id
  WHERE cr.status = 'finalizado'
    AND (cr.calculado_em AT TIME ZONE 'America/Fortaleza')::DATE BETWEEN v_inicio AND v_fim;

  -- Pedidos com margem negativa ou abaixo de 20%
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'pedido_id', p.id,
    'cliente_nome', p.nome_cliente,
    'receita_liquida', cr.receita_liquida_snapshot,
    'custo_total', cr.custo_atribuivel_total,
    'margem_valor', cr.margem_contribuicao_valor,
    'margem_pct', cr.margem_contribuicao_percentual,
    'calculado_em', cr.calculado_em
  )), '[]'::jsonb)
  INTO v_pedidos_alerta
  FROM public.pedido_custos_realizados cr
  JOIN public.pedidos p ON p.id = cr.pedido_id
  WHERE cr.status = 'finalizado'
    AND (cr.calculado_em AT TIME ZONE 'America/Fortaleza')::DATE BETWEEN v_inicio AND v_fim
    AND (cr.margem_contribuicao_valor < 0 OR cr.margem_contribuicao_percentual < 20.00)
  LIMIT 20;

  RETURN jsonb_build_object(
    'success', true,
    'periodo', jsonb_build_object('inicio', v_inicio, 'fim', v_fim),
    'resumo', jsonb_build_object(
      'total_pedidos_calculados', v_resumo.total_pedidos_calculados,
      'receita_liquida_total', v_resumo.receita_liquida_total,
      'custo_atribuivel_total', v_resumo.custo_atribuivel_total,
      'margem_contribuicao_total', v_resumo.margem_contribuicao_total,
      'frete_subsidiado_total', v_resumo.frete_subsidiado_total,
      'margem_media_percentual', v_resumo.margem_media_percentual
    ),
    'pedidos_alerta', v_pedidos_alerta
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_dashboard_margens_admin FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_dashboard_margens_admin TO authenticated, service_role;


-- ==========================================================================
-- >>> MIGRATION 029_alertas_auditoria_healthcheck_global.sql
-- ==========================================================================

-- ==============================================================================
-- MIGRATION 029: ALERTAS OPERACIONAIS PROATIVOS, AUDITORIA AVANÇADA & HEALTH-CHECK GLOBAL
-- ==============================================================================
-- 1. ESTRUTURAS DE ALERTAS: alertas_configuracoes, alertas_operacionais e
--    alertas_reconhecimentos com desacoplamento estrito (alertas como projeção).
-- 2. TRILHA DE AUDITORIA OPERACIONAL: auditoria_operacional_eventos append-only
--    imutável (rejeita UPDATE e DELETE físicos com erro 42501).
-- 3. TRIGGERS AUTOMÁTICOS DE AUDITORIA: monitoram alterações em catálogo (preço/status),
--    ajustes manuais de ingredientes/lotes, políticas de precificação e configurações.
-- 4. MOTOR DE ALERTAS DINÂMICO: detecção de ruptura de insumos, lotes vencidos,
--    risco de validade FEFO, risco de atraso na bancada, qualidade retida e margem crítica.
-- 5. SANITIZAÇÃO DE OPERADOR: visão de bancada estritamente desprovida de dados financeiros,
--    custos, margens, markups e markdowns.
-- 6. HEALTH-CHECK GLOBAL: diagnóstico sistêmico estritamente read-only em 5 eixos
--    (saldos vs lotes, financeiro vs pagamentos, integridade de pedidos, FEFO e margens).
-- 7. ZERO EFEITO FINANCEIRO: alertas e auditoria são observacionais; zero efeito
--    em financeiro_lancamentos ou pedido_pagamentos (caixa e DRE intocados).
-- 8. RBAC FAIL-CLOSED: health-check global, auditoria e margens restritos a Administradores.
-- ==============================================================================

-- ------------------------------------------------------------------------------
-- 1. CONFIGURAÇÕES GLOBAIS DE ALERTAS OPERACIONAIS
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.alertas_configuracoes (
  id SMALLINT PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  dias_aviso_validade INTEGER NOT NULL DEFAULT 7 CHECK (dias_aviso_validade >= 1),
  margem_minima_alvo NUMERIC(5,2) NOT NULL DEFAULT 30.00 CHECK (margem_minima_alvo >= 0.00 AND margem_minima_alvo <= 100.00),
  antecedencia_atraso_minutos INTEGER NOT NULL DEFAULT 120 CHECK (antecedencia_atraso_minutos >= 15),
  ativo BOOLEAN NOT NULL DEFAULT true,
  atualizado_em TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Seed de inicialização único
INSERT INTO public.alertas_configuracoes (id, dias_aviso_validade, margem_minima_alvo, antecedencia_atraso_minutos, ativo)
VALUES (1, 7, 30.00, 120, true)
ON CONFLICT (id) DO NOTHING;

-- ------------------------------------------------------------------------------
-- 2. TABELA DE ALERTAS OPERACIONAIS (FATO OPERACIONAL / PROJEÇÃO)
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.alertas_operacionais (
  id BIGSERIAL PRIMARY KEY,
  tipo_alerta TEXT NOT NULL CHECK (tipo_alerta IN (
    'RUPTURA_ESTOQUE',
    'LOTE_VENCIMENTO',
    'LOTE_VENCIDO',
    'ATRASO_PEDIDO',
    'MARGEM_CRITICA',
    'QUALIDADE_RETIDA',
    'DIVERGENCIA_INVENTARIO',
    'SISTEMICO'
  )),
  nivel TEXT NOT NULL CHECK (nivel IN ('CRITICO', 'ATENCAO', 'OPERACIONAL', 'INFO')),
  origem_tabela TEXT,
  origem_id TEXT,
  titulo TEXT NOT NULL,
  descricao TEXT NOT NULL,
  dados_contexto JSONB NOT NULL DEFAULT '{}'::jsonb,
  status TEXT NOT NULL DEFAULT 'ATIVO' CHECK (status IN ('ATIVO', 'RECONHECIDO', 'RESOLVIDO')),
  criado_em TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  atualizado_em TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  resolvido_em TIMESTAMPTZ,
  CONSTRAINT uq_alerta_origem_tipo UNIQUE (tipo_alerta, origem_tabela, origem_id)
);

CREATE INDEX IF NOT EXISTS idx_alertas_op_status ON public.alertas_operacionais(status);
CREATE INDEX IF NOT EXISTS idx_alertas_op_nivel ON public.alertas_operacionais(nivel);
CREATE INDEX IF NOT EXISTS idx_alertas_op_tipo ON public.alertas_operacionais(tipo_alerta);
CREATE INDEX IF NOT EXISTS idx_alertas_op_criado_em ON public.alertas_operacionais(criado_em DESC);

-- ------------------------------------------------------------------------------
-- 3. TABELA DE RECONHECIMENTOS DE ALERTAS (COMPORTAMENTO HUMANO AUDITÁVEL)
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.alertas_reconhecimentos (
  id BIGSERIAL PRIMARY KEY,
  alerta_id BIGINT NOT NULL REFERENCES public.alertas_operacionais(id) ON DELETE CASCADE,
  usuario_id UUID NOT NULL REFERENCES auth.users(id),
  usuario_nome TEXT,
  acao TEXT NOT NULL DEFAULT 'RECONHECER',
  observacao TEXT,
  criado_em TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_alerta_reconhecimento_usuario UNIQUE (alerta_id, usuario_id)
);

CREATE INDEX IF NOT EXISTS idx_alertas_rec_alerta ON public.alertas_reconhecimentos(alerta_id);
CREATE INDEX IF NOT EXISTS idx_alertas_rec_usuario ON public.alertas_reconhecimentos(usuario_id);

-- ------------------------------------------------------------------------------
-- 4. TRILHA DE AUDITORIA OPERACIONAL AVANÇADA (APPEND-ONLY IMUTÁVEL)
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.auditoria_operacional_eventos (
  id BIGSERIAL PRIMARY KEY,
  evento_tipo TEXT NOT NULL,
  entidade TEXT NOT NULL,
  entidade_id TEXT NOT NULL,
  antes JSONB,
  depois JSONB,
  usuario_id UUID,
  origem TEXT NOT NULL DEFAULT 'SISTEMA',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_audit_op_entidade ON public.auditoria_operacional_eventos(entidade, entidade_id);
CREATE INDEX IF NOT EXISTS idx_audit_op_evento ON public.auditoria_operacional_eventos(evento_tipo);
CREATE INDEX IF NOT EXISTS idx_audit_op_created_at ON public.auditoria_operacional_eventos(created_at DESC);

-- Trigger de Imutabilidade Estrita em auditoria_operacional_eventos
CREATE OR REPLACE FUNCTION public._bloquear_mutacao_auditoria_operacional()
RETURNS TRIGGER AS $$
BEGIN
  RAISE EXCEPTION 'AUDITORIA_APPEND_ONLY: Registros da trilha de auditoria são estritamente imutáveis e não podem ser alterados ou excluídos.'
    USING ERRCODE = '42501';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_bloquear_mutacao_auditoria_operacional ON public.auditoria_operacional_eventos;
CREATE TRIGGER trg_bloquear_mutacao_auditoria_operacional
  BEFORE UPDATE OR DELETE ON public.auditoria_operacional_eventos
  FOR EACH ROW
  EXECUTE FUNCTION public._bloquear_mutacao_auditoria_operacional();

-- ------------------------------------------------------------------------------
-- 5. TRIGGERS AUTOMÁTICOS DE AUDITORIA OPERACIONAL
-- ------------------------------------------------------------------------------

-- 5.1 Auditoria de alteração de preço e status em produtos
CREATE OR REPLACE FUNCTION public._audit_produtos_mutacao()
RETURNS TRIGGER AS $$
DECLARE
  v_uid UUID;
BEGIN
  v_uid := auth.uid();
  IF TG_OP = 'UPDATE' THEN
    IF (OLD.preco IS DISTINCT FROM NEW.preco) OR (OLD.ativo IS DISTINCT FROM NEW.ativo) THEN
      INSERT INTO public.auditoria_operacional_eventos (
        evento_tipo, entidade, entidade_id, antes, depois, usuario_id, origem
      ) VALUES (
        'ALTERACAO_CATALOGO_PRODUTO',
        'produtos',
        NEW.id::TEXT,
        jsonb_build_object('preco', OLD.preco, 'ativo', OLD.ativo, 'nome', OLD.nome),
        jsonb_build_object('preco', NEW.preco, 'ativo', NEW.ativo, 'nome', NEW.nome),
        v_uid,
        'TRIGGER_PRODUTOS'
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

DROP TRIGGER IF EXISTS trg_audit_produtos_mutacao ON public.produtos;
CREATE TRIGGER trg_audit_produtos_mutacao
  AFTER UPDATE ON public.produtos
  FOR EACH ROW
  EXECUTE FUNCTION public._audit_produtos_mutacao();

-- 5.2 Auditoria de alteração em bloqueio de qualidade de lotes
CREATE OR REPLACE FUNCTION public._audit_ingrediente_lotes_mutacao()
RETURNS TRIGGER AS $$
DECLARE
  v_uid UUID;
BEGIN
  v_uid := auth.uid();
  IF TG_OP = 'UPDATE' THEN
    IF (OLD.bloqueado_qualidade IS DISTINCT FROM NEW.bloqueado_qualidade) OR
       (OLD.motivo_bloqueio IS DISTINCT FROM NEW.motivo_bloqueio) THEN
      INSERT INTO public.auditoria_operacional_eventos (
        evento_tipo, entidade, entidade_id, antes, depois, usuario_id, origem
      ) VALUES (
        'ALTERACAO_BLOQUEIO_LOTE',
        'ingrediente_lotes',
        NEW.id::TEXT,
        jsonb_build_object('bloqueado', OLD.bloqueado_qualidade, 'motivo', OLD.motivo_bloqueio, 'lote', OLD.codigo_lote),
        jsonb_build_object('bloqueado', NEW.bloqueado_qualidade, 'motivo', NEW.motivo_bloqueio, 'lote', NEW.codigo_lote),
        v_uid,
        'TRIGGER_LOTES'
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

DROP TRIGGER IF EXISTS trg_audit_ingrediente_lotes_mutacao ON public.ingrediente_lotes;
CREATE TRIGGER trg_audit_ingrediente_lotes_mutacao
  AFTER UPDATE ON public.ingrediente_lotes
  FOR EACH ROW
  EXECUTE FUNCTION public._audit_ingrediente_lotes_mutacao();

-- 5.3 Auditoria de alteração de políticas de precificação
CREATE OR REPLACE FUNCTION public._audit_politicas_precificacao_mutacao()
RETURNS TRIGGER AS $$
DECLARE
  v_uid UUID;
BEGIN
  v_uid := auth.uid();
  IF TG_OP = 'UPDATE' THEN
    INSERT INTO public.auditoria_operacional_eventos (
      evento_tipo, entidade, entidade_id, antes, depois, usuario_id, origem
    ) VALUES (
      'ALTERACAO_POLITICA_PRECIFICACAO',
      'politicas_precificacao',
      NEW.id::TEXT,
      to_jsonb(OLD),
      to_jsonb(NEW),
      v_uid,
      'TRIGGER_POLITICAS'
    );
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

DROP TRIGGER IF EXISTS trg_audit_politicas_precificacao_mutacao ON public.politicas_precificacao;
CREATE TRIGGER trg_audit_politicas_precificacao_mutacao
  AFTER UPDATE ON public.politicas_precificacao
  FOR EACH ROW
  EXECUTE FUNCTION public._audit_politicas_precificacao_mutacao();

-- ------------------------------------------------------------------------------
-- 6. RPC: PROCESSAMENTO AUTÔNOMO PROATIVO DE ALERTAS OPERACIONAIS (WORKER/CRON)
-- ------------------------------------------------------------------------------
-- Executada de forma autônoma e periódica por crons ou trabalhadores em background,
-- materializando e resolvendo alertas mesmo sem qualquer usuário com o painel aberto.
CREATE OR REPLACE FUNCTION public.processar_alertas_operacionais()
RETURNS JSONB AS $$
DECLARE
  v_cfg RECORD;
  v_resolvidos INT := 0;
  v_total_ativos INT := 0;
BEGIN
  -- Obter configurações ativas
  SELECT * INTO v_cfg FROM public.alertas_configuracoes WHERE id = 1;
  IF NOT FOUND THEN
    v_cfg.dias_aviso_validade := 7;
    v_cfg.margem_minima_alvo := 30.00;
    v_cfg.antecedencia_atraso_minutos := 120;
    v_cfg.ativo := true;
  END IF;

  -- 1. Detecção: RUPTURA_ESTOQUE (insumos com estoque atual <= estoque mínimo)
  INSERT INTO public.alertas_operacionais (tipo_alerta, nivel, origem_tabela, origem_id, titulo, descricao, dados_contexto, status)
  SELECT
    'RUPTURA_ESTOQUE',
    CASE WHEN COALESCE(s.saldo_atual, i.estoque_qtd, 0) <= 0 THEN 'CRITICO' ELSE 'OPERACIONAL' END,
    'ingredientes',
    i.id::TEXT,
    'Ruptura de Estoque: ' || i.nome,
    'Estoque atual (' || COALESCE(s.saldo_atual, i.estoque_qtd, 0) || ' ' || i.unidade || ') está abaixo ou no nível mínimo configurado (' || i.estoque_minimo || ' ' || i.unidade || ').',
    jsonb_build_object(
      'ingrediente_id', i.id,
      'nome', i.nome,
      'saldo_atual', COALESCE(s.saldo_atual, i.estoque_qtd, 0),
      'estoque_minimo', i.estoque_minimo,
      'unidade', i.unidade
    ),
    'ATIVO'
  FROM public.ingredientes i
  LEFT JOIN public.ingrediente_saldos s ON s.ingrediente_id = i.id
  WHERE i.ativo = true
    AND COALESCE(s.saldo_atual, i.estoque_qtd, 0) <= i.estoque_minimo
  ON CONFLICT (tipo_alerta, origem_tabela, origem_id)
  DO UPDATE SET
    nivel = EXCLUDED.nivel,
    descricao = EXCLUDED.descricao,
    dados_contexto = EXCLUDED.dados_contexto,
    status = CASE WHEN public.alertas_operacionais.status = 'RESOLVIDO' THEN 'ATIVO' ELSE public.alertas_operacionais.status END,
    resolvido_em = CASE WHEN public.alertas_operacionais.status = 'RESOLVIDO' THEN NULL ELSE public.alertas_operacionais.resolvido_em END,
    atualizado_em = NOW();

  -- 2. Detecção: LOTE_VENCIDO (lotes vencidos ainda com saldo físico positivo)
  INSERT INTO public.alertas_operacionais (tipo_alerta, nivel, origem_tabela, origem_id, titulo, descricao, dados_contexto, status)
  SELECT
    'LOTE_VENCIDO',
    'CRITICO',
    'ingrediente_lotes',
    l.id::TEXT,
    'Lote Vencido com Saldo: ' || l.codigo_lote,
    'Lote ' || l.codigo_lote || ' de ' || i.nome || ' venceu em ' || to_char(l.data_validade, 'DD/MM/YYYY') || ' e ainda possui saldo de ' || l.quantidade_atual || ' ' || i.unidade || '.',
    jsonb_build_object(
      'lote_id', l.id,
      'codigo_lote', l.codigo_lote,
      'ingrediente_id', i.id,
      'ingrediente_nome', i.nome,
      'quantidade_atual', l.quantidade_atual,
      'data_validade', l.data_validade,
      'dias_vencido', (CURRENT_DATE - l.data_validade)
    ),
    'ATIVO'
  FROM public.ingrediente_lotes l
  JOIN public.ingredientes i ON i.id = l.ingrediente_id
  WHERE l.quantidade_atual > 0
    AND l.data_validade < CURRENT_DATE
  ON CONFLICT (tipo_alerta, origem_tabela, origem_id)
  DO UPDATE SET
    nivel = 'CRITICO',
    descricao = EXCLUDED.descricao,
    dados_contexto = EXCLUDED.dados_contexto,
    status = CASE WHEN public.alertas_operacionais.status = 'RESOLVIDO' THEN 'ATIVO' ELSE public.alertas_operacionais.status END,
    resolvido_em = CASE WHEN public.alertas_operacionais.status = 'RESOLVIDO' THEN NULL ELSE public.alertas_operacionais.resolvido_em END,
    atualizado_em = NOW();

  -- 3. Detecção: LOTE_VENCIMENTO (lotes válidos próximos da validade FEFO)
  INSERT INTO public.alertas_operacionais (tipo_alerta, nivel, origem_tabela, origem_id, titulo, descricao, dados_contexto, status)
  SELECT
    'LOTE_VENCIMENTO',
    'ATENCAO',
    'ingrediente_lotes',
    l.id::TEXT,
    'Validade Próxima: Lote ' || l.codigo_lote,
    'Lote ' || l.codigo_lote || ' de ' || i.nome || ' vence em ' || (l.data_validade - CURRENT_DATE) || ' dia(s) (' || to_char(l.data_validade, 'DD/MM/YYYY') || '). Saldo: ' || l.quantidade_atual || ' ' || i.unidade || '.',
    jsonb_build_object(
      'lote_id', l.id,
      'codigo_lote', l.codigo_lote,
      'ingrediente_id', i.id,
      'ingrediente_nome', i.nome,
      'quantidade_atual', l.quantidade_atual,
      'data_validade', l.data_validade,
      'dias_restantes', (l.data_validade - CURRENT_DATE)
    ),
    'ATIVO'
  FROM public.ingrediente_lotes l
  JOIN public.ingredientes i ON i.id = l.ingrediente_id
  WHERE l.quantidade_atual > 0
    AND l.data_validade >= CURRENT_DATE
    AND l.data_validade <= (CURRENT_DATE + v_cfg.dias_aviso_validade)
  ON CONFLICT (tipo_alerta, origem_tabela, origem_id)
  DO UPDATE SET
    nivel = 'ATENCAO',
    descricao = EXCLUDED.descricao,
    dados_contexto = EXCLUDED.dados_contexto,
    status = CASE WHEN public.alertas_operacionais.status = 'RESOLVIDO' THEN 'ATIVO' ELSE public.alertas_operacionais.status END,
    resolvido_em = CASE WHEN public.alertas_operacionais.status = 'RESOLVIDO' THEN NULL ELSE public.alertas_operacionais.resolvido_em END,
    atualizado_em = NOW();

  -- 4. Detecção: ATRASO_PEDIDO (pedidos confirmados/em produção com entrega iminente ou atrasada)
  INSERT INTO public.alertas_operacionais (tipo_alerta, nivel, origem_tabela, origem_id, titulo, descricao, dados_contexto, status)
  SELECT
    'ATRASO_PEDIDO',
    CASE
      WHEN p.data_entrega < CURRENT_DATE OR (p.data_entrega = CURRENT_DATE AND p.hora_entrega <= CURRENT_TIME) THEN 'CRITICO'
      ELSE 'ATENCAO'
    END,
    'pedidos',
    p.id::TEXT,
    'Risco de Atraso: Pedido #' || p.id,
    'Pedido #' || p.id || ' (' || p.nome_cliente || ') com entrega prevista para ' || to_char(p.data_entrega, 'DD/MM/YYYY') || ' às ' || p.hora_entrega || ' ainda está em status ' || p.status_operacional || '.',
    jsonb_build_object(
      'pedido_id', p.id,
      'nome_cliente', p.nome_cliente,
      'data_entrega', p.data_entrega,
      'hora_entrega', p.hora_entrega,
      'status_operacional', p.status_operacional,
      'total', p.total
    ),
    'ATIVO'
  FROM public.pedidos p
  WHERE p.status_operacional IN ('aguardando_producao', 'em_producao', 'pronto')
    AND p.status_comercial NOT IN ('cancelado')
    AND (
      p.data_entrega < CURRENT_DATE
      OR (
        p.data_entrega = CURRENT_DATE
        AND (p.data_entrega + p.hora_entrega) <= (NOW() + (v_cfg.antecedencia_atraso_minutos || ' minutes')::interval)
      )
    )
  ON CONFLICT (tipo_alerta, origem_tabela, origem_id)
  DO UPDATE SET
    nivel = EXCLUDED.nivel,
    descricao = EXCLUDED.descricao,
    dados_contexto = EXCLUDED.dados_contexto,
    status = CASE WHEN public.alertas_operacionais.status = 'RESOLVIDO' THEN 'ATIVO' ELSE public.alertas_operacionais.status END,
    resolvido_em = CASE WHEN public.alertas_operacionais.status = 'RESOLVIDO' THEN NULL ELSE public.alertas_operacionais.resolvido_em END,
    atualizado_em = NOW();

  -- 5. Detecção: MARGEM_CRITICA (pedidos calculados com margem < margem_minima_alvo)
  INSERT INTO public.alertas_operacionais (tipo_alerta, nivel, origem_tabela, origem_id, titulo, descricao, dados_contexto, status)
  SELECT
    'MARGEM_CRITICA',
    CASE WHEN c.margem_contribuicao_percentual < 0 THEN 'CRITICO' ELSE 'ATENCAO' END,
    'pedido_custos_realizados',
    c.id::TEXT,
    'Margem Crítica: Pedido #' || c.pedido_id,
    'Pedido #' || c.pedido_id || ' fechou com margem de ' || to_char(c.margem_contribuicao_percentual, 'FM990.00') || '%, inferior ao alvo configurado de ' || to_char(v_cfg.margem_minima_alvo, 'FM990.00') || '%.',
    jsonb_build_object(
      'custo_id', c.id,
      'pedido_id', c.pedido_id,
      'receita_liquida', c.receita_liquida_snapshot,
      'custo_atribuivel_total', c.custo_atribuivel_total,
      'margem_contribuicao_valor', c.margem_contribuicao_valor,
      'margem_contribuicao_percentual', c.margem_contribuicao_percentual,
      'alvo_configurado', v_cfg.margem_minima_alvo
    ),
    'ATIVO'
  FROM public.pedido_custos_realizados c
  WHERE c.status = 'finalizado'
    AND c.margem_contribuicao_percentual < v_cfg.margem_minima_alvo
  ON CONFLICT (tipo_alerta, origem_tabela, origem_id)
  DO UPDATE SET
    nivel = EXCLUDED.nivel,
    descricao = EXCLUDED.descricao,
    dados_contexto = EXCLUDED.dados_contexto,
    status = CASE WHEN public.alertas_operacionais.status = 'RESOLVIDO' THEN 'ATIVO' ELSE public.alertas_operacionais.status END,
    resolvido_em = CASE WHEN public.alertas_operacionais.status = 'RESOLVIDO' THEN NULL ELSE public.alertas_operacionais.resolvido_em END,
    atualizado_em = NOW();

  -- 6. Detecção: QUALIDADE_RETIDA (itens com checkpoint de qualidade REPROVADO não resolvidos)
  INSERT INTO public.alertas_operacionais (tipo_alerta, nivel, origem_tabela, origem_id, titulo, descricao, dados_contexto, status)
  SELECT
    'QUALIDADE_RETIDA',
    'CRITICO',
    'producao_controles_qualidade',
    q.id::TEXT,
    'Retenção de Qualidade: Pedido #' || q.pedido_id,
    'Pedido #' || q.pedido_id || ' foi reprovado na etapa ' || q.etapa || ' e requer reinspeção ou intervenção.',
    jsonb_build_object(
      'controle_id', q.id,
      'pedido_id', q.pedido_id,
      'etapa', q.etapa,
      'observacao', q.observacao,
      'responsavel', q.responsavel_nome,
      'inspecionado_em', q.registrado_em
    ),
    'ATIVO'
  FROM public.producao_controles_qualidade q
  JOIN public.pedidos p ON p.id = q.pedido_id
  WHERE q.resultado = 'REPROVADO'
    AND p.status_operacional NOT IN ('entregue', 'retirado')
    AND p.status_comercial NOT IN ('cancelado')
    AND NOT EXISTS (
      SELECT 1 FROM public.producao_controles_qualidade q2
      WHERE q2.pedido_id = q.pedido_id
        AND q2.etapa = q.etapa
        AND q2.resultado = 'APROVADO'
        AND q2.registrado_em > q.registrado_em
    )
  ON CONFLICT (tipo_alerta, origem_tabela, origem_id)
  DO UPDATE SET
    nivel = 'CRITICO',
    descricao = EXCLUDED.descricao,
    dados_contexto = EXCLUDED.dados_contexto,
    status = CASE WHEN public.alertas_operacionais.status = 'RESOLVIDO' THEN 'ATIVO' ELSE public.alertas_operacionais.status END,
    resolvido_em = CASE WHEN public.alertas_operacionais.status = 'RESOLVIDO' THEN NULL ELSE public.alertas_operacionais.resolvido_em END,
    atualizado_em = NOW();

  -- RESOLUÇÃO AUTOMÁTICA (a condição de risco deixou de existir no mundo real)
  -- 1) Rupturas resolvidas
  WITH resolvidas AS (
    UPDATE public.alertas_operacionais a
    SET status = 'RESOLVIDO', resolvido_em = NOW()
    WHERE a.tipo_alerta = 'RUPTURA_ESTOQUE'
      AND a.status IN ('ATIVO', 'RECONHECIDO')
      AND EXISTS (
        SELECT 1 FROM public.ingredientes i
        LEFT JOIN public.ingrediente_saldos s ON s.ingrediente_id = i.id
        WHERE i.id::TEXT = a.origem_id
          AND COALESCE(s.saldo_atual, i.estoque_qtd, 0) > i.estoque_minimo
      )
    RETURNING a.id
  )
  SELECT v_resolvidos + count(*) INTO v_resolvidos FROM resolvidas;

  -- 2) Lotes vencidos com saldo zerado
  WITH resolvidas AS (
    UPDATE public.alertas_operacionais a
    SET status = 'RESOLVIDO', resolvido_em = NOW()
    WHERE a.tipo_alerta IN ('LOTE_VENCIDO', 'LOTE_VENCIMENTO')
      AND a.status IN ('ATIVO', 'RECONHECIDO')
      AND EXISTS (
        SELECT 1 FROM public.ingrediente_lotes l
        WHERE l.id::TEXT = a.origem_id
          AND l.quantidade_atual <= 0
      )
    RETURNING a.id
  )
  SELECT v_resolvidos + count(*) INTO v_resolvidos FROM resolvidas;

  -- 3) Pedidos atrasados que foram entregues ou cancelados
  WITH resolvidas AS (
    UPDATE public.alertas_operacionais a
    SET status = 'RESOLVIDO', resolvido_em = NOW()
    WHERE a.tipo_alerta = 'ATRASO_PEDIDO'
      AND a.status IN ('ATIVO', 'RECONHECIDO')
      AND EXISTS (
        SELECT 1 FROM public.pedidos p
        WHERE p.id::TEXT = a.origem_id
          AND (p.status_operacional IN ('entregue', 'retirado') OR p.status_comercial = 'cancelado')
      )
    RETURNING a.id
  )
  SELECT v_resolvidos + count(*) INTO v_resolvidos FROM resolvidas;

  -- 4) Qualidade retida liberada por nova inspeção
  WITH resolvidas AS (
    UPDATE public.alertas_operacionais a
    SET status = 'RESOLVIDO', resolvido_em = NOW()
    WHERE a.tipo_alerta = 'QUALIDADE_RETIDA'
      AND a.status IN ('ATIVO', 'RECONHECIDO')
      AND EXISTS (
        SELECT 1 FROM public.producao_controles_qualidade q
        JOIN public.producao_controles_qualidade q2
          ON q2.pedido_id = q.pedido_id AND q2.etapa = q.etapa AND q2.resultado = 'APROVADO' AND q2.registrado_em > q.registrado_em
        WHERE q.id::TEXT = a.origem_id
      )
    RETURNING a.id
  )
  SELECT v_resolvidos + count(*) INTO v_resolvidos FROM resolvidas;

  SELECT count(*) INTO v_total_ativos FROM public.alertas_operacionais WHERE status IN ('ATIVO', 'RECONHECIDO');

  RETURN jsonb_build_object(
    'success', true,
    'processado_em', NOW(),
    'resolvidos', v_resolvidos,
    'total_ativos', v_total_ativos
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.processar_alertas_operacionais() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.processar_alertas_operacionais() TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 6.1 RPC: SINCRONIZAR E OBTER ALERTAS OPERACIONAIS (ADMINISTRADOR)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.obter_alertas_operacionais_admin(
  p_tipo TEXT DEFAULT NULL,
  p_nivel TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_caller_id UUID;
  v_cfg RECORD;
  v_criticos INT := 0;
  v_atencao INT := 0;
  v_operacionais INT := 0;
  v_info INT := 0;
  v_alertas JSONB := '[]'::jsonb;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL OR NOT public.is_admin() THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Apenas administradores podem acessar o painel completo de alertas e diagnósticos.',
      'code', 'PERMISSION_DENIED'
    );
  END IF;

  -- Processamento proativo autônomo de alertas
  PERFORM public.processar_alertas_operacionais();

  -- Obter configurações ativas
  SELECT * INTO v_cfg FROM public.alertas_configuracoes WHERE id = 1;
  IF NOT FOUND THEN
    v_cfg.dias_aviso_validade := 7;
    v_cfg.margem_minima_alvo := 30.00;
    v_cfg.antecedencia_atraso_minutos := 120;
    v_cfg.ativo := true;
  END IF;

  -- Contagem de métricas agregadas dos alertas não-resolvidos
  SELECT
    COUNT(*) FILTER (WHERE nivel = 'CRITICO' AND status != 'RESOLVIDO'),
    COUNT(*) FILTER (WHERE nivel = 'ATENCAO' AND status != 'RESOLVIDO'),
    COUNT(*) FILTER (WHERE nivel = 'OPERACIONAL' AND status != 'RESOLVIDO'),
    COUNT(*) FILTER (WHERE nivel = 'INFO' AND status != 'RESOLVIDO')
  INTO v_criticos, v_atencao, v_operacionais, v_info
  FROM public.alertas_operacionais;

  -- Seleção dos alertas solicitados
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', a.id,
      'tipo_alerta', a.tipo_alerta,
      'nivel', a.nivel,
      'origem_tabela', a.origem_tabela,
      'origem_id', a.origem_id,
      'titulo', a.titulo,
      'descricao', a.descricao,
      'dados_contexto', a.dados_contexto,
      'status', a.status,
      'criado_em', a.criado_em,
      'atualizado_em', a.atualizado_em,
      'resolvido_em', a.resolvido_em,
      'reconhecido_por', (
        SELECT jsonb_agg(jsonb_build_object(
          'usuario_id', r.usuario_id,
          'usuario_nome', r.usuario_nome,
          'observacao', r.observacao,
          'criado_em', r.criado_em
        ))
        FROM public.alertas_reconhecimentos r
        WHERE r.alerta_id = a.id
      )
    ) ORDER BY
      CASE a.nivel
        WHEN 'CRITICO' THEN 1
        WHEN 'ATENCAO' THEN 2
        WHEN 'OPERACIONAL' THEN 3
        ELSE 4
      END,
      a.criado_em DESC
  ) INTO v_alertas
  FROM public.alertas_operacionais a
  WHERE (p_tipo IS NULL OR a.tipo_alerta = p_tipo)
    AND (p_nivel IS NULL OR a.nivel = p_nivel)
    AND a.status != 'RESOLVIDO';

  RETURN jsonb_build_object(
    'success', true,
    'metricas', jsonb_build_object(
      'criticos', COALESCE(v_criticos, 0),
      'atencao', COALESCE(v_atencao, 0),
      'operacionais', COALESCE(v_operacionais, 0),
      'info', COALESCE(v_info, 0),
      'total_pendentes', (COALESCE(v_criticos, 0) + COALESCE(v_atencao, 0) + COALESCE(v_operacionais, 0) + COALESCE(v_info, 0))
    ),
    'configuracoes', to_jsonb(v_cfg),
    'alertas', COALESCE(v_alertas, '[]'::jsonb)
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_alertas_operacionais_admin(TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_alertas_operacionais_admin(TEXT, TEXT) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 7. RPC: OBTER ALERTAS OPERACIONAIS SANITIZADOS (OPERADOR DE BANCADA)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.obter_alertas_operacionais_operador()
RETURNS JSONB AS $$
DECLARE
  v_caller_id UUID;
  v_res JSONB;
  v_itens JSONB := '[]'::jsonb;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Usuário não autenticado.',
      'code', 'UNAUTHENTICATED'
    );
  END IF;

  -- Processamento proativo autônomo de alertas
  PERFORM public.processar_alertas_operacionais();

  -- Seleciona somente alertas operacionais de chão de fábrica/produção
  -- Oculta estritamente MARGEM_CRITICA, SISTEMICO e DIVERGENCIA_INVENTARIO
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', a.id,
      'tipo_alerta', a.tipo_alerta,
      'nivel', a.nivel,
      'origem_tabela', a.origem_tabela,
      'origem_id', a.origem_id,
      'titulo', a.titulo,
      'descricao', a.descricao,
      -- Sanitização estrita: remove todos os dados financeiros e custos
      'dados_contexto', a.dados_contexto - 'custo_atribuivel_total' - 'margem_contribuicao_valor' - 'margem_contribuicao_percentual' - 'receita_liquida' - 'alvo_configurado' - 'total',
      'status', a.status,
      'criado_em', a.criado_em
    ) ORDER BY
      CASE a.nivel WHEN 'CRITICO' THEN 1 WHEN 'ATENCAO' THEN 2 ELSE 3 END,
      a.criado_em DESC
  ) INTO v_itens
  FROM public.alertas_operacionais a
  WHERE a.status != 'RESOLVIDO'
    AND a.tipo_alerta IN ('RUPTURA_ESTOQUE', 'LOTE_VENCIMENTO', 'LOTE_VENCIDO', 'ATRASO_PEDIDO', 'QUALIDADE_RETIDA');

  RETURN jsonb_build_object(
    'success', true,
    'modo', 'operador_sanitizado',
    'alertas', COALESCE(v_itens, '[]'::jsonb)
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.obter_alertas_operacionais_operador() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.obter_alertas_operacionais_operador() TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 8. RPC: RECONHECER ALERTA OPERACIONAL (COM IDEMPOTÊNCIA E AUDITORIA)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.reconhecer_alerta_operacional(
  p_alerta_id BIGINT,
  p_motivo TEXT DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_caller_id UUID;
  v_user_nome TEXT;
  v_alerta RECORD;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Usuário não autenticado.',
      'code', 'UNAUTHENTICATED'
    );
  END IF;

  -- Localizar o alerta
  SELECT * INTO v_alerta FROM public.alertas_operacionais WHERE id = p_alerta_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Alerta operacional não localizado.',
      'code', 'ALERT_NOT_FOUND'
    );
  END IF;

  -- Resolver nome do usuário
  SELECT COALESCE(nome, email, 'Colaborador') INTO v_user_nome
  FROM public.profiles
  WHERE id = v_caller_id;

  -- Idempotência: Se o usuário já reconheceu o alerta
  IF EXISTS (
    SELECT 1 FROM public.alertas_reconhecimentos
    WHERE alerta_id = p_alerta_id AND usuario_id = v_caller_id
  ) THEN
    RETURN jsonb_build_object(
      'success', true,
      'idempotente', true,
      'alerta_id', p_alerta_id,
      'mensagem', 'Alerta já reconhecido previamente por este usuário.'
    );
  END IF;

  -- Gravar reconhecimento humano
  INSERT INTO public.alertas_reconhecimentos (
    alerta_id, usuario_id, usuario_nome, acao, observacao
  ) VALUES (
    p_alerta_id, v_caller_id, v_user_nome, 'RECONHECER', p_motivo
  );

  -- Atualizar status do alerta para RECONHECIDO se ainda estiver ATIVO
  UPDATE public.alertas_operacionais
  SET status = 'RECONHECIDO', atualizado_em = NOW()
  WHERE id = p_alerta_id AND status = 'ATIVO';

  -- Gravar evento na trilha imutável de auditoria
  INSERT INTO public.auditoria_operacional_eventos (
    evento_tipo, entidade, entidade_id, antes, depois, usuario_id, origem
  ) VALUES (
    'RECONHECIMENTO_ALERTA_OPERACIONAL',
    'alertas_operacionais',
    p_alerta_id::TEXT,
    jsonb_build_object('status_anterior', v_alerta.status),
    jsonb_build_object('novo_status', 'RECONHECIDO', 'motivo', p_motivo, 'usuario', v_user_nome),
    v_caller_id,
    'RPC_RECONHECER_ALERTA'
  );

  RETURN jsonb_build_object(
    'success', true,
    'idempotente', false,
    'alerta_id', p_alerta_id,
    'reconhecido_em', NOW()
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.reconhecer_alerta_operacional(BIGINT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.reconhecer_alerta_operacional(BIGINT, TEXT) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 9. RPC: EXECUTAR HEALTH-CHECK GLOBAL DO SISTEMA (ESTRITAMENTE READ-ONLY)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.executar_healthcheck_global_admin()
RETURNS JSONB AS $$
DECLARE
  v_caller_id UUID;
  v_status_geral TEXT := 'OK';
  v_checks JSONB := '[]'::jsonb;

  -- Contadores de divergência
  v_div_lotes INT := 0;
  v_div_financeiro INT := 0;
  v_div_orfaos INT := 0;
  v_div_fefo INT := 0;
  v_div_margens INT := 0;

  v_detalhes_lotes JSONB := '[]'::jsonb;
  v_detalhes_fin JSONB := '[]'::jsonb;
  v_detalhes_orfaos JSONB := '[]'::jsonb;
  v_detalhes_fefo JSONB := '[]'::jsonb;
  v_detalhes_margens JSONB := '[]'::jsonb;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL OR NOT public.is_admin() THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Apenas administradores podem executar o health-check global.',
      'code', 'PERMISSION_DENIED'
    );
  END IF;

  -- ----------------------------------------------------------------------------
  -- CHECK 1: SALDOS_LOTES
  -- Compara a soma dos lotes ativos com ingrediente_saldos.saldo_atual
  -- ----------------------------------------------------------------------------
  SELECT
    COUNT(*),
    COALESCE(jsonb_agg(jsonb_build_object(
      'ingrediente_id', sub.ingrediente_id,
      'nome', sub.nome,
      'saldo_consolidado', sub.saldo_consolidado,
      'soma_lotes', sub.soma_lotes,
      'diferenca', sub.diferenca
    )), '[]'::jsonb)
  INTO v_div_lotes, v_detalhes_lotes
  FROM (
    SELECT
      i.id AS ingrediente_id,
      i.nome,
      COALESCE(s.saldo_atual, 0) AS saldo_consolidado,
      COALESCE(SUM(l.quantidade_atual), 0) AS soma_lotes,
      ABS(COALESCE(s.saldo_atual, 0) - COALESCE(SUM(l.quantidade_atual), 0)) AS diferenca
    FROM public.ingredientes i
    JOIN public.ingrediente_saldos s ON s.ingrediente_id = i.id
    LEFT JOIN public.ingrediente_lotes l ON l.ingrediente_id = i.id
    WHERE i.ativo = true AND (i.controlar_lote = true OR i.controlar_validade = true)
    GROUP BY i.id, i.nome, s.saldo_atual
    HAVING ABS(COALESCE(s.saldo_atual, 0) - COALESCE(SUM(l.quantidade_atual), 0)) > 0.001
  ) sub;

  -- ----------------------------------------------------------------------------
  -- CHECK 2: FINANCEIRO_PEDIDOS
  -- Verifica pedidos marcados como 'pago' que não possuam registro de pagamento
  -- ----------------------------------------------------------------------------
  SELECT
    COUNT(*),
    COALESCE(jsonb_agg(jsonb_build_object(
      'pedido_id', p.id,
      'total', p.total,
      'status_financeiro', p.status_financeiro,
      'created_at', p.created_at
    )), '[]'::jsonb)
  INTO v_div_financeiro, v_detalhes_fin
  FROM public.pedidos p
  WHERE p.status_financeiro = 'pago'
    AND p.total > 0
    AND NOT EXISTS (
      SELECT 1 FROM public.pedido_pagamentos pp
      WHERE pp.pedido_id = p.id AND pp.status = 'aprovado'
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.financeiro_lancamentos fl
      WHERE fl.pedido_id = p.id AND fl.tipo = 'receita'
    );

  -- ----------------------------------------------------------------------------
  -- CHECK 3: PEDIDOS_ORFAOS
  -- Verifica pedidos sem itens filhos ou com valores negativos anômalos
  -- ----------------------------------------------------------------------------
  SELECT
    COUNT(*),
    COALESCE(jsonb_agg(jsonb_build_object(
      'pedido_id', p.id,
      'cliente', p.nome_cliente,
      'motivo', CASE WHEN p.total < 0 THEN 'VALOR_NEGATIVO' ELSE 'SEM_ITENS' END
    )), '[]'::jsonb)
  INTO v_div_orfaos, v_detalhes_orfaos
  FROM public.pedidos p
  WHERE (p.total < 0)
     OR (NOT EXISTS (SELECT 1 FROM public.pedido_itens pi WHERE pi.pedido_id = p.id) AND p.status_comercial != 'cancelado');

  -- ----------------------------------------------------------------------------
  -- CHECK 4: FEFO_INTEGRIDADE
  -- Verifica se existem lotes com quantidade_atual negativa ou sem data de validade
  -- ----------------------------------------------------------------------------
  SELECT
    COUNT(*),
    COALESCE(jsonb_agg(jsonb_build_object(
      'lote_id', l.id,
      'codigo_lote', l.codigo_lote,
      'ingrediente_id', l.ingrediente_id,
      'quantidade_atual', l.quantidade_atual
    )), '[]'::jsonb)
  INTO v_div_fefo, v_detalhes_fefo
  FROM public.ingrediente_lotes l
  WHERE l.quantidade_atual < 0 OR l.data_validade IS NULL;

  -- ----------------------------------------------------------------------------
  -- CHECK 5: MARGENS_ANOMALAS
  -- Identifica pedidos finalizados cuja receita líquida seja positiva mas margem seja nula
  -- ----------------------------------------------------------------------------
  SELECT
    COUNT(*),
    COALESCE(jsonb_agg(jsonb_build_object(
      'custo_id', c.id,
      'pedido_id', c.pedido_id,
      'margem_percentual', c.margem_contribuicao_percentual
    )), '[]'::jsonb)
  INTO v_div_margens, v_detalhes_margens
  FROM public.pedido_custos_realizados c
  WHERE c.status = 'finalizado'
    AND (c.margem_contribuicao_percentual IS NULL OR c.custo_atribuivel_total < 0);

  -- Avaliação do Status Geral
  IF (v_div_lotes > 0 OR v_div_financeiro > 0 OR v_div_fefo > 0) THEN
    v_status_geral := 'CRITICAL';
  ELSIF (v_div_orfaos > 0 OR v_div_margens > 0) THEN
    v_status_geral := 'DEGRADED';
  ELSE
    v_status_geral := 'OK';
  END IF;

  -- Montagem dos 5 checks padronizados
  v_checks := jsonb_build_array(
    jsonb_build_object(
      'codigo', 'SALDOS_LOTES',
      'nome', 'Reconciliação de Saldos Agregados vs Lotes (Frente L)',
      'status', CASE WHEN v_div_lotes = 0 THEN 'OK' ELSE 'CRITICAL' END,
      'divergencias', v_div_lotes,
      'detalhes', v_detalhes_lotes
    ),
    jsonb_build_object(
      'codigo', 'FINANCEIRO_PEDIDOS',
      'nome', 'Integridade Pedidos Pagos vs Lançamentos de Caixa (Frentes C/H)',
      'status', CASE WHEN v_div_financeiro = 0 THEN 'OK' ELSE 'CRITICAL' END,
      'divergencias', v_div_financeiro,
      'detalhes', v_detalhes_fin
    ),
    jsonb_build_object(
      'codigo', 'PEDIDOS_ORFAOS',
      'nome', 'Consistência de Itens e Valores de Pedidos',
      'status', CASE WHEN v_div_orfaos = 0 THEN 'OK' ELSE 'DEGRADED' END,
      'divergencias', v_div_orfaos,
      'detalhes', v_detalhes_orfaos
    ),
    jsonb_build_object(
      'codigo', 'FEFO_INTEGRIDADE',
      'nome', 'Integridade de Lotes e Validades FEFO',
      'status', CASE WHEN v_div_fefo = 0 THEN 'OK' ELSE 'CRITICAL' END,
      'divergencias', v_div_fefo,
      'detalhes', v_detalhes_fefo
    ),
    jsonb_build_object(
      'codigo', 'MARGENS_ANOMALAS',
      'nome', 'Conformidade de Cálculos de Margem & Custo (Frente M)',
      'status', CASE WHEN v_div_margens = 0 THEN 'OK' ELSE 'DEGRADED' END,
      'divergencias', v_div_margens,
      'detalhes', v_detalhes_margens
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'executado_em', NOW(),
    'status', v_status_geral,
    'total_checks', 5,
    'checks', v_checks
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.executar_healthcheck_global_admin() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.executar_healthcheck_global_admin() TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 10. RPC: SALVAR CONFIGURAÇÕES DE ALERTAS (ADMINISTRADOR)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.salvar_configuracoes_alertas_admin(
  p_dias_aviso_validade INTEGER DEFAULT NULL,
  p_margem_minima_alvo NUMERIC DEFAULT NULL,
  p_antecedencia_atraso_minutos INTEGER DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_caller_id UUID;
  v_antiga RECORD;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL OR NOT public.is_admin() THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Apenas administradores podem alterar as configurações de alertas.',
      'code', 'PERMISSION_DENIED'
    );
  END IF;

  SELECT * INTO v_antiga FROM public.alertas_configuracoes WHERE id = 1;

  UPDATE public.alertas_configuracoes
  SET
    dias_aviso_validade = COALESCE(p_dias_aviso_validade, dias_aviso_validade),
    margem_minima_alvo = COALESCE(p_margem_minima_alvo, margem_minima_alvo),
    antecedencia_atraso_minutos = COALESCE(p_antecedencia_atraso_minutos, antecedencia_atraso_minutos),
    atualizado_em = NOW()
  WHERE id = 1;

  -- Gravar evento na trilha imutável de auditoria
  INSERT INTO public.auditoria_operacional_eventos (
    evento_tipo, entidade, entidade_id, antes, depois, usuario_id, origem
  ) VALUES (
    'ALTERACAO_CONFIGURACAO_ALERTAS',
    'alertas_configuracoes',
    '1',
    to_jsonb(v_antiga),
    (SELECT to_jsonb(c) FROM public.alertas_configuracoes c WHERE c.id = 1),
    v_caller_id,
    'RPC_SALVAR_CONFIG_ALERTAS'
  );

  RETURN jsonb_build_object(
    'success', true,
    'configuracoes', (SELECT to_jsonb(c) FROM public.alertas_configuracoes c WHERE c.id = 1)
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.salvar_configuracoes_alertas_admin(INTEGER, NUMERIC, INTEGER) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.salvar_configuracoes_alertas_admin(INTEGER, NUMERIC, INTEGER) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 11. RPC: LISTAR TRILHA DE AUDITORIA OPERACIONAL (ADMINISTRADOR)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.listar_auditoria_operacional_admin(
  p_entidade TEXT DEFAULT NULL,
  p_evento_tipo TEXT DEFAULT NULL,
  p_limite INT DEFAULT 50,
  p_offset INT DEFAULT 0
)
RETURNS JSONB AS $$
DECLARE
  v_caller_id UUID;
  v_total INT;
  v_eventos JSONB := '[]'::jsonb;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL OR NOT public.is_admin() THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Apenas administradores podem visualizar a trilha de auditoria operacional.',
      'code', 'PERMISSION_DENIED'
    );
  END IF;

  SELECT COUNT(*) INTO v_total
  FROM public.auditoria_operacional_eventos a
  WHERE (p_entidade IS NULL OR a.entidade = p_entidade)
    AND (p_evento_tipo IS NULL OR a.evento_tipo = p_evento_tipo);

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', a.id,
      'evento_tipo', a.evento_tipo,
      'entidade', a.entidade,
      'entidade_id', a.entidade_id,
      'antes', a.antes,
      'depois', a.depois,
      'usuario_id', a.usuario_id,
      'usuario_nome', (SELECT COALESCE(nome, email, 'Colaborador') FROM public.profiles WHERE id = a.usuario_id),
      'origem', a.origem,
      'created_at', a.created_at
    ) ORDER BY a.created_at DESC
  ) INTO v_eventos
  FROM (
    SELECT * FROM public.auditoria_operacional_eventos a
    WHERE (p_entidade IS NULL OR a.entidade = p_entidade)
      AND (p_evento_tipo IS NULL OR a.evento_tipo = p_evento_tipo)
    ORDER BY a.created_at DESC
    LIMIT LEAST(GREATEST(p_limite, 1), 200)
    OFFSET GREATEST(p_offset, 0)
  ) a;

  RETURN jsonb_build_object(
    'success', true,
    'total', v_total,
    'limite', p_limite,
    'offset', p_offset,
    'eventos', COALESCE(v_eventos, '[]'::jsonb)
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth;

REVOKE ALL ON FUNCTION public.listar_auditoria_operacional_admin(TEXT, TEXT, INT, INT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.listar_auditoria_operacional_admin(TEXT, TEXT, INT, INT) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- 12. SEGURANÇA E ROW LEVEL SECURITY (FAIL-CLOSED)
-- ------------------------------------------------------------------------------
ALTER TABLE public.alertas_configuracoes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.alertas_operacionais ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.alertas_reconhecimentos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.auditoria_operacional_eventos ENABLE ROW LEVEL SECURITY;

-- Revoke explícito de acesso direto às tabelas
REVOKE ALL ON public.alertas_configuracoes FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.alertas_operacionais FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.alertas_reconhecimentos FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.auditoria_operacional_eventos FROM PUBLIC, anon, authenticated;

-- Políticas de RLS restritas para service_role e admins
DROP POLICY IF EXISTS alertas_configuracoes_admin ON public.alertas_configuracoes;
CREATE POLICY alertas_configuracoes_admin ON public.alertas_configuracoes
  FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS alertas_operacionais_admin ON public.alertas_operacionais;
CREATE POLICY alertas_operacionais_admin ON public.alertas_operacionais
  FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS alertas_reconhecimentos_admin ON public.alertas_reconhecimentos;
CREATE POLICY alertas_reconhecimentos_admin ON public.alertas_reconhecimentos
  FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS auditoria_operacional_select_admin ON public.auditoria_operacional_eventos;
CREATE POLICY auditoria_operacional_select_admin ON public.auditoria_operacional_eventos
  FOR SELECT TO authenticated USING (public.is_admin());

DROP POLICY IF EXISTS auditoria_operacional_service_role ON public.auditoria_operacional_eventos;
CREATE POLICY auditoria_operacional_service_role ON public.auditoria_operacional_eventos
  FOR ALL TO service_role USING (true) WITH CHECK (true);


-- ==========================================================================
-- >>> MIGRATION 030_equipe_turnos_escalas_capacidade_real.sql
-- ==========================================================================

-- ==============================================================================
-- MIGRATION 030: PESSOAS, TURNOS, ESCALAS & CAPACIDADE REAL DA EQUIPE (FRENTE O)
-- ==============================================================================
-- 1. ESTRUTURAS: funcoes_equipe, colaboradores, colaborador_funcoes, turnos_trabalho,
--    escalas_equipe, escala_intervalos, ausencias_equipe, equipe_configuracoes.
-- 2. SEGREGAÇÃO CONCEITUAL RÍGIDA:
--    - escala_planejada_minutos != minutos_trabalhados_reais (sem ponto/clock-in nesta fase)
--    - capacidade_humana_planejada_minutos != capacidade_producao_pontos (Frente E intocada)
--    - colaborador != auth.users (colaborador pode ou não ter login no sistema)
-- 3. ZERO FOLHA / RH: sem salários, benefícios, horas extras financeiras ou banco de horas.
-- 4. AUSÊNCIAS NÃO-CLÍNICAS: motivos operacionais (FOLGA, FERIAS, AUSENCIA, ATESTADO, INDISPONIBILIDADE, OUTRO) sem diagnósticos médicos.
-- 5. MINUTOS DISPONÍVEIS DERIVADOS: calculados dinamicamente (turno - intervalos - ausências).
-- 6. CARGA E UTILIZAÇÃO POR FUNÇÃO: integra com produto_tempos_producao da Frente M.
-- 7. DETECÇÃO PROATIVA (Frente N / Modelo B): processar_alertas_operacionais() estendida com SOBRECARGA_EQUIPE.
-- 8. ZERO EFEITO FINANCEIRO: sem lançamentos em financeiro_lancamentos ou pedido_pagamentos.
-- ==============================================================================

-- ------------------------------------------------------------------------------
-- 1. FUNÇÕES DA EQUIPE OPERACIONAL
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.funcoes_equipe (
  id BIGSERIAL PRIMARY KEY,
  codigo TEXT NOT NULL UNIQUE CHECK (codigo ~ '^[A-Z0-9_]+$'),
  nome TEXT NOT NULL,
  descricao TEXT,
  cor_identificadora TEXT NOT NULL DEFAULT '#3b82f6',
  etapas_padrao TEXT[] NOT NULL DEFAULT '{}'::TEXT[],
  ativo BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_funcoes_equipe_ativo ON public.funcoes_equipe(ativo);

-- Seed de funções operacionais da confeitaria
INSERT INTO public.funcoes_equipe (codigo, nome, descricao, cor_identificadora, etapas_padrao, ativo)
VALUES
  ('CONFEITARIA', 'Confeitaria Artística', 'Montagem fina, recheio, cobertura e acabamento artesanal', '#ec4899', '{"recheio","cobertura","decoracao","finalizacao"}', true),
  ('AUXILIAR', 'Auxiliar de Cozinha', 'Pesagem, preparo de massas, cocção em fornos e resfriamento', '#f59e0b', '{"preparo","forno","resfriamento"}', true),
  ('EMBALAGEM', 'Embalagem & Expedição', 'Caixas personalizadas, laços, rotulagem e conferência final', '#8b5cf6', '{"embalagem"}', true),
  ('ENTREGA', 'Logística & Entrega', 'Separação de rotas, transporte seguro e entrega ao cliente', '#06b6d4', '{"outro"}', true),
  ('ATENDIMENTO', 'Atendimento & Balcão', 'Recepção de clientes para retirada e suporte a encomendas', '#10b981', '{"outro"}', true)
ON CONFLICT (codigo) DO UPDATE SET
  nome = EXCLUDED.nome,
  descricao = EXCLUDED.descricao,
  etapas_padrao = EXCLUDED.etapas_padrao;

-- ------------------------------------------------------------------------------
-- 2. CADASTRO DE COLABORADORES (PESSOAS FÍSICAS OPERACIONAIS)
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.colaboradores (
  id BIGSERIAL PRIMARY KEY,
  nome TEXT NOT NULL,
  apelido TEXT,
  telefone TEXT,
  email TEXT,
  auth_user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  ativo BOOLEAN NOT NULL DEFAULT true,
  observacoes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- O2: auth_user_id não pode vincular dois colaboradores ativos
CREATE UNIQUE INDEX IF NOT EXISTS uq_colaborador_auth_user_ativo 
ON public.colaboradores(auth_user_id) 
WHERE auth_user_id IS NOT NULL AND ativo = true;

CREATE INDEX IF NOT EXISTS idx_colaboradores_ativo ON public.colaboradores(ativo);

-- ------------------------------------------------------------------------------
-- 3. VÍNCULO COLABORADOR <-> FUNÇÕES (HABILIDADES E COMPETÊNCIAS)
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.colaborador_funcoes (
  id BIGSERIAL PRIMARY KEY,
  colaborador_id BIGINT NOT NULL REFERENCES public.colaboradores(id) ON DELETE CASCADE,
  funcao_id BIGINT NOT NULL REFERENCES public.funcoes_equipe(id) ON DELETE CASCADE,
  principal BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_colaborador_funcao UNIQUE (colaborador_id, funcao_id)
);

CREATE INDEX IF NOT EXISTS idx_colab_funcoes_colab ON public.colaborador_funcoes(colaborador_id);
CREATE INDEX IF NOT EXISTS idx_colab_funcoes_funcao ON public.colaborador_funcoes(funcao_id);

-- ------------------------------------------------------------------------------
-- 4. TURNOS DE TRABALHO (MODELOS / TEMPLATES DE JORNADA)
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.turnos_trabalho (
  id BIGSERIAL PRIMARY KEY,
  nome TEXT NOT NULL,
  hora_inicio TIME NOT NULL,
  hora_fim TIME NOT NULL,
  intervalo_minutos INT NOT NULL DEFAULT 60 CHECK (intervalo_minutos >= 0),
  dias_semana INT[] NOT NULL DEFAULT '{1,2,3,4,5,6}'::INT[],
  ativo BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT chk_turno_horarios CHECK (hora_fim > hora_inicio)
);

-- Seed de turnos padrão da confeitaria
INSERT INTO public.turnos_trabalho (nome, hora_inicio, hora_fim, intervalo_minutos, dias_semana, ativo)
VALUES
