  ADD CONSTRAINT comunicacoes_cliente_tipo_check CHECK (
    tipo IN (
      'ORCAMENTO_ENVIADO',
      'ORCAMENTO_VENCENDO',
      'SINAL_CONFIRMADO',
      'PEDIDO_PRONTO',
      'SAIU_PARA_ENTREGA',
      'CUPOM_ANIVERSARIO',
      'VOLTE_A_COMPRAR',
      'CAMPANHA_PASCOA',
      'CAMPANHA_PROMOCIONAL',
      'LEMBRETE_PONTOS_EXPIRANDO',
      'PEDIDO_CONFIRMADO',
      'PAGAMENTO_CONFIRMADO',
      'PRODUCAO_INICIADA',
      'PEDIDO_ENTREGUE',
      'PEDIDO_RETIRADO',
      'ORCAMENTO_APROVADO',
      'LEMBRETE_RETIRADA'
    )
  );

