ALTER TABLE public.comunicacoes_cliente
  DROP CONSTRAINT IF EXISTS comunicacoes_cliente_canal_check;

ALTER TABLE public.comunicacoes_cliente
  ADD CONSTRAINT comunicacoes_cliente_canal_check CHECK (
